-- Yen Thoa website: database + schema + sample data (generated by scripts/build-seed-sql.mjs, do not edit by hand)
--
-- This one file is enough to set the database up. Run it from the MySQL shell or the command line:
--     mysql> source db/seed.sql
--     mysql -u root -p < db/seed.sql          (cmd / bash; in PowerShell use: mysql -u root -p -e "source db/seed.sql")
-- It creates the database `yenthoa_db` (utf8mb4), the tables and the sample data, then you set
--     DATABASE_URL=mysql://USER:PASSWORD@127.0.0.1:3306/yenthoa_db
-- Importing again is safe: existing rows (same slug / key) are kept, so your edits are never overwritten.
--
-- Importing into a database that already exists under another name (phpMyAdmin, a hosting panel)?
-- Delete the two lines CREATE DATABASE and USE below, select your database, then import.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `yenthoa_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `yenthoa_db`;

CREATE TABLE IF NOT EXISTS settings (
    k VARCHAR(64) NOT NULL PRIMARY KEY,
    v JSON NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS posts (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(191) NOT NULL,
    title VARCHAR(300) NOT NULL,
    date DATE NOT NULL,
    section VARCHAR(40) NOT NULL DEFAULT 'tin-tuc',
    excerpt TEXT NOT NULL,
    img VARCHAR(500) NULL,
    html MEDIUMTEXT NOT NULL,
    published TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_posts_slug (slug),
    KEY ix_posts_list (published, date, id)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS products (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(191) NOT NULL,
    code VARCHAR(40) NULL,
    name VARCHAR(200) NOT NULL,
    brand VARCHAR(60) NOT NULL DEFAULT '',
    types JSON NOT NULL,
    price BIGINT UNSIGNED NOT NULL DEFAULT 0,
    price_max BIGINT UNSIGNED NOT NULL DEFAULT 0,
    img VARCHAR(500) NULL,
    gallery JSON NOT NULL,
    colors JSON NOT NULL,
    variants JSON NULL,
    specs JSON NULL,
    short_html MEDIUMTEXT NOT NULL,
    html MEDIUMTEXT NOT NULL,
    active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_products_slug (slug),
    KEY ix_products_list (active, name)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS media (
    id CHAR(16) NOT NULL PRIMARY KEY,
    name VARCHAR(200) NOT NULL DEFAULT '',
    file VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY ix_media_created (created_at, id)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS hero_slides (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    eyebrow VARCHAR(200) NOT NULL DEFAULT '',
    title VARCHAR(200) NOT NULL,
    sub VARCHAR(300) NOT NULL DEFAULT '',
    img VARCHAR(500) NOT NULL,
    img_mobile VARCHAR(500) NULL,
    fit VARCHAR(10) NOT NULL DEFAULT 'cover',
    link VARCHAR(500) NULL,
    dim TINYINT(1) NOT NULL DEFAULT 1,
    sort INT NOT NULL DEFAULT 0,
    active TINYINT(1) NOT NULL DEFAULT 1,
    KEY ix_slides (active, sort)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

