INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('1-em-xe-dap-the-thao-ve-voi-bac-khach-yen-hoa-2026-02-02', '1 em xe đạp thể thao về với Bác Khách Yên Hoà', '2026-02-02', 'tin-tuc', '1 em xe đạp thể thao về với Bác Khách Yên Hoà. Bác bảo 12 năm trước mua xe cho con gái đi học cấp 3 xe đi chắc chắn, bền lắm nên hôm nay quay lại mua thêm cái xe đạp 2 ông bà đạp thể dục buổi sáng.…', '/sites/yenthoa/logo.png', '<p>1 em xe đạp thể thao về với Bác Khách Yên Hoà. Bác bảo 12 năm trước mua xe cho con gái đi học cấp 3 xe đi chắc chắn, bền lắm nên hôm nay quay lại mua thêm cái xe đạp 2 ông bà đạp thể dục buổi sáng.</p><p>Cháu cám ơn Bác đã tin tưởng và ủng hộ Siêu Thị Yên Thoa. Chúc hai Bác thật nhiều sức khoẻ.</p><p>Các Bác cần tư vấn mẫu xe đạp thể thao, xe đạp phổ thông, xe trẻ em Ib em nhé!</p>', 1);
