INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('bo-me-dang-tim-xe-cho-cac-con-cu-ghe-xe-dap-yen-thoa-a-2026-08-16', 'Bố mẹ đang tìm xe cho các con cứ ghé xe đạp Yên Thoa ạ', '2026-08-16', 'tin-tuc', 'Bố mẹ đang tìm xe cho các con cứ ghé xe đạp Yên Thoa ạ. Nhà em luôn sẵn các mẫu xe đạp phục vụ cả này ạ. Các Bác cần tư vấn mẫu xe nào cứ ib em tư vấn ạ! khoe Lộc Sang M3 nhà em ạ!', '/sites/yenthoa/logo.png', '<p>Bố mẹ đang tìm xe cho các con cứ ghé xe đạp Yên Thoa ạ. Nhà em luôn sẵn các mẫu xe đạp phục vụ cả này ạ. Các Bác cần tư vấn mẫu xe nào cứ ib em tư vấn ạ!</p><p>khoe Lộc</p><p>Sang M3 nhà em ạ!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('cac-bac-can-1-chiec-xe-dap-the-thao-chac-chan-ben-bi-cho-cac-2026-01-14', 'Các Bác cần 1 chiếc xe đạp thể thao chắc chắn, bền bỉ cho các bạn học sinh tới…', '2026-01-14', 'tin-tuc', 'Các Bác cần 1 chiếc xe đạp thể thao chắc chắn, bền bỉ cho các bạn học sinh tới trường hay tập thể dục nhẹ nhàng thì em MTB 26-02 là lựa chọn phù hợp', '/sites/yenthoa/logo.png', '<p>Các Bác cần 1 chiếc xe đạp thể thao chắc chắn, bền bỉ cho các bạn học sinh tới trường hay tập thể dục nhẹ nhàng thì em MTB 26-02 là lựa chọn phù hợp</p>', 1);
