INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('cac-bac-can-tim-1-chiec-xe-dia-hinh-dep-chac-chan-cho-cac-be-2026-03-27', 'Các Bác cần tìm 1 chiếc xe địa hình đẹp- chắc chắn cho các bé trai từ 6-9 tuổi…', '2026-03-27', 'tin-tuc', 'Các Bác cần tìm 1 chiếc xe địa hình đẹp- chắc chắn cho các bé trai từ 6-9 tuổi thì tham khảo mẫu ĐH 20-01 nhà Sallway nhé. Xe thiết kế hợp kim thép chắc chắn Sơn xe tĩnh điện tăng độ thẩm mĩ và độ…', '/sites/yenthoa/logo.png', '<p>Các Bác cần tìm 1 chiếc xe địa hình đẹp- chắc chắn cho các bé trai từ 6-9 tuổi thì tham khảo mẫu ĐH 20-01 nhà Sallway nhé.</p><p>Xe thiết kế hợp kim thép chắc chắn</p><p>Sơn xe tĩnh điện tăng độ thẩm mĩ và độ bền xe</p><p>Xe trang bị thêm giỏ xe và Baga tiện lợi</p><p>Xe sẵn đủ màu tại Siêu Thị Yên Thoa nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('cac-bac-can-tim-1-dia-chi-mua-xe-dap-uy-tin-chat-luong-nho-g-2026-07-20', 'Các Bác cần tìm 1 địa chỉ mua xe đạp uy tín, chất lượng nhớ ghé qua xe đạp Yên…', '2026-07-20', 'tin-tuc', 'Các Bác cần tìm 1 địa chỉ mua xe đạp uy tín, chất lượng nhớ ghé qua xe đạp Yên Thoa nhé!', '/sites/yenthoa/logo.png', '<p>Các Bác cần tìm 1 địa chỉ mua xe đạp uy tín, chất lượng nhớ ghé qua xe đạp Yên Thoa nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('cac-bac-da-co-xe-choi-tet-chua-a-2026-02-02', 'Các Bác đã có xe chơi Tết chưa ạ', '2026-02-02', 'tin-tuc', 'Các Bác đã có xe chơi Tết chưa ạ? TỚI Ngày Siêu Thị Yên Thoa nhé. Em sẵn nhiều mẫu cho các Bác lựa chọn ạ.', '/sites/yenthoa/logo.png', '<p>Các Bác đã có xe chơi Tết chưa ạ? TỚI Ngày Siêu Thị Yên Thoa nhé. Em sẵn nhiều mẫu cho các Bác lựa chọn ạ.</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('cac-bac-dang-tim-1-chiec-xe-dap-de-di-lai-hang-ngay-2026-10-30', 'Các Bác đang tìm 1 chiếc xe đạp để đi lại hàng ngày', '2026-10-30', 'tin-tuc', 'Các Bác đang tìm 1 chiếc xe đạp để đi lại hàng ngày??? LD 26 Thống Nhất kaf 1 lựa chọn hoàn hảo Giỏ trước để túi xách, balo hoặc đồ dùng cá nhân. Baga sau để chở thêm đồ hoặc lắp đệm ngồi tùy nhu…', '/sites/yenthoa/logo.png', '<p>Các Bác đang tìm 1 chiếc xe đạp để đi lại hàng ngày???</p><p>LD 26 Thống Nhất kaf 1 lựa chọn hoàn hảo</p><p>Giỏ trước để túi xách, balo hoặc đồ dùng cá nhân.</p><p>Baga sau để chở thêm đồ hoặc lắp đệm ngồi tùy nhu cầu.</p><p>Chắn bùn trước và sau, hạn chế bùn nước bắn lên người khi đi đường ướt.</p><p>Chuông xe hỗ trợ phát tín hiệu khi di chuyển.</p><p>Bánh 26 inch, lốp Kenda giúp xe dễ điều khiển và ổn định trên đường phố, khu dân cư.</p><p>Khung xe thấp cũng giúp việc lên xuống thuận tiện hơn, phù hợp với người cao khoảng 150–170cm.</p><p>Mẫu xe đạp LD 26 sẵn đủ màu tại xe đạp Yên Thoa, các Bác quan tâm ib em tư vấn nhé!</p><p>0902003145</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('cac-bac-dang-tim-1-mau-xe-chac-chan-ben-bi-thi-khong-the-bo-2026-08-13', 'Các Bác đang tìm 1 mẫu xe chắc chắn, bền bỉ thì không thể bỏ qua em xe đạp GN…', '2026-08-13', 'tin-tuc', 'Các Bác đang tìm 1 mẫu xe chắc chắn, bền bỉ thì không thể bỏ qua em xe đạp GN 2.0 700c này ạ. Xe bánh 700C phù hợp với chiều cao 1m55-1m8 nên phù hợp cho người dùng cần 1 chiếc xe đạp đi học, đi làm,…', '/sites/yenthoa/logo.png', '<p>Các Bác đang tìm 1 mẫu xe chắc chắn, bền bỉ thì không thể bỏ qua em xe đạp GN 2.0 700c này ạ.</p><p>Xe bánh 700C phù hợp với chiều cao 1m55-1m8 nên phù hợp cho người dùng cần 1 chiếc xe đạp đi học, đi làm, hoặc di chuyển nhẹ nhàng trên phố.</p><p>xe sẵn tại cửa hàng ạ.</p>', 1);
