INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('chi-khach-bao-chi-hoi-may-nguoi-deu-gioi-thieu-len-nha-em-mu-2026-10-02', 'Chị khách bảo chị hỏi mấy người đều giới thiệu lên nhà em mua xe đạp', '2026-10-02', 'tin-tuc', 'Chị khách bảo chị hỏi mấy người đều giới thiệu lên nhà em mua xe đạp. Trên em nhiều xe, xe đi chắc chắn nên hôm nay anh chị lên mua cho cháu 1 cái để cháu đi học', '/sites/yenthoa/logo.png', '<p>Chị khách bảo chị hỏi mấy người đều giới thiệu lên nhà em mua xe đạp. Trên em nhiều xe, xe đi chắc chắn nên hôm nay anh chị lên mua cho cháu 1 cái để cháu đi học</p>', 1);
