INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('su-tin-tuong-cua-quy-khach-hang-la-dong-luc-de-xe-dap-yen-th-2026-10-29', 'Sự tin tưởng của Quý khách hàng là động lực để xe đạp Yên Thoa cố gắng hơn mỗi…', '2026-10-29', 'tin-tuc', 'Sự tin tưởng của Quý khách hàng là động lực để xe đạp Yên Thoa cố gắng hơn mỗi ngày. Các Bác quan tâm các mẫu xe đạp, xe điện, xe ba bánh ib em tư vấn nhé!', '/sites/yenthoa/logo.png', '<p>Sự tin tưởng của Quý khách hàng là động lực để xe đạp Yên Thoa cố gắng hơn mỗi ngày. Các Bác quan tâm các mẫu xe đạp, xe điện, xe ba bánh ib em tư vấn nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('supper-24-thong-nhat-2026-01-17', 'Supper 24 Thống Nhất', '2026-01-17', 'tin-tuc', 'Supper 24 Thống Nhất Chiếc xe đạp thể thao mà bé trai nào cũng mơ ước có. Xe có size 24 phù hợp cho các bé từ 9 tuổi ( cao tầm 1m4 trở lên) Các Bác quan tâm Ib em tư vấn nhé!', '/sites/yenthoa/logo.png', '<p>Supper 24 Thống Nhất</p><p>Chiếc xe đạp thể thao mà bé trai nào cũng mơ ước có.</p><p>Xe có size 24 phù hợp cho các bé từ 9 tuổi ( cao tầm 1m4 trở lên)</p><p>Các Bác quan tâm Ib em tư vấn nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('tam-biet-nam-at-ty-chao-don-nam-binh-ngo-2026-02-16', 'Tạm biệt năm Ất Tỵ chào đón năm Bính Ngọ', '2026-02-16', 'tin-tuc', 'Tạm biệt năm Ất Tỵ chào đón năm Bính Ngọ Xe đạp Yên Thoa xin gửi lời cám ơn tới tất cả Quý Khách Hàng, Quý Đối tác đã luôn tin tưởng , ủng hộ và đồng hành cùng xe đạp Yên Thoa Năm Bính Ngọ xắp sang…', '/sites/yenthoa/logo.png', '<p>Tạm biệt năm Ất Tỵ chào đón năm Bính Ngọ</p><p>Xe đạp Yên Thoa xin gửi lời cám ơn tới tất cả Quý Khách Hàng, Quý Đối tác đã luôn tin tưởng , ủng hộ và đồng hành cùng xe đạp Yên Thoa</p><p>Năm Bính Ngọ xắp sang Xe đạp Yên Thoa xin kính chúc mọi người, mọi nhà thật nhiều sức khỏe, hạnh phúc, Vạn Sự Như Ý!</p>', 1);
