INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-dap-ba-banh-cac-bac-can-alo-em-nhe-2026-04-10', 'Xe ĐẠP BA BÁNH .Các Bác cần alo em nhé', '2026-04-10', 'tin-tuc', 'Xe ĐẠP BA BÁNH .Các Bác cần alo em nhé! dành cho người tai biến nhẹ cần nâng cao sức khoẻ . dành cho người già chở cháu đi chơi - hay chở rau đi bán nhẹ . dành cho gia đình có con nhỏ . Xe có 3 màu:…', '/sites/yenthoa/logo.png', '<p>Xe ĐẠP BA BÁNH .Các Bác cần alo em nhé!</p><p>dành cho người tai biến nhẹ cần nâng cao sức khoẻ .</p><p>dành cho người già chở cháu đi chơi - hay chở rau đi bán nhẹ .</p><p>dành cho gia đình có con nhỏ .</p><p>Xe có 3 màu: Kem-xanh - Nâu</p><p>SHIP cod hàng toàn quốc : 0902003145</p>', 1);
