INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-air-blade-125', 'Xe Air blade 125', 'honda', '[]', 43200000, 44800000, '/sites/yenthoa/img/2024/11/airblade-125-phien-ban-cao-cap-mau-bac-xanh-den.webp', '[\"/sites/yenthoa/img/2024/11/airblade-125-phien-ban-cao-cap-mau-bac-xanh-den.webp\"]', '[\"Bạc Đỏ Đen\",\"Bạc Xanh Đen\",\"Đen Bạc\",\"Đen Vàng\",\"Đỏ Đen Bạc\",\"Xám Đỏ Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/airblade-125-phien-ban-tieu-chuan-mau-den-bac.webp\",\"price\":43200000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/airblade-125-phien-ban-tieu-chuan-mau-do-den-bac.webp\",\"price\":43200000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Vàng\"}],\"img\":\"/sites/yenthoa/img/2024/11/airblade-125-phien-ban-dac-biet-mau-den-vang.webp\",\"price\":43800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Xanh Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/airblade-125-phien-ban-cao-cap-mau-bac-xanh-den.webp\",\"price\":43800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/airblade-125-phien-ban-cao-cap-mau-bac-do-den.webp\",\"price\":43800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/airblade-125-phien-ban-the-thao-mau-xam-do-den.webp\",\"price\":44800000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"4,4 lít\"},{\"label\":\"Công suất tối đa\",\"value\":\"8,75kW/8500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"0,8 lít khi thay nhớt 0,9 lít khi rã máy\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2,14l/100km\"},{\"label\":\"Loại truyền động\",\"value\":\"Dây đai, biến thiên vô cấp\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"11,3 N.m/6500 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"124,8cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"53,50mm x 55,50mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,5:1\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xi-lanh, làm mát bằng chất lỏng\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Lốp trước 80/90 - Lốp sau 90/90\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"113kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.887mm x 687mm x 1.092mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.286mm\"},{\"label\":\"Độ cao yên\",\"value\":\"775mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"141mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Air blade 125 nổi bật với sự kết hợp hoàn hảo giữa thiết kế sắc sảo và phong cách thể thao đầy cuốn hút. Đây chính là lựa chọn lý tưởng dành cho những người trẻ tuổi, luôn khao khát thể hiện cá tính mạnh mẽ và phong cách riêng biệt.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>XE AIR BLADE 125 CHÍNH HÃNG GIÁ RẺ CỦA HONDA</h2>\n<p>Là một trong những mẫu xe tay ga thể thao tầm trung hàng đầu, <b>Air blade 125</b> nổi bật với sự kết hợp hoàn hảo giữa thiết kế sắc sảo và phong cách thể thao đầy cuốn hút. Đây chính là lựa chọn lý tưởng dành cho những người trẻ tuổi, luôn khao khát thể hiện cá tính mạnh mẽ và phong cách riêng biệt trên mọi chặng đường. Với <b>xe ab 125</b>, mỗi hành trình không chỉ đơn thuần là di chuyển mà còn là cơ hội để khẳng định bản thân và trải nghiệm sự phấn khích không ngừng.</p>\n<p>Dưới đây là những điểm nổi bật của<b> honda ab 125</b> và giá <b>xe ab 125</b> mới nhất hiện nay tại Yên Thoa.</p>\n\n<h2>1. Thiết kế thể thao của dòng xe AB 125</h2>\n<p><em>Kiểu dáng thể thao năng động</em></p>\n<p>Dòng <b>xe air blade 125 </b>không chỉ đơn thuần là một phương tiện di chuyển, mà còn là một tác phẩm nghệ thuật với thiết kế thể thao cao cấp. Lấy cảm hứng từ hình ảnh “tia sét”, chiếc xe mang đến vẻ ngoài ấn tượng với những đường nét sắc sảo và hiện đại. Sự kết hợp hoàn hảo giữa sự cứng cáp và sự mềm mại trong thiết kế đã tạo ra một tổng thể hài hòa, thu hút mọi ánh nhìn. Tem số<b> ab 125</b> mới được thiết kế nổi bật, không chỉ mang lại cảm giác hiện đại mà còn thể hiện sự năng động của người lái.</p>\n\n<p><em>Phiên bản màu sắc đa dạng</em></p>\n<p><b>Air blade 125</b> cung cấp cho người tiêu dùng nhiều lựa chọn màu sắc phong phú, phù hợp với sở thích và phong cách cá nhân. Phiên bản Tiêu chuẩn 125cc có hai màu sắc chủ đạo là Đen Bạc và Đỏ Đen Bạc, tạo nên sự tương phản mạnh mẽ, kích thích thị giác và mang lại hình ảnh của một chiếc xe tay ga thể thao tiêu chuẩn nhưng vẫn nổi bật giữa đám đông.</p>\n<p>Đối với những ai yêu thích sự sang trọng và mạnh mẽ, phiên bản cao cấp của <b>honda ab 125</b> với tông màu Bạc Xanh Đen và Bạc Đỏ Đen sẽ là lựa chọn lý tưởng. Các chi tiết phối màu thời thượng không chỉ làm tăng tính thẩm mỹ mà còn khẳng định đẳng cấp của người sở hữu.</p>\n<p>Phiên bản Đặc biệt của <b>xe ab 125</b> gây ấn tượng mạnh mẽ với sắc màu Đen nhám huyền bí cùng các chi tiết trang trí logo và tên xe màu vàng rực rỡ. Sự kết hợp này tạo ra điểm nhấn độc đáo, góp phần làm nổi bật hình ảnh tổng thể mạnh mẽ và nam tính của chiếc xe.</p>\n<p>Không dừng lại ở đó, phiên bản Thể thao cũng không kém phần hấp dẫn với tông màu xám khỏe khoắn. Những miếng ốp đỏ trên thân xe tạo nên điểm nhấn nổi bật, trong khi yên xe xám đen cùng dải chỉ đỏ làm tăng thêm vẻ đẹp mạnh mẽ và nam tính cho sản phẩm.</p>\n<p><em>Cụm đèn LED hiện đại</em></p>\n<p>Một trong những điểm nhấn đáng chú ý của<b> air blade 125</b> chính là cụm đèn LED hiện đại. Xe được trang bị đèn định vị LED cỡ lớn cùng thiết kế đèn trước mô phỏng cấu trúc từ những mẫu xe phân khối lớn. Điều này không chỉ mang lại ánh sáng tốt hơn cho người lái trong điều kiện thiếu sáng mà còn tạo cảm giác thể thao năng động hơn cho chiếc xe.</p>\n\n<p><b>Xe air blade 125</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn khẳng định phong cách sống năng động của người sử dụng. Đây thực sự là một chiếc xe tay ga lý tưởng cho những ai yêu thích sự trẻ trung, hiện đại nhưng vẫn muốn giữ vững chất riêng của mình trên từng chặng đường.</p>\n<h2>2. Động cơ và tiện ích nổi bật trang bị trên xe Air Blade 125</h2>\n<p><em>Động cơ eSP+ 4 van mạnh mẽ và hiệu quả</em></p>\n<p><b>Xe air blade 125</b> được trang bị động cơ eSP+ với thiết kế 4 van, mang lại hiệu suất vượt trội. Hệ thống động cơ này không chỉ giúp tăng cường công suất mà còn đảm bảo vận hành êm ái, tiết kiệm nhiên liệu và thân thiện với môi trường. Điều này giúp người dùng có những trải nghiệm lái xe thoải mái và bền bỉ hơn.</p>\n\n<p><em>Chế độ đèn chiếu sáng thông minh</em></p>\n<p>Một trong những điểm nổi bật của<b> honda ab 125</b> là chế độ đèn chiếu sáng luôn hoạt động. Tính năng này không chỉ đảm bảo tầm nhìn tốt nhất cho người lái trong điều kiện ánh sáng yếu mà còn nâng cao khả năng hiện diện của xe trên đường phố. Nhờ đó, các phương tiện khác dễ dàng nhận diện và tránh va chạm, góp phần tăng cường an toàn giao thông.</p>\n<p><em>Mặt đồng hồ LCD hiện đại</em></p>\n<p>Mặt đồng hồ LCD kỹ thuật số của <b>xe ab 125</b> được thiết kế tinh tế và hiện đại, giúp hiển thị thông tin một cách rõ ràng và dễ quan sát. Ngoài việc cung cấp thông tin về hành trình, đồng hồ còn hiển thị mức tiêu thụ nhiên liệu tức thời và trung bình, giúp người dùng theo dõi hiệu suất xe trong từng tình huống lái khác nhau.</p>\n\n<p><em>Hệ thống khóa thông minh Smart Key</em></p>\n<p>Với hệ thống khóa thông minh Smart Key, việc khóa/mở xe trở nên đơn giản hơn bao giờ hết. Người dùng có thể thực hiện thao tác từ xa, xác định vị trí xe cũng như kích hoạt chức năng báo động chỉ với một chiếc FOB nhỏ gọn. Điều này không chỉ mang lại sự tiện lợi mà còn gia tăng cảm giác an toàn cho người sử dụng.</p>\n<p><em>Cổng sạc USB tiện lợi</em></p>\n<p><b>Air blade 125 </b>được trang bị cổng sạc USB (Loại A) với nắp chống nước nằm trong hộc đựng đồ dưới yên xe. Với dòng điện đầu ra lên tới 2,1A, việc sạc điện thoại trở nên nhanh chóng và thuận tiện hơn bao giờ hết. Tính năng này nâng cao trải nghiệm của khách hàng khi di chuyển trên mọi nẻo đường.</p>\n<p><em>Hộc đựng đồ rộng rãi và thông minh</em></p>\n<p>Hộc đựng đồ dưới yên xe có dung tích lớn lên tới 23,2 lít, cho phép chứa đến hai mũ bảo hiểm nửa đầu cùng nhiều vật dụng cá nhân khác mà vẫn giữ được thiết kế thon gọn. Đặc biệt, đèn soi hộc đồ giúp người dùng dễ dàng tìm kiếm vật dụng trong điều kiện thiếu ánh sáng. Vách ngăn thông minh bên trong hộc đồ cho phép chia nhỏ không gian thành hai khoang riêng biệt, tăng tính tiện lợi khi sử dụng.</p>\n<h2>3. Giá xe AB 125 tại Hệ thống Siêu Thị Yên Thoa</h2>\n<p>Xe máy <b>air blade 125</b> không chỉ nổi bật với hiệu suất vận hành mạnh mẽ và khả năng tiết kiệm nhiên liệu tối ưu, mà còn được thiết kế với sự chú trọng đặc biệt đến yếu tố an toàn và tiện nghi cho người sử dụng. Đây chính là lý do khiến <b>ab 125 </b>đã trở thành lựa chọn hàng đầu cho những ai đang tìm kiếm một chiếc xe máy hiện đại, năng động và đầy sức mạnh.</p>\n<p>Nếu quý khách đang có nhu cầu tìm hiểu về <b>giá xe ab 125</b>, hãy nhanh chóng liên hệ với Hệ thống Siêu Thị Yên Thoa. Là <a href=\"/xe-may\"><b>đại lý xe máy</b></a> chính thức của bốn thương hiệu xe lớn nhất hiện nay, Yên Thoa cam kết mang đến cho quý khách hàng những sản phẩm chất lượng và dịch vụ tốt nhất.</p>\n\n<p>Khi mua <b>xe air blade 125</b> hoặc tham khảo <b>giá xe ab 125 </b>tại cửa hàng của chúng tôi, quý khách sẽ nhận được nhiều ưu đãi hấp dẫn:</p>\n<p>– Tặng ngay combo quà tặng độc quyền trị giá 2.350.000đ khi hoàn tất giao dịch mua xe.</p>\n<p>– Cơ hội trải nghiệm chạy thử miễn phí các mẫu xe mới hiên nay</p>\n<p>– Hỗ trợ trả góp với lãi suất cực kỳ ưu đãi chỉ với 0%</p>\n<p>– Dịch vụ giao xe tận nhà nhanh chóng và tiện lợi.</p>\n<p>– Cam kết bảo hành chính hãng cho mọi sản phẩm.</p>\n<p>Hiện tại <b>giá xe ab125</b> tại Yên Thoa đang dao động từ 43 đến 45 triệu đồng tuỳ vào từng phiên bản mà giá <b>xe air blade 125</b> sẽ có sự chênh lệch. Để biết thêm thông tin chi tiết hoặc nhận tư vấn <a href=\"/xe-may?nhom=honda\"><strong>mua xe honda</strong></a> quý khách vui lòng liên hệ qua hotline. Chúng tôi luôn sẵn sàng phục vụ quý khách!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
