INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-angela-50cc', 'Xe Angela 50cc', 'sym', '[\"xe-so\"]', 18400000, 18400000, '/sites/yenthoa/img/2024/11/angela-50-cc-mau-xanh-ngoc-trang.webp', '[\"/sites/yenthoa/img/2024/11/angela-50-cc-mau-xanh-ngoc-trang.webp\"]', '[\"Xám Trắng\",\"Xanh ngọc Trắng\",\"Xanh Trắng\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xám Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/angela-50-cc-mau-xanh-xam-trang.webp\",\"price\":18400000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh ngọc Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/angela-50-cc-mau-xanh-ngoc-trang.webp\",\"price\":18400000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/angela-50-cc-mau-xanh-trang.webp\",\"price\":18400000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Động cơ/Làm mát/Truyền động\",\"value\":\"4 thì/ Làm mát bằng không khí/Hộp số 4 số\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"39mmx41.4mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9.7:1\"},{\"label\":\"Phân khối\",\"value\":\"49.5cc\"},{\"label\":\"Mức hao xăng\",\"value\":\"1,26L/100km\"},{\"label\":\"Momen cực đại\",\"value\":\"2,5Nm/6.500rpm\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"3.4L\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"C.D.I\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống thắng trước\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Phanh trống (đùm)\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Vỏ (lốp trước, có ruột)\",\"value\":\"Vỏ (lốp trước, có ruột)\"},{\"label\":\"Phuộc trước\",\"value\":\"Thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài - Rộng - Cao\",\"value\":\"1920mm - 680mm -1070mm\"},{\"label\":\"Khoảng cách 2 trục\",\"value\":\"1230mm\"},{\"label\":\"Khoảng cách gầm\",\"value\":\"125mm\"},{\"label\":\"Tổng trọng lượng khô\",\"value\":\"95kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Lò xo trụ\",\"value\":\"24 tháng hoặc 30.000km\"}]}]', '<p>Sym angela 50cc là mẫu xe máy nổi bật với thiết kế tinh tế và sự lựa chọn màu sắc đa dạng, phù hợp với xu hướng thị trường hiện nay.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>DÒNG XE ANGELA 50CC KHUYẾN MÃI GIÁ RẺ CỦA SYM</h2>\n<p>Dòng xe <b>angela 50cc </b>của hãng SYM đã khẳng định vị thế là một trong những mẫu xe số 50cc hàng đầu trên thị trường hiện nay. Với mức <b>giá xe angela 50</b> hợp lý, khả năng điều khiển dễ dàng và không yêu cầu bằng lái, <b>sym angela 50cc</b> trở thành lựa chọn lý tưởng cho nhiều đối tượng, đặc biệt là học sinh cấp 3 và sinh viên. Hãy cùng Yên Thoa khám phá mẫu <b>xe 50 angela</b> qua bài viết dưới đây.</p>\n<h2>1. Đánh giá chi tiết về thiết kế Angela 50</h2>\n<p><b>Sym angela 50cc</b> là một trong những mẫu xe số nhỏ gọn và hiện đại, được thiết kế đặc biệt dành cho những người chưa có bằng lái. Với quy định chỉ cần đủ 16 tuổi và tuân thủ luật giao thông, chiếc xe này trở thành lựa chọn lý tưởng cho học sinh, sinh viên cũng như người cao tuổi.</p>\n<p><em>Thiết kế độc đáo và thẩm mỹ</em></p>\n<p>Với thiết kế tương tự như Honda Wave Alpha, nhưng <b>sym angela 50cc</b> vẫn mang đến sự mới mẻ và độc đáo riêng. Những đường nét mềm mại, thanh thoát cùng các góc cạnh được bố trí hài hòa tạo nên một tổng thể bắt mắt. Kích thước của <b>xe angela 50</b> được tối ưu hóa cho người Việt Nam với chiều dài 1920mm, chiều rộng 680mm và chiều cao 1070mm, cùng trọng lượng khoảng 95kg. Điều này không chỉ giúp <b>angela 50cc</b> dễ dàng di chuyển trong đô thị mà còn tạo cảm giác thoải mái cho người sử dụng.</p>\n<p><em>Khung sườn chắc chắn</em></p>\n<p>Một điểm nổi bật khác của <b>sym angela 50cc </b>chính là khung sườn vững chắc, giúp tăng cường độ ổn định khi di chuyển trên nhiều loại địa hình khác nhau. Dù bạn đang đi trên đường phố đông đúc hay những con đường nông thôn gập ghềnh, <b>sym angela </b>vẫn đảm bảo mang lại trải nghiệm lái an toàn và thoải mái.</p>\n<p><em>Biểu tượng phong cách cá nhân</em></p>\n<p>Khi sở hữu một chiếc <b>xe 50 angela</b>, bạn không chỉ đơn thuần có được một phương tiện di chuyển tiện lợi mà còn thể hiện phong cách cá nhân đầy cuốn hút. Với thiết kế trẻ trung và năng động, <b>angela 50</b> sẽ là người bạn đồng hành lý tưởng trong mọi hành trình của bạn.</p>\n<p><b>Xe angela 50 </b>không chỉ đáp ứng nhu cầu di chuyển mà còn mang đến sự tự tin và phong cách cho người sử dụng. Đây thực sự là lựa chọn hoàn hảo cho những ai đang tìm kiếm một chiếc xe số nhỏ gọn nhưng đầy tính năng vượt trội.</p>\n<h2>2. Các phiên bản màu sắc của xe Angela&nbsp;</h2>\n<p><b>Sym angela 50cc</b> là mẫu xe máy nổi bật với thiết kế tinh tế và sự lựa chọn màu sắc đa dạng, phù hợp với xu hướng thị trường hiện nay. Phiên bản tiêu chuẩn của dòng xe này được trang bị ba gam màu chủ đạo: xám trắng, xanh trắng và xanh ngọc trắng. Những tông màu này không chỉ mang lại vẻ đẹp sang trọng và lịch lãm mà còn tạo nên sự hài hòa, dễ dàng thu hút ánh nhìn của người tiêu dùng.</p>\n<p>Điểm nhấn đặc biệt của <b>xe angela 50cc</b> nằm ở bộ vành nan hoa được thiết kế tinh xảo. Sự kết hợp giữa các chi tiết kỹ thuật chính xác và thẩm mỹ cao cấp đã tạo ra một sản phẩm không chỉ bền bỉ mà còn có tính thẩm mỹ vượt trội. Điều này giúp chiếc xe trở nên cuốn hút hơn trong mắt những ai đang tìm kiếm một phương tiện di chuyển vừa tiện dụng vừa thời trang.</p>\n<p>Bên cạnh phiên bản tiêu chuẩn, SYM cũng giới thiệu phiên bản sơn mờ với sự kết hợp màu đỏ đen đầy cá tính. Đây là lựa chọn lý tưởng cho những ai yêu thích phong cách mạnh mẽ và nổi bật. Màu sắc này không chỉ thể hiện sự phóng khoáng mà còn phản ánh rõ nét phong cách cá nhân của chủ nhân chiếc xe. Với lớp sơn mờ độc đáo, <b>angela 50cc</b> mang đến cảm giác mới lạ, khác biệt so với các dòng xe thông thường trên thị trường.</p>\n<p><b>Xe 50 Angela</b> không chỉ là một phương tiện di chuyển mà còn là biểu tượng của phong cách sống hiện đại. Với thiết kế đẹp mắt cùng sự đa dạng về màu sắc, chiếc xe này chắc chắn sẽ làm hài lòng cả những khách hàng khó tính nhất.</p>\n<h2>3.Tính năng và ưu điểm nổi bật của xe Angela 50cc</h2>\n<p>Dưới đây là những điểm nổi bật khiến dòng xe <b>sym angela</b> trở thành sự lựa chọn lý tưởng cho người dùng.</p>\n<p><em>Khả năng tiết kiệm nhiên liệu vượt trội</em></p>\n<p>Một trong những ưu điểm đáng chú ý nhất của <b>angela 50cc</b> chính là khả năng tiết kiệm nhiên liệu. Với dung tích bình xăng lên tới 3,4 lít và mức tiêu hao chỉ khoảng 1.8L/100km, người dùng có thể dễ dàng di chuyển lên đến 270km mà không cần lo lắng về việc hết xăng. Điều này không chỉ giúp tiết kiệm chi phí di chuyển mà còn góp phần bảo vệ môi trường.</p>\n<p><em>Động cơ mạnh mẽ, vận hành êm ái</em></p>\n<p><b>Xe angela 50cc</b> được trang bị động cơ tiên tiến với công nghệ mới nhất, mang lại khả năng vận hành mạnh mẽ và ổn định. Hệ thống hộp số 4 cấp kết hợp với động cơ 4 thì làm mát bằng không khí giúp xe khởi động nhẹ nhàng và tăng tốc một cách dễ dàng. Sự kết hợp này đảm bảo rằng người lái sẽ có trải nghiệm lái xe thoải mái và an toàn.</p>\n<p><em>Công nghệ hiện đại và tiện ích đáng kể</em></p>\n<p>Ngoài động cơ mạnh mẽ, <b>angela 50</b> còn được trang bị nhiều công nghệ hiện đại và tiện ích:</p>\n<p>– Mặt đồng hồ analog: Thiết kế mặt đồng hồ mang phong cách cổ điển nhưng vẫn rất tinh tế. Màn hình rõ nét hiển thị các thông số quan trọng như tốc độ, mức nhiên liệu, đèn tín hiệu và đèn báo số, giúp người dùng dễ dàng theo dõi tình trạng xe.</p>\n<p>– Đèn pha sáng rực rỡ: Đèn pha lớn với công suất lên tới 35W cung cấp ánh sáng mạnh mẽ và xa, đảm bảo an toàn khi di chuyển vào ban đêm hoặc trong điều kiện thời tiết xấu.</p>\n<p>– Đèn đuôi an toàn: Đèn đuôi phản xạ nhiều tầng giúp tăng cường khả năng nhận diện từ các phương tiện phía sau, góp phần nâng cao an toàn cho người lái.</p>\n<p>– Cốp đựng đồ rộng rãi: Cốp chứa đồ của<b> angela 50cc</b> có dung tích lớn đủ để chứa một chiếc nón bảo hiểm cùng nhiều vật dụng cá nhân khác. Ngoài ra, hộc chứa đồ phía trước cũng được thiết kế tiện lợi để tối ưu hóa không gian lưu trữ cho người sử dụng.</p>\n<p>Với nhiều tính năng ưu việt đáp ứng nhu cầu di chuyển hàng ngày của người dùng. <b>Sym angela 50cc</b> chắc chắn là lựa chọn hoàn hảo cho những ai đang tìm kiếm một chiếc xe máy vừa tiết kiệm nhiên liệu vừa an toàn và tiện ích.</p>\n<h2>4. Địa điểm mua Angela 50 giá rẻ chất lượng</h2>\n<p>Hệ thống Siêu Thị Yên Thoa tự hào là một trong những địa chỉ uy tín chuyên cung cấp các dòng <a href=\"/xe-may?nhom=sym\"><strong>xe máy sym</strong></a>, đặc biệt là mẫu <b>xe angela 50</b>. Với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh xe máy, chúng tôi cam kết mang đến cho khách hàng những sản phẩm chất lượng cao cùng dịch vụ hậu mãi tận tâm. Tại đây, bạn sẽ tìm thấy đa dạng các phiên bản và <b>giá xe angela 50</b> ưu đãi nhất.</p>\n<p>Hiện tại, <b>giá xe angela 50</b> tại Yên Thoa đang là 18.400.000đ với vô vàn những quà tặng hấp dẫn.&nbsp;</p>\n<p>– Tặng ngay combo quà tặng độc quyền trị giá 2.350.000đ khi <a href=\"/xe-may\"><b>mua xe máy</b></a> ngay hôm nay</p>\n<p>– Hỗ trợ trả góp lãi suất 0%, thủ tục vô cùng đơn giản chỉ cần CCCD</p>\n<p>– Bảo hành xe đầy đủ theo chính sách từ nhà hãng, tặng thêm 18 tháng kiểm tra miễn phí sau khi hết thời hạn bảo hành</p>\n<p>– Dịch vụ giao xe tận nhà vô cùng tiện lợi giúp khách hàng tiết kiệm thời gian&nbsp;</p>\n<p>Quý khách có thể tham khảo <b>giá xe angela 50</b> trực tiếp tại các cửa hàng của Yên Thoa hoặc liên hệ qua hotline để được tư vấn chi tiết về <b>xe 50 angela</b>.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
