INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-cub-50', 'Xe Cub 50', 'xe-50cc', '[\"xe-so\"]', 13900000, 14900000, '/sites/yenthoa/img/2024/11/cub-50.webp', '[\"/sites/yenthoa/img/2024/11/cub-50.webp\"]', '[]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Căm thường Việt Thái\"}],\"img\":\"/sites/yenthoa/img/2024/11/cub-50.webp\",\"price\":13900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Căm đôi Việt Thái\"}],\"img\":\"/sites/yenthoa/img/2024/11/cub-50.webp\",\"price\":14900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Mâm đôi Việt Thái\"}],\"img\":\"/sites/yenthoa/img/2024/11/cub-50.webp\",\"price\":14900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"4.1 lít\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"49.5 cm3\"},{\"label\":\"Loại động cơ\",\"value\":\"Chạy bằng xăng, 4 kỳ, làm mát bằng không khí\"},{\"label\":\"Công suất tối đa\",\"value\":\"6.12kW / 7500 rpm\"},{\"label\":\"Kích cỡ lốp\",\"value\":\"Lốp trước: 70/90-17 38P TUBE Lốp sau: 80/90-17 50P TUBE\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1.60 lít / 100 KM\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Phuộc trước, sau\",\"value\":\"Giảm chấn thuỷ lực\"},{\"label\":\"Vành đúc nhôm\",\"value\":\"Vành trước: 17×1.6 Vành sau: 17×1.85\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước bên ngoài\",\"value\":\"1900x715x1080\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]', '<p>Xe Cub 50 là lựa chọn lý tưởng những ai tìm kiếm một phương tiện tiện lợi. Với kiểu dáng nhỏ gọn, xe Cub 50 không chỉ thu hút sự chú ý của giới trẻ mà còn phù hợp với nhiều đối tượng khác nhau.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE CUB 50 KHUYẾN MÃI MỚI NHẤT HIỆN NAY</h2>\n<p>Thu hút sự chú ý và quan tâm nhờ vào thiết kế cổ điển đẹp mắt, <b>xe cub 50</b> là một trong những phương tiện di chuyển được nhiều người yêu thích, đặc biệt là trong giới học sinh. Nếu bạn đang tìm hiểu về <b>giá xe cub 50</b> cũng như những ưu điểm của mẫu xe này, hãy cùng Yên Thoa khám phá chi tiết trong bài viết dưới đây!&nbsp;</p>\n<h2>1. Khám phá những điểm nổi bật của mẫu xe Cub 50&nbsp;</h2>\n<p><b>Xe cub 50</b> đã trở thành một biểu tượng trong thế giới xe máy nhờ vào thiết kế tinh tế và <b>giá xe cub 50</b> hợp lý. Với kiểu dáng nhỏ gọn, chiếc xe này không chỉ thu hút sự chú ý của giới trẻ mà còn phù hợp với nhiều đối tượng khác nhau, từ học sinh, sinh viên cho đến người cao tuổi. Đặc biệt, một trong những điểm nổi bật khiến <b>cub 50cc </b>được yêu thích là người dùng không cần phải có bằng lái để điều khiển.</p>\n<p><i>Thiết kế đầu xe thanh lịch</i></p>\n<p>Đầu <b>xe cub 50 mới</b> được thiết kế với sự tỉ mỉ và tinh tế. Hệ thống đèn pha và đèn xi nhan được bố trí hài hòa, tạo nên vẻ đẹp hiện đại nhưng vẫn giữ được nét cổ điển đặc trưng của dòng xe cub. Công nghệ chiếu sáng Halogen được áp dụng giúp tăng cường khả năng chiếu sáng xa và rộng hơn, đảm bảo an toàn cho người lái trong mọi điều kiện ánh sáng.</p>\n<p><i>Đồng hồ cơ hiển thị thông số rõ ràng</i></p>\n<p>Một trong những điểm nổi bật không thể bỏ qua của mẫu xe <b>cub 50</b> chính là đồng hồ cơ hiển thị thông số đầy đủ. Bảng đồng hồ cung cấp thông tin chi tiết về vận tốc hiện tại, tổng quãng đường đã đi và lượng xăng còn lại. Điều này giúp người điều khiển dễ dàng theo dõi tình trạng hoạt động của xe, từ đó có những điều chỉnh kịp thời để đảm bảo an toàn.</p>\n<p><i>Hệ thống công tắc tiện lợi</i></p>\n<p><b>Xe cub 50</b> còn được trang bị hệ thống công tắc điều khiển tiện lợi với tay cầm chắc chắn. Tay cầm được làm từ chất liệu cao su mềm mại, giúp chống trơn trượt hiệu quả khi lái xe. Các công tắc tín hiệu rẽ trái – phải cùng còi xe đều được bố trí hợp lý, tạo sự thuận tiện tối đa cho người sử dụng.</p>\n<p><i>Thiết kế yên xe và đuôi xe hoài cổ</i></p>\n<p>Nhà sản xuất đã khéo léo giữ lại nét hoài cổ của chiếc xe<b> cub 50cc</b> qua thiết kế yên và đuôi xe. Mặc dù có sự cải tiến về hình dáng để trở nên thon gọn và đẹp mắt hơn so với các thế hệ trước, nhưng vẫn giữ nguyên phong cách truyền thống mà nhiều người yêu thích. Điều này không chỉ mang lại cảm giác quen thuộc mà còn tạo nên sự kết nối giữa các thế hệ sử dụng.</p>\n<p><i>Hệ thống phanh an toàn</i></p>\n<p>Hệ thống phanh cơ trên cả bánh trước và bánh sau đảm bảo an toàn tối đa cho người lái. Với thiết kế đơn giản nhưng hiệu quả, phanh cơ của<b> xe cub 50</b> giúp kiểm soát tốc độ tốt hơn trên mọi loại địa hình. Bên cạnh đó, hệ thống phuộc nhún hiện đại cũng góp phần mang lại trải nghiệm lái êm ái và thoải mái hơn.</p>\n<p><i>Khả năng vận hành linh hoạt</i></p>\n<p><b>Xe cub 50cc mới</b> không chỉ nổi bật về thiết kế mà còn ghi điểm ở khả năng vận hành linh hoạt trên nhiều loại địa hình khác nhau. Nhờ vào trọng lượng nhẹ cùng động cơ mạnh mẽ nhưng tiết kiệm nhiên liệu, chiếc xe dễ dàng di chuyển trong phố đông đúc hay trên những con đường nông thôn hẹp.</p>\n<p><i>Tính năng tiết kiệm nhiên liệu</i></p>\n<p>Một ưu điểm lớn nữa của mẫu xe <b>cub 50</b> là khả năng tiết kiệm nhiên liệu vượt trội. Với động cơ nhỏ gọn nhưng mạnh mẽ, mẫu <b>xe cub 50 mới </b>tiêu thụ rất ít nhiên liệu so với nhiều dòng xe khác trên thị trường hiện nay. Điều này không chỉ giúp giảm chi phí vận hành mà còn thân thiện với môi trường.</p>\n<p>Mẫu <b>xe Cub 50</b> thực sự là một lựa chọn hoàn hảo cho những ai đang tìm kiếm một phương tiện di chuyển vừa tiện lợi vừa phong cách tại các <b>cửa hàng xe 50cc</b>. Với thiết kế đẹp mắt cùng nhiều tính năng ưu việt như hệ thống đèn Halogen hiện đại, đồng hồ hiển thị thông số rõ ràng và khả năng tiết kiệm nhiên liệu tốt nhất trong phân khúc, chiếc xe này xứng đáng trở thành bạn đồng hành lý tưởng cho mọi lứa tuổi.</p>\n<p>Không chỉ đơn thuần là một phương tiện di chuyển, <b>cub 50cc </b>còn mang đến trải nghiệm thú vị và cảm giác tự do mỗi khi bạn lăn bánh trên đường phố hay khám phá những cung đường mới lạ.</p>\n<h2>2. Khám phá động cơ của xe Cub 50cc</h2>\n<p><b>Xe Cub 50 </b>là lựa chọn lý tưởng những ai tìm kiếm một phương tiện di chuyển an toàn và tiết kiệm. Với động cơ tích 50cc, chiếc xe này không phù hợp với các bạn học sinh, sinh viên mà còn là sự chọn đáng tin cho người cao tuổi. Đặc biệt, việc vận hành xe <b>cub 50cc</b> không yêu cầu bằng lái, giúp các bậc phụ huynh yên tâm khi để con em mình sử dụng.</p>\n<p>Xe<b> cub 50 mới </b>được trang bị hộp số 4 cấp, mang lại trải nghiệm lái mượt mà trên mọi cung đường. Khả năng tiêu thụ nhiên liệu của <b>cub 50cc</b> cũng rất ấn tượng, chỉ khoảng 1,2 lít cho mỗi 100 km. Điều này không chỉ giúp tiết kiệm chi phí xăng dầu mà còn góp phần bảo vệ môi trường.</p>\n<p>Với vận tốc tối đa từ 45 đến 50 km/h, xe <b>cub 50</b> đảm bảo an toàn khi di chuyển trong đô thị đông đúc. Tốc độ này vừa đủ để người dùng cảm thấy thoải mái và tự tin khi điều khiển xe mà không lo lắng về nguy cơ tai nạn giao thông. Nhờ những ưu điểm vượt trội này, mẫu <b>xe cub 50</b> đã trở thành một trong những dòng xe được yêu thích nhất hiện nay.</p>\n<h2>3. Giá xe Cub 50 khuyến mãi giá rẻ tại Yên Thoa&nbsp;</h2>\n<p>Hiện tại, <b>giá xe cub 50</b> được bán tại Yên Thoa rất đa dạng, tuỳ vào từng phiên bản và màu sắc mà giá xe sẽ có sự thay đổi. Quý khách hàng đang có nhu cầu tham khảo giá xe <b>cub 50cc</b> mới nhất, vui lòng liên hệ qua Yên Thoa để được tư vấn miễn phí! Với mức giá chỉ từ 14 triệu, Yên Thoa cam kết mang đến cho khách hàng mức giá cạnh nhất hiện nay cùng với nhiều chương trình khuyến mãi vô cùng hấp dẫn.&nbsp;</p>\n<p>Khi mua xe tại <a href=\"/\"><b>cửa hàng xe máy</b></a> Yên Thoa, quý khách sẽ nhận ngay combo quà tặng độc quyền trị giá 2.350.000đ. Chúng tôi cũng cam kết bảo hành chính hãng cho mọi sản phẩm, mang lại sự yên tâm tuyệt đối cho khách hàng.</p>\n<p>Ngoài ra, Yên Thoa còn hỗ trợ hình thức mua xe trả góp với lãi suất chỉ 0%. Quý khách chỉ cần xuất trình CCCD/CMND mà không cần chứng minh thu nhập. Điều này giúp việc sở hữu chiếc xe mơ ước trở nên dễ dàng hơn bao giờ hết.</p>\n<p>Hãy liên hệ với Yên Thoa qua hotline ngay hôm nay để được hỗ trợ sớm nhất!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
