INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-cub-89', 'Xe Cub 89', 'xe-50cc', '[\"xe-so\"]', 17600000, 17600000, '/sites/yenthoa/img/2024/11/cub-89-1.webp', '[\"/sites/yenthoa/img/2024/11/cub-89-1.webp\"]', '[]', '[]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích xi lanh\",\"value\":\"49,5 cm3\"},{\"label\":\"Động cơ\",\"value\":\"Xăng, 4 kỳ, xy-lanh, làm mát bằng không khí\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"50 km/h\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"3.7 lít\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đề điện (Start) và cần khởi động\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Phanh\",\"value\":\"Phanh cơ/Phanh cơ\"},{\"label\":\"Lốp\",\"value\":\"Có Săm\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thuỷ lực\"},{\"label\":\"Hộp số\",\"value\":\"Cơ Khí , 4 Số Tròn\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.715 mm x 696 mm x 1.052 mm\"},{\"label\":\"Trọng lượng bản thân\",\"value\":\"70kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]', '<p>Xe cub 89 50cc không chỉ gây ấn tượng với động cơ vận hành êm ái và thiết kế bắt mắt, mà còn thu hút người dùng nhờ vào tính năng tiện ích vượt trội.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>DÒNG XE CUB 89 GIÁ RẺ MỚI NHẤT TRÊN THỊ TRƯỜNG</h2>\n<p>Xe máy <b>cub 89</b> là một trong những mẫu xe nổi bật với thiết kế cổ điển đầy cuốn hút, kết hợp cùng các gam màu ấn tượng mang đến vẻ đẹp thời thượng cho người sử dụng. Hãy cùng Hệ thống Siêu Thị Yên Thoa khám phá ngay <b>cub 89 50cc</b> mới nhất hiện nay.</p>\n<h2>1. Giới thiệu thiết kế của xe Cub 89 50cc</h2>\n<p>Xe máy 50cc<b> cub 89</b> được xem là biểu tượng của phong cách sống năng động và cá tính. Với thiết kế ngoại hình nổi bật và đa dạng màu sắc, <b>xe cub 89</b> đã tạo nên một làn sóng mới trong thị trường xe máy. Khác với những mẫu xe cub truyền thống thường mang gam màu trắng đơn điệu, phiên bản này mang đến cho người dùng nhiều lựa chọn màu sắc hấp dẫn như đen, đỏ, xanh, cam và nhiều sắc thái khác. Điều này không chỉ giúp xe <b>cub 89 50cc</b> trở nên nổi bật mà còn thể hiện được gu thẩm mỹ riêng của từng chủ sở hữu.</p>\n<p><i>Kích thước và khung xe được tinh chỉnh</i></p>\n<p>Với kích thước tổng thể 1640mm x 640mm x 1200mm cùng chiều cao yên chỉ khoảng 750mm, <b>cub 89</b> hoàn toàn phù hợp với vóc dáng người Châu Á, đặc biệt là học sinh và sinh viên. Khung <b>xe cub 89</b> được chế tạo từ sắt cao cấp với thiết kế chắc chắn, đảm bảo khả năng vận hành ổn định trên mọi địa hình. Nhờ vào cấu trúc này, <b>cub 89 50cc</b> giảm thiểu rung lắc, mang lại trải nghiệm lái mượt mà và thoải mái cho người sử dụng.</p>\n<p><i>Dàn áo bền bỉ và sang trọng</i></p>\n<p>Dàn áo của <b>cub 89</b> được làm từ nhựa ABS chất lượng cao, kết hợp với lớp sơn tĩnh điện chống phai màu lên đến bảy lớp. Điều này giúp <b>xe cub 89</b> giữ được vẻ đẹp bền lâu theo thời gian. Phiên bản mới còn được trang trí bằng bộ tem nước độc đáo, tạo nên sự khác biệt rõ rệt so với các dòng xe khác trên thị trường.</p>\n<p><i>Thiết kế phần mặt trước cuốn hút</i></p>\n<p>Phần mặt nạ trước của xe <b>cub 89 50cc </b>gây chú ý với đèn pha LED dạng tròn cổ điển kết hợp dải đèn LED demi trợ sáng ở giữa. Viền đèn pha mạ crom sáng bóng không chỉ tăng tính thẩm mỹ mà còn làm nổi bật phần đầu xe. Đặc biệt, hệ thống đèn xi nhan trước được thiết kế liền kề với bóng LED siêu sáng giúp tăng cường khả năng nhận diện trong mọi điều kiện ánh sáng.</p>\n<p><i>Thân xe thon gọn và hiện đại</i></p>\n<p>Thân xe <b>cub 89</b> có thiết kế mượt mà và thon gọn, tạo cảm giác nhẹ nhàng nhưng vẫn rất chắc chắn. Logo xe nổi bật được dập chìm vào lốc máy không chỉ khẳng định thương hiệu mà còn dễ dàng nhận diện sản phẩm chính hãng. Mặc dù hãng chưa trang bị phần baga trên lườn xe <b>cub 89 50cc </b>nhưng người dùng có thể dễ dàng tìm mua phụ kiện bổ sung để gia tăng khả năng chở đồ cũng như bảo vệ cho chiếc xe yêu quý của mình.</p>\n<p>Xe <b>cub 89 50cc</b> không chỉ là một phương tiện di chuyển thông thường mà còn là sự lựa chọn hoàn hảo cho những ai yêu thích sự trẻ trung và hiện đại trong từng chi tiết thiết kế.</p>\n<h2>2. Động cơ mạnh mẽ của Cub 89</h2>\n<p>Xe <b>cub 89 </b>đang thu hút sự chú ý của nhiều người tiêu dùng nhờ vào khả năng vận hành ổn định và độ bền bỉ vượt trội. Được sản xuất trên dây chuyền công nghệ tiên tiến, chiếc xe này không chỉ sở hữu động cơ được tối ưu hóa về công suất mà còn mang lại hiệu suất vận hành mạnh mẽ, giúp người lái dễ dàng di chuyển trên mọi loại địa hình.</p>\n<p><i>Tiết kiệm nhiên liệu tối ưu</i></p>\n<p>Một trong những điểm nổi bật nhất của <b>xe cub 89</b> chính là khả năng tiết kiệm nhiên liệu. Với mức tiêu hao chỉ khoảng 1.65 lít xăng cho mỗi 100 km, xe nằm trong danh sách những mẫu xe số 50cc tiết kiệm nhiên liệu hàng đầu trên thị trường hiện nay. Công nghệ động cơ tiên tiến đã giúp chiếc xe không chỉ hoạt động hiệu quả mà còn giảm thiểu chi phí cho người sử dụng, mang lại lợi ích kinh tế rõ rệt.</p>\n<p><i>Hộp số 4 cấp và động cơ xăng 4 kỳ</i></p>\n<p><b>Cub 89 50cc </b>được trang bị hộp số 4 cấp kết hợp với động cơ xăng 4 kỳ, cho phép người lái điều khiển một cách linh hoạt và chính xác. Tốc độ tối đa đạt khoảng 50-55 km/h, một con số khá ấn tượng, đảm bảo sự mạnh mẽ và ổn định ngay cả khi chở hai người. Điều này khiến <b>xe cub 89</b> trở thành lựa chọn lý tưởng cho cả những chuyến đi dài lẫn việc di chuyển hàng ngày.</p>\n<p><i>Hệ thống phuộc và giảm chấn hiện đại</i></p>\n<p>Hệ thống phuộc của <b>xe cub 89 </b>bao gồm phuộc trước và sau đều được trang bị công nghệ giảm chấn tiên tiến. Hệ thống này giúp giảm thiểu tác động rung chấn từ mặt đất, mang đến sự ổn định và cảm giác thoải mái trong suốt hành trình. Nhờ vào công nghệ này, người lái có thể trải nghiệm sự mượt mà hơn khi di chuyển trên các bề mặt đường khác nhau.</p>\n<p><i>Hệ thống phanh cơ tiên tiến</i></p>\n<p>Vành xe của <b>cub 89</b> được thiết kế với cấu trúc nan hoa chắc chắn, bao gồm tổng cộng 72 căm đan chi tiết. Thiết kế này không chỉ gia tăng độ cứng cáp cho bánh xe mà còn cải thiện khả năng chịu lực. Hệ thống phanh cơ đời mới kết hợp với thiết kế vành xe giúp người lái dễ dàng kiểm soát tốc độ và hạn chế hiện tượng trơn trượt khi phanh gấp, đảm bảo an toàn tối đa trong các tình huống khẩn cấp.</p>\n<h2>3. Tiện ích của xe Cub 89 50cc</h2>\n<p>Xe<b> cub 89 50cc</b> không chỉ gây ấn tượng với động cơ vận hành êm ái và thiết kế bắt mắt, mà còn thu hút người dùng nhờ vào tính năng tiện ích vượt trội. Dưới đây những điểm nổi bật mẫu xe này.</p>\n<p><i>Hệ thống giảm xóc tối ưu</i></p>\n<p>Hệ thống giảm xóc của <b>xe cub 89</b> được thiết kế tinh tế, mang lại sự thoải mái và hiệu suất vận hành tối ưu trên nhiều loại địa hình. Cả phần giảm xóc ở phía trước và phía sau đều được trang bị gạt điều chỉnh, cho phép người dùng tùy chỉnh mức độ giảm xóc phù hợp với trọng tải của xe. Điều này giúp xe <b>cub 89 50cc </b>hoạt động ổn định hơn, giảm thiểu rung lắc và tạo cảm giác dễ chịu cho cả người lái lẫn hành khách trong suốt hành trình.</p>\n<p><i>Hệ thống khởi động tiện lợi</i></p>\n<p><b>Cub 89</b> được trang bị hệ thống khởi động bằng nút đề hiện đại, giúp quá trình khởi động trở nên nhanh chóng và thuận tiện hơn bao giờ hết. Hộp số 4 cấp với thiết kế số tròn cho phép người lái dễ dàng chuyển đổi giữa các số khi di chuyển. Sự chính xác và mượt mà trong việc điều khiển hộp số giúp người lái tự tin hơn trong việc kiểm soát tốc độ và khả năng tăng tốc của xe.</p>\n<p><i>Thiết kế yên xe tách rời độc đáo</i></p>\n<p><b>Xe cub 89</b> được trang bị hai yên tách rời: yên trước bọc đệm da cao cấp mang lại cảm giác sang trọng, trong khi yên sau có miếng baga nhôm dày dạn chắc chắn. Đây là một cải tiến đáng giá so với nhiều dòng xe Cub đời mới hiện nay có phần yên baga sau mỏng manh, dễ bị hư hỏng khi chở đồ.</p>\n<p><i>Hệ thống đèn chiếu sáng hiện đại</i></p>\n<p>Hệ thống đèn pha LED trước và sau được điều khiển thông qua công tắc bên phải của xe, trong khi công tắc bên trái cho phép bật đèn pha/cos một cách dễ dàng. Thiết kế này không chỉ giúp xe <b>cub 89</b> mang lại sự tiện lợi tối đa mà còn đảm bảo an toàn cho người sử dụng trong mọi điều kiện ánh sáng.</p>\n<p><i>Mặt đồng hồ thông minh</i></p>\n<p><b>Cub 89 50cc</b> sở hữu mặt đồng hồ cơ học với các kim chỉ báo rõ ràng và chính xác, bao gồm: báo xăng, tốc độ, hộp số đang chạy cùng đèn xi nhan và đèn pha/cos. Đồng hồ cũng hiển thị quãng đường đã di chuyển, giúp người lái theo dõi tình trạng vận hành của xe một cách dễ dàng và hiệu quả.</p>\n<p>Với những tính năng tiện ích vượt trội cùng thiết kế tinh tế, <b>xe cub 89</b> không chỉ là phương tiện di chuyển mà còn là lựa chọn lý tưởng cho những ai yêu thích sự thoải mái và phong cách.&nbsp;</p>\n<h2>4. Nên mua xe Cub 89 50cc ở đâu?</h2>\n<p>Nếu bạn đang tìm kiếm một địa chỉ uy tín để mua xe máy <b>cub 89 50cc</b>, Hệ thống Siêu Thị Yên Thoa chính là sự lựa chọn hoàn hảo dành cho bạn. Với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh <a href=\"/\"><b>xe máy</b></a>, Yên Thoa cam kết mang đến cho khách hàng những sản phẩm chất lượng và dịch vụ tận tâm nhất.</p>\n<p>Khi đến với Yên Thoa, bạn sẽ được trải nghiệm những ưu đãi hấp dẫn như sau:</p>\n<p>– Giao xe tận nhà: Dịch vụ giao hàng nhanh chóng và tiện lợi, giúp bạn tiết kiệm thời gian.</p>\n<p>– Hỗ trợ trả góp lãi suất thấp: Chỉ cần trả trước từ 10%, bạn đã có thể sở hữu ngay chiếc xe yêu thích mà không lo về tài chính.</p>\n<p>– Quà tặng độc quyền trị giá 2.350.000đ: Nhận ngay combo quà tặng gồm 11 phần quà đặc biệt cùng hàng ngàn chương trình khuyến mãi hấp dẫn khác.</p>\n<p>– Chương trình thu cũ đổi mới: Dễ dàng nâng cấp lên mẫu xe mới mà không gặp khó khăn.</p>\n<p>– Bảo hành chính hãng: Đội ngũ kỹ thuật viên chuyên nghiệp luôn sẵn sàng hỗ trợ và bảo trì cho chiếc xe của bạn.</p>\n<p>Hiện tại, giá xe <strong>cub 89 50cc</strong> tại Xe máy Yên Thoa đang chỉ từ 17.600.000đ</p>\n<p>Nếu bạn có nhu cầu tham khảo giá cả <a href=\"/xe-may?nhom=xe-50cc\"><b>xe 50cc</b></a> hoặc cần thêm thông tin về giá <strong>xe cub 89</strong>, hãy liên hệ ngay với chúng tôi qua các thông tin dưới đây. Đội ngũ nhân viên của Yên Thoa sẽ tư vấn và hỗ trợ bạn một cách nhanh chóng và hiệu quả nhất!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
UPDATE products SET specs = '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích xi lanh\",\"value\":\"49,5 cm3\"},{\"label\":\"Động cơ\",\"value\":\"Xăng, 4 kỳ, xy-lanh, làm mát bằng không khí\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"50 km/h\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"3.7 lít\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đề điện (Start) và cần khởi động\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Phanh\",\"value\":\"Phanh cơ/Phanh cơ\"},{\"label\":\"Lốp\",\"value\":\"Có Săm\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thuỷ lực\"},{\"label\":\"Hộp số\",\"value\":\"Cơ Khí , 4 Số Tròn\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.715 mm x 696 mm x 1.052 mm\"},{\"label\":\"Trọng lượng bản thân\",\"value\":\"70kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]' WHERE slug = 'xe-cub-89' AND specs IS NULL;
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dien-i8', 'Xe điện i8', 'yadea', '[\"xe-dap-dien\"]', 13990000, 13990000, '/sites/yenthoa/img/2024/11/yadea-i8-mau-xanh.webp', '[\"/sites/yenthoa/img/2024/11/yadea-i8-mau-xanh.webp\"]', '[\"Nâu sữa\",\"Trắng sữa\",\"Xanh da trời\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh da trời\"}],\"img\":\"/sites/yenthoa/img/2024/11/yadea-i8-mau-xanh.webp\",\"price\":13990000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng sữa\"}],\"img\":\"/sites/yenthoa/img/2024/11/yadea-i8-mau-trang-sua.webp\",\"price\":13990000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Nâu sữa\"}],\"img\":\"/sites/yenthoa/img/2024/11/yadea-i8-mau-nau-sua.webp\",\"price\":13990000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại động cơ\",\"value\":\"Động cơ điện một chiều không chổi than\"},{\"label\":\"Công suất danh định\",\"value\":\"350W\"},{\"label\":\"Công suất tối đa\",\"value\":\"700W\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"31km/h\"},{\"label\":\"Loại ắc quy\",\"value\":\"Ắc quy Graphene TTFAR\"},{\"label\":\"Dung lượng ắc quy\",\"value\":\"48V22Ah\"},{\"label\":\"Độ dài quãng đường\",\"value\":\"70 km\"},{\"label\":\"Trọng Lượng/ Kích thước PIN/ẮC QUY\",\"value\":\"7kg*4 bình\"},{\"label\":\"Thời gian sạc\",\"value\":\"7-8 tiếng\"},{\"label\":\"Chế độ lái\",\"value\":\"1 chế độ\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại vành\",\"value\":\"MT1.95X8/J10X1.5\"},{\"label\":\"Đường kính vành trước/sau\",\"value\":\"8/10inch\"},{\"label\":\"Hệ thống phanh\",\"value\":\"Tang trống/ Tang trống\"},{\"label\":\"Loại lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Thông số lốp (trước/sau)\",\"value\":\"2.75-8 / 60/100-10\"},{\"label\":\"Hệ thống đèn\",\"value\":\"LED\"},{\"label\":\"Tổ hợp nút bấm\",\"value\":\"Cụm công tắc trái: xi nhan, còi. Cụm công tắc phải: Nút Parking, công tắc đèn.\"},{\"label\":\"Cách khởi động xe\",\"value\":\"Mở khóa bằng thẻ NFC hoặc khóa cơ\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x rộng x cao (mm)\",\"value\":\"1460x665x1010 mm\"},{\"label\":\"Màn hình\",\"value\":\"Màn hình tinh thể lỏng 5.5 inch\"},{\"label\":\"Khoảng sáng xe\",\"value\":\"135 mm\"},{\"label\":\"Chiều cao yên\",\"value\":\"700 mm\"},{\"label\":\"Khối lượng bản thân\",\"value\":\"68 kg\"},{\"label\":\"Khối lượng cho phép chở\",\"value\":\"75 kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"2500km/ 3 tháng (Tùy theo điều kiện nào đến trước)\"}]}]', '<p>Yadea i8 không chỉ đơn giản là một chiếc xe đạp điện thông thường mà còn được tích hợp nhiều công nghệ tiên tiến, mang đến trải nghiệm an toàn, tiện lợi và tiết kiệm cho người dùng.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>XE ĐẠP ĐIỆN YADEA I8 – DÒNG XE GIÁ RẺ DÀNH CHO HỌC SINH</h2>\n<p>Việc lựa chọn một chiếc xe đạp điện nhỏ gọn, bền bỉ và tiết kiệm chi phí đang là xu hướng của nhiều học sinh – sinh viên và cả người đi làm. Trong số rất nhiều thương hiệu hiện nay, <b>Yadea i8</b> được xem là mẫu xe đạp điện giá rẻ bán chạy hàng đầu, vừa mang lại trải nghiệm tuyệt vời vừa đem đến sự tiện lợi và thoải mái cho người dùng. Đây thực sự là một sản phẩm đáng để bạn cân nhắc khi muốn sở hữu một chiếc <b>xe đạp điện Yadea</b> chính hãng, hiện đại và bền bỉ.</p>\n<h2><b>1. Giới thiệu về xe đạp điện Yadea i8</b></h2>\n<p>Yadea là một trong những thương hiệu xe điện hàng đầu thế giới, được thành lập từ năm 2001 tại Giang Tô, Trung Quốc. Hiện nay, trụ sở chính đặt tại Hồng Kông và sản phẩm của Yadea đã có mặt tại hơn 80 quốc gia. Với chiến lược phát triển bền vững, Yadea đã đầu tư mạnh mẽ vào công nghệ xanh, đưa ra thị trường những dòng xe điện vừa thân thiện với môi trường vừa tiết kiệm chi phí cho người tiêu dùng.</p>\n<p>Tính đến nay, <a href=\"/xe-may?nhom=yadea\"><strong>xe điện yadea</strong></a> đã bán ra hàng chục triệu sản phẩm trên toàn cầu. Tại Việt Nam, thương hiệu này nhanh chóng chiếm được lòng tin của khách hàng nhờ giá thành hợp lý, mẫu mã phong phú và độ bền vượt trội.</p>\n<p><strong><em>Yadea i8 – mẫu xe dành cho giới trẻ</em></strong></p>\n<p>Trong số các dòng xe nổi bật, <b>Yadea i8</b> được xem là mẫu xe đạp điện có doanh số cao nhờ thiết kế nhỏ gọn, dễ sử dụng, phù hợp với nhiều lứa tuổi, đặc biệt là học sinh – sinh viên. Xe có kích thước 1450mm x 670mm x 910mm, chiều cao yên 750mm và khoảng sáng gầm 120mm – vừa vặn để điều khiển thoải mái trong môi trường đô thị đông đúc.</p>\n<p>Khung xe được chế tạo chắc chắn, lớp sơn phủ pastel nhẹ nhàng nhưng sang trọng, tạo nên vẻ ngoài tinh tế và hiện đại. Đặc biệt, xe có 6 màu sắc thời trang gồm: trắng, hồng, xanh ngọc, xanh da trời, kem và xám – đáp ứng nhiều phong cách cá tính khác nhau.</p>\n<h2><b>2. Công nghệ và tính năng nổi bật của Yadea i8</b></h2>\n<p><strong>Yadea i8</strong> không chỉ đơn giản là một chiếc xe đạp điện thông thường mà còn được tích hợp nhiều công nghệ tiên tiến, mang đến trải nghiệm an toàn, tiện lợi và tiết kiệm cho người dùng hiện đại.</p>\n<h3><b>2.1 Động cơ mạnh mẽ – vận hành ổn định</b></h3>\n<p><strong>Xe yadea i8</strong> được trang bị động cơ điện công suất 250W, vận tốc tối đa đạt 25 km/h. Đây là mức vận tốc lý tưởng cho học sinh, sinh viên – vừa đảm bảo an toàn, vừa đủ nhanh để di chuyển linh hoạt trong thành phố. Động cơ hoạt động êm ái, không gây tiếng ồn và gần như không cần bảo dưỡng nhiều như xe máy chạy xăng.</p>\n<p>Khả năng leo dốc của xe cũng khá tốt nhờ hệ thống truyền động mượt mà. Điều này giúp người dùng dễ dàng di chuyển qua các tuyến đường nội thành có cầu vượt, dốc ngắn mà không gặp khó khăn.</p>\n<h3><b>2.2 Quãng đường dài – tiết kiệm chi phí</b></h3>\n<p>Một trong những điểm mạnh của <b>xe đạp điện Yadea i8</b> chính là ắc quy Graphene TTFAR 48V độc quyền. Với dung lượng cao, xe có thể đi được 60 – 65 km chỉ sau một lần sạc đầy. Con số này hoàn toàn đáp ứng nhu cầu đi học, đi làm hay đi chơi hằng ngày mà không lo hết điện giữa chừng.</p>\n<p>Thời gian sạc đầy chỉ khoảng 8 – 10 giờ. Người dùng có thể sạc qua đêm, sáng hôm sau đã có một chiếc xe đầy pin sẵn sàng cho hành trình mới. So với việc đổ xăng hàng ngày, Yadea i8 tiết kiệm chi phí đáng kể, chỉ mất khoảng vài nghìn đồng tiền điện cho mỗi lần sạc.</p>\n<h3><b>2.3 Hệ thống chiếu sáng Full LED hiện đại</b></h3>\n<p><strong>Xe đạp điện i8</strong> được trang bị hệ thống đèn LED toàn bộ. Đèn pha LED tròn có kích thước lớn, tầm chiếu sáng xa và rộng, giúp người lái dễ dàng quan sát vào ban đêm. Ngoài ra, xi nhan và đèn hậu LED cũng có độ sáng cao, đảm bảo an toàn khi tham gia giao thông.</p>\n<p>Ưu điểm lớn nhất của hệ thống LED là bền bỉ và tiết kiệm điện, giúp kéo dài tuổi thọ ắc quy và giảm chi phí thay thế.</p>\n<h3><b>2.4 Khóa NFC thông minh – chống trộm hiệu quả</b></h3>\n<p>Một trong những tính năng được nhiều người dùng đánh giá cao trên <strong>xe điện yadea i8</strong> chính là khóa NFC thông minh. Chỉ cần chạm thẻ từ vào màn hình, người dùng có thể mở khóa và khởi động xe dễ dàng. Khi xe ở chế độ tắt, hệ thống sẽ tự động kích hoạt chế độ chống trộm, ngăn chặn việc di chuyển trái phép.</p>\n<p>Bên cạnh đó, xe còn được trang bị cảm biến rung. Nếu có va chạm hoặc tác động lạ, xe sẽ phát ra còi báo động kết hợp khóa cứng bánh xe, mang lại sự an tâm tối đa cho người sử dụng.</p>\n<h3><b>2.5 Đồng hồ điện tử LCD – hiện đại và tiện dụng</b></h3>\n<p>Màn hình LCD trên <strong>xe điện i8</strong> hiển thị đầy đủ các thông tin cần thiết: tốc độ, dung lượng pin, quãng đường đã đi. Thiết kế chống lóa giúp người dùng dễ dàng quan sát ngay cả khi di chuyển dưới ánh nắng gắt.</p>\n<h3><b>2.6 Hệ thống phanh và giảm xóc an toàn</b></h3>\n<p>Xe được trang bị phanh tang trống trước và sau, giúp tăng cường khả năng kiểm soát tốc độ, giảm nguy cơ trượt bánh. Kết hợp cùng giảm xóc thủy lực, xe vận hành êm ái, ít rung lắc ngay cả khi đi qua đoạn đường gồ ghề.</p>\n<h2><b>3. Lý do nên chọn xe đạp điện Yadea i8</b></h2>\n<p>Với những ưu điểm nổi bật về thiết kế, giá thành, an toàn, thời trang và chi phí vận hành, <b>Yadea i8 </b>thực sự là lựa chọn thông minh cho học sinh, sinh viên và những ai cần một phương tiện di chuyển tiện lợi, tiết kiệm, thân thiện với môi trường.</p>\n<h3><b>3.1 Thiết kế nhỏ gọn – dễ sử dụng</b></h3>\n<p><strong>Xe điện i8</strong> được thiết kế với kiểu dáng tinh gọn, khung xe chắc chắn nhưng không quá nặng, rất phù hợp với học sinh, sinh viên hoặc những người mới bắt đầu sử dụng xe điện. Nhờ bán kính vòng quay nhỏ và chiều cao yên hợp lý, xe dễ dàng di chuyển trong những con hẻm chật hẹp hay đường phố đông đúc. Đây cũng là lý do khiến nhiều phụ huynh lựa chọn Yadea i8 làm phương tiện an toàn và thuận tiện cho con em mình đi học hằng ngày.</p>\n<h3><b>3.2 Giá thành hợp lý</b></h3>\n<p>Trong phân khúc xe đạp điện cao cấp, mức giá của Yadea i8 chỉ khoảng hơn <b>13 triệu đồng</b>, được xem là lựa chọn đáng tiền khi so với các dòng xe khác cùng tầm. Với khoản đầu tư này, khách hàng không chỉ sở hữu một chiếc xe bền bỉ, tiết kiệm chi phí sử dụng, mà còn được đảm bảo chất lượng chính hãng từ thương hiệu Yadea – thương hiệu xe điện toàn cầu đã có mặt tại hơn 80 quốc gia.</p>\n<h3><b>3.3 An toàn tối ưu</b></h3>\n<p><strong>Xe yadea i8</strong> được trang bị hệ thống phanh đĩa trước và phanh cơ sau giúp tăng khả năng kiểm soát tốc độ trong mọi tình huống. Giảm xóc đôi hoạt động êm ái, hạn chế rung lắc khi di chuyển trên những cung đường gồ ghề. Đặc biệt, xe còn có hệ thống chống trộm thông minh, khóa điện tử hiện đại giúp người dùng yên tâm khi gửi xe tại trường học, bãi giữ xe công cộng hoặc khu dân cư. Đây là yếu tố được nhiều phụ huynh đánh giá cao khi chọn mua xe điện cho con.</p>\n<h3><b>3.4 Thời trang và cá tính</b></h3>\n<p>Điểm nhấn của <strong>Yadea i8</strong> chính là bộ sưu tập màu sắc đa dạng, với nhiều gam pastel trẻ trung và thanh lịch. Các tông màu như hồng phấn, xanh mint, trắng ngọc trai hay đen nhám không chỉ phù hợp với học sinh – sinh viên mà còn được nhiều bạn trẻ văn phòng ưa chuộng. Thiết kế hiện đại, phối màu tinh tế giúp Yadea i8 trở thành món phụ kiện thể hiện cá tính, gu thẩm mỹ của người sử dụng, chứ không chỉ là phương tiện di chuyển thông thường.</p>\n<h3><b>3.5 Chi phí vận hành thấp – tiết kiệm vượt trội</b></h3>\n<p>Sử dụng <strong>xe đạp điện Yadea i8</strong> đồng nghĩa với việc bạn không còn phải lo lắng về chi phí xăng dầu ngày càng tăng. Mỗi lần sạc đầy chỉ tiêu tốn một lượng điện năng rất nhỏ, tính ra chỉ vài nghìn đồng cho quãng đường hơn 60km. Ngoài ra, xe điện nói chung ít tốn chi phí bảo dưỡng định kỳ hơn xe máy chạy xăng, không cần thay dầu nhớt, lọc gió hay bugi. Đây chính là giải pháp kinh tế dài hạn cho học sinh, sinh viên và phụ huynh muốn tiết kiệm chi phí đi lại hằng ngày.</p>\n<h3><b>3.6 Bền bỉ – dễ bảo trì</b></h3>\n<p>Một ưu điểm khác khiến nhiều người chọn Yadea i8 là khả năng vận hành ổn định và độ bền cao. Khung xe được làm từ thép chịu lực, phủ sơn tĩnh điện chống gỉ, đảm bảo tuổi thọ lâu dài ngay cả khi thường xuyên đi mưa nắng. Hệ thống pin và động cơ chính hãng có độ bền tốt, ít hỏng vặt, đồng thời dễ dàng thay thế hoặc sửa chữa khi cần thiết tại các trung tâm bảo hành của Yên Thoa.</p>\n<h2><b>4. Địa chỉ mua xe đạp điện Yadea i8 chính hãng&nbsp;</b></h2>\n<p>Nếu bạn đang tìm kiếm <a href=\"/xe-may\"><strong>xe điện</strong></a> giá rẻ, chất lượng và chính hãng, Xe máy Yên Thoa là địa chỉ đáng tin cậy hàng đầu. Với nhiều năm kinh nghiệm trong ngành xe máy – xe điện, Yên Thoa luôn mang đến cho khách hàng sản phẩm chính hãng 100%, có giấy tờ đầy đủ và chính sách bảo hành rõ ràng.</p>\n<p>Khi mua <strong>xe điện yadea i8</strong> tại Xe máy Yên Thoa, bạn sẽ được:</p>\n<ul>\n<li>Bảo hành chính hãng lâu dài, cam kết quyền lợi tối đa cho khách hàng.</li>\n<li>Giá bán cạnh tranh, nhiều chương trình khuyến mãi hấp dẫn.</li>\n<li>Hỗ trợ trả góp linh hoạt, chỉ cần CMND/CCCD và bằng lái hoặc hộ khẩu.</li>\n<li>Dịch vụ chăm sóc khách hàng chuyên nghiệp, tư vấn tận tâm.</li>\n<li>Giao xe tận nơi nhanh chóng, tiện lợi.</li>\n</ul>\n<p>Liên hệ ngay với Xe máy Yên Thoa để được tư vấn chi tiết về giá bán, khuyến mãi và các gói trả góp khi mua xe đạp điện. Đây chắc chắn là lựa chọn tuyệt vời cho những ai muốn sở hữu một chiếc xe đạp điện chính hãng, bền bỉ và giá hợp lý.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
