INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dien-neos', 'Xe điện NEO’s', 'xe-dien-yamaha', '[\"xe-may-dien\"]', 36900000, 36900000, '/sites/yenthoa/img/2025/02/xe-neos-mau-xanh.webp', '[\"/sites/yenthoa/img/2025/02/xe-neos-mau-xanh.webp\"]', '[\"Đen\",\"Đen Xám\",\"Đỏ Xám\",\"Hồng Xám\",\"Trắng\",\"Trắng Xám\",\"Xám\",\"Xanh lam\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s 2026\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Xám\"}],\"img\":\"/sites/yenthoa/img/2026/06/neos-2026-den-xam.webp\",\"price\":36900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s 2026\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Xám\"}],\"img\":\"/sites/yenthoa/img/2025/02/xe-neos-mau-xanh.webp\",\"price\":36900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s 2026\"},{\"name\":\"Màu sắc\",\"value\":\"Hồng Xám\"}],\"img\":\"/sites/yenthoa/img/2025/02/xe-neos-mau-xanh.webp\",\"price\":36900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s 2026\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Xám\"}],\"img\":\"/sites/yenthoa/img/2025/02/xe-neos-mau-xanh.webp\",\"price\":36900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s 2026\"},{\"name\":\"Màu sắc\",\"value\":\"Xám\"}],\"img\":\"/sites/yenthoa/img/2026/06/neos-2026-xam.webp\",\"price\":36900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2025/02/xe-neos-mau-den.webp\",\"price\":36900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng\"}],\"img\":\"/sites/yenthoa/img/2025/02/xe-neos-mau-trang.webp\",\"price\":36900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"NEO\'s\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh lam\"}],\"img\":\"/sites/yenthoa/img/2025/02/xe-neos-mau-xanh.webp\",\"price\":36900000}]', '[]', '<p>Xe điện yamaha neo’s là một mẫu xe máy điện nổi bật với thiết kế khung underbone được phát triển đặc biệt, nhằm đáp ứng nhu cầu đa dạng của người dùng trong nhiều tình huống khác nhau.&nbsp;</p>', '<h2>XE ĐIỆN YAMAHA NEO’S GIÁ RẺ MỚI NHẤT THỊ TRƯỜNG</h2>\n<p><b>Yamaha neo</b>, dòng xe điện tiên tiến chinh phục thị trường châu Âu đã chính thức ra mắt tại Việt Nam. Với những tính năng và công nghệ hiện đại, <b>xe điện neos</b> không chỉ là một phương tiện di chuyển mà còn là biểu tượng của sự thân thiện với môi trường. Mẫu xe này hứa hẹn sẽ trở thành lựa chọn hàng đầu cho giới trẻ năng động, thời thượng và hiện đại, những người luôn hướng tới một lối sống xanh cho cộng đồng.</p>\n\n<h2>1. Giới thiệu về thiết kế của xe NEO</h2>\n<p><b>Xe điện yamaha neo’s</b> là một mẫu xe máy điện nổi bật với thiết kế khung underbone được phát triển đặc biệt, nhằm đáp ứng nhu cầu đa dạng của người dùng trong nhiều tình huống khác nhau.&nbsp;</p>\n<p>Với kích thước tổng thể 1.875 x 695 x 1.120 mm và trọng lượng chỉ 98 kg (bao gồm cả pin) và đường kính bánh xe 70 cm, xe được đánh giá là có kiểu dáng nhỏ gọn, dễ dàng phù hợp với mọi đối tượng khách hàng từ thanh niên năng động đến những người lớn tuổi cần một phương tiện di chuyển nhẹ nhàng.</p>\n\n<p>Thiết kế của <b>Yamaha NEO</b> dựa trên triết lý jin-ki kanno – sự hòa quyện giữa con người và phương tiện – lấy cảm hứng từ mẫu concept MotoRoid và phiên bản NEO’s 50 phân khối trước đây. So với các dòng xe máy điện khác trên thị trường, <b>xe neos</b> nổi bật nhờ thiết kế trẻ trung cùng bảng màu trung tính như Đen, Trắng và Xanh. Những gam màu này không chỉ mang lại vẻ ngoài thời thượng mà còn thể hiện phong cách “futuristic”, bắt kịp xu hướng hiện đại của thời đại mới.</p>\n<h2>2. Đánh giá về động cơ và tiện ích của dòng xe NEO’S</h2>\n<p><b>Xe điện neo’s</b> không chỉ nổi bật với thiết kế hiện đại mà còn sở hữu những tính năng vượt trội về hiệu suất và tiện ích sử dụng hàng ngày. Đây thực sự là lựa chọn lý tưởng cho những ai đang tìm kiếm một chiếc xe máy điện chất lượng cao và đáng tin cậy</p>\n<p><em>Động cơ điện hiện đại YIPU 2 độc quyền từ Yamaha</em></p>\n<p>Xe được trang bị động cơ điện thế hệ mới YIPU 2, một thiết kế độc quyền từ Yamaha, mang lại mô-men xoắn cao ở dải vòng tua thấp, giúp di chuyển mượt mà và ổn định. Đặc biệt, động cơ không chổi than này được làm mát bằng không khí và truyền động trực tiếp, hoàn toàn loại bỏ tiếng ồn, mang đến trải nghiệm vận hành êm ái cho người sử dụng.</p>\n\n<p><em>Khả năng vận hành ấn tượng</em></p>\n<p>Với bộ pin dung lượng 23,2 Ah có thể sạc đầy trong vòng 9 tiếng, NEO’s cho phép di chuyển quãng đường lên tới 72km với tốc độ ổn định ở mức 30km/h và trọng lượng người lái là 75kg. Ngoài ra, khách hàng có thể lắp thêm pin phụ để tăng quãng đường vận hành lên đến 144km. Pin có thiết kế tháo rời tiện lợi, cho phép sạc tại nhà hoặc trực tiếp trên xe.</p>\n<p><em>Trải nghiệm lái mượt mà và vững chắc</em></p>\n<p>Nhiều người dùng thường so sánh khả năng vận hành của dòng xe điện này với các dòng xe máy chạy xăng. Thực tế cho thấy, <b>xe điện yamaha neos</b> mang lại cảm giác lái vững vàng trên các tuyến đường nội thành, không thua kém bất kỳ dòng xe tay ga nào khác của Yamaha.</p>\n<p>Hiện xe có hai chế độ lái: chế độ bình thường (STD) và chế độ tiết kiệm pin (ECO). Trong chế độ bình thường, xe có thể đạt tốc độ trên 35km/h. Khi dung lượng pin giảm xuống dưới 20%, chế độ ECO sẽ tự động kích hoạt để giới hạn tốc độ ở mức 30km/h nhằm tiết kiệm năng lượng.</p>\n<p><em>An toàn tối đa khi vận hành</em></p>\n<p>Một điểm nổi bật của <b>xe điện NEO’s</b> là tính năng tự hãm động cơ khi nhả tay ga, giúp ngăn chặn tình trạng trôi xe như một số mẫu xe máy điện khác. Điều này đảm bảo an toàn tối đa cho người sử dụng. Hơn nữa, độ nhạy của tay ga cũng hỗ trợ việc khởi động ngang dốc dễ dàng hơn.</p>\n<p><em>Dung tích cốp rộng rãi</em></p>\n<p>Cốp xe rộng rãi với dung tích lên tới 27 lít là một điểm cộng lớn đối với nhiều khách hàng nữ. Không gian cốp đủ để chứa hai mũ bảo hiểm nửa đầu hoặc một số vật dụng cần thiết khác.</p>\n<p><em>Trang bị hiện đại và tiện ích</em></p>\n<p>Hướng tới nhóm khách hàng trẻ trung và năng động, Yamaha đã trang bị cho <b>xe điện Yamaha NEO’s</b> nhiều tính năng hữu ích như cổng sạc điện thoại tiện lợi, hộc để đồ thông minh và cụm đồng hồ LCD hiện đại. Đặc biệt hơn cả là hệ thống khóa thông minh giúp tự động khởi động hoặc tắt máy trong phạm vi gần.</p>\n<h2>3. Giá xe NEO’s</h2>\n<p>Hiện tại mức <b>giá xe neos</b> tại Yên Thoa đang có ưu đãi vô cùng hấp dẫn. Với mức giá chỉ từ <b>49.241.000đ</b>, dòng xe này đã trở thành một trong những dòng xe điện bán chạy nhất hiện nay.</p>\n<p><em>Lưu ý:</em> Mức giá trên chủ là giá bán lẻ, giá xe có thể thay đổi tuỳ theo từng thời điểm và khu vực. Để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline <strong>0789.619.698</strong> để được tư vấn.</p>\n\n<p>Thiết kế thời thượng, vận hành êm ái, công nghệ tiên tiến và tiện ích thông minh là những điểm nổi bật mà khách hàng đánh giá cao về mẫu <b>xe máy điện neos</b>. Đây là lựa chọn lý tưởng cho giới trẻ, nhân viên văn phòng, học sinh, sinh viên và các bà nội trợ cần di chuyển trong thành phố. Việc lựa chọn <a href=\"/xe-may\"><b>xe điện</b></a> không chỉ đáp ứng nhu cầu di chuyển mà còn góp phần bảo vệ môi trường, hòa nhịp cùng xu hướng sống xanh đang thịnh hành trên toàn cầu.</p>\n<p>Khi mua <a href=\"/xe-may?nhom=xe-dien-yamaha\"><strong>xe diện yamaha</strong></a> tại Yên Thoa, khách hàng có thể hoàn toàn yên tâm với chính sách bảo hành và bảo dưỡng tận tâm. Là đại lý chính hãng của Yamaha, cửa hàng cam kết mang đến sản phẩm chất lượng cao cùng nhiều ưu đãi hấp dẫn. </p>', 1);
