INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dream-50', 'Xe Dream 50', 'xe-50cc', '[\"xe-so\"]', 14700000, 14700000, '/sites/yenthoa/img/2024/11/dream-50.webp', '[\"/sites/yenthoa/img/2024/11/dream-50.webp\"]', '[]', '[]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"3.7L\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xi-lanh, làm mát bằng không khí\"},{\"label\":\"Dung tích xi lanh\",\"value\":\"49.5cm3\"},{\"label\":\"Mức tiêu hao nhiêu liệu\",\"value\":\"1.7L/100km\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ lốp sau\",\"value\":\"2.25-17 - 17 M/C 38P , 2.25-17 - 17 M/C 50P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1.715 mm x 696 mm x 1.052 mm\"},{\"label\":\"Khối lượng bản thân\",\"value\":\"80 Kg\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1215mm\"},{\"label\":\"Độ cao yên\",\"value\":\"Độ cao yên:\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"135mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]', '<p>Được xem là phiên bản trẻ trung và hiện đại của dòng xe Honda Dream huyền thoại, Dream 50cc đã nhanh chóng trở thành tâm điểm chú ý của đông đảo người đam mê xe máy.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>XE DREAM 50CC KHUYẾN MÃI GIÁ RẺ MỚI NHẤT HIỆN NAY</h2>\n<p><b>Dream 50cc</b> là một mẫu xe máy mang đậm dấu ấn của thiết kế dòng xe Dream cổ điển, không chỉ đơn thuần là phương tiện di chuyển mà còn là biểu tượng gắn liền với ký ức của nhiều thế hệ người Việt Nam. Với thiết kế cổ điển, <b>dream 50cc</b> khéo léo kết hợp giữa nét đẹp truyền thống và sự tiện dụng, đáp ứng nhu cầu di chuyển hàng ngày một cách hiệu quả.</p>\n<p>Chiếc xe này đặc biệt phù hợp với đối tượng học sinh, sinh viên và những người chưa có bằng lái mà muốn tham gia giao thông. Hãy cùng Yên Thoa khám phá chi tiết hơn về mẫu <b>xe dream 50 phân khối </b>qua bài viết dưới đây.</p>\n<h2>1. Điểm nổi bật trong của dòng xe cup 50cc</h2>\n<h3>1.1 Thiết kế xe đẹp mắt</h3>\n<p>Được xem là phiên bản trẻ trung và hiện đại của dòng xe Honda Dream huyền thoại, <b>Dream 50cc </b>đã nhanh chóng trở thành tâm điểm chú ý của đông đảo người đam mê xe máy. Sự kết hợp giữa vẻ đẹp cổ điển và những cải tiến hiện đại đã giúp xe <b>dream 50 phân khối</b> không chỉ giữ vững vị thế trong lòng người hâm mộ mà còn mở rộng sức hấp dẫn đến với thế hệ trẻ ngày nay.</p>\n<p>Phần đầu <b>xe dream 50</b> được thiết kế dạng vuông tinh tế, với đường viền trung màu bao xung quanh tạo nên điểm nhấn đặc biệt. Đèn xi nhan và sương mù được bố trí đối xứng ở hai bên, tạo nên sự cân đối và sang trọng. Hệ thống đèn halogen không chỉ mang lại ánh sáng tốt mà còn có vùng chiếu sáng rộng, giúp người lái an toàn khi di chuyển vào buổi tối.</p>\n<p><b>Xe dream 50 phân khối </b>là sự kết hợp tinh tế giữa phong cách cổ điển và hiện đại. Với cụm đèn hậu được trang bị choá đèn trong suốt, việc nhận biết xe từ phía sau trở nên dễ dàng hơn, giúp hạn chế tối đa những tai nạn không mong muốn. Đi kèm với đó là tay nắm phía sau được thiết kế cứng cáp, phù hợp với nhiều mục đích sử dụng khác nhau.</p>\n<p>Đồng hồ analog trên <b>dream 50cc </b>không chỉ đơn giản là một bộ công cụ hiển thị thông số, mà còn là điểm nhấn thể hiện sự quan trọng của chiếc xe. Cùng với cụm công tắc được sắp xếp gọn gàng, người dùng dễ dàng làm quen với xe hơn.</p>\n<p>Kết cấu khung mới và yên xe thiết kế ngồi thoải mái của <b>xe dream 50cc</b> không chỉ mang lại sự êm ái cho người lái mà còn giúp tránh được tình trạng mỏi khi di chuyển xa.</p>\n<p>Với thiết kế cổ điển nhưng vẫn mang tính hiện đại và cá tính,<b> xe dream 50</b> đã chinh phục được lòng của rất nhiều người yêu thích xe máy. Đây chính là lựa chọn hoàn hảo cho những ai muốn sở hữu một chiếc xe mang phong cách riêng biệt.</p>\n<h3>1.2 Tính năng an toàn tuyệt đối</h3>\n<p><b>Dream 50cc</b> là một mẫu xe được trang bị hệ thống phanh cơ ở cả bánh trước và sau, đem lại sự an toàn tuyệt đối cho người sử dụng. Đặc biệt, với đối tượng chủ yếu là học sinh, sinh viên và người trung niên.</p>\n<p>Hệ thống phanh cơ giúp người lái có thể kiểm soát xe một cách dễ dàng và hiệu quả hơn trong mọi tình huống. Đồng thời, việc sử dụng vành căm cùng bánh có kích thước lớn giúp tăng khả năng tiếp xúc với đường, từ đó nâng cao tính ổn định và an toàn khi di chuyển.</p>\n<p>Không chỉ vậy, hệ thống giảm xóc trước và sau của<b> xe dream 50cc</b> cũng được thiết kế để đem lại sự thoải mái khi di chuyển trên mọi loại địa hình. Giảm xóc trước dạng ống lồng cứng cáp giúp cân bằng phần thân trước, trong khi giảm xóc sau có thể tự điều chỉnh chế độ tải theo ý muốn.</p>\n<h3>1.3 Động cơ xe mạnh mẽ</h3>\n<p><b>Dream 50</b> là chiếc xe mang trong mình khả năng vận hàng mạnh mẽ, nhờ vào khối động cơ 4 kỳ, xi-lanh đơn, dung tích 49.5cc. Kết hợp với thiết kế xe gọn nhẹ giúp tối ưu hóa công suất và mô-men xoắn. Dream 50cc có thể đạt vận tốc tối đa 50km/h và tiêu thụ nhiên liệu ở mức 1,30 lít cho 100km đi được.</p>\n<p>Động cơ của <b>dream 50cc</b> không chỉ bền bỉ mà còn tiết kiệm nhiên liệu. Hệ thống xả của xe được trang bị hệ thống giảm thanh hiệu quả, giúp giảm tiếng ồn khi di chuyển và tạo cảm giác êm ái cho người sử dụng.</p>\n<p>Với <b>xe dream 50 phân khối</b>, bạn không chỉ sở hữu một chiếc xe máy tiện lợi và linh hoạt trong việc di chuyển hàng ngày, mà còn là biểu tượng của sức mạnh và hiệu suất cao trong phân khúc xe 50cc</p>\n<h2>2. Mua xe dream 50cc giá tốt chất lượng tại Hệ thống Siêu Thị Yên Thoa</h2>\n<p>Là một trong những dòng xe phổ biến và được ưa chuộng bởi sự tiết kiệm nhiên liệu, thiết kế nhỏ gọn và dễ sử dụng nhất hiện nay, <b>dream 50cc </b>đang có đầy đủ các phiên bản màu sắc tại Hệ thống Siêu Thị Yên Thoa.</p>\n<p>Khi quyết định mua xe máy, việc chọn lựa một địa chỉ uy tín và chất lượng là điều vô cùng quan trọng. Với hơn 20 năm kinh nghiệm trong lĩnh vực kinh doanh xe máy, <a href=\"/xe-may\"><strong>đại lý xe máy</strong></a> Yên Thoa cam kết mang lại sản phẩm có giá tốt nhất và chất lượng nhất cho quý khách khách hàng.</p>\n<p>Tại Yên Thoa, không chỉ có chất lượng sản phẩm được đảm bảo mà còn có những ưu đãi hấp dẫn đặc biệt. Khi mua xe tại <a href=\"/xe-may?nhom=xe-50cc\"><strong>cửa hàng xe 50cc</strong></a> trong hôm nay, quý khách hàng sẽ được nhận ngay combo quà tặng độc quyền trị giá lên đến 2.350.000đ. Đồng thời, được&nbsp; hỗ trợ trả góp với lãi suất cực thấp, trả trước chỉ từ 0đ rước xe về ngay.</p>\n<p>Ngoài ra, Yên Thoa còn có dịch vụ thu xe cũ đổi xe mới, lái thử xe miễn phí và giao xe tận nhà nhằm hỗ trợ và mang lại sự tiện lợi cho khách hàng. Đội ngũ nhân viên tư vấn chuyên nghiệp của Yên Thoa luôn sẵn lòng hỗ trợ bạn 24/7 để giải đáp mọi thắc mắc và mang lại trải nghiệm mua sắm tốt nhất.</p>\n<p>Hãy đến với Yên Thoa ngay hôm nay để sở hữu và tham khảo giá <b>xe dream 50</b> mới nhất</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
