INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-elegant-110', 'Xe Elegant 110', 'sym', '[\"xe-so\"]', 16400000, 16400000, '/sites/yenthoa/img/2024/11/elegant-110-mau-xanh-den.webp', '[\"/sites/yenthoa/img/2024/11/elegant-110-mau-xanh-den.webp\"]', '[\"Đỏ Đen\",\"Xanh đậm Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/elegant-110-mau-do-den.webp\",\"price\":16400000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/elegant-110-mau-xanh-den.webp\",\"price\":16400000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Động cơ/ Làm mát/ Truyền động\",\"value\":\"4 thì/ Làm mát bằng không khí/ Hộp số 4 số\"},{\"label\":\"Hành trình Pit tông\",\"value\":\"55mm\"},{\"label\":\"Nhiên liệu sử dụng\",\"value\":\"Xăng không chì (trên A92)\"},{\"label\":\"Phân khối\",\"value\":\"108 cm3\"},{\"label\":\"Công suất tối đa\",\"value\":\"5.3kW/7500 rpm\"},{\"label\":\"Momen cực đại\",\"value\":\"7,45Nm/ 5000 rpm\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"C.D.I\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống thắng trước\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Hệ thống thắng sau\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Vỏ (lốp trước, có ruột)\",\"value\":\"70/80-17\"},{\"label\":\"Vỏ (lốp sau, có ruột)\",\"value\":\"80/80-17\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài - Rộng - Cao\",\"value\":\"1,920mm - 680mm - 1,060mm\"},{\"label\":\"Khoảng cách 2 trục\",\"value\":\"1,225mm\"},{\"label\":\"Tổng trọng lượng khô\",\"value\":\"95kg\"},{\"label\":\"Đường kính xi lanh\",\"value\":\"50mm\"},{\"label\":\"Mức hao xăng\",\"value\":\"1,85L/100km\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4L\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"24 tháng hoặc 30.000km\"}]}]', '<p>Một trong những điểm nhấn&nbsp; chú ý khác của dòng xe sym elegant 110 chính là ống pô được thiết kế theo phong cách thể thao, mang lại âm thanh mạnh mẽ nhưng vẫn nhẹ nhàng.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE ELEGANT 110 CHÍNH HÃNG GIÁ TỐT CỦA SYM&nbsp;</h2>\n<p>Việc lựa chọn một chiếc xe phù hợp không chỉ dựa vào hiệu suất mà còn phụ thuộc vào thiết kế và tính năng, dòng<b> xe elegant 110cc </b>chính là một minh chứng cho sự kết hợp hoàn hảo giữa phong cách, tiện ích và hiệu năng vượt trội. Dưới đây là những ưu điểm vượt trội của<b> sym elegant 110</b> và giá <b>xe elegant 110</b> mới nhất.</p>\n<h2>1. Thiết kế của xe Elegant 110</h2>\n<p>Với thiết kế hiện đại, <b>sym elegant 110 </b>gây ấn tượng mạnh mẽ ngay từ cái nhìn đầu tiên. Những nét mềm mại, sắc sảo kết hợp với màu sắc đa dạng tạo nên một tổng thể hài hòa, thu hút mọi ánh nhìn và thể hiện rõ nét cá tính của người sử dụng.</p>\n<p>Phần đầu xe và mặt nạ được thiết kế mới mẻ, cùng bộ tem độc đáo với họa tiết tinh xảo, giúp <b>elegant 110cc</b> nổi bật hơn bao giờ hết. Tay nắm sau dạng ngang của yên rời không chỉ mang lại sự tiện lợi mà còn đảm bảo an toàn khi chở hàng hóa. Điều này không chỉ nâng cao tính năng sử dụng mà còn tạo nên vẻ mỹ quan hoàn chỉnh cho chiếc xe.</p>\n<p>Một trong những điểm nhấn đáng chú ý khác của dòng xe <b>sym elegant 110</b> chính là ống pô được thiết kế theo phong cách thể thao, mang lại âm thanh mạnh mẽ nhưng vẫn nhẹ nhàng. Hệ thống giảm xóc sau được bọc kín giúp hạn chế bụi bẩn, đồng thời đảm bảo sự êm ái trong quá trình di chuyển. Với khả năng chịu tải tốt và thích hợp với nhiều loại địa hình khác nhau, <b>xe elegant 110cc</b> thực sự là lựa chọn lý tưởng cho những ai yêu thích khám phá.</p>\n<h2>2. Các phiên bản màu sắc của xe Elegant 110</h2>\n<p><b>Xe elegant 110 </b>là một trong những mẫu xe được yêu thích trên thị trường hiện nay, không chỉ bởi thiết kế tinh tế mà còn bởi sự đa dạng trong màu sắc. Hiện tại, dòng xe này đang có hai phiên bản màu sắc nổi bật: xanh đen và đỏ đen.</p>\n<p>Phiên bản màu xanh đen mang đến vẻ đẹp thanh lịch và hiện đại. Sự kết hợp giữa tông màu xanh dịu dàng và đen mạnh mẽ tạo nên một phong cách trẻ trung, phù hợp với nhiều đối tượng người dùng. Màu sắc này không chỉ giúp <b>elegant 110cc</b> nổi bật giữa phố phường mà còn thể hiện cá tính của người sở hữu. Đặc biệt, lớp sơn bóng bẩy còn giúp chiếc xe luôn giữ được vẻ ngoài mới mẻ, bền bỉ theo thời gian.</p>\n<p>Ngược lại, phiên bản đỏ đen lại toát lên sự năng động và mạnh mẽ. Màu đỏ rực rỡ kết hợp với nền đen huyền bí tạo nên một tổng thể đầy cuốn hút. Đây là lựa chọn lý tưởng cho những ai yêu thích sự nổi bật và muốn khẳng định phong cách riêng của mình trên đường phố. Phiên bản này không chỉ thu hút ánh nhìn mà còn mang đến cảm giác phấn khích cho người lái.</p>\n<p>Cả hai phiên bản đều được thiết kế tỉ mỉ với các chi tiết tinh xảo, đảm bảo không chỉ về mặt thẩm mỹ mà còn về độ bền và an toàn khi sử dụng. Với sự lựa chọn đa dạng về màu sắc,<b> xe elegant 110</b> chắc chắn sẽ đáp ứng được nhu cầu của nhiều khách hàng khác nhau, từ những người yêu thích sự nhẹ nhàng đến những ai tìm kiếm sự nổi bật và cá tính.&nbsp;</p>\n<h2>3. Động cơ của Elegant 110cc</h2>\n<p><b>Elegant 110cc</b> không chỉ nổi bật với thiết kế mà còn được cải tiết về động cơ, mang đến cho người tiêu dùng một sản phẩm hoàn hảo hơn. Động cơ 110 phân khối của xe được trang bị bộ chế hòa khí hiện đại, giúp tối ưu hóa hiệu suất tiêu thụ nhiên liệu. Nhờ vào công nghệ tiên tiến, xe không chỉ tiết kiệm xăng mà còn sở hữu công suất mạnh mẽ, mang lại trải nghiệm lái xe mượt mà và êm ái.</p>\n<p>Một trong những điểm nhấn nổi bật của <b>sym elegant 110</b> là khả năng vận hành nhẹ nhàng và linh hoạt. Người lái sẽ cảm nhận rõ ràng sự khác biệt khi sang số, với cảm giác nhẹ nhàng và chính xác. Điều này không chỉ giúp việc điều khiển trở nên dễ dàng hơn mà còn tạo ra sự thoải mái trong suốt hành trình.</p>\n<p>Đặc biệt, sản phẩm đã được Trung tâm kỹ thuật đo lường chất lượng kiểm định về khả năng tiết kiệm nhiên liệu, khẳng định vị thế của mình trên thị trường. Với tất cả những ưu điểm vượt trội này, <b>xe elegant 110cc</b> chắc chắn sẽ là lựa chọn lý tưởng cho những ai đang tìm kiếm một chiếc xe máy vừa mạnh mẽ vừa tiết kiệm.</p>\n<h2>4. Địa chỉ mua xe elegant 110 chính hãng giá tốt&nbsp;</h2>\n<p>Với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh xe máy, Hệ thống Siêu Thị Yên Thoa tự hào là một trong những địa chỉ uy tín được nhiều khách hàng tin tưởng. Chúng tôi cam kết mang đến cho khách hàng<b> giá xe elegant 110 </b>ưu đãi và sản phẩm chất lượng nhất</p>\n<p>Yên Thoa không chỉ đa dạng về sản phẩm mà còn chú trọng đến dịch vụ chăm sóc khách hàng, với nhiều chương trình khuyến mãi vô cùng hấp dẫn. Khi ghé thăm cửa hàng của chúng tôi, bạn sẽ có cơ hội trải nghiệm và sở hữu <b>giá xe elegant 110 </b>ưu đãi chỉ từ 16 triệu đồng. Chúng tôi luôn sẵn sàng đồng hành cùng bạn trên mọi nẻo đường, mang lại <a href=\"/xe-may\"><strong>giá xe máy</strong></a> tốt nhất thị trường&nbsp;</p>\n<p>Đặc biệt, khi mua <b>xe elegant 110cc</b> tại Yên Thoa ngay hôm nay, quý khách sẽ nhận được những ưu đãi hấp dẫn:</p>\n<p>– Giao xe tận nhà.</p>\n<p>– Hỗ trợ trả góp với lãi suất cực thấp.</p>\n<p>– Trả trước chỉ 10% để rước xe về ngay.</p>\n<p>– Nhận ngay combo quà tặng độc quyền trị giá 2.350.000đ cùng hàng ngàn chương trình khuyến mãi khác.</p>\n<p>– Thu mua xe cũ đổi lấy xe mới.</p>\n<p>– Bảo hành chính hãng cho mọi sản phẩm.</p>\n<p>Mọi chi tiết về xe <b>sym elegant 110</b> hoặc <a href=\"/xe-may?nhom=sym\"><strong>giá xe sym</strong></a>, quý khách xin vui lòng liên hệ qua hotline để được tư vấn chi tiết!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
