INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-elegant-50cc', 'Xe Elegant 50cc', 'sym', '[\"xe-so\"]', 16900000, 17900000, '/sites/yenthoa/img/2024/11/elegant-50-mau-do-den.webp', '[\"/sites/yenthoa/img/2024/11/elegant-50-mau-do-den.webp\"]', '[\"Đỏ Đen\",\"Trắng Đen\",\"Xám Đen\",\"Xanh rêu Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh căm\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/elegant-50-mau-do-den.webp\",\"price\":16900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh căm\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/elegant-50-mau-trang-den.webp\",\"price\":16900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh căm\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh rêu Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/elegant-50-mau-xanh-reu-den.webp\",\"price\":16900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh mâm\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/elegant-50-banh-mam-mau-xam-den.webp\",\"price\":17900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh mâm\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh rêu Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/elegant-50-banh-mam-mau-xanh-reu-den.webp\",\"price\":17900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Đường kính và hành trình piston\",\"value\":\"39mm x 41.4mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9.7:1\"},{\"label\":\"Động cơ/ Làm mát/ Truyền động\",\"value\":\"4 thì/ Làm mát bằng không khí/ Hộp số 4 số\"},{\"label\":\"Phân khối\",\"value\":\"49.5cc\"},{\"label\":\"Công suất tối đa\",\"value\":\"1,7kW/7500 vòng/phút\"},{\"label\":\"Mức hao xăng\",\"value\":\"1,53L/100km\"},{\"label\":\"Momen cực đại\",\"value\":\"2,5Nm/6.000rpm\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4L\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"C.D.I\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống thắng trước\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Hệ thống thắng sau\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Vỏ (lốp trước, có ruột)\",\"value\":\"70/80-17\"},{\"label\":\"Vỏ (lốp sau, có ruột)\",\"value\":\"80/80-17\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài - Rộng - Cao\",\"value\":\"1,920mm - 680mm - 1,060mm\"},{\"label\":\"1,920mm - 680mm - 1,060mm\",\"value\":\"1,225mm\"},{\"label\":\"Tổng trọng lượng khô\",\"value\":\"95kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Bảo hành\",\"value\":\"24 tháng hoặc 30.000km\"}]}]', '<p>Dòng xe sym elegant 50cc không chỉ gây ấn tượng với thiết kế hiện đại và động cơ mạnh mẽ, mà còn nổi bật nhờ hàng loạt tiện ích thông minh, đáp ứng tối đa nhu cầu di chuyển.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE ELEGANT 50CC CỰC RẺ MỚI NHẤT CỦA SYM</h2>\n<p>Được xem là sự lựa chọn hoàn hảo dành cho học sinh, sinh viên và những người chưa có bằng lái, dòng <b>xe elegant 50cc </b>sở hữu hàng loạt những ưu điểm nổi bật như: thiết kế trẻ trung, động cơ mạnh mẽ và khả năng tiết kiệm nhiên liệu. Trong bài viết này, Hệ thống Siêu Thị Yên Thoa sẽ giới thiệu cho bạn chi tiết về dòng xe <b>sym elegant 50cc</b> và <b>giá xe elegant 50</b> mới nhất trên thị trường.</p>\n<h2>1. Thiết kế của xe máy Elegant 50cc</h2>\n<p>Với kích thước nhỏ gọn,<b> elegant 50</b> dễ dàng di chuyển trong các khu đô thị đông đúc mà vẫn đảm bảo sự thoải mái tối đa cho người sử dụng. Dưới đây là những điểm nổi bật trong thiết kế của <b>xe elegant 50cc</b></p>\n<p><em>Kích thước và trọng lượng</em></p>\n<p>Xe <b>sym elegant 50cc</b> có chiều dài tổng thể 1.920mm, chiều rộng 680mm và chiều cao 1.060mm. Với trọng lượng chỉ 95 kg, việc điều khiển xe trở nên nhẹ nhàng và linh hoạt hơn bao giờ hết.</p>\n<p><em>Thiết kế phần đầu xe</em></p>\n<p>Phần đầu <b>xe elegant 50</b> nổi bật với cụm đèn pha halogen phản xạ đa chiều, cung cấp khả năng chiếu sáng vượt trội hơn 20% so với các dòng xe số thông thường. Đèn xi nhan được tích hợp liền mạch với đèn pha, tạo nên một tổng thể hài hòa và hiện đại.</p>\n<p><em>Thiết kế phần thân xe</em></p>\n<p>Thân xe được thiết kế với các đường gân dập nổi tinh tế, không chỉ tạo điểm nhấn mà còn tăng thêm sự năng động cho tổng thể thiết kế. Yên xe rộng rãi được bọc da nhân tạo cao cấp, mang lại cảm giác thoải mái cho người ngồi trong suốt hành trình.</p>\n<p><em>Thiết kế phần đuôi xe</em></p>\n<p>Phần đuôi xe thon gọn với cụm đèn hậu dạng LED tích hợp đèn xi nhan, giúp tăng cường khả năng cảnh báo khi di chuyển trên đường. Ngoài ra, <b>xe elegant 50cc</b> còn được trang bị giá để đồ sau tiện lợi, giúp người dùng dễ dàng mang theo các vật dụng cần thiết.</p>\n<p>Với thiết kế hiện đại và trẻ trung, <b>sym elegant 50cc</b> chắc chắn sẽ là lựa chọn lý tưởng cho những ai đang tìm kiếm một chiếc xe nhỏ gọn nhưng đầy phong cách và tiện ích.</p>\n<h2>2. Tiện ích vượt trội của SYM Elegant 50cc</h2>\n<p>Dòng xe <b>sym elegant 50cc</b> không chỉ gây ấn tượng với thiết kế hiện đại và động cơ mạnh mẽ, mà còn nổi bật nhờ hàng loạt tiện ích thông minh, đáp ứng tối đa nhu cầu di chuyển của người dùng trong cuộc sống hàng ngày.</p>\n<p><em>Yên xe rộng rãi và thoải mái</em></p>\n<p>Với thiết kế yên xe rộng rãi và êm ái, <b>xe máy elegant 50cc</b> mang đến trải nghiệm lái xe thoải mái ngay cả trong những chuyến đi dài. Đây là yếu tố quan trọng đối với những người thường xuyên phải di chuyển xa hoặc sử dụng xe liên tục trong nhiều giờ.</p>\n<p><em>Hệ thống khóa an toàn tiên tiến</em></p>\n<p>Xe được trang bị hệ thống khóa hiện đại, đảm bảo an toàn cho cả phương tiện và đồ đạc bên trong. Tính năng này giúp người dùng hoàn toàn yên tâm khi để xe ở những khu vực công cộng.</p>\n<p><em>Hệ thống chiếu sáng cải tiến</em></p>\n<p>Hệ thống đèn pha halogen kết hợp với đèn hậu LED không chỉ tăng cường khả năng chiếu sáng mà còn nâng cao độ an toàn khi di chuyển vào ban đêm. Ánh sáng mạnh mẽ và rõ ràng giúp người lái dễ dàng quan sát đường đi cũng như các chướng ngại vật xung quanh.</p>\n<p><em>Cốp xe dưới yên rộng rãi</em></p>\n<p><b>Elegant 50cc</b> được trang bị cốp chứa đồ rộng rãi dưới yên xe, tạo điều kiện thuận lợi cho việc mang theo các vật dụng cá nhân khi di chuyển. Tính năng này đặc biệt hữu ích cho những ai cần mang theo nhiều đồ đạc nhưng không muốn sử dụng ba lô hay túi xách lớn.</p>\n<p>Với những tiện ích vượt trội như vậy, dòng xe <b>sym elegant 50cc</b> thực sự là lựa chọn lý tưởng cho những ai tìm kiếm một phương tiện di chuyển linh hoạt, an toàn và tiện lợi trong cuộc sống hàng ngày.</p>\n<h2>3. Động cơ của xe Elegant 50</h2>\n<p>Không chỉ nổi bật với thiết kế hiện đại trẻ trung, <b>elegant 50</b> còn được trang bị khối động cơ 50cc, 4 thì kết hợp với xi-lanh đơn, mang lại sự cân bằng hoàn hảo giữa hiệu suất vận hành và khả năng tiết kiệm nhiên liệu cho xe.</p>\n<p>Hệ thống làm mát hiện đại</p>\n<p>Động cơ của <b>elegant 50cc</b> được trang bị hệ thống làm mát bằng không khí tiên tiến. Điều này không chỉ giúp duy trì nhiệt độ hoạt động ổn định mà còn kéo dài tuổi thọ cho động cơ. Hệ thống làm mát hiệu quả đảm bảo rằng xe luôn vận hành trong điều kiện tốt nhất, ngay cả khi di chuyển dưới thời tiết nóng bức.</p>\n<p>Hiệu suất mạnh mẽ và tiêu hao nhiên liệu tối ưu</p>\n<p>Một trong những ưu điểm nổi bật của dòng xe <b>sym elegant 50cc</b> chính là khả năng tiêu hao nhiên liệu cực kỳ thấp. Với dung tích xi-lanh nhỏ gọn kết hợp cùng công nghệ tiên tiến về tiết kiệm nhiên liệu, chiếc xe này giúp người dùng giảm thiểu chi phí vận hành hàng ngày một cách đáng kể. Đây thực sự là lựa chọn lý tưởng cho những ai cần một phương tiện di chuyển kinh tế nhưng vẫn đảm bảo hiệu suất cao.</p>\n<p>Việc sở hữu một chiếc <b>xe elegant 50</b> không chỉ mang đến sự tiện lợi và linh hoạt trong việc di chuyển mà còn giúp người dùng tiết kiệm chi phí nhờ vào khả năng tiêu hao nhiên liệu thấp cùng hệ thống làm mát hiệu quả. Đây chắc chắn là một khoản đầu tư xứng đáng cho bất kỳ ai đang tìm kiếm một chiếc xe máy 50cc nhỏ gọn nhưng mạnh mẽ và bền bỉ.</p>\n<h2>4. Cập nhật giá xe Elegant 50 tại Hệ thống Siêu Thị Yên Thoa&nbsp;</h2>\n<p>Khi quyết định mua <a href=\"/xe-may\"><b>xe máy</b></a>, việc lựa chọn một đại lý uy tín và chất lượng là yếu tố quan trọng hàng đầu để đảm bảo sự hài lòng và an tâm cho khách hàng. Đặc biệt, đối với những ai đang tìm kiếm các dòng xe của thương hiệu SYM, việc chọn đúng đại lý phân phối chính hãng không chỉ giúp bạn sở hữu sản phẩm chất lượng cao mà còn được hưởng các chính sách bảo hành đáng tin cậy.</p>\n<p>Hệ thống Siêu Thị Yên Thoa tự hào là đại lý chính hãng của SYM với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh xe máy. Chúng tôi cam kết mang đến cho khách hàng <a href=\"/xe-may?nhom=sym\"><b>giá xe sym</b></a> với những ưu đãi tốt nhất trên thị trường.</p>\n<p>Hiện nay, dòng <b>xe elegant 50cc</b> đang được phân phối tại Yên Thoa với mức <b>giá xe elegant 50</b> cực kỳ hấp dẫn, chỉ từ 18 triệu đồng. Đây là cơ hội tuyệt vời để bạn sở hữu một chiếc xe chất lượng với <b>giá xe elegant 50</b> phải chăng. Hãy đến ngay Hệ thống Siêu Thị Yên Thoa để trải nghiệm và lựa chọn cho mình chiếc xe phù hợp nhất! Mọi chi tiết về dòng xe <b>sym elegant 50cc</b> quý khách vui lòng liên hệ qua hotline để được tư vấn miễn phí.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
