INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-exciter-150', 'Xe Exciter 150', 'yamaha', '[\"xe-tay-con\"]', 45950000, 45950000, '/sites/yenthoa/img/2024/11/exciter-150-mau-xam-den.webp', '[\"/sites/yenthoa/img/2024/11/exciter-150-mau-xam-den.webp\"]', '[\"Trắng Đen\",\"Xám ánh xanh Đen\",\"Xám Đen\",\"Xanh đậm Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-150-mau-trang-den.webp\",\"price\":45950000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xám ánh xanh Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-150-mau-xam-anh-xanh-den.webp\",\"price\":45950000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-150-mau-xam-den.webp\",\"price\":45950000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-150-mau-xanh-den.webp\",\"price\":45950000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"4 thì, 4 van, SOHC, làm mát bằng dung dịch\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"149.8\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"57.0 x 58.7 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"10.4:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"11,3 kW (15,4 PS) / 8.500 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"13,8 N·m (1,4 kgf·m) / 7.000 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Các te ướt\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"1,15 lít\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,2 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"2 l/100km\"},{\"label\":\"Bộ chế hòa khí\",\"value\":\"Phun xăng (1 vòi phun)\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"T.C.I (kỹ thuật số)\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"3,042 (73/24) / 3,000 (42/14)\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Đa đĩa loại ướt\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"1: 2.833 / 2: 1.875 / 3: 1.429 / 4: 1.143 / 5: 0.957\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"5 số\"},{\"label\":\"Két làm mát\",\"value\":\"107mm x 185mm (Diện tích 19,795 mm2)\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Ống thép – cấu trúc kim cương\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Ống lồng\"},{\"label\":\"Hành trình phuộc trước\",\"value\":\"100 mm\"},{\"label\":\"Độ lệch phương trục lái\",\"value\":\"25,8°/87mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Giảm chấn thủy lực lò xo trụ\"},{\"label\":\"Hành trình giảm xóc sau\",\"value\":\"32 mm\"},{\"label\":\"Phanh trước\",\"value\":\"Đĩa thủy lực (đường kính 245 mm)\"},{\"label\":\"Phanh sau\",\"value\":\"Đĩa thủy lực (đường kính 203 mm)\"},{\"label\":\"Lốp trước\",\"value\":\"90/80-17M/C 46P (lốp không săm)\"},{\"label\":\"Lốp sau\",\"value\":\"120/70-17M/C 58P (lốp không săm)\"},{\"label\":\"Đèn trước/đèn sau\",\"value\":\"Bóng đèn LED 12V 10W x2\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1,985 mm × 670 mm × 1,100 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"795 mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"155mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1,290 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"117 kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Với sự chăm chút tỉ mỉ và cải tiến vượt bậc, Yamaha exciter 150 không chỉ là “con cưng” mà còn là biểu tượng của sự đổi mới trong thiết kế và công nghệ. Hãy cùng Yên Thoa khám phá mẫu xe exciter 150 và giá xe exciter 150 chính hãng của yamaha qua bài viết dưới đây.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE EXCITER 150 CỦA YAMAHA MỚI NHẤT HÔM NAY</h2>\n<p>Tiếp nối những thành công vang dội của dòng <b>ex 150</b> trên thị trường xe côn tay underbone tại Việt Nam, Yamaha đã không ngừng đầu tư và phát triển mẫu xe <b>Exciter 150</b>, biến nó thành một trong những sản phẩm chủ lực của hãng. Với sự chăm chút tỉ mỉ và cải tiến vượt bậc,<b> Yamaha exciter 150 </b>không chỉ là “con cưng” mà còn là biểu tượng của sự đổi mới trong thiết kế và công nghệ. Hãy cùng Yên Thoa khám phá mẫu <b>xe exciter 150 </b>và <b>giá xe exciter 150</b> chính hãng của yamaha qua bài viết dưới đây.</p>\n\n<h2>1. Giới thiệu về thiết kế của xe exciter 150 chính hãng của yamaha</h2>\n<p><b>Xe exciter 150</b> từ lâu đã trở thành biểu tượng trong phân khúc xe thể thao cỡ nhỏ. Với những đường nét góc cạnh sắc sảo, mẫu xe này không chỉ thu hút ánh nhìn mà còn thể hiện sự nam tính và phong cách thể thao đặc trưng. Bộ sưu tập màu sắc của <b>Exciter 150</b> đã gây ấn tượng mạnh mẽ với sự kết hợp hài hòa giữa các gam màu thời thượng.</p>\n\n<p>Phiên bản mới nhất của <b>yamaha exciter 150</b> đã chính thức ra mắt, mang đến cho người tiêu dùng một trải nghiệm hoàn toàn mới với nhiều cải tiến nổi bật. Dưới đây là những điểm nhấn đáng chú ý của mẫu xe này.</p>\n<p><em>Cụm đèn pha độc đáo:</em> Được thiết kế như đôi mắt sắc lẹm của một mãnh thú, cụm đèn pha không chỉ mang lại vẻ đẹp mạnh mẽ mà còn sử dụng công nghệ LED tiên tiến. Điều này giúp tăng cường khả năng chiếu sáng trong điều kiện thiếu ánh sáng hoặc khi di chuyển vào ban đêm. Đặc biệt, vị trí cao của cụm đèn giúp người lái dễ dàng quan sát và điều khiển xe trong những khúc cua gấp.</p>\n<p><em>Tư thế ngồi thoải mái:</em> Với chiều cao yên lý tưởng đạt 795mm, tư thế ngồi trên <b>Exciter 150</b> vừa thể thao vừa thoải mái. Điều này không chỉ mang lại cảm giác dễ chịu cho người lái mà còn tăng tính linh hoạt khi di chuyển trong đô thị cũng như trên những chặng đường dài.</p>\n\n<p><em>Lốp xe cải tiến:</em> Lốp trước có kích thước 90/80-17 giúp cải thiện độ bám đường và tạo sự cân bằng cho tổng thể xe. Lốp sau lớn hơn với thông số 120/70-17 mang đến cảm giác vững chãi hơn, tương tự như các mẫu xe phân khối lớn.</p>\n<p><em>Thiết kế phần đuôi thể thao:</em> Phần đuôi xe được thiết kế vuốt nhọn đầy cuốn hút. Cụm đèn hậu với các góc vát tinh tế tạo nên vẻ đẹp sang trọng và hiện đại cho chiếc xe.</p>\n<p><b>Ex 150</b> không chỉ nổi bật với thiết kế mạnh mẽ và hiện đại mà còn được trang bị nhiều tính năng ưu việt. Mẫu xe này hứa hẹn sẽ mang đến trải nghiệm tuyệt vời cho người sử dụng. Đặc biệt, <b>giá xe exciter 150</b> tại Yên Thoa đang đi kèm nhiều ưu đãi hấp dẫn, là cơ hội tuyệt vời để sở hữu một chiếc xe chất lượng cao.</p>\n<h2>2. Giới thiệu về động cơ của xe exciter 150</h2>\n<p>Được trang bị động cơ SOHC xi-lanh đơn dung tích 150cc, dòng <b>xe exciter 150</b> không chỉ mạnh mẽ mà còn sở hữu hiệu suất vượt trội, với công suất tối đa đạt 15,1 mã lực tại 8.500 vòng/phút và mô-men xoắn cực đại lên tới 13,8Nm tại 7.000 vòng/phút. Nhờ vào những thông số kỹ thuật này, <b>exciter 150</b> có khả năng bứt tốc nhanh chóng và duy trì sự ổn định khi vận hành ở tốc độ cao.</p>\n<p>Ngoài ra, xe <b>ex 150</b> còn được trang bị tay côn và hộp số tròn 5 cấp, giúp người lái dễ dàng điều chỉnh theo nhu cầu cá nhân để tối ưu hóa hiệu suất vận hành. Sự linh hoạt này không chỉ mang lại cảm giác thoải mái mà còn nâng cao trải nghiệm lái cho người sử dụng.</p>\n\n<p>Về cấu trúc thiết kế, các chi tiết khung xe, hệ thống treo và phanh của <b>Exciter 150</b> đều được chế tạo tỉ mỉ để đáp ứng tốt nhu cầu di chuyển ở tốc độ cao. Trong khi nhiều mẫu xe tay côn thông thường chỉ có thể đạt tốc độ giới hạn từ 60 – 70 km/h thì exciter 150, một mẫu xe tay côn hiệu suất cao cho phép người lái tự tin kiểm soát ở tốc độ từ 80 – 100 km/h mà vẫn đảm bảo an toàn.</p>\n<p>Với những cải tiến đáng kể về động cơ và thiết kế tinh tế, <b>yamaha exciter 150</b> không chỉ mang đến trải nghiệm lái thú vị mà còn cam kết sự an toàn và ổn định cho người sử dụng ngay cả trong những chuyến đi dài hoặc khi di chuyển ở tốc độ cao. Đây thực sự là một lựa chọn lý tưởng cho những ai yêu thích sự mạnh mẽ và phong cách trong từng chuyến hành trình.</p>\n<h2>3. Giới thiệu về tính năng của xe yamaha exciter 150</h2>\n<p><b>Xe exciter 150</b> không chỉ thu hút người dùng bởi thiết kế thể thao mạnh mẽ, mà còn ghi điểm với những trang bị và công nghệ hiện đại. Một trong những tính năng nổi bật nhất là chìa khóa định vị “Answer Back Key”, giúp người dùng dễ dàng tìm kiếm xe trong phạm vi lên tới 20 mét. Tính năng này thực sự hữu ích, đặc biệt khi bạn phải tìm xe trong những bãi đỗ lớn, tiết kiệm thời gian và công sức một cách hiệu quả.</p>\n<p>Mặt đồng hồ của <b>exciter 150</b> cũng đã được nâng cấp đáng kể từ kiểu analog truyền thống sang đồng hồ điện tử toàn phần với màn hình LCD sắc nét. Màn hình này cung cấp thông tin rõ ràng và trực quan về các thông số quan trọng như tốc độ, mức tiêu hao nhiên liệu, quãng đường đã đi và nhiều thông tin khác, giúp người lái dễ dàng theo dõi tình trạng xe.</p>\n\n<p>Về mặt an toàn, phiên bản mới của <b>yamaha exciter 150</b> được trang bị hệ thống phanh đĩa trước và sau với kích thước lần lượt là 245mm và 203mm. Hệ thống phuộc trước dạng ống lồng mới cùng giảm xóc sau lò xo không chỉ tăng cường khả năng hấp thụ xung động mà còn mang lại trải nghiệm lái mượt mà và an toàn hơn cho người sử dụng.</p>\n<p><b>Exciter 150</b> không chỉ gây ấn tượng bởi vẻ ngoài thể thao cuốn hút mà còn chinh phục người dùng nhờ những cải tiến vượt trội về công nghệ và an toàn. Chính vì vậy, chủ đề về <b>giá xe exciter 150</b> luôn thu hút sự quan tâm từ đông đảo khách hàng. Xe không chỉ là phương tiện di chuyển mà còn là biểu tượng phong cách sống năng động của giới trẻ hiện đại.</p>\n<h2>4. Cập nhật giá xe exciter 150 mới nhất tại Hệ thống Siêu Thị Yên Thoa&nbsp;</h2>\n<p>Hệ thống Siêu Thị Yên Thoa tự hào là một trong những đại lý chính hãng uy tín hàng đầu chuyên phân phối các thương hiệu xe nổi tiếng như Honda, Yamaha, Sym, Suzuki và xe điện Yadea,…</p>\n<p>Chúng tôi cam kết mang đến cho quý khách hàng những sản phẩm chất lượng cao với mức <strong><a href=\"/xe-may?nhom=yamaha\">giá xe yamaha</a></strong> hợp lý nhất. Sự an tâm của khách hàng khi mua sắm tại cửa hàng luôn là ưu tiên hàng đầu của Yên Thoa.</p>\n<p>Hiện tại, <strong>giá xe exciter 150</strong> đang được bán tại Yên Thoa với ưu đãi vô cùng hấp dẫn, chỉ từ: 45.950.000đ</p>\n\n<p>Đặc biệt, khi quý khách đăng ký <strong>mua xe máy</strong> tại Yên Thoa ngay hôm nay, quý khách sẽ được nhận ngay Combo quà tặng độc quyền trị giá 2.950.000đ. Chúng tôi cũng hỗ trợ hình thức trả góp với lãi suất cực thấp và dịch vụ giao xe tận nhà nhanh chóng. Đừng ngần ngại liên hệ ngay qua hotline hoặc ghé thăm cửa hàng để được tư vấn chi tiết về<b> giá xe exciter 150</b> chính hãng mới nhất hôm nay.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
