 giữa 2 trục bánh xe\",\"value\":\"1.295 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"121 kg\"},{\"label\":\"Khoảng sáng gầm xe tối thiểu\",\"value\":\"150 mm\"},{\"label\":\"Tải trọng lớn nhất (kg)\",\"value\":\"150 kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30,000km (tuỳ điều kiện nào đến trước)\"}]}]' WHERE slug = 'xe-exciter-155-vva-tcs' AND specs IS NULL;
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-exciter-155-vva', 'Xe Exciter 155VVA', 'yamaha', '[\"xe-tay-con\"]', 55500000, 60000000, '/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-cao-cap-mau-nau-den.webp', '[\"/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-cao-cap-mau-nau-den.webp\"]', '[\"Đen\",\"Đen Nâu\",\"Đen Xám\",\"Đỏ\",\"Đỏ Xám\",\"Trắng Đen\",\"Trắng Xám Đen\",\"Vàng Xám\",\"Xám Bạc Đen\",\"Xám Xanh lá\",\"Xanh Bạc Đen\",\"Xanh đậm\",\"Xanh Đen\",\"Xanh lam\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Giới hạn ABS GP\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-gioi-han-abs-monster.webp\",\"price\":60000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Monster ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-gioi-han-abs-monster.webp\",\"price\":56500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Xanh lá\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-cao-cap-abs-mau-xam-xanh.webp\",\"price\":60000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-cao-cap-abs-mau-trang-den.webp\",\"price\":60000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-cao-cap-abs-mau-den.webp\",\"price\":60000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh lam\"}],\"img\":\"/sites/yenthoa/img/2024/11/exciter-155vva-phien-ban-cao-cap-abs-mau-xanh.webp\",\"price\":60000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu