INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-galaxy-50cc', 'Xe Galaxy 50cc', 'sym', '[\"xe-so\"]', 17900000, 18900000, '/sites/yenthoa/img/2024/11/galaxy-50-banh-mam-mau-xanh-den.webp', '[\"/sites/yenthoa/img/2024/11/galaxy-50-banh-mam-mau-xanh-den.webp\"]', '[\"Đen Đỏ\",\"Đỏ Đen\",\"Xám Đen\",\"Xanh dương Đen\",\"Xanh đậm Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh căm\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/galaxy-50-mau-xam-den.webp\",\"price\":17900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh mâm\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/yenthoa/img/2024/12/galaxy-50-banh-mam-mau-den-do.webp\",\"price\":18900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh mâm\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/galaxy-50-banh-mam-mau-xanh-den.webp\",\"price\":18900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh mâm\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/galaxy-50-banh-mam-mau-xam-den.webp\",\"price\":18900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh căm\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/galaxy-50-mau-do-den.webp\",\"price\":17900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Bánh căm\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh dương Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/galaxy-50-mau-xanh-den.webp\",\"price\":17900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Động cơ/Làm mát/Truyền động\",\"value\":\"4 thì/ Làm mát bằng không khí/Hộp số 4 số\"},{\"label\":\"Phân khối\",\"value\":\"49.5cc\"},{\"label\":\"Mức hao xăng\",\"value\":\"1,29L/100km\"},{\"label\":\"Công suất tối đa\",\"value\":\"1.9kW/7.500rpm\"},{\"label\":\"Momen cực đại\",\"value\":\"2,85Nm/4.500rpm\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống thắng trước\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Hệ thống thắng sau\",\"value\":\"Phanh trống (đùm)\"},{\"label\":\"Vỏ (lốp trước, có ruột)\",\"value\":\"70/80-17\"},{\"label\":\"Vỏ (lốp sau, có ruột)\",\"value\":\"80/80-17\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài - Rộng - Cao\",\"value\":\"1,940mm - 695mm - 1,095mm\"},{\"label\":\"Khoảng cách 2 trục\",\"value\":\"1,240 mm\"},{\"label\":\"Tổng trọng lượng khô\",\"value\":\"99kg\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"3,4L\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Bảo hành\",\"value\":\"24 tháng hoặc 30.000km\"}]}]', '<p>Dòng xe galaxy 50cc không chỉ thu hút bởi vẻ ngoài hiện đại mà còn tích hợp nhiều tính năng tiện ích vượt trội, đáp ứng nhu cầu sử dụng hàng ngày của người tiêu dùng.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE SYM GALAXY 50CC ƯU ĐÃI DÀNH CHO HỌC SINH</h2>\n<p>Kể từ khi ra mắt dòng <b>xe galaxy 50cc</b> thuộc thương hiệu SYM, đã nhanh chóng chiếm lĩnh thị trường nhờ vào những ưu điểm nổi bật. Với thiết kế nhỏ gọn và tinh tế, <b>galaxy 50cc</b> không chỉ dễ dàng di chuyển trong các khu vực đông đúc mà còn mang lại sự tiện lợi cho người sử dụng. Hãy cùng Yên Thoa khám phá dòng xe<b> sym galaxy 50cc </b>và <b>giá xe galaxy 50</b> mới nhất dành cho học sinh qua bài viết dưới đây.</p>\n<h2>1. Thiết kế và màu sắc của xe galaxy 50cc</h2>\n<p>Một trong những điểm nổi bật nhất của dòng <b>xe galaxy 50cc</b> chính là thiết kế nhỏ gọn nhưng vô cùng chắc chắn. Khung xe được chế tạo từ hợp kim nhôm cao cấp, giúp giảm trọng lượng tổng thể mà vẫn đảm bảo độ bền vượt trội. Điều này không chỉ giúp xe dễ dàng luồn lách qua những con phố đông đúc của đô thị mà còn gia tăng tuổi thọ cho động cơ, mang lại sự an tâm cho người sử dụng trong suốt hành trình.</p>\n<p>Màu sắc của <b>xe galaxy 50</b> cũng là một yếu tố quan trọng thu hút sự chú ý từ phía người tiêu dùng. Với bảng màu đa dạng và bắt mắt, từ những gam màu tươi sáng như xanh dương hay đỏ rực rỡ đến những gam màu trầm và sang trọng như đen xám, dòng xe này mang đến nhiều lựa chọn để người dùng có thể tự do thể hiện phong cách cá nhân. Mỗi màu sắc đều được lựa chọn kỹ lưỡng để không chỉ làm nổi bật vẻ đẹp của chiếc xe mà còn phản ánh cá tính riêng biệt của chủ sở hữu.</p>\n<p>Hiện tại, dòng xe <b>sym galaxy 50cc</b> có hai phiên bản chính: phiên bản bánh căm và phiên bản bánh mâm. Phiên bản bánh căm bao gồm ba tùy chọn màu sắc: đen đỏ, xanh đen sơn mờ cao cấp và xám đen. Trong khi đó, phiên bản bánh mâm cũng không kém phần đa dạng với ba lựa chọn: xanh đen, đen đỏ và xám đen. Sự đa dạng này giúp khách hàng dễ dàng tìm thấy chiếc xe phù hợp nhất với sở thích và nhu cầu sử dụng của mình.</p>\n<p>Không chỉ đơn thuần là một phương tiện di chuyển tiện lợi, <b>galaxy 50cc</b> còn trở thành biểu tượng của sự tự tin và cá tính cho người sử dụng. Thiết kế hiện đại kết hợp cùng công nghệ tiên tiến mang lại khả năng vận hành êm ái và ổn định trên mọi cung đường. Người lái sẽ cảm nhận được sự thoải mái tối đa khi điều khiển chiếc xe này nhờ vào hệ thống giảm xóc hiệu quả cùng động cơ mạnh mẽ nhưng tiết kiệm nhiên liệu.</p>\n<p>Ngoài ra, <b>xe galaxy 50</b> còn được trang bị nhiều tính năng tiện ích nhằm nâng cao trải nghiệm lái cho người dùng. Hệ thống phanh an toàn giúp kiểm soát tốc độ tốt hơn trong mọi tình huống giao thông phức tạp. Đèn pha LED sáng rõ không chỉ tăng cường khả năng chiếu sáng vào ban đêm mà còn tiết kiệm điện năng đáng kể.</p>\n<p>Với tất cả những ưu điểm nổi bật trên, không khó hiểu khi dòng xe <b>sym galaxy 50</b> ngày càng trở nên phổ biến trên thị trường Việt Nam. Đây thực sự là lựa chọn lý tưởng dành cho học sinh, sinh viên và những ai đang tìm kiếm một chiếc <a href=\"/xe-may?nhom=sym\"><strong>xe sym</strong></a> vừa thời trang vừa chất lượng để đồng hành trong cuộc sống hàng ngày.</p>\n<h2>2. Giới thiệu động cơ của xe sym galaxy 50</h2>\n<p>Xe máy <b>galaxy 50cc</b> được trang bị khối động cơ tiên tiến, mang đến hiệu suất hoạt động tối ưu cho người sử dụng. Với dung tích xi-lanh 50cc, động cơ này không chỉ đảm bảo khả năng vận hành mượt mà mà còn duy trì sự ổn định trong mọi điều kiện di chuyển.</p>\n<p>Nhà sản xuất đã đặc biệt chú trọng đến yếu tố an toàn trong quá trình phát triển động cơ của dòng xe này. Hệ thống phanh đĩa ở phía trước kết hợp với phanh tang trống ở phía sau giúp người lái có thể dừng xe nhanh chóng và an toàn, ngay cả trong những tình huống khẩn cấp. Đặc biệt, động cơ của<b> xe galaxy 50cc</b> còn được áp dụng công nghệ hiện đại giúp giảm thiểu khí thải CO2 và góp phần bảo vệ môi trường.</p>\n<p>Ngoài ra, <b>galaxy 50cc</b> còn được trang bị hệ thống truyền động linh hoạt cùng hộp số tự động, giúp người lái dễ dàng điều chỉnh tốc độ mà không cần lo lắng về việc chuyển số phức tạp. Điều này không chỉ mang lại sự tiện lợi mà còn tạo cảm giác thoải mái khi di chuyển.</p>\n<p>Với thiết kế hiện đại và khả năng vận hành linh hoạt, <b>sym galaxy 50</b> thực sự là lựa chọn lý tưởng cho những ai đang tìm kiếm một chiếc xe nhỏ gọn nhưng mạnh mẽ và tiết kiệm nhiên liệu. Những tính năng an toàn vượt trội cùng trải nghiệm lái xe tuyệt vời mà dòng xe này mang lại chắc chắn sẽ làm hài lòng mọi người dùng.&nbsp;</p>\n<h2>3. Tính năng nổi bật và tiện ích của dòng xe sym Galaxy 50cc</h2>\n<p>Dòng<b> xe galaxy 50cc</b> không chỉ thu hút bởi vẻ ngoài hiện đại mà còn tích hợp nhiều tính năng tiện ích vượt trội, đáp ứng nhu cầu sử dụng hàng ngày của người tiêu dùng. Dưới đây là những tính năng và tiện ích nổi bật được trang bị trên <b>sym galaxy 50cc</b>.</p>\n<p><em>Hệ thống đèn LED hiện đại</em></p>\n<p>Dòng <b>xe galaxy 50</b> được trang bị hệ thống đèn LED signal phía trước với thiết kế tinh tế và hiện đại. Hệ thống chiếu sáng này không chỉ mang lại khả năng chiếu sáng vượt trội trong điều kiện ban đêm mà còn giúp người lái dễ dàng nhận diện và di chuyển an toàn hơn trong những khu vực thiếu ánh sáng. Điều này góp phần nâng cao mức độ an toàn cho người sử dụng, đặc biệt là trong những chuyến đi vào buổi tối.</p>\n<p><em>Hộc chứa đồ tiện lợi</em></p>\n<p>Một trong những điểm nổi bật của <b>galaxy 50cc </b>chính là hộc chứa đồ phía trước, được thiết kế thông minh và tiện lợi. Với không gian đủ lớn để chứa các vật dụng nhỏ như điện thoại, chìa khóa hay ví tiền, người lái có thể dễ dàng tiếp cận và sử dụng khi cần thiết. Thiết kế này không chỉ mang lại sự tiện nghi mà còn giúp người dùng tổ chức đồ đạc một cách gọn gàng.</p>\n<p><em>Tay lái chống rung cao cấp</em></p>\n<p>Tay lái của <b>xe galaxy 50</b> được chế tạo với công nghệ chống rung tiên tiến, giúp duy trì sự ổn định và cân bằng khi di chuyển. Điều này mang lại cảm giác thoải mái tối đa cho người lái, đặc biệt là trên những cung đường dài hoặc gồ ghề. Sự thoải mái này sẽ làm cho mỗi chuyến đi trở nên thú vị hơn bao giờ hết.</p>\n<p><em>Không gian chứa đồ rộng rãi dưới yên xe</em></p>\n<p>Không gian chứa đồ dưới yên xe của <b>sym galaxy 50cc</b> rất rộng rãi, đủ để chứa một mũ bảo hiểm nửa đầu hoặc các vật dụng cá nhân khác. Thiết kế này không chỉ tăng cường khả năng lưu trữ mà còn đảm bảo sự thoải mái cho người ngồi trên xe. Người dùng có thể yên tâm khi mang theo nhiều đồ dùng cần thiết mà không lo lắng về việc thiếu chỗ.</p>\n<h2>4. Cập nhật giá xe galaxy 50cc mới nhất hiện nay</h2>\n<p>Trong bối cảnh thị trường xe máy ngày càng phong phú và đa dạng, việc tìm kiếm một chiếc xe phù hợp với nhu cầu sử dụng và ngân sách trở nên vô cùng khó khăn. Nếu bạn đang tìm kiếm một địa chỉ uy tín tham khảo <b>giá xe galaxy 50cc</b> thì Hệ thống Siêu Thị Yên Thoa chính là lựa chọn lý tưởng mà bạn không thể bỏ qua. Dưới đây là những lý do thuyết phục để bạn cân nhắc mua <b>xe galaxy 50cc</b> tại Yên Thoa.</p>\n<p><em>Chất lượng vượt trội</em></p>\n<p>Hệ thống Siêu Thị Yên Thoa cam kết mang đến cho khách hàng những sản phẩm chất lượng chính hãng với dòng<b> xe galaxy 50</b> được sản xuất theo tiêu chuẩn nghiêm ngặt, đảm bảo độ bền bỉ và an toàn tuyệt đối cho người sử dụng.&nbsp;</p>\n<p><em>Giá cả cạnh tranh hấp dẫn</em></p>\n<p><a href=\"/xe-may\"><strong>Giá xe máy</strong></a> luôn là yếu tố quan trọng khi quyết định mua xe. Tại Hệ thống Siêu Thị Yên Thoa, bạn sẽ được trải nghiệm mức <b>giá xe galaxy 50cc </b>cạnh tranh nhất trên thị trường. Đặc biệt, cửa hàng thường xuyên tổ chức các chương trình khuyến mãi hấp dẫn, giúp bạn tiết kiệm chi phí mà vẫn sở hữu được chiếc xe mơ ước. Hiện nay, <b>giá xe galaxy 50cc</b> tại cửa hàng đang chỉ từ 17 triệu đồng.</p>\n<p><em>Dịch vụ khách hàng tận tâm và chuyên nghiệp</em></p>\n<p>Đội ngũ nhân viên giàu kinh nghiệm tại Hệ thống Siêu Thị Yên Thoa sẽ luôn sẵn sàng tư vấn và hỗ trợ khách hàng trong suốt quá trình mua xe. Chính sách bảo hành dài hạn cùng dịch vụ hậu mãi chu đáo cũng là điểm cộng lớn khi bạn quyết định mua xe tại đây.</p>\n<p><em>Thủ tục mua bán nhanh chóng và đơn giản</em></p>\n<p>Quy trình mua bán tại Hệ thống Siêu Thị Yên Thoa được diễn ra nhanh chóng và thuận tiện nhất có thể. Bạn chỉ cần thực hiện vài bước đơn giản để hoàn tất thủ tục mà không gặp bất kỳ khó khăn nào, giúp tiết kiệm thời gian quý báu của quý khách hàng.</p>\n<p><em>Sản phẩm đa dạng cùng phụ kiện chính hãng</em></p>\n<p>Ngoài mẫu<b> xe galaxy 50cc</b>, hệ thống còn cung cấp nhiều dòng sản phẩm khác từ các thương hiệu uy tín trên thị trường. Quý khách cũng có thể tìm thấy đầy đủ các loại phụ kiện chính hãng để nâng cấp hoặc thay thế cho chiếc xe của mình.Hãy đến ngay Yên Thoa để trải nghiệm và sở hữu chiếc xe <b>sym galaxy 50cc</b> đẳng cấp! Mọi thông tin chi tiết về <b>giá xe galaxy 50cc</b> hay các dòng sản phẩm khác vui lòng liên hệ qua hotline để được tư vấn miễn phí!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
