INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-gsx-s150', 'Xe GSX S150', 'suzuki', '[\"xe-tay-con\"]', 66000000, 66000000, '/sites/yenthoa/img/2024/11/gsx-s150-mau-xanh.webp', '[\"/sites/yenthoa/img/2024/11/gsx-s150-mau-xanh.webp\"]', '[\"Đen\",\"Đen Đỏ\",\"Xanh đậm\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/gsx-s150-mau-den.webp\",\"price\":66000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/yenthoa/img/2024/11/gsx-s150-mau-den-do.webp\",\"price\":66000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm\"}],\"img\":\"/sites/yenthoa/img/2024/11/gsx-s150-mau-xanh.webp\",\"price\":66000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Hệ thống làm mát\",\"value\":\"Bằng dung dịch\"},{\"label\":\"Loại động cơ\",\"value\":\"4-thì\"},{\"label\":\"Phân khối\",\"value\":\"150cccc\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"147.3 cm3\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,5:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"14,1 kw/10.500 vòng/phút\"},{\"label\":\"Moment cực đại\",\"value\":\"14,0 Nm/9.000 vòng/phút\"},{\"label\":\"Hệ thống bơm xăng\",\"value\":\"FI\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"11 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,98 lít/100km\"},{\"label\":\"Đường kính x hành trình piston\",\"value\":\"62,0 mm x 48,8 mm\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung sườn\",\"value\":\"Cấu trúc dạng kim cương\"},{\"label\":\"Hệ thống phanh trước/sau\",\"value\":\"Đĩa/ đĩa (nan hoa)\"},{\"label\":\"Hệ thống giảm xóc trước/sau\",\"value\":\"Phuộc ống lồng/ phuộc nhún\"},{\"label\":\"Kích cỡ vỏ xe trước/sau\",\"value\":\"90/80-17M/C 46P/ 130/70-17M/C 62P\"},{\"label\":\"Đèn pha\",\"value\":\"LED\"},{\"label\":\"Đèn hậu\",\"value\":\"Đèn bóng halogen\"},{\"label\":\"Cụm đồng hồ\",\"value\":\"Kỹ thuật số\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Độ cao yên\",\"value\":\"785mm\"},{\"label\":\"Khối lượng\",\"value\":\"130kg\"},{\"label\":\"Dài x rộng x cao\",\"value\":\"2.020 mm x 745mm x 1.040mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1.300mm\"},{\"label\":\"Độ cao gầm\",\"value\":\"155mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000KM\"}]}]', '<p>Không chỉ sở hữu thiết kế tinh tế và hiệu suất vượt trội điển hình của dòng xe tay côn suzuki, xe gsx s150 còn thu hút sự quan tâm của đông đảo người tiêu dùng tính năng vượt trội.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE TAY CÔN SUZUKI GSX S150 MỚI NHẤT HIỆN NAY</h2>\n<p><b>Suzuki gsx s150</b> là một trong những dòng xe tay côn thể thao nổi bật nhất hiện nay. Được trang bị công nghệ tiên tiến, <b>gsx s150 </b>không chỉ tiết kiệm nhiên liệu mà còn mang đến trải nghiệm lái tuyệt vời cho những tín đồ yêu thích tốc độ. Hãy cùng khám phá ngay những ưu điểm vượt trội và <b>giá xe gsx s150</b> mới nhất hiện nay trên thị trường.</p>\n<h2>1. Tổng quan về ngoại hình thiết kế của dòng xe Suzuki GSX S150</h2>\n<p>Kể từ khi ra mắt, <b>xe côn tay suzuki gsx s150 </b>đã nhanh chóng thu hút sự chú ý nhờ vào ngoại hình mạnh mẽ và phong cách độc đáo. Sự ấn tượng trong thiết kế không chỉ mang lại vẻ ngoài hầm hố mà còn đảm bảo tính tiện dụng và khả năng điều khiển dễ dàng.</p>\n<p>Với sự kết hợp hoàn hảo giữa động cơ mạnh mẽ và trọng lượng nhẹ, <b>suzuki gsx s150</b> không chỉ mang đến khả năng tăng tốc vượt trội mà còn đảm bảo sự ổn định và linh hoạt trong quá trình vận hành. Điều này giúp người lái tự tin hơn khi di chuyển trên nhiều loại địa hình khác nhau.</p>\n<p>Suzuki đã rất chú trọng đến việc tối ưu hóa thiết kế của <b>xe gsx s150 </b>để tạo ra một chiếc xe gọn nhẹ và linh hoạt. Mẫu xe hiện có ba tùy chọn màu sắc: đen mờ, đen bóng và xanh dương, mỗi màu sắc đều mang đến một vẻ đẹp hiện đại và cá tính riêng biệt cho chiếc xe.</p>\n<p>Một trong những điểm nhấn đáng chú ý của<b> xe gsx s150</b> là cụm đèn pha LED được thiết kế theo chiều dọc. Cụm đèn này không chỉ cung cấp ánh sáng mạnh mẽ giúp người lái dễ dàng quan sát trong điều kiện thiếu sáng mà còn tiết kiệm nhiên liệu hiệu quả hơn so với các loại đèn truyền thống. Đèn hậu cũng được chăm chút tỉ mỉ, kết hợp với hệ thống chắn bùn giúp giảm rung lắc và tăng độ bền cho xe.</p>\n<p>Yên xe của <b>gsx s150</b> có kiểu dáng thể thao hiện đại, gọn gàng và đặc biệt phù hợp với vóc dáng người châu Á nhờ độ cao yên chỉ 785mm. Thiết kế này không chỉ tạo cảm giác thoải mái khi ngồi mà còn giúp người lái dễ dàng kiểm soát phương tiện hơn trong suốt hành trình.</p>\n<p>Hệ thống phuộc nhún sau của <b>suzuki gsx s150</b> cũng là một điểm cộng lớn, mang lại cảm giác an toàn và ổn định trên mọi cung đường. Điều này đặc biệt quan trọng đối với những ai thường xuyên di chuyển qua các địa hình phức tạp hoặc thực hiện những chuyến đi dài.</p>\n<p>Ngoài ra, Suzuki còn chú trọng đến từng chi tiết nhỏ nhất trên mỗi bộ phận của xe để đảm bảo rằng mỗi chiếc <b>gsx s150</b> đều đạt tiêu chuẩn cao nhất về chất lượng và hiệu suất. Các chi tiết như khung sườn chắc chắn, hệ thống phanh hiệu quả cùng động cơ mạnh mẽ đều góp phần tạo nên một chiếc xe hoàn hảo từ trong ra ngoài.</p>\n<p><b>Suzuki gsx s150</b> không chỉ là một mẫu xe côn tay nổi bật về ngoại hình mà còn vượt trội về hiệu suất vận hành. Với thiết kế hiện đại, tính năng tiên tiến cùng khả năng vận hành linh hoạt, việc sở hữu một chiếc <b>xe côn tay suzuki gsx s150</b> chắc chắn sẽ là lựa chọn lý tưởng cho những ai yêu thích dòng xe Naked đầy phong cách nhưng vẫn đảm bảo tính thực dụng cao.</p>\n<h2>2. Những điểm nổi bật của xe GSX S150</h2>\n<p>Không chỉ sở hữu thiết kế tinh tế và hiệu suất vượt trội, <b>xe gsx s150</b> còn thu hút sự quan tâm của đông đảo người tiêu dùng tính năng vượt trội. Dưới đây là những điểm nổi bật trong tính năng của dòng xe GSX S150</p>\n<p>Thiết kế xe ấn tượng</p>\n<p>Ngay từ cái nhìn đầu tiên, <b>suzuki gsx s150</b> đã gây ấn tượng với ngoại hình mạnh mẽ hơn so với các dòng xe côn tay khác của hãng. Với chiều cao tổng thể 1.040 mm và khoảng sáng gầm lên đến 155 mm, mẫu xe này rất phù hợp cho việc di chuyển trong điều kiện thời tiết khắc nghiệt như mưa bão. Điều này không chỉ nâng cao khả năng vận hành mà còn mang lại cảm giác an toàn cho người lái. Đặc biệt, mẫu xe này còn thừa hưởng bộ khung gầm vững chắc từ người anh em R150, tạo nên sự kết hợp hoàn hảo giữa tính năng và thẩm mỹ.</p>\n<p>Động cơ mạnh mẽ</p>\n<p>Nằm trong top những mẫu xe côn tay được yêu thích nhất hiện nay, <b>gsx s150</b> sở hữu động cơ 150cc, 4 thì, làm mát bằng dung dịch và công nghệ DOHC – tương tự như trên dòng Raider Fi thế hệ mới. Khối động cơ này không chỉ mang lại hiệu suất mạnh mẽ mà còn đảm bảo khả năng tăng tốc vượt trội với sự chuyển số êm ái.</p>\n<p>Công nghệ SCEM được áp dụng trên piston cùng lớp mạ bạc giúp giảm ma sát và tăng độ bền cho động cơ, đồng thời duy trì hiệu suất ổn định qua thời gian dài sử dụng. Hệ thống tản nhiệt hiện đại cũng là một điểm cộng lớn khi giữ cho động cơ luôn hoạt động ổn định mà không bị nóng quá mức.</p>\n<p><b>Xe gsx s150</b> không chỉ chú trọng vào hiệu suất vận hành mà còn đặc biệt quan tâm đến vấn đề tiết kiệm nhiên liệu và bảo vệ môi trường. Mẫu xe này được trang bị hệ thống xả hiệu suất cao cùng bộ xử lý khí thải đạt chuẩn Euro 3, góp phần giảm thiểu ô nhiễm môi trường.</p>\n<p>Tiện ích và an toàn</p>\n<p>Về mặt tiện ích và an toàn, <b>gsx s150 </b>cũng không kém cạnh khi sở hữu nhiều công nghệ tiên tiến. Nút khởi động một lần chạm giúp người lái dễ dàng khởi động máy chỉ với một thao tác đơn giản mà không cần phải giữ nút lâu. Nắp khóa được thiết kế thông minh nhằm ngăn bụi bẩn và nước vào ổ khóa, đồng thời tăng khả năng chống trộm.</p>\n<p>Bình xăng dung tích lớn lên đến 11 lít là một ưu điểm nổi bật khác của mẫu xe này. Với khả năng lưu trữ nhiều nhiên liệu hơn, bạn có thể thoải mái di chuyển trên quãng đường dài mà không lo hết xăng giữa chừng. Bình xăng được bố trí phía trước với thiết kế tinh tế tạo nên sự gọn gàng và thuận tiện khi cầm lái.</p>\n<p>Cụm đồng hồ LCD hiện đại cũng là một điểm nhấn đáng chú ý trên xe với thiết kế hợp lý giúp người lái dễ dàng theo dõi các thông số kỹ thuật cần thiết như tốc độ, mức nhiên liệu hay quãng đường đã đi – tất cả đều hiển thị rõ ràng trên màn hình LCD sắc nét.</p>\n<p><b>Suzuki gsx s150</b> không chỉ gây ấn tượng bởi thiết kế đẹp mắt mà còn bởi hiệu suất vận hành mạnh mẽ cùng hàng loạt tính năng tiện ích hiện đại. Đây thực sự là lựa chọn lý tưởng cho những ai yêu thích sự kết hợp giữa phong cách thể thao và công nghệ tiên tiến trong một chiếc xe côn tay.</p>\n<h2>3. Giá xe GSX S150 mới nhất tại Hệ thống Siêu Thị Yên Thoa&nbsp;</h2>\n<p>Trước khi quyết định mua<b> xe gsx s150</b>, việc lựa chọn một đại lý uy tín là điều vô cùng quan trọng. Hiện nay, trên thị trường có rất nhiều <a href=\"/xe-may?nhom=suzuki\"><strong>cửa hàng suzuki</strong></a>, từ quy mô nhỏ đến lớn. Tuy nhiên, không phải tất cả đều đảm bảo chất lượng sản phẩm và <b>giá xe gsx s150</b>.</p>\n<p>Hệ thống Siêu Thị Yên Thoa tự hào là một trong những địa chỉ hàng đầu cung cấp các dòng xe Suzuki chính hãng với chất lượng vượt trội và<b> giá xe gsx s150 </b>cạnh tranh. Chúng tôi cam kết mang đến cho khách hàng mức <b>giá xe gsx s150 </b>ưu đãi nhất chỉ từ 66 triệu đồng.</p>\n<p>Đặc biệt, khi quý khách mua <a href=\"/xe-may\"><b>xe máy</b></a> tại Yên Thoa, không còn được nhận nhiều chương trình khuyến mãi hấp dẫn cùng chính sách bảo hành chu đáo. Đội ngũ nhân viên tư vấn chuyên nghiệp của chúng tôi luôn sẵn sàng hỗ trợ và giải đáp mọi thắc mắc của quý khách.</p>\n<p>Để biết thêm thông tin chi tiết về <b>giá xe gsx s150</b> cũng như các ưu đãi hiện có, xin vui lòng liên hệ với chúng tôi qua hotline. Hãy đến với Hệ thống Siêu Thị Yên Thoa để trải nghiệm dịch vụ tốt nhất và sở hữu <b>xe côn tay suzuki gsx s150</b> hấp dẫn!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
