INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-janus', 'Xe Janus', 'yamaha', '[]', 29151000, 33382000, '/sites/yenthoa/img/2024/11/janus-moi-phien-ban-gioi-han-mau-bac-nham.webp', '[\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-gioi-han-mau-bac-nham.webp\"]', '[\"Bạc nhám\",\"Đen bóng\",\"Đen Vàng nhám\",\"Đen Xám nhám\",\"Đỏ bóng\",\"Trắng Bạc bóng\",\"Trắng Đen bóng\",\"Xám nhám\",\"Xanh nhám\",\"Xanh Xám nhám\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Giới hạn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Xám nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-gioi-han-mau-xanh-xam-nham.webp\",\"price\":33382000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Giới hạn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Vàng nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-gioi-han-mau-den-vang-nham.webp\",\"price\":33382000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Giới hạn\"},{\"name\":\"Màu sắc\",\"value\":\"Xám nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-gioi-han-mau-xam-nham.webp\",\"price\":33382000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Giới hạn\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-gioi-han-mau-bac-nham.webp\",\"price\":33382000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ bóng\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-dac-biet-mau-do-bong.webp\",\"price\":33176000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Xám nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-dac-biet-mau-den-xam-nham.webp\",\"price\":33176000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-dac-biet-mau-xanh-nham.webp\",\"price\":33176000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Bạc bóng\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-dac-biet-mau-trang-bac-bong.webp\",\"price\":33176000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen bóng\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-tieu-chuan-mau-trang-den-bong.webp\",\"price\":29151000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ bóng\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-tieu-chuan-mau-do-bong.webp\",\"price\":29151000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen bóng\"}],\"img\":\"/sites/yenthoa/img/2024/11/janus-moi-phien-ban-tieu-chuan-mau-den-bong.webp\",\"price\":29151000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"Blue Core, 4 thì, 2 van, SOHC, Làm mát bằng không khí cưỡng bức\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"124.9 cc\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"52,4 mm x 57,9 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9,5 : 1\"},{\"label\":\"Công suất tối đa\",\"value\":\"7,0 kW (9,5 ps)/8.000 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"9.6 Nm (1.0 kgf-m)/5500 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Các te ướt\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"0,84 L\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,2 L\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"1,87\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"T.C.I (kỹ thuật số)\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"1,000/10,156 (50/16 x 39/12)\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Khô, ly tâm tự động\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"2,294 - 0,804 : 1\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"Dây đai V tự động\"},{\"label\":\"Hệ thống làm mát\",\"value\":\"Làm mát bằng không khí\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Underbone\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Phuộc ống lồng\"},{\"label\":\"Độ lệch phương trục lái\",\"value\":\"26°30 / 100 mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Giảm chấn lò xo dầu\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa đơn thủy lực\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh tang trống\"},{\"label\":\"Lốp trước\",\"value\":\"80/80-14M/C 43P\"},{\"label\":\"Lốp sau\",\"value\":\"110/70-14M/C 56P\"},{\"label\":\"Đèn trước\",\"value\":\"Halogen 12V 35W / 35W x 1\"},{\"label\":\"Đèn sau\",\"value\":\"LED\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1850 mm x 705 mm x 1120 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"769 mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"135 mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1260 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"99 kg\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,2 L\"},{\"label\":\"Ngăn chứa đồ\",\"value\":\"14.2\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tuỳ theo điều kiện nào đến trước)\"}]}]', '<p>Với những cải tiến vượt bậc, mua xe janus chắc chắn sẽ là một lựa chọn hấp dẫn cho những ai yêu thích sự trẻ trung và cá tính trong từng chuyến đi. Hiện nay, xe janus đang được phân phối tại Yên Thoa với mức giá xe janus hấp dẫn.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE JANUS CỦA YAMAHA MỚI NHẤT TRÊN THỊ TRƯỜNG&nbsp;</h2>\n<p>Dòng <b>xe janus</b> đã mở ra một khái niệm hoàn toàn mới về sự tiện nghi và phong cách trong thế giới xe tay ga. Với thiết kế tinh tế cùng công nghệ tiên tiến, <b>mua xe janus </b>không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn thể hiện rõ nét gu thẩm mỹ và phong cách sống của người sử dụng. Hãy cùng Yên Thoa khám phá những điểm nổi bật của<b> xe tay ga janus.</b> Dưới đây là<b> giá xe janus </b>mới nhất trên thị trường của yamaha.</p>\n\n<h2>1. Thiết kế trẻ trung và cá tính của xe janus hoàn toàn mới của yamaha</h2>\n<p>Yamaha Việt Nam vừa ra mắt phiên bản nâng cấp của mẫu <b>xe tay ga Janus</b>, mang đến cho người tiêu dùng một lựa chọn phong phú trong phân khúc xe tay ga cỡ nhỏ với mức giá khoảng 30 triệu đồng. Với thiết kế trẻ trung và cá tính, <b>xe janus</b> không chỉ là phương tiện di chuyển mà còn là biểu tượng cho phong cách sống của thế hệ Gen Z.</p>\n<p>Dựa trên thông điệp “Match Your Freak – Hệ J Chất Dị”, <b>Yamaha janus</b> mới không ngừng khẳng định sự độc đáo và cá tính của người sử dụng. Mẫu xe này cho phép giới trẻ thể hiện cái “chất dị” của riêng mình, giúp họ tự tin trở thành bất cứ ai mà họ mong muốn.</p>\n\n<p>Khác với những bản nâng cấp thông thường thường tập trung vào việc thay đổi diện mạo tổng thể, <b>xe janus </b>giữ nguyên kiểu dáng đầu xe quen thuộc. Các cải tiến chủ yếu được thực hiện ở phần thân sau và đuôi xe. Điểm nhấn nổi bật là các phối màu mới đầy năng động, hướng đến đối tượng khách hàng trẻ tuổi yêu thích sự mới mẻ.</p>\n<p>Một trong những điểm đáng chú ý nhất trên <b>xe tay ga janus</b> chính là cụm đèn hậu LED được thiết kế gọn gàng và sắc sảo. Tuy nhiên, hình dáng hai tầng cách điệu theo kiểu chữ X có thể khiến người dùng liên tưởng đến một số mẫu xe khác trên thị trường. Điểm cộng lớn là đèn xi-nhan đã được bố trí cao hơn, giúp phần đuôi xe trở nên gọn gàng và tinh tế hơn.</p>\n\n<p>Ngoài ra, yên xe cũng đã được thiết kế lại với chiều dài tăng thêm 77 mm cùng chất liệu PVC bọc yên chống nóng, mang lại cảm giác thoải mái hơn cho người lái. Khu vực sàn để chân cũng được mở rộng thêm 20 mm, tạo điều kiện thuận lợi cho việc điều khiển xe.</p>\n<p>Hiện tại, <b>xe janus</b> có ba phiên bản khác nhau cùng với 11 màu sắc trendy đầy thu hút, đáp ứng nhu cầu đa dạng của khách hàng trẻ tuổi. Với những cải tiến vượt bậc về thiết kế và tính năng, <b>mua xe janus</b> chắc chắn sẽ là một lựa chọn hấp dẫn cho những ai yêu thích sự trẻ trung và cá tính trong từng chuyến đi.</p>\n<h2>2. Động cơ được thiết kế theo công nghệ mới với hiệu suất vượt trội của yamaha janus</h2>\n<p>Được thiết kế với khối động cơ 125cc mạnh mẽ, <b>xe janus </b>mang đến cho người lái những trải nghiệm tuyệt vời, đồng thời giúp giảm thiểu chi phí sử dụng một cách hiệu quả.</p>\n<p>Một trong những điểm nổi bật của <b>yamaha janus</b> chính là khả năng tối ưu hóa mức tiêu hao nhiên liệu. Nhờ vào công nghệ động cơ Blue Core tiên tiến, xe không chỉ tiết kiệm nhiên liệu mà còn nâng cao hiệu suất hoạt động. Hệ thống ly hợp khô và ly tâm tự động được trang bị trên xe giúp việc vận hành trở nên mượt mà và dễ dàng hơn bao giờ hết.</p>\n\n<p>Ngoài ra, hệ thống giảm xóc của<b> xe tay ga janus</b> cũng đã được tinh chỉnh một cách tỉ mỉ, cho phép xe dễ dàng vượt qua mọi loại địa hình. Điều này đảm bảo rằng người lái luôn cảm thấy êm ái và ổn định trong suốt hành trình.</p>\n<p><b>Xe janus</b> không chỉ chú trọng đến hiệu suất mà còn cam kết bảo vệ môi trường. Công nghệ tiên tiến được áp dụng giúp giảm thiểu khí thải độc hại, góp phần tạo nên một tương lai xanh hơn cho cộng đồng.</p>\n<p><b>Yamaha janus </b>là sự kết hợp hoàn hảo giữa công nghệ hiện đại và tính năng thân thiện với môi trường, mang đến cho người dùng những trải nghiệm lái xe tuyệt vời nhất.</p>\n<h2>3. Tiện ích vượt trội của xe tay ga janus</h2>\n<p><b>Xe tay ga Janus</b> không chỉ thu hút người dùng bởi thiết kế ngoại hình tinh tế, mà còn nổi bật với nhiều tính năng ưu việt và tiện ích hiện đại, mang đến trải nghiệm lái xe tuyệt vời.</p>\n<p><em>Mặt đồng hồ LCD đa chức năng</em></p>\n<p>Xe được trang bị màn hình hiển thị LCD với thiết kế tối giản và phông chữ hiện đại, giúp người dùng dễ dàng theo dõi các thông số cần thiết trong mọi điều kiện ánh sáng. Điều này không chỉ nâng cao tính tiện dụng mà còn tạo cảm giác sang trọng cho người sử dụng.</p>\n\n<p><em>Hệ thống khóa thông minh</em></p>\n<p>Hệ thống khóa thông minh với nút xoay tích hợp nhiều chức năng như định vị tìm xe, mở/tắt khóa điện, mở/khoá cổ xe và mở yên xe (kết hợp cùng nút bấm seat). Tính năng này không chỉ mang lại sự tiện lợi mà còn đảm bảo an toàn cho phương tiện của bạn.</p>\n\n<p><em>Cổng sạc USB tiện lợi</em></p>\n<p>Janus được trang bị cổng sạc USB tiện lợi, cho phép người dùng sạc điện thoại di động hoặc các thiết bị điện tử một cách nhanh chóng và dễ dàng. Tuy nhiên, cần lưu ý không để điện thoại hoặc pin trong cốp xe khi đang sạc để tránh nguy cơ cháy nổ.</p>\n\n<p><em>Cốp chứa đồ rộng rãi</em></p>\n<p>Với dung tích tăng thêm 1,1L so với phiên bản trước, cốp chứa đồ của<b> xe janus</b> được thiết kế rộng rãi hơn. Lớp cách nhiệt bên trong giúp giảm nhiệt độ từ động cơ, bảo vệ đồ đạc bên trong khỏi những tác động xấu do nhiệt độ cao.</p>\n<p><em>Bình xăng cải tiến</em></p>\n<p>Bình xăng của <b>yamaha janus </b>được tối ưu hóa về thiết kế, giúp việc tiếp nhiên liệu trở nên dễ dàng hơn và tiết kiệm không gian. Điều này góp phần làm tăng tính tiện nghi cho người sử dụng.</p>\n<p><em>Chỗ để chân rộng hơn</em></p>\n<p>Khu vực để chân của <b>xe janus </b>đã được mở rộng thêm 20mm so với phiên bản trước, mang đến sự thoải mái tối đa cho người lái khi di chuyển trên những quãng đường dài. Điều này giúp bạn dễ dàng thư giãn và tận hưởng chuyến đi một cách trọn vẹn nhất.</p>\n\n<p><em>Lốp xe không săm</em></p>\n<p>Lốp xe không săm không chỉ giúp giảm trọng lượng của xe mà còn hạn chế nguy cơ thủng lốp đột ngột. Tính năng này đảm bảo an toàn tối đa cho người lái trong suốt hành trình.</p>\n<p><b>Xe tay ga Janus </b>là sự kết hợp hoàn hảo giữa thiết kế tinh tế và những tính năng hiện đại vượt trội. Với <b>giá xe janus </b>đang cực kì ưu đãi, đây chắc chắn là lựa chọn hàng đầu cho những ai yêu thích <a href=\"/xe-may?nhom=yamaha\"><strong>xe máy yamaha</strong></a>.</p>\n<h2>4. Giá xe janus mới nhất tại Yên Thoa&nbsp;</h2>\n<p>Hiện nay,<b> xe janus</b> phiên bản mới nhất đang được phân phối tại hệ thống Yên Thoa với mức <b>giá xe janus</b> hấp dẫn chỉ từ 30 triệu đồng, kèm theo hàng loạt ưu đãi đặc biệt dành cho khách hàng.</p>\n<p><strong>Giá xe janus</strong> phiên bản tiêu chuẩn: <strong>30.500.000đ</strong></p>\n<p><strong>Giá xe janus</strong> phiên bản đặc biệt: <strong>33.900.000đ</strong></p>\n<p><strong>Giá xe janus</strong> phiên bản giới hạn: <strong>34.400.000đ</strong></p>\n<p>Với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh <strong>xe máy</strong>, Yên Thoa tự hào là địa chỉ tin cậy cho những ai tìm kiếm một cửa hàng chính hãng. Khi quý khách lựa chọn mua xe máy yamaha, đặc biệt là dòng <strong>xe janus</strong>, quý vị sẽ được nhận ngay những lợi ích độc quyền sau đây.</p>\n\n<p><em>Đội ngũ nhân viên chuyên nghiệp:</em> Chúng tôi cam kết mang đến trải nghiệm mua sắm tuyệt vời với dịch vụ tư vấn chuyên nghiệp 24/7. Quý khách có thể liên hệ qua Hotline, Zalo, Fanpage Facebook hoặc trực tiếp tại ba chi nhánh của chúng tôi.</p>\n<p><em>Hỗ trợ mua xe trả góp:</em> Yên Thoa triển khai chương trình hỗ trợ <b>mua xe janus</b> trả góp với thủ tục đơn giản và lãi suất cực kỳ ưu đãi. Chỉ cần trả trước từ 0đ, quý khách đã có thể sở hữu ngay chiếc xe mơ ước.</p>\n<p><em>Chương trình thu xe cũ đổi xe mới:</em> Giúp quý khách dễ dàng nâng cấp lên đời xe mới thông qua chương trình thu xe cũ đổi xe mới tiện lợi và nhanh chóng.</p>\n<p><em>Dịch vụ giao xe tận nhà:</em> Để tạo điều kiện thuận lợi nhất cho khách hàng, chúng tôi cung cấp dịch vụ giao xe tận nhà nhanh chóng và an toàn.</p>\n<p><em>Khuyến mãi hấp dẫn:</em> Khi <b>mua xe janus</b> tại Yên Thoa, quý khách sẽ nhận ngay combo quà tặng gồm 14 phần quà trị giá lên đến 2.950.000 đồng cùng nhiều chương trình khuyến mãi hấp dẫn khác.</p>\n<p>Để biết thêm thông tin chi tiết về <b>giá xe janus</b> cũng như các chương trình ưu đãi hiện có, xin vui lòng liên hệ với chúng tôi qua hotline để được hỗ trợ miễn phí! Hãy đến với Hệ thống Siêu Thị Yên Thoa để trải nghiệm sự khác biệt và sở hữu ngay những dòng xe máy chất lượng!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
