INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-lead', 'Xe Lead', 'honda', '[]', 40300000, 43700000, '/sites/yenthoa/img/2024/11/lead-phien-ban-dac-biet-abs-xanh-den.webp', '[\"/sites/yenthoa/img/2024/11/lead-phien-ban-dac-biet-abs-xanh-den.webp\"]', '[\"Đen mờ\",\"Đỏ\",\"Trắng\",\"Xanh đậm\",\"Xanh lá Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm\"}],\"img\":\"/sites/yenthoa/img/2024/11/lead-phien-ban-cao-cap-mau-xanh.webp\",\"price\":42800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/lead-phien-tieu-chuan-mau-trang.webp\",\"price\":40300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ\"}],\"img\":\"/sites/yenthoa/img/2024/11/lead-phien-ban-cao-cap-mau-do.webp\",\"price\":42800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen mờ\"}],\"img\":\"/sites/yenthoa/img/2024/11/lead-phien-ban-dac-biet-abs-den-mo.webp\",\"price\":43700000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh lá Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/lead-phien-ban-dac-biet-abs-xanh-den.webp\",\"price\":43700000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"6,0 lít\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xi-lanh,làm mát bằng chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"8,22kW/8500 vòng/ phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả 0,8 lít Sau khi tháo lọc dầu 0.85 lít Sau khi rã máy 0.9 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2.1 lít/100km\"},{\"label\":\"Loại truyền động\",\"value\":\"Truyền động đai\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"11,7Nm/5250 vòng/ phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"124,8 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"53,5 mm x 55,5 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,5:1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Trước: 90/90-12 44J Sau: 100/90-10 56J\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"114 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.844mm x 714mm x 1.132mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.273 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"760 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"140 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Honda lead là một trong những mẫu xe tay ga được yêu thích nhất hiện nay, không chỉ bởi hiệu suất vận hành mà còn nhờ vào sự đa dạng trong thiết kế và màu sắc.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE LEAD 125 GIÁ RẺ CHÍNH HÃNG CỦA HONDA</h2>\n<p><b>Honda lead </b>không chỉ mang đến những tiện ích vượt trội mà còn là biểu tượng hoàn hảo của sự kết hợp giữa vẻ đẹp thời thượng và tính năng ưu việt. Mẫu <b>xe máy lead</b> được ra đời với mong muốn tôn vinh nét đẹp tự nhiên của người phụ nữ hiện đại, độc lập và tự tin, giúp họ thể hiện phong cách cá nhân qua những lựa chọn riêng biệt.</p>\n<p>Hãy cùng Hệ thống Siêu Thị Yên Thoa tìm hiểu ngay <b>giá xe lead </b>và những ưu đãi khi <b>mua xe lead </b>qua bài viết dưới đây.<br>\n</p>\n\n<h2>1. Tìm hiểu về thiết kế hoàn toàn mới của dòng xe tay ga Lead</h2>\n<p>Dòng <b>xe tay ga lead</b> không chỉ đơn thuần là phương tiện di chuyển, mà còn là biểu tượng của phong cách sống tự tin và độc lập với từng chi tiết được chăm chút tỉ mỉ.</p>\n<p><em>Thiết kế năng động và hiện đại</em></p>\n<p>Dòng<b> xe lead</b> sở hữu thiết kế nổi bật với các đường gờ 3D dọc hai bên thân xe, tạo nên diện mạo sắc nét và ấn tượng. Mặt nạ trước được trang trí bằng chi tiết chrome chữ V kết hợp với ốp màu khác biệt, thu hút ánh nhìn ngay từ lần đầu tiên. Công nghệ đèn chiếu sáng phía trước luôn sáng đảm bảo tầm nhìn tốt trong điều kiện ánh sáng yếu, tăng cường khả năng nhận diện khi lưu thông trên đường phố.</p>\n\n<p><em>Đa dạng phiên bản và màu sắc</em></p>\n<p><b>Honda lead</b> là một trong những mẫu xe tay ga được yêu thích nhất hiện nay, không chỉ bởi hiệu suất vận hành mà còn nhờ vào sự đa dạng trong thiết kế và màu sắc, giúp người dùng dễ dàng tìm thấy phiên bản phù hợp với phong cách cá nhân của mình.</p>\n<p>– Phiên bản tiêu chuẩn: Với gam màu trắng thanh lịch phiên bản này mang đến vẻ đẹp tinh tế và thời thượng, phù hợp cho những ai yêu thích sự đơn giản nhưng vẫn nổi bật.</p>\n<p>– Phiên bản cao cấp: Được trang bị hai màu sắc ấn tượng là đỏ và xanh,<b> lead 125 </b>cao cấp thu hút ánh nhìn ngay từ cái nhìn đầu tiên. Sự kết hợp giữa màu sắc tươi sáng và thiết kế hiện đại tạo nên một phong cách cuốn hút, lý tưởng cho những tín đồ yêu thích sự nổi bật.</p>\n<p>– Phiên bản đặc biệt: Nổi bật với màu xanh xám hoàn toàn mới kết hợp cùng sắc đen bí ẩn, phiên bản này mang đến một diện mạo mạnh mẽ và trẻ trung. Những tông màu này không chỉ thể hiện cá tính mà còn phản ánh phong cách sống năng động của người sử dụng.</p>\n<p>Logo hiện đại và tinh tế</p>\n<p>Logo <b>lead</b> được thiết kế tối giản nhưng lại là điểm nhấn nổi bật trên thân xe. Với chất liệu chrome cùng tông màu vàng nổi bật trên nền sơn nhám, logo toát lên hình ảnh tổng thể hiện đại và bắt mắt.</p>\n\n<p>Với sự đa dạng trong thiết kế và màu sắc, <b>mua xe lead</b> chắc chắn sẽ là lựa chọn lý tưởng cho những ai muốn khẳng định phong cách cá nhân trong từng chuyến đi.</p>\n<h2>2. Tìm hiểu về động cơ của xe máy Lead 125</h2>\n<p>Động cơ của xe máy <b>lead 125</b> là một bước tiến vượt bậc trong công nghệ động cơ Honda Việt Nam, đặc biệt trong phân khúc xe tay ga cao cấp. Với thiết kế tinh vi, động cơ này không chỉ mang lại hiệu suất hoạt động tối ưu mà còn đảm bảo khả năng vận hành mạnh mẽ và ổn định.&nbsp;</p>\n<p>Đặc biệt, dòng <b>xe lead</b> nổi bật với tính năng tiết kiệm nhiên liệu vượt trội, góp phần giảm thiểu tác động đến môi trường. Sự kết hợp hoàn hảo giữa công nghệ hiện đại và sự thân thiện với môi trường đã tạo nên một sản phẩm đáng chú ý trên thị trường xe máy.</p>\n\n<h2>3. Tìm hiểu về tiện ích và tính năng an toàn của Honda Lead</h2>\n<p><b>Xe máy lead</b> không chỉ nổi bật với thiết kế hiện đại mà còn được trang bị nhiều tiện ích và tính năng an toàn vượt trội, mang đến trải nghiệm lái xe tuyệt vời cho người sử dụng. Dưới đây là những điểm nổi bật về tiện ích và tính năng an toàn của mẫu <b>xe lead</b>.</p>\n<p><em>Hộc đựng đồ tiện lợi</em></p>\n<p>Một trong những cải tiến đáng chú ý nhất trên <b>xe lead </b>chính là hộc đựng đồ phía trước. Với dung tích lớn hơn và thiết kế sâu hơn, hộc đựng đồ này không chỉ giúp người dùng dễ dàng chứa đựng chai nước mà còn có thể lưu trữ nhiều vật dụng thiết yếu khác. Đặc biệt, cổng sạc USB Type C được tích hợp sẵn giúp bạn dễ dàng sạc pin điện thoại mọi lúc, mọi nơi, mang lại sự tiện lợi tối đa trong quá trình di chuyển.</p>\n\n<p><em>Cốp đựng đồ rộng rãi</em></p>\n<p>Cốp đựng đồ của <b>honda lead</b> có dung tích lên đến 37 lít nhờ vào thiết kế thông minh, tối ưu hóa không gian dưới yên xe. Điều này cho phép bạn chứa được hai mũ bảo hiểm cỡ lớn cùng nhiều vật dụng cá nhân khác một cách dễ dàng. Hơn nữa, việc tìm kiếm và sắp xếp đồ đạc trong cốp trở nên đơn giản hơn bao giờ hết nhờ vào hệ thống đèn soi sáng và tấm chia ngăn mới. Bạn sẽ không còn phải lo lắng về việc tìm kiếm đồ vật trong bóng tối hay khi di chuyển.</p>\n\n<p><em>Hệ thống khóa thông minh Smart Key</em></p>\n<p><b>Lead 125</b> được trang bị hệ thống khóa thông minh Smart Key, mang lại sự tiện lợi và an tâm cho người sử dụng. Tính năng xác định vị trí và mở/khóa xe từ xa giúp bạn dễ dàng kiểm soát chiếc xe của mình mà không cần phải mất thời gian tìm chìa khóa. Bên cạnh đó, tính năng báo động cũng được tích hợp để bảo vệ chiếc xe khỏi những tình huống không mong muốn.</p>\n\n<p><em>Mặt đồng hồ hiện đại</em></p>\n<p>Mặt đồng hồ trên xe Lead đã được cải tiến với sự kết hợp hoàn hảo giữa chỉ số analog và kỹ thuật số. Thiết kế tinh tế cùng với các đường nét hài hòa giúp người dùng dễ dàng theo dõi thông tin cần thiết trong mọi điều kiện di chuyển. Điều này không chỉ nâng cao tính thẩm mỹ mà còn đảm bảo sự tiện lợi cho người lái.</p>\n\n<p><em>Hệ thống chống bó cứng phanh ABS</em></p>\n<p>Đặc biệt, phiên bản đặc biệt của <b>xe máy lead </b>còn được trang bị hệ thống chống bó cứng phanh ABS. Tính năng này giúp hạn chế tình trạng trượt bánh khi phanh gấp ở tốc độ cao hoặc trên những mặt đường trơn trượt. Nhờ đó, người lái có thể tự tin khám phá mọi cung đường mà không lo lắng về vấn đề an toàn.</p>\n<p><b>Xe tay ga lead </b>là một lựa chọn hoàn hảo cho những ai đang tìm kiếm một phương tiện di chuyển vừa hiện đại vừa an toàn. Với nhiều tiện ích thông minh như hộc đựng đồ rộng rãi, cốp chứa lớn cùng hệ thống khóa thông minh và mặt đồng hồ hiện đại, chiếc xe này chắc chắn sẽ đáp ứng tốt nhu cầu của người sử dụng. </p>\n<p>Hệ thống chống bó cứng phanh ABS cũng là một điểm cộng lớn giúp tăng cường độ an toàn khi lái xe trên mọi địa hình. Nếu bạn đang cân nhắc lựa chọn một chiếc xe tay ga chất lượng cao thì<b> mua xe lead </b>chính là sự lựa chọn lý tưởng dành cho bạn!</p>\n<h2>4. Cập nhật giá xe LEAD mới chính hãng của Honda&nbsp;</h2>\n<p>Theo thông tin mới nhất từ các <a href=\"/xe-may?nhom=honda\"><b>đại lý honda</b></a> chính hãng, <b>giá xe lead</b> hiện đang dao động trong khoảng từ 40.300.000đ đến 43.700.000đ, tùy thuộc vào từng phiên bản và khu vực phân phối mà <b>giá xe lead </b>sẽ có sư chênh lệch. Khách hàng nên tham khảo kỹ lưỡng để chọn lựa phiên bản phù hợp nhất với nhu cầu của mình.</p>\n<p>Với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh xe máy, Hệ thống Siêu Thị Yên Thoa tự hào là đại lý chính hãng của Honda, chuyên cung cấp các dòng xe máy chất lượng. Chúng tôi không chỉ chú trọng đến việc mang đến những sản phẩm tốt nhất mà còn đặc biệt quan tâm đến trải nghiệm của khách hàng.</p>\n\n<p>Tại Yên Thoa, đội ngũ nhân viên chuyên nghiệp và tận tâm sẽ luôn sẵn sàng hỗ trợ quý khách hàng mọi lúc. Chúng tôi cam kết giải đáp mọi thắc mắc và vấn đề của quý khách một cách nhanh chóng và hiệu quả nhất.</p>\n<p>Đặc biệt, khi<b> mua xe lead</b> tại Yên Thoa, quý khách sẽ được hưởng chính sách hỗ trợ mua xe trả góp với thủ tục đơn giản và nhanh chóng. Chỉ cần thanh toán trước 10% giá trị xe, quý khách đã có thể rước chiếc xe yêu thích về ngay!</p>\n<p>Nếu quý khách đang cần <a href=\"/xe-may\"><b>mua xe máy</b></a> hoặc muốn tham khảo <b>giá xe lead</b>, hãy liên hệ với chúng tôi qua hotline để được tư vấn tận tình và chu đáo nhất!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
