INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-lexi', 'Xe Lexi', 'yamaha', '[]', 48650000, 49050000, '/sites/yenthoa/img/2024/11/lexi-phien-ban-cao-cap-mau-xanh-reu-nham.webp', '[\"/sites/yenthoa/img/2024/11/lexi-phien-ban-cao-cap-mau-xanh-reu-nham.webp\"]', '[\"Bạc ánh kim\",\"Đen nhám\",\"Đỏ ánh kim\",\"Xám nhám\",\"Xanh dương nhám\",\"Xanh rêu nhám\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc ánh kim\"}],\"img\":\"/sites/yenthoa/img/2024/11/lexi-phien-ban-tieu-chuan-mau-bac-anh-kim.webp\",\"price\":48650000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ ánh kim\"}],\"img\":\"/sites/yenthoa/img/2024/11/lexi-phien-ban-tieu-chuan-mau-do-anh-kim.webp\",\"price\":48650000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xám nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/lexi-phien-ban-tieu-chuan-mau-xam-nham.webp\",\"price\":48650000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh dương nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/lexi-phien-ban-cao-cap-mau-xanh-duong-nham.webp\",\"price\":49050000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh rêu nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/lexi-phien-ban-cao-cap-mau-xanh-reu-nham.webp\",\"price\":49050000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đen nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/lexi-phien-ban-cao-cap-mau-den-nham.webp\",\"price\":49050000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"Động cơ xăng, 4 kỳ, 1 xi lanh, làm mát bằng chất lỏng\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xi lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"155,1 cc\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"58,0 x 58,7\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,6:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"11,3 kW/ 8000 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"14,2 N.m/ 6500 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Khởi động điện\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,2 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"2,19\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"Tỷ số truyền đai: 0,724 ~ 2,30/ Tỷ số truyền toàn bộ: 7,391 ~ 23,478/ Tỷ số truyền cuối cùng: 56/16 x 35/12 = 10,208\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"Ly hợp ly tâm tự động\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Underbone\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Lò xo trụ, giảm chấn thuỷ lực\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Lò xo trụ, giảm chấn thuỷ lực\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa, dẫn động thuỷ lực, trang bị ABS\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh tang trống, dẫn động cơ\"},{\"label\":\"Lốp trước\",\"value\":\"90/90-14M/C 46P\"},{\"label\":\"Lốp sau\",\"value\":\"100/90-14M/C 57P\"},{\"label\":\"Đèn trước/đèn sau\",\"value\":\"LED\"},{\"label\":\"Đèn pha/Đèn báo rẽ (trước/sau)\",\"value\":\"12V 10W/12V 10W\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1968 x 719 x1138 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"768 mm\"},{\"label\":\"Chiều dài cơ sở\",\"value\":\"1353 mm\"},{\"label\":\"Trọng lượng\",\"value\":\"118 kg\"},{\"label\":\"Khoảng sáng gầm xe tối thiểu\",\"value\":\"135 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30,000 km tuỳ theo điều kiện nào đến trước\"}]}]', '<p>Xe lexi là biểu tượng của sự kết hợp hoàn hảo giữa phong cách thể thao và tinh tế hiện đại. Nếu bạn đang tìm kiếm một địa chỉ để mua xe yamaha lexi, xe máy Yên Thoa chính là lựa chọn hàng đầu dành cho bạn.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE LEXI 155 GIÁ RẺ CHÍNH HÃNG TẠI ĐẠI LÝ YAMAHA</h2>\n<p>Với thông điệp “Both lives maximized – “Max” cả đôi đường” dòng <b>xe lexi</b> hoàn toàn mới đã tạo nên một sức hút khó cưỡng đối với người tiêu dùng. Dưới đây là những điểm nổi bật của dòng <b>xe yamaha lexi</b> hoàn toàn mới và <b>giá xe yamaha lexi</b> hiện nay.</p>\n\n<h2>1. Điểm nhấn nổi bật về thiết kế của dòng xe Lexi 155</h2>\n<p><b>Xe lexi</b> là biểu tượng của sự kết hợp hoàn hảo giữa phong cách thể thao mạnh mẽ và sự tinh tế hiện đại. Thiết kế của xe lấy cảm hứng từ dòng maxi scooter, với phần đầu xe đồ sộ gợi nhớ đến những mẫu môtô phân khối lớn, tạo nên một diện mạo đầy ấn tượng. Phần thân xe thon gọn dần về phía sau với khung kiểu underbone, mang lại vẻ ngoài mạnh mẽ nhưng không kém phần thanh lịch. Đặc biệt, vị trí ngồi rộng rãi và thoải mái cho hai người cùng chiều cao yên ở mức 768 mm, đảm bảo trải nghiệm lái xe dễ chịu và tiện lợi.</p>\n\n<p>Một trong những điểm nổi bật của <b>lexi 155</b> là sàn để chân phẳng hoàn toàn, mang lại sự thoải mái tối đa cho người lái ở bất kỳ tư thế nào. Thiết kế này giúp xua tan cảm giác mỏi mệt trong những chuyến đi dài, nâng cao trải nghiệm lái xe lên một tầm cao mới.</p>\n<p>Bánh xe của <b>yamaha lexi</b> cũng là một điểm nhấn đáng chú ý. Với lốp to bản có đường kính vành 14 inch cùng các vân gai cơ bắp trên lốp, chiếc xe không chỉ tăng cường độ bám đường mà còn thể hiện rõ nét sự cứng cáp và thể thao.</p>\n<p>Hệ thống chiếu sáng công nghệ LED hiện đại là một yếu tố không thể bỏ qua khi nói về thiết kế của <b>lexi 155</b>. Cụm đèn LED được thiết kế theo phong cách thể thao – hiện đại, tạo điểm nhấn ấn tượng cho phần đầu xe. Hệ thống chiếu sáng này không chỉ tăng cường tầm nhìn cho người lái khi di chuyển vào ban đêm mà còn góp phần nâng cao tính thẩm mỹ tổng thể của chiếc xe.</p>\n\n<p>Ngoài ra, hộc chứa đồ rộng rãi cũng là một ưu điểm nổi bật khác của xe<b> lexi 155</b>. Người dùng có thể dễ dàng đựng một mũ bảo hiểm 3/4 cùng các vật dụng cá nhân khác mà không gặp bất kỳ khó khăn nào.</p>\n<p>Về màu sắc, dòng<b> xe lexi</b> hiện đang có hai phiên bản với sáu màu sắc thời thượng. Những gam màu trendy này không chỉ mang lại vẻ sang trọng mà còn giúp khách hàng dễ dàng lựa chọn để phản ánh phong cách cá nhân riêng biệt.</p>\n<p>Với những đặc điểm nổi bật trên, <b>xe lexi</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang lại trải nghiệm lái thú vị và tiện nghi cho người sử dụng. Đây thực sự là lựa chọn lý tưởng cho những ai tìm kiếm một chiếc <a href=\"/xe-may?nhom=yamaha\"><b>xe yamaha</b></a> vừa thời trang vừa hiệu quả trong việc di chuyển hàng ngày.</p>\n<h2>2. Điểm nhấn nổi bật về động cơ và tiện ích của dòng xe yamaha lexi giá tốt</h2>\n<p>Dòng <b>xe yamaha lexi</b> không chỉ gây ấn tượng thiết kế hiện đại mà còn được trang bị hàng loạt công nghệ tiên tiến, mang đến trải nghiệm lái xe tuyệt vời cho người dùng.</p>\n<p><em>Mặt đồng hồ điện tử LCD sắc nét</em></p>\n<p><b>Lexi 155</b> tự hào sở hữu mặt đồng hồ điện tử LCD, hiển thị rõ ràng và đầy đủ các thông số quan trọng như tốc độ, mức xăng và vòng tua máy. Đặc biệt, màn hình này còn có khả năng kết nối với điện thoại thông qua ứng dụng Y-connect, cho phép người lái nhận thông báo mà không cần rời mắt khỏi đường.</p>\n\n<p><em>Cổng sạc USB tích hợp tiện lợi</em></p>\n<p>Với cổng sạc USB tích hợp trên<b> xe lexi</b>, bạn sẽ không còn lo lắng về việc thiết bị di động hết pin giữa chừng. Dù ở bất kỳ đâu, bạn cũng có thể dễ dàng sạc pin để duy trì kết nối liên tục và đảm bảo thiết bị luôn trong trạng thái “full pin”.</p>\n<p><em>Hệ thống khóa thông minh an toàn smartkey</em></p>\n<p><b>Xe Lexi</b> được trang bị hệ thống khóa smartkey hiện đại, nâng cao tính bảo mật và mang lại sự tiện lợi tối đa cho người sử dụng. Hệ thống này không chỉ bảo vệ xe tốt hơn mà còn thể hiện phong cách sống tiện nghi và hiện đại.</p>\n\n<p><em>Kết nối điện thoại qua Y-connect</em></p>\n<p>Tính năng kết nối điện thoại qua ứng dụng Y-connect là một điểm nhấn nổi bật của dòng <b>xe lexi</b>. Người dùng có thể dễ dàng theo dõi các thông báo từ điện thoại trực tiếp trên màn hình đồng hồ của xe, tạo nên sự thuận tiện tối đa trong quá trình sử dụng.</p>\n<p><em>Phanh ABS đảm bảo an toàn tuyệt đối</em></p>\n<p>Hệ thống phanh ABS (Anti-lock Braking System) trên <b>yamaha lexi</b> giúp tăng cường độ an toàn khi phanh gấp hoặc trong điều kiện đường trơn trượt. Công nghệ này ngăn chặn bánh xe bị khóa cứng khi phanh mạnh, đảm bảo an toàn tuyệt đối cho người lái.</p>\n\n<p><em>Động cơ Blue Core 155VVA mạnh mẽ và tiết kiệm nhiên liệu</em></p>\n<p><b>Xe Lexi </b>sở hữu động cơ Blue Core 155VVA mạnh mẽ nhưng vẫn tiết kiệm nhiên liệu. Công nghệ VVA (Variable Valve Actuation) tối ưu hóa hiệu suất động cơ ở mọi dải tốc độ, mang lại trải nghiệm lái mượt mà và tiết kiệm xăng hơn bao giờ hết.</p>\n\n<p><b>Yamaha Lexi</b> là sự kết hợp hoàn hảo giữa thiết kế tinh tế và công nghệ tiên tiến, hứa hẹn mang đến những hành trình thú vị và an toàn cho người dùng.</p>\n<h2>3. Địa chỉ mua xe lexi mới của yamaha giá tốt</h2>\n<p>Nếu bạn đang tìm kiếm một địa chỉ uy tín để mua<b> xe lexi</b>, Hệ thống Siêu Thị Yên Thoa chính là lựa chọn hàng đầu dành cho bạn. Là đại lý chính hãng của Yamaha, Yên Thoa cam kết mang đến cho khách hàng những trải nghiệm mua sắm tuyệt vời và đáng tin cậy nhất.</p>\n<p>Cập nhật <b>giá xe yamaha lexi </b>mới nhất hiện nay tại xe máy Yên Thoa&nbsp;</p>\n<p>– <b>Giá xe yamaha lexi</b> tiêu chuẩn: <strong>48.650.000đ</strong></p>\n<p>– <b>Giá xe yamaha lexi</b> cao cấp: <strong>49.050.000đ</strong></p>\n\n<p>Khi mua các dòng xe yamaha tại Yên Thoa trong ngày hôm nay, quý khách sẽ được hưởng những ưu đãi đặc biệt sau:</p>\n<p>– Mua xe trả góp với lãi suất cực thấp chỉ từ 0% thủ tục đơn giản và nhanh chóng chỉ cần CCCD hoặc CMND.</p>\n<p>– Dịch vụ giao xe tận nhà đáp ứng nhu cầu của khách hàng mọi lúc, mọi nơi.</p>\n<p>– Quà tặng hấp dẫn nhận ngay bộ quà tặng độc quyền trị giá 2.950.000 VNĐ khi mua xe.</p>\n<p>– Hỗ trợ thu cũ đổi mới giúp bạn dễ dàng nâng cấp lên dòng xe mới mà không cần lo lắng về chiếc xe cũ.</p>\n<p>Ngoài ra, còn có hàng ngàn quà tặng và chương trình khuyến mãi hấp dẫn khác đang chờ đón quý khách. Nếu bạn quan tâm đến việc sở hữu một chiếc <strong>xe máy</strong> chất lượng và cần tham khảo <b>giá xe yamaha lexi</b>, hãy liên hệ ngay với Hệ thống Siêu Thị Yên Thoa qua hotline! Chúng tôi luôn sẵn sàng phục vụ và mang đến sự hài lòng tối đa cho quý khách hàng.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
