INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-mt-15', 'Xe MT15', 'yamaha', '[\"xe-the-thao\"]', 78150000, 78150000, '/sites/yenthoa/img/2024/11/mt-15-mau-xanh-den.webp', '[\"/sites/yenthoa/img/2024/11/mt-15-mau-xanh-den.webp\"]', '[\"Đen\",\"Xanh đậm Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/mt-15-mau-xanh-den.webp\",\"price\":78150000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/mt15-mau-den.webp\",\"price\":78150000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"4 thì, 1 xylanh, SOHC, làm mát bằng chất lỏng\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"155,2cc\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"58 x 58,7 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,6 : 1\"},{\"label\":\"Công suất tối đa\",\"value\":\"14,2 kW (19,3 PS)/10.000 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"14,7 N.m (1,5kgf.m)/8.500 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"1,05 lít\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"10 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"1,94\"},{\"label\":\"Bộ chế hòa khí\",\"value\":\"Hệ thống phun xăng điện tử\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"3,042 - 3,714\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Ly hợp ướt, đa đĩa\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"Bánh răng ăn khớp, 6 số\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Thép biên dạng kim cương\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Hành trình ngược (Upside down)\"},{\"label\":\"Hành trình phuộc trước\",\"value\":\"130 mm\"},{\"label\":\"Độ lệch phương trục lái\",\"value\":\"25,7° /89mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Tay xoay liên kết\"},{\"label\":\"Hành trình giảm xóc sau\",\"value\":\"108 mm\"},{\"label\":\"Phanh trước\",\"value\":\"Đĩa đơn thuỷ lực\"},{\"label\":\"Phanh sau\",\"value\":\"Đĩa đơn thuỷ lực\"},{\"label\":\"Lốp trước\",\"value\":\"110/70 - 17 M/C 54S (lốp không săm)\"},{\"label\":\"Lốp sau\",\"value\":\"140/70 - 17 M/C 66S (lốp không săm)\"},{\"label\":\"Đèn trước\",\"value\":\"LED\"},{\"label\":\"Đèn sau\",\"value\":\"LED\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1965 mm x 800 mm x 1065 mm\"},{\"label\":\"1965 mm x 800 mm x 1065 mm\",\"value\":\"810 mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"170 mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1335 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"133 kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000 km (tuỳ theo điều kiện nào đến trước)\"}]}]', '<p>Yamaha mt 15 mang trong mình dáng vẻ của một “chiến binh” mạnh mẽ, tiếp nối tinh hoa của dòng xe MT-Series danh tiếng. Hãy cùng khám phá sức hút đặc biệt và giá xe mt 15 qua bài viết dưới đây.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE MT 15 DÒNG XE THỂ THAO MẠNH MẼ CỦA YAMAHA&nbsp;</h2>\n<p>Dòng xe <b>yamaha mt 15</b>&nbsp;nổi tiếng với thiết kế mạnh mẽ và đầy cá tính. Được trang bị động cơ 155cc cùng công nghệ van biến thiên VVA tiên tiến, <b>mt 15</b> mang lại hiệu suất vượt trội, trở thành lựa chọn hàng đầu cho những tín đồ đam mê tốc độ. Hãy cùng khám phá sức hút đặc biệt và <b>giá xe mt 15</b> qua bài viết dưới đây.</p>\n\n<h2>1. Thiết kế mạnh mẽ của dòng xe MT15&nbsp;</h2>\n<p><b>Yamaha mt 15</b> mang trong mình dáng vẻ của một “chiến binh” mạnh mẽ, tiếp nối tinh hoa của dòng xe MT-Series danh tiếng. Với hình dáng thon gọn nhưng không kém phần uy lực, <b>xe mt 15</b> gây ấn tượng mạnh mẽ ngay từ cái nhìn đầu tiên. Bình xăng xe được thiết kế gồ cao cùng với cánh gió sắc sảo tạo nên một tổng thể hài hòa, vừa thể hiện sự cá tính vừa toát lên vẻ đẹp tinh tế.</p>\n<p>Mỗi chi tiết trên <b>xe mt 15</b> đều được chăm chút tỉ mỉ để phản ánh sự mạnh mẽ và năng động. Không chỉ dừng lại ở thiết kế ngoại hình, chiếc xe còn được trang bị những công nghệ tiên tiến và các tính năng cao cấp, giúp nâng tầm trải nghiệm cho người sử dụng. Những trang bị này không chỉ làm cho yamaha mt 15 trở nên nổi bật trên đường phố mà còn khẳng định đẳng cấp của chủ nhân sở hữu.&nbsp;</p>\n<figure><img src=\"/sites/yenthoa/img/2024/11/mt-15-mau-xanh-den.webp\" alt=\"\" loading=\"lazy\" width=\"1040\" height=\"800\"><figcaption><em>Thiết kế mạnh mẽ của dòng xe moto MT15&nbsp;</em></figcaption></figure>\n<p>Yamaha đã thành công trong việc tạo ra một mẫu xe không chỉ vượt trội về hiệu suất mà còn là biểu tượng của phong cách và đẳng cấp. Dòng xe moto <strong>mt</strong><strong>15</strong> không đơn thuần chỉ là phương tiện di chuyển mà nó là một tuyệt tác nghệ thuật mang đến trải nghiệm lái xe đầy phấn khích và cảm giác tự do không giới hạn. Với vẻ ngoài đậm chất phân khối lớn, chiếc xe này chắc chắn sẽ thu hút mọi ánh nhìn và làm say lòng những ai đam mê tốc độ.&nbsp;</p>\n<h2>2. Động cơ và tính năng của xe Yamaha MT 15</h2>\n<p><b>Yamaha mt 15 </b>là một trong những mẫu xe nổi bật trong phân khúc thể thao naked bike, dòng xe này đã thu hút sự chú ý của nhiều người yêu xe nhờ vào thiết kế mạnh mẽ và hiệu suất ấn tượng. Hãy cùng khám phá những điểm nổi bật về động cơ và tính năng của<b> xe mt 15</b></p>\n<p><em>Động cơ mạnh mẽ và tiên tiến</em></p>\n<p><b>Yamaha mt 15 </b>được trang bị động cơ 155cc vượt trội, tích hợp công nghệ van biến thiên VVA hiện đại nhất. Điều này không chỉ mang đến khả năng tăng tốc mượt mà mà còn tạo ra trải nghiệm lái đầy phấn khích và hiệu quả. Hộp số 6 cấp kết hợp với bộ nồi chống trượt giúp người lái dễ dàng kiểm soát khi chuyển số đột ngột, tăng cường sự an toàn và tiện lợi trong quá trình điều khiển.</p>\n\n<p><em>Màn hình kỹ thuật số hiện đại</em></p>\n<p>Cụm đồng hồ của <b>mt15 </b>sử dụng công nghệ màn hình LCD sắc nét, hiển thị trực quan nhiều thông số vận hành cần thiết. Điều này không chỉ giúp người lái dễ dàng quan sát mà còn tăng thêm vẻ hiện đại cho chiếc xe.</p>\n\n<p><em>Phuộc trước Upside Down mạnh mẽ</em></p>\n<p>Thiết kế phuộc trước Upside Down tạo điểm nhấn khỏe khoắn và nổi bật cho phần đầu xe. Kết hợp với tay lái đúc nguyên khối, hệ thống này mang lại cảm giác lái êm ái và linh hoạt hơn, nâng cao trải nghiệm điều khiển xe.</p>\n\n\n<p><em>Hệ thống đèn LED tối ưu</em></p>\n<p>Hệ thống đèn pha LED của <b>Yamaha mt 15</b> được thiết kế theo phong cách tối giản nhưng đầy tính thể thao, đảm bảo khả năng chiếu sáng tối ưu. Đèn định vị có thiết kế ấn tượng và sắc sảo như đôi mắt dũng mãnh của một thú săn mồi, tạo nên diện mạo cuốn hút cho chiếc xe.</p>\n\n<p><em>Bánh xe hợp kim đúc 17 inch</em></p>\n<p>Với kích thước lớn 17 inch, bánh xe của<b> mt15 </b>được chế tạo từ hợp kim đúc không chỉ nâng cao cảm giác lái mạnh mẽ mà còn mang đến trải nghiệm tăng tốc vượt trội, đặc biệt khi thực hiện các khúc cua. Thiết kế này không chỉ cải thiện hiệu suất vận hành mà còn góp phần tạo nên vẻ ngoài thể thao và hiện đại cho chiếc xe của bạn.</p>\n\n<h2>3. Giá xe MT 15 chính hãng giá tốt tại Hệ thống Siêu Thị Yên Thoa</h2>\n<p>Quý khách hàng đang có nhu cầu mua <b>xe mt 15</b>? Quý khách đang muốn tham khảo <b>giá xe mt 15</b>? Hãy liên hệ với Yên Thoa ngay hôm nay. Là đại lý chính hãng của Yamaha, Hệ thống Siêu Thị Yên Thoa luôn cập nhật đầy đủ các phiên bản và màu sắc mới nhất của <b>yamaha mt 15</b>. Nếu bạn đang tìm kiếm thông tin về <b>giá xe mt 15</b>, đừng ngần ngại liên hệ với chúng tôi để được tư vấn chi tiết và tận tình.</p>\n<p>Hiện tại, <b>giá xe mt 15</b> tại Yên Thoa đang là <b>78.150.000đ</b> (Lưu ý: giá xe có thể thay đổi tuỳ theo từng thời điểm)</p>\n\n<p>Tại Hệ thống Siêu Thị Yên Thoa, chúng tôi luôn đặt khách hàng lên hàng đầu và không ngừng nỗ lực để mang đến những trải nghiệm mua sắm hoàn hảo nhất. Dưới đây là những ưu đãi hấp khi mua xe tại Yên Thoa.</p>\n<p>– Combo quà tặng giá trị: Khi <strong>mua xe máy</strong> tại Xe máy Yên Thoa, quý khách sẽ được tặng ngay combo quà tặng độc quyền trị giá 2.950.000đ, bao gồm 13 phần quà hấp dẫn.</p>\n<p>– Dịch vụ thu xe cũ đổi xe mới: Chương trình hỗ trợ thu lại xe cũ với mức giá hợp lý giúp khách hàng dễ dàng lên đời xe mới và tiết kiệm chi phí một cách hiệu quả.</p>\n<p>– Dịch vụ giao xe tận nhà tiện lợi: Để mang lại sự tiện lợi tối đa cho khách hàng, chúng tôi còn cung cấp dịch vụ giao xe tận nhà theo yêu cầu.&nbsp;</p>\n<p>– Chế độ bảo hành chính hãng: Hệ thống Siêu Thị Yên Thoa cam kết bảo hành sản phẩm theo đúng quy định của hãng sản xuất, đảm bảo sự yên tâm tuyệt đối cho quý khách khi mua xe tại cửa hàng.</p>\n<p>– Tặng thêm 18 tháng kiểm tra định kỳ miễn phí: Sau khi hết thời gian bảo hành chính hãng, quý khách sẽ được tặng thêm 18 tháng kiểm tra định kỳ miễn phí để đảm bảo chiếc xe luôn hoạt động trong tình trạng tốt nhất.</p>\n<p>Ngoài ra, Hệ thống Siêu Thị Yên Thoa còn cung cấp các chính sách hỗ trợ trả góp linh hoạt và đa dạng. Chỉ cần thanh toán trước 0đ, quý khách đã có thể sở hữu ngay chiếc <a href=\"/xe-may?nhom=yamaha\"><strong>xe yamaha</strong></a> mơ ước với thủ tục đơn giản và nhanh chóng. Chúng tôi cũng cung cấp nhiều gói lãi suất hấp dẫn phù hợp với nhu cầu tài chính của mọi đối tượng khách hàng.&nbsp;Hãy liên hệ ngay với chúng tôi qua hotline để cập nhật <b>giá xe mt 15</b> và chương trình mãi mới nhất hiện nay!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
