UPDATE products SET specs = '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"Blue Core, 4 thì, 4 van, SOHC, làm mát bằng dung dịch\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"155,1 cc\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"58 x 58,7mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,6:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"11,3kW (15,4 PS)/8.000 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"13,9 N.m (1,4kgf.m)/6.500 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"5,5 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"2,19\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"2,300-0,724:1\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"CVT\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Backbone\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Phuộc ống lồng\"},{\"label\":\"Hành trình phuộc trước\",\"value\":\"Phuộc nhún lò xo/Giảm chấn dầu\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa thuỷ lực, trang bị ABS, đường kính 230mm\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh cơ (đùm), đường kính 130mm\"},{\"label\":\"Lốp trước\",\"value\":\"110/80-14M/C 53P (Lốp không săm)\"},{\"label\":\"Lốp sau\",\"value\":\"140/70-14M/C 62P (Lốp không săm)\"},{\"label\":\"Đèn trước\",\"value\":\"LED\"},{\"label\":\"Đèn trước/đèn sau\",\"value\":\"LED/ 12V, 10Wx2\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1.980mm x 700mm x 1.150mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"790 mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"145mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1.350mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"125kg\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"5,5L\"},{\"label\":\"găn chứa đồ\",\"value\":\"25\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]' WHERE slug = 'xe-nvx-155' AND specs IS NULL;
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-pg1', 'Xe PG1', 'yamaha', '[\"xe-so\"]', 36500000, 41000000, '/sites/yenthoa/img/2025/09/pg1-2026.webp', '[\"/sites/yenthoa/img/2025/09/pg1-2026.webp\"]', '[\"Cam Bạc\",\"Đen Bạc\",\"Đỏ bóng\",\"Đỏ Đen\",\"Ghi đậm\",\"Nâu Cát\",\"Vàng Đen\",\"Vàng Đen Bạc\",\"Xám Đen Bạc\",\"Xanh Camo\",\"Xanh dương\",\"Xanh Đen\",\"Xanh Đen Bạc\",\"Xanh rêu Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn mới\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2026/01/pg1-phien-ban-tieu-chuan-2026-mau-xanh-den-bac.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn mới\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2026/01/pg1-phien-ban-tieu-chuan-2026-mau-xam-den-bac.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn mới\"},{\"name\":\"Màu sắc\",\"value\":\"Vàng Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2026/01/pg1-phien-ban-tieu-chuan-2026-mau-vang-den-bac.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn mới\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2026/01/pg1-phien-ban-tieu-chuan-2026-mau-den-bac.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2025/09/pg1-abs-do-den.webp\",\"price\":41000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen\"}],\"img\":\"/sites/yenthoa/img/2025/09/pg1-abs-xanh-den.webp\",\"price\":41000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp ABS\"},{\"name\":\"Màu sắc\",\"value\":\"Mặc định\"}],\"img\":\"/sites/yenthoa/img/2025/09/pg1-abs-xam-den.webp\",\"price\":41000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Giới hạn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Camo\"}],\"img\":\"/sites/yenthoa/img/2025/09/pg1-2026-xanh-camo.webp\",\"price\":41000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Cam Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/pg1-mau-cam-bac.webp\",\"price\":36500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/pg1-mau-den-bac.webp\",\"price\":36500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Nâu Cát\"}],\"img\":\"/sites/yenthoa/img/2024/11/pg1-mau-nau-cat.webp\",\"price\":36500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Vàng Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/pg1-mau-vang-den.webp\",\"price\":36500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh dương\"}],\"img\":\"/sites/yenthoa/img/2024/11/pg1-mau-xanh-duong.webp\",\"price\":36500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh rêu Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/pg1-mau-xanh-reu-den.webp\",\"price\":36500000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"4 kỳ, 2 van, SOHC, làm mát bằng không khí\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xi lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"113.7 cm3\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"50.0 x 57.9 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9.3:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"6.6kW/ 7,000 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"9.5Nm/ 5,500 vòng/ phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Khởi động điện\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Cacte ướt\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"0.8 L\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"5.1 L\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"1,69L\"},{\"label\":\"Bộ chế hòa khí\",\"value\":\"Phun xăng điện tử\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI (kỹ thuật số)\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"2.900 (58/20) / 3.077 (40/13)\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Đa đĩa ly tâm tự động loại ướt\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"1: 2.833 (34/ 12)/ 2:1875 (30/ 16)/ 3: 1.353 (23/17)/ 4: 1.045 (23/ 22)\"},{\"label\":\"Điện áp ắc quy\",\"value\":\"12V 3Ah (10HR)\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Khung xương sống\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Phuộc ống lồng\"},{\"label\":\"Hành trình phuộc trước\",\"value\":\"130 mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Giảm xóc tay đòn (hệ thống treo liên kết)\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa đơn/ Thuỷ lực\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh tang trống/ Cơ khí\"},{\"label\":\"Lốp trước\",\"value\":\"90/ 100-16M/ C 51P (lốp có săm)\"},{\"label\":\"Lốp sau\",\"value\":\"90/ 100-16M/ C 51P (lốp có săm)\"},{\"label\":\"Đèn pha/Đèn báo rẽ (trước/sau)\",\"value\":\"35W/ 10W\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1,980 mm x 805 mm x 1,050 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"795 mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1,280 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"107 kg (Khối lượng bản thân)\"},{\"label\":\"Khoảng sáng gầm xe tối thiểu\",\"value\":\"190 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30,000 km tuỳ theo điều kiện nào đến trước\"}]}]', '<p>Yamaha pg1 đã nhanh chóng gây ấn tượng mạnh mẽ nhờ vào thiết kế đột phá và phong cách hoàn toàn mới. Với vẻ ngoài cuốn hút, xe pg1 đã chinh phục người dùng ngay từ cái nhìn đầu tiên. Hãy cùng Yên Thoa khám phá chi tiết về thiết kế và giá pg1.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE PG1 KHUYẾN MÃI CỰC RẺ TẠI ĐẠI LÝ YAMAHA</h2>\n<p>Dù mới được ra mắt, <b>yamaha pg1</b> đã nhanh chóng gây ấn tượng mạnh mẽ trong cộng đồng yêu xe nhờ thiết kế đột phá và phong cách hoàn toàn mới lạ so với các dòng xe số trước đây. Với vẻ ngoài cuốn hút, <b>xe pg1</b> đã chinh phục người dùng ngay từ cái nhìn đầu tiên. Hãy cùng Yên Thoa khám phá chi tiết về thiết kế và <b>giá xe pg1</b> khuyến mãi cực rẻ tại đại lý yamaha trong bài viết dưới đây.</p>\n\n<h2>1. Thiết kế và màu sắc của xe pg1</h2>\n<p>Với thông điệp mạnh mẽ “Phiêu Cùng Tự Do – Free To Wander”, Yamaha đã chính thức khởi động một hành trình mới đầy thách thức trong việc chinh phục thị trường xe máy. Dòng <b>xe pg-1</b> không chỉ đơn thuần là một sản phẩm, mà còn là biểu tượng của sự tiên phong và sáng tạo, thể hiện tầm nhìn vượt thời gian của Yamaha trong việc đáp ứng nhu cầu và mong muốn của những người yêu thích tốc độ.</p>\n<p><b>Yamaha pg1</b> được thiết kế đặc biệt dành cho giới trẻ – những cá nhân năng động, đam mê khám phá và luôn tìm kiếm những trải nghiệm mới mẻ. Mỗi chi tiết trên chiếc xe đều được chăm chút tỉ mỉ nhằm tạo ra một sản phẩm hoàn hảo về cả chất lượng lẫn thẩm mỹ.</p>\n<p>Một trong những điểm nổi bật nhất của <b>xe pg-1</b> chính là bảng màu sắc đa dạng. Hiểu rõ tâm lý và sở thích của giới trẻ, Yamaha đã lựa chọn những gam màu tươi sáng, năng động nhưng vẫn giữ được sự tinh tế. Đặc biệt, hãng đã mạnh dạn áp dụng các tông màu pastel – xu hướng đang rất được ưa chuộng hiện nay. Những gam màu này không chỉ mang lại cảm giác nhẹ nhàng mà còn giúp chiếc xe trở nên nổi bật và khác biệt giữa đám đông.</p>\n\n<p><b>Xe pg-1</b> có tổng cộng 6 màu sắc khác nhau đối với phiên bản 2024 và 4 màu sắc khác nhau đối với phiên bản 2026, mỗi màu sắc đều mang một cá tính riêng biệt từ sôi nổi đến trưởng thành. Sự phối hợp hài hòa giữa hai mảng màu không chỉ giúp <b>xe máy pg1</b> tránh khỏi sự nhàm chán mà còn khẳng định vị thế độc đáo trên thị trường xe máy hiện nay.&nbsp;</p>\n<p><em>Thiết kế vừa cổ điển vừa hiện đại đầy độc đáo</em></p>\n<p><b>Xe máy pg1</b> sở hữu thiết kế hoàn toàn mới lạ, không giống bất kỳ dòng xe nào khác trên thị trường. Sự đổi mới này thể hiện rõ tham vọng của Yamaha trong việc chinh phục thị trường bằng cách cải cách và sáng tạo nên những xu hướng đi đầu.</p>\n<p>Ngay từ cái nhìn đầu tiên, người dùng có thể dễ dàng nhận thấy những điểm nhấn thiết kế ấn tượng trên dòng <strong>xe pg1</strong>:</p>\n<p>– Cụm đồng hồ analog của <strong>xe pg1</strong> được thiết kế tinh tế, hiển thị rõ ràng các thông số cần thiết, giúp người lái dễ dàng nắm bắt tình trạng xe chỉ trong tích tắc. Đặc biệt, mặt đồng hồ còn tích hợp hiển thị cấp số, mang lại sự tiện lợi tối đa trong suốt hành trình.</p>\n<p>– Đèn pha phía trước mang đậm phong cách cổ điển của các dòng mô tô thể thao phân khối lớn, tạo nên vẻ oai vệ và mạnh mẽ cho chiếc xe. Vị trí lắp đặt đèn được tối ưu hóa gần khung sườn, không chỉ tăng tính thẩm mỹ mà còn đảm bảo hiệu suất chiếu sáng tốt nhất.</p>\n<p>– Đèn hậu được thiết kế sắc nét và hiện đại hơn, không chỉ làm tăng thêm vẻ đẹp cho <b>xe pg1</b> mà còn đảm bảo cung cấp đủ ánh sáng trong mọi điều kiện đường xá.</p>\n<p><em>Thiết kế đèn phía trước và đèn hậu thẩm mỹ, đảm bảo hiệu suất</em></p>\n<p>– Phần vè chắn bùn phía sau có kiểu dáng ngắn gọn nhưng vẫn hài hòa với tổng thể chiếc xe, tạo cảm giác linh hoạt và gọn gàng cho người sử dụng.– Ghi đông được chú trọng đến sự thoải mái của người lái với tư thế thẳng lưng. Độ cứng của ghi đông cũng được tối ưu hóa để phù hợp với nhiều dáng người khác nhau, mang lại trải nghiệm lái xe dễ chịu.– Tay dắt ở yên sau tuy đơn giản nhưng rất tiện dụng; dễ dàng cầm nắm và hỗ trợ tốt trong nhiều tình huống di chuyển khác nhau, giúp việc điều khiển trở nên thuận lợi hơn bao giờ hết.</p>\n<p>Với tất cả những tính năng vượt trội cùng thiết kế cuốn hút, <b>giá xe pg1 </b>hiện đang ở mức rất cạnh tranh. Có thể nói rằng <b>xe pg-1 </b>xứng đáng là một trong những lựa chọn hàng đầu cho những ai đang tìm kiếm một chiếc xe máy vừa đẹp vừa chất lượng tại thời điểm này!</p>\n<h2>2. Động cơ và tính năng nổi bật của xe pg-1 </h2>\n<p><em>Động cơ mạnh mẽ, bứt tốc ấn tượng</em></p>\n<p><b>Yamaha pg1</b> là một trong các loại xe số yamaha nổi bật trên thị trường với động cơ 115 phân khối, mang đến sức mạnh vượt trội và khả năng bứt tốc nhanh chóng. Sở hữu thiết kế tối ưu, PG1 không chỉ giúp người lái dễ dàng di chuyển trên các loại địa hình khác nhau mà còn mang lại trải nghiệm lái xe thú vị và đầy phấn khích.</p>\n\n<p><em>Hệ thống phanh an toàn và hiện đại</em></p>\n<p>Một trong những điểm nhấn đáng chú ý của <b>xe máy pg1 </b>chính là hệ thống phanh trước được trang bị phanh đĩa, đảm bảo an toàn tối đa khi cần phải dừng gấp. Thiết kế này không chỉ nâng cao tính năng an toàn mà còn tạo nên vẻ đẹp hiện đại, hòa quyện giữa phong cách cổ điển và sự tinh tế, giúp <strong>xe pg1</strong> nổi bật hơn so với các dòng xe khác.</p>\n<p><em>Lốp xe lớn với độ bám đường xuất sắc</em></p>\n<p><b>Yamaha pg1</b> được trang bị lốp xe lớn với kích thước 16 inch cho cả bánh trước và bánh sau, cùng với thiết kế gai vuông đặc trưng. Điều này không chỉ giúp xe duy trì sự ổn định trên mọi địa hình mà còn tăng cường độ bám đường nhờ vào các vân gai được thiết kế tỉ mỉ. Sự kết hợp này mang lại cảm giác lái an toàn và tự tin cho người sử dụng trong mọi tình huống.</p>\n<p><em>Chiều cao yên xe lý tưởng</em></p>\n<p>Một trong những điểm đặc biệt của <b>xe pg1 </b>chính là chiều cao yên xe được điều chỉnh ở mức 795 mm. Thiết kế này phù hợp với chiều cao trung bình của người Việt Nam, giúp người có chiều cao khiêm tốn dễ dàng đặt chân xuống đất và kiểm soát xe tốt hơn trong mọi tình huống di chuyển.</p>\n<p><em>Ổ khóa cơ đơn giản nhưng bền bỉ</em></p>\n<p><b>Yamaha pg1</b> sử dụng ổ khóa dạng cơ đơn giản nhưng rất bền bỉ theo thời gian. Thiết kế này của <strong>xe pg1</strong> không chỉ phù hợp với vẻ đẹp cổ điển của chiếc xe mà còn tạo nên sự hài hòa cuốn hút đối với người dùng.</p>\n<p><em>Bình xăng dung tích lớn</em></p>\n<p>Với dung tích lên đến 5.1 lít, bình xăng của <b>xe pg1 </b>cho phép di chuyển xa hơn so với nhiều dòng xe máy khác hiện nay. Đặc biệt, mức tiêu hao nhiên liệu chỉ khoảng 1,69 lít/100 km, mang lại hiệu quả tiết kiệm đáng kể cho người sử dụng.</p>\n<p><em>Thiết kế yên xe độc đáo</em></p>\n<p>Yên xe được thiết kế xẻ đôi, thể hiện rõ nét truyền thống của những chiếc xe số Việt Nam từ nhiều năm trước. Hai phần yên tách rời giúp cả người lái và hành khách có thể tự do điều chỉnh tư thế ngồi thoải mái nhất.</p>\n<p>Việc sở hữu một chiếc <b>xe máy pg1</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang lại trải nghiệm lái xe thoải mái và tiết kiệm. Với những tiện ích nổi bật cùng thiết kế tinh tế,<b> xe pg-1</b> chắc chắn sẽ làm hài lòng cả những khách hàng khó tính nhất. Hãy để <b>yamaha pg1</b> trở thành người bạn đồng hành đáng tin cậy trên mỗi chặng đường!</p>\n<h2>3. Những điểm thay đổi đáng chú ý của PG-1 phiên bản 2026 so với phiên bản cũ</h2>\n<div>\n<p>So với phiên bản tiền nhiệm, <strong>xe&nbsp;pg1</strong> 2026 thực sự là một bước tiến dài, mang đến nhiều nâng cấp giá trị cả về thiết kế lẫn công nghệ. Dưới đây là những thay đổi nổi bật:</p>\n<p>– Trang bị phanh ABS: Nếu trước đây người dùng chỉ có hệ thống phanh cơ bản, thì nay <strong>xe pg1</strong> đã được tích hợp ABS cho bánh trước, nâng tầm an toàn khi vận hành.</p>\n<p>– Đồng hồ hiển thị LCD: Thay thế cho cụm đồng hồ analog truyền thống, PG-1 2026 sở hữu màn hình LCD tròn hiện đại, cung cấp nhiều thông số vận hành hơn.</p>\n\n<p>– Động cơ 115cc tối ưu mô-men xoắn: Động cơ được tinh chỉnh, cho khả năng bứt tốc mạnh mẽ ở dải tua thấp, đồng thời tiết kiệm nhiên liệu hơn so với thế hệ cũ.</p>\n<p>– Thiết kế đa dụng và tiện ích hơn: Ghi đông cao, yên ngồi thoải mái, khoảng sáng gầm xe lớn – tất cả tạo nên sự khác biệt rõ rệt so với phiên bản trước, giúp xe phù hợp cả đô thị lẫn đường trường.</p>\n<p>– Bộ lốp IRC bản rộng và hệ thống treo cải tiến: Mang đến cảm giác lái chắc chắn, êm ái hơn, điều mà bản cũ chưa thực sự làm tốt.</p>\n<p>Những thay đổi này cho thấy Yamaha không chỉ đơn giản “nâng cấp nhẹ”, mà thực sự mang đến một thế hệ <strong>xe pg1 hoàn toàn mới</strong>, đáp ứng tốt hơn nhu cầu ngày càng cao của người dùng.</p>\n</div>\n<h2>4. Cập nhật giá xe pg1 tại Xe máy Yên Thoa</h2>\n<p>Với uy tín và nhiều năm kinh nghiệm trong ngành kinh doanh xe gắn máy, Hệ thống Siêu Thị Yên Thoa tự hào là một trong những <b>đại lý xe máy</b> chính hãng hàng đầu, cung cấp các sản phẩm từ những thương hiệu nổi tiếng như Honda, Yamaha, SYM, Suzuki và xe điện Yadea.Chúng tôi cam kết mang đến cho khách hàng những sản phẩm chất lượng cao với mức giá hợp lý nhất.</p>\n<p>Đặc biệt, khi đến với Yên Thoa, quý khách sẽ hoàn toàn yên tâm về sự an toàn và độ tin cậy khi mua sắm xe máy. Hiện tại, các dòng xe Yamaha đang có mặt đầy đủ tại Yên Thoa với mức <b>giá xe pg-1</b> vô cùng hấp dẫn.</p>\n<ul>\n<li><b>Giá xe pg1</b> phiên bản 2024: 36.000.000đ</li>\n<li><b>Giá xe pg1 </b>phiên bản 2025: sẽ giao động từ 36.500.000đ đến 40 triệu đồng tuỳ vào từng thời điểm và khu vực</li>\n</ul>\n\n<div></div>\n<p>Không chỉ dừng lại ở những ưu đãi về giá cả, đội ngũ nhân viên chuyên nghiệp của <a href=\"/xe-may?nhom=yamaha\"><b>đại lý yamaha</b></a> Yên Thoa luôn sẵn sàng hỗ trợ và tư vấn tận tình cho quý khách mọi lúc mọi nơi. Chúng tôi cam kết mang đến trải nghiệm dịch vụ hoàn hảo nhất và giúp quý khách hiện thực hóa giấc mơ sở hữu chiếc xe máy yêu thích.</p>\n<p>Đừng ngần ngại liên hệ qua hotline hoặc ghé thăm trực tiếp cửa hàng để được tư vấn chi tiết!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA</strong></p>', 1);
