INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-priti-50cc', 'Xe Priti 50cc', 'sym', '[]', 26900000, 26900000, '/sites/yenthoa/img/2024/11/priti-50-mau-xanh-anh-bac.webp', '[\"/sites/yenthoa/img/2024/11/priti-50-mau-xanh-anh-bac.webp\"]', '[\"Trắng ánh Hồng\",\"Xanh ánh Bạc\",\"Xanh ánh Tím\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng ánh Hồng\"}],\"img\":\"/sites/yenthoa/img/2024/11/priti-50-mau-trang-anh-hong.webp\",\"price\":26900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh ánh Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/priti-50-mau-xanh-anh-bac.webp\",\"price\":26900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh ánh Tím\"}],\"img\":\"/sites/yenthoa/img/2024/11/priti-50-mau-xanh-anh-tim.webp\",\"price\":26900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,81 L/ 100 km\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng 4 kỳ, 01 xi lanh, làm mát bằng không khí\"},{\"label\":\"Đường kính xi lanh\",\"value\":\"37 mm\"},{\"label\":\"Hành trình pít tông\",\"value\":\"46 mm\"},{\"label\":\"Công suất lớn nhất/ tốc độ quay\",\"value\":\"2,5 kW/ 7500 vòng/ phút\"},{\"label\":\"Mô men xoắn lớn nhất/ tốc độ quay\",\"value\":\"3,2 Nm/ 7500 vòng/ phút\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"ECU\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Hệ thống truyền động\",\"value\":\"Tự động vô cấp\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống phanh trước\",\"value\":\"Phanh đĩa\"},{\"label\":\"Hệ thống phanh sau\",\"value\":\"Tang trống (đùm)\"},{\"label\":\"Phuộc trước\",\"value\":\"Lò xo trụ, Thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, Thủy lực\"},{\"label\":\"Vỏ/ lốp trước\",\"value\":\"Không ruột, 90/90-10\"},{\"label\":\"Vỏ/ lốp sau\",\"value\":\"Không ruột, 90/90-10\"},{\"label\":\"Đèn chiếu sáng phía trước\",\"value\":\"12V 15/15W\"},{\"label\":\"Đèn sau/ đèn phanh\",\"value\":\"12V 0.22W/2.2W\"},{\"label\":\"Đèn tín hiệu báo rẽ (4 cái)\",\"value\":\"12V 2.4W\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"93 kg\"},{\"label\":\"Kích thước bao: Dài x Rộng x Cao\",\"value\":\"1780 x 630 x 1060 mm\"},{\"label\":\"Khoảng cách hai trục\",\"value\":\"1250 mm\"},{\"label\":\"Khoảng cách gầm\",\"value\":\"99 mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"725 mm\"},{\"label\":\"Dung tích thùng nhiên liệu\",\"value\":\"6,5 L\"}]}]', '<p>Xe Priti 50cc nổi bật với thiết kế nhỏ gọn, lấy cảm hứng từ loài chim ruồi. Xe không chỉ có ngoại hình khác biệt so với các đối thủ cùng phân khúc mà còn sở hữu nhiều tiện ích.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>CẬP NHẬT GIÁ XE PRITI 50CC CỦA SYM MỚI NHẤT HÔM NAY</h2>\n<p>Mới đây, SYM Việt Nam đã cho ra mắt dòng xe <b>priti 50</b>, mẫu xe tay ga 50cc đầu tiên tại Việt Nam được trang bị hệ thống phun xăng điện tử EFI. Với hiệu suất vận hành mạnh mẽ, tiết kiệm nhiên liệu và thân thiện với môi trường, <b>xe priti 50cc</b> nổi bật với thiết kế nhỏ gọn, lấy cảm hứng từ loài chim ruồi. Xe không chỉ có ngoại hình khác biệt so với các đối thủ cùng phân khúc mà còn sở hữu nhiều tiện ích. </p>\n<p><b>Priti 50</b> chính&nbsp;là lựa chọn lý tưởng cho những bạn gái trẻ yêu thích sự năng động và cá tính. Hãy cùng Yên Thoa khám phá ngay <b>giá xe priti 50</b> và chi tiết dòng xe <b>sym priti 50cc</b> qua bài viết đây.</p>\n<h2>1. Thiết kế của dòng xe Priti 50cc&nbsp;</h2>\n<p>Dòng <b>xe priti 50cc </b>mang đến một thiết kế độc đáo, kết hợp giữa tính thẩm mỹ và sự tiện dụng, phù hợp với nhu cầu di chuyển của người dùng hiện đại. Với cảm hứng từ sự uyển chuyển và linh hoạt của chim ruồi, <b>priti 50cc</b> không chỉ là một phương tiện di chuyển mà còn là biểu tượng của phong cách sống năng động.</p>\n<p>Thiết kế thân xe&nbsp;</p>\n<p>Thân <b>xe priti 50cc</b> được thiết kế nhỏ gọn, với trọng lượng chỉ 93kg, giúp người lái dễ dàng điều khiển và di chuyển trong những con ngõ hẹp hay những tuyến phố đông đúc. Kiểu dáng thanh thoát và hiện đại không chỉ tạo cảm giác thoải mái khi sử dụng mà còn thu hút ánh nhìn từ mọi người xung quanh. Đặc biệt, thiết kế khí động học giúp xe vận hành mượt mà hơn, tiết kiệm nhiên liệu tối ưu.</p>\n<p>Thiết kế logo xe</p>\n<p>Điểm nhấn nổi bật trên dòng xe này chính là logo <b>priti 50</b> được đặt tại đèn xi nhan. Với thiết kế tinh tế và màu sắc cầu vồng dưới khúc xạ ánh sáng, logo không chỉ thể hiện thương hiệu mà còn tạo nên sự khác biệt cho chiếc xe. Điều này giúp người dùng dễ dàng nhận diện thương hiệu trong mọi hoàn cảnh.</p>\n<p>Phiên bản màu sắc</p>\n<p><b>Priti 50cc</b> hiện đang có ba phiên bản màu sắc bắt mắt: Trắng ánh hồng, Xanh ánh bạc và Xanh ánh tím. Mỗi màu sắc đều mang đến một cá tính riêng biệt cho chiếc xe, phù hợp với sở thích đa dạng của người tiêu dùng. Phiên bản trắng ánh hồng thể hiện sự nữ tính và dịu dàng; xanh ánh bạc mang lại vẻ sang trọng và hiện đại; trong khi xanh ánh tím lại toát lên sự trẻ trung và năng động.</p>\n<p>Với những ưu điểm vượt trội về thiết kế, <b>sym priti 50cc</b> chắc chắn sẽ là lựa chọn lý tưởng cho những ai đang tìm kiếm một chiếc <a href=\"/xe-may?nhom=sym\"><strong>xe sym</strong></a> vừa thời trang vừa tiện lợi. Hãy trải nghiệm ngay dòng xe này để cảm nhận sự khác biệt mà nó mang lại!</p>\n<h2>2. Tính năng và tiện ích hiện đại của xe Priti 50cc</h2>\n<p><b>Xe priti 50cc</b> không chỉ là một phương tiện di chuyển thông mà còn là biểu tượng của sự nghi và hiện đại. Với tính năng vượt trội, chiếc xe này hứa hẹn sẽ mang đến trải nghiệm lái xe tuyệt vời cho người sử dụng.</p>\n<p>Động cơ mạnh mẽ và tiết kiệm nhiên liệu</p>\n<p>Xe được trang bị động cơ xăng 4 kỳ, 1 xi lanh có dung tích lên đến 50cc mang đến khả năng vận hành mạnh mẽ cho xe. <b>Priti 50</b> tự hào là dòng xe 50cc đầu tiên trên thị trường được trang bị hệ thống phun xăng điện tử (EFI). Công nghệ này không chỉ giúp tối ưu hóa quá trình tiêu thụ nhiên liệu mà còn mang lại trải nghiệm lái xe mượt mà và êm ái. Hệ thống làm mát bằng không khí cũng góp phần giúp xe giảm thiểu tiếng ồn, tạo ra một không gian thoải mái cho người sử dụng.</p>\n<p>Không gian sàn để chân thoải mái và tiện lợi</p>\n<p>Một trong những điểm nổi bật của <b>Priti 50cc</b> chính là sàn để chân rộng rãi với kích thước lên tới 264mm. Không gian này đủ lớn để bạn có thể dễ dàng mang theo vali kích thước 20 inch hoặc balo thú cưng mà không gặp bất kỳ trở ngại nào. Điều này rất thuận tiện cho những chuyến đi xa hoặc khi bạn cần di chuyển nhiều đồ đạc.</p>\n<p>Mặt đồng hồ hiện đại</p>\n<p>Mặt đồng hồ LCD trên xe được trang bị cảm biến ánh sáng tự động, giúp điều chỉnh độ sáng màn hình theo môi trường xung quanh. Điều này không chỉ giúp người lái dễ dàng quan sát thông tin cần thiết mà còn tăng tính an toàn khi di chuyển vào ban đêm hoặc trong điều kiện ánh sáng yếu.</p>\n<p>Gương chiếu hậu thông minh</p>\n<p>Gương chiếu hậu của <b>sym priti 50cc</b> được thiết kế độc đáo với khả năng xoay ngược, cho phép người lái dễ dàng điều chỉnh góc nhìn mọi lúc mọi nơi. Tính năng này giúp tăng cường khả năng quan sát phía sau, đảm bảo an toàn tối đa trong quá trình di chuyển.</p>\n<p>Hệ thống đèn LED toàn xe</p>\n<p><b>Xe priti 50cc</b> được trang bị hệ thống đèn LED siêu sáng bao gồm đèn pha, đèn hậu, đèn định vị và đèn xi-nhan. Hệ thống chiếu sáng này không chỉ tăng cường khả năng quan sát mà còn nâng cao độ nhận diện của xe trong mọi điều kiện thời tiết và ánh sáng khác nhau.</p>\n<p>Cốp xe rộng rãi và hộc chứa đồ tiện lợi</p>\n<p>Cốp xe <b>Priti 50cc</b> có dung tích lớn, đủ sức chứa hai nón bảo hiểm nữa đầu cùng nhiều đồ dùng cá nhân khác. Bên cạnh đó, hộc chứa đồ nhỏ gọn phía trước cũng rất tiện lợi để bạn có thể lưu trữ các vật dụng cần thiết như điện thoại hay ví tiền.</p>\n<p>Cổng sạc điện thoại thông minh</p>\n<p>Một điểm cộng nổi bật khác của <b>Priti 50</b> là cổng sạc nhanh USB được đặt bên cạnh hộc chứa đồ. Với nắp chụp chống nước, bạn có thể dễ dàng sạc điện thoại ngay cả khi đang lái xe mà không lo lắng về vấn đề an toàn hay hư hỏng do nước.</p>\n<p><b>Xe priti 50cc</b> không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang đến sự thoải mái và tiện ích tối đa cho người sử dụng. Với những tính năng hiện đại cùng thiết kế thông minh, đây chắc chắn là lựa chọn lý tưởng cho những ai yêu thích sự tiện nghi trong cuộc sống hàng ngày.</p>\n<h2>3. Cập nhật giá xe Priti 50cc của SYM tại Yên Thoa</h2>\n<p>Với nhiều năm kinh nghiệm trong ngành kinh doanh xe máy, Hệ thống Siêu Thị Yên Thoa tự hào là một trong những đại lý chính hãng hàng đầu, uy tín của các thương hiệu nổi tiếng như Honda, Yamaha, SYM, Suzuki và xe điện Yadea.</p>\n<p>Tại Yên Thoa, chúng tôi cam kết mang đến cho khách hàng <b>giá xe priti 50</b> hợp lý nhất. Đội ngũ nhân viên tận tâm và chuyên nghiệp của chúng tôi sẵn sàng tư vấn và hỗ trợ quý khách hàng trong việc lựa chọn chiếc xe <b>sym priti 50cc</b> phù hợp nhất với nhu cầu và sở thích cá nhân. Chúng tôi hiểu rằng việc <a href=\"/xe-may\"><strong>mua xe máy</strong></a> là một quyết định quan trọng, vì vậy sự an tâm của khách hàng luôn được đặt lên hàng đầu.</p>\n<p>Hiện nay, dòng xe Priti 50cc của SYM đang có mặt đầy đủ các phiên bản và màu sắc tại cửa hàng chúng tôi. Với mức <b>giá xe priti 50 </b>chỉ từ 26 triệu đồng, <b>priti 50</b> không chỉ nổi bật về thiết kế hiện đại mà còn được trang bị công nghệ tiên tiến, mang lại trải nghiệm lái xe mượt mà và an toàn cho người sử dụng.</p>\n<p>Mọi chi tiết về <b>giá xe priti 50</b> quý khách vui lòng liên hệ qua hotline để được tư vấn chi tiết!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
