INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-r15', 'Xe R15', 'yamaha', '[\"xe-the-thao\"]', 79150000, 79150000, '/sites/yenthoa/img/2024/11/r15m-phien-ban-monster-mau-den-xanh.webp', '[\"/sites/yenthoa/img/2024/11/r15m-phien-ban-monster-mau-den-xanh.webp\"]', '[\"Bạc Đen\",\"Đen\",\"Xanh đậm\",\"Xanh Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/r15-mau-den.webp\",\"price\":79150000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm\"}],\"img\":\"/sites/yenthoa/img/2024/11/r15-mau-xanh-gp.webp\",\"price\":79150000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"4 thì, 4 van, SOHC, 1 xy-lanh, làm mát bằng dung dịch, van biến thiên VVA\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy-lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"155.1\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"58.0 x 58.7 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11.6:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"14.2 kW (19.3 PS)/10000 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"14.7 N.m (1.5 kgf.m)/8500 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Cácte ướt\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"2.30\"},{\"label\":\"Bộ chế hòa khí\",\"value\":\"Bộ chế hòa khí\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"3.042 (73/24) / 3.429 (48/14)\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Ly hợp ướt đa đĩa\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"theo cấp số 1: 2.833 (34/12) / 2: 1.875 (30/16) / 3: 1.364 (30/22) / 4: 1.143 (24/21) / 5: 0.957 (22/23) / 6: 0.840 (21/25)\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"Bánh răng ăn khớp, 6 số\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Delta-box\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Hệ thống giảm xóc trước\"},{\"label\":\"Hành trình phuộc trước\",\"value\":\"130 mm\"},{\"label\":\"Độ lệch phương trục lái\",\"value\":\"25°30\' / 88mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Phuộc Monoshock\"},{\"label\":\"Phanh trước\",\"value\":\"Đĩa thuỷ lực (đường kính 282 mm)\"},{\"label\":\"Phanh sau\",\"value\":\"Đĩa thuỷ lực (đường kính 220 mm)\"},{\"label\":\"Lốp trước\",\"value\":\"100/80-17M/C 52P (lốp không săm)\"},{\"label\":\"Lốp sau\",\"value\":\"140/70-17M/C 66S (lốp không săm)\"},{\"label\":\"Đèn trước\",\"value\":\"bi-LED\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1990 x 725 x 1135 (mm)\"},{\"label\":\"Độ cao yên xe\",\"value\":\"815 mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"170 mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1325 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"140 kg\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"11 lít\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"1.05 lít\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000 km (tuỳ điều kiện nào đến trước)\"}]}]', '<p>Yamaha r15 đã có những cải tiến đáng kể, mang đến một diện mạo mới mẻ và trải nghiệm lái xe vượt trội. Hiện nay, yamaha r15 đang được bán tại Yên Thoa với mức giá xe r15 hấp dẫn cùng nhiều ưu đãi đặc biệt.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE R15 KHUYẾN MÃI GIÁ RẺ TẠI ĐẠI LÝ YAMAHA</h2>\n<p><b>Yamaha r15 </b>là một trong những dòng xe moto nổi tiếng hiện nay. Thiết kế của dòng xe <b>r15</b> gây ấn tượng mạnh bởi phong cách thể thao độc đáo, mang đậm dấu ấn R-ADN. Không chỉ dừng lại ở vẻ ngoài cuốn hút, <b>xe r15 </b>còn được trang bị động cơ 155cc mạnh mẽ, cho phép xe bứt tốc nhanh chóng và mang đến cho người lái những trải nghiệm tuyệt vời trên mọi cung đường.</p>\n<p>Hiện nay, <b>yamaha r15</b> đang được bán tại Yên Thoa với mức <b>giá xe r15 </b>hấp dẫn cùng nhiều ưu đãi đặc biệt.</p>\n\n<h2>1. Giới thiệu về thiết kế và tính năng của xe moto R15</h2>\n<p><b>Yamaha r15</b> phiên bản mới đã có những cải tiến đáng kể, mang đến một diện mạo mới mẻ và trải nghiệm lái xe vượt trội so với các mẫu xe tiền nhiệm. Điểm nhấn của dòng xe thể thao này chính là sự cân bằng hoàn hảo giữa thiết kế khí động học và tính ổn định khi di chuyển ở tốc độ cao.</p>\n<p><em>Thiết kế khí động học tối ưu</em></p>\n<p>Một trong những thay đổi quan trọng nhất trên <b>xe r15</b> là việc giảm trọng lượng, giúp xe trở nên nhẹ nhàng và linh hoạt hơn. Thiết kế khí động học kết hợp với các góc cạnh tinh tế không chỉ nâng cao hiệu suất mà còn mang lại cảm giác lái mượt mà, đầy phấn khích.</p>\n\n<p><em>Thiết kế đầu xe ấn tượng</em></p>\n<p>Thiết kế đầu xe của <b>yamaha r15</b> thực sự nổi bật với hốc gió trung tâm được tối ưu hóa cùng bộ tản nhiệt hiện đại. Điều này không chỉ giúp giảm nhiệt lượng phát sinh trong quá trình vận hành mà còn cải thiện hiệu suất động cơ và tăng cường độ bền cho các linh kiện bên trong.</p>\n\n<p><em>Mặt đồng hồ LCD hiện đại</em></p>\n<p>Mặt đồng hồ LCD mới trên <b>xe moto r15</b> được thiết kế theo phong cách đơn sắc cổ điển nhưng vẫn cung cấp đầy đủ thông tin cần thiết như tốc độ, mức xăng, quãng đường và nhiên liệu tiêu thụ. Đặc biệt, đồng hồ còn tích hợp tính năng tua điện tử mới và thông báo chìa khóa khi bật tắt, mang lại sự tiện lợi tối đa cho người sử dụng.</p>\n\n<p><em>Nút đèn pha xin vượt</em></p>\n<p>Xe được trang bị nút đèn pha xin vượt ở bên trái tay lái, cho phép đèn pha phát sáng mạnh trong thời gian ngắn khi cần thiết để tăng cường khả năng quan sát. Ngoài ra, nút bật/tắt công tắc điện an toàn ở phía bên phải giúp tiết kiệm năng lượng và đảm bảo an toàn khi đỗ xe.</p>\n<p><em>Công nghệ sang số nhanh Quick Shifter trên Yamaha R15</em></p>\n<p>Công nghệ sang số nhanh Quick Shifter trên<strong> yamaha r15</strong> mang đến cho người lái khả năng chuyển số mà không cần sử dụng côn, giúp tối ưu hóa thời gian chuyển số và cải thiện hiệu suất duy trì cũng như tăng tốc của xe. Hệ thống này tự động kích hoạt khi xe đạt tốc độ trên 20 km/h và vòng tua máy vượt quá 2000 vòng/phút, đặc biệt hữu ích trong quá trình tăng tốc.</p>\n\n<p><em>Chế độ Track Mode &amp; Street Mode của Yamaha R15</em></p>\n<p><strong>Xe r15</strong> còn được trang bị hai chế độ lái: Track Mode và Street Mode, cho phép người dùng dễ dàng chuyển đổi chỉ bằng một nút bấm tiện lợi gần tay ga. Điều này giúp người lái linh hoạt điều chỉnh phong cách lái phù hợp với điều kiện đường xá và nhu cầu cá nhân, mang lại trải nghiệm lái xe tối ưu nhất.</p>\n\n<p><em>Kết nối thông minh Y-Connect</em></p>\n<p><b>R15</b> được tích hợp tính năng Y-Connect thông minh, cho phép kết nối điện thoại với xe qua ứng dụng chuyên dụng. Người lái có thể dễ dàng theo dõi cuộc gọi đến, tin nhắn và các thông báo khác ngay trên màn hình đồng hồ của xe, mang lại sự tiện lợi và an toàn tối đa trong quá trình di chuyển.</p>\n\n<p><em>Hệ thống phanh hiệu quả</em></p>\n<p>Xe được trang bị hệ thống phanh đĩa trước với đường kính 282mm, đi kèm với kẹp má phanh kép sử dụng công nghệ 2 piston. Điều này không chỉ giúp tăng cường hiệu suất phanh mà còn đảm bảo độ ổn định và an toàn trong quá trình vận hành.</p>\n\n<p>Với những cải tiến đáng giá cả về thiết kế lẫn tính năng công nghệ hiện đại, <b>xe moto r15</b> chắc chắn sẽ là lựa chọn lý tưởng cho những ai yêu thích dòng xe thể thao mạnh mẽ và tiên tiến.</p>\n<h2>2. Giới thiệu động cơ xe Yamaha R15</h2>\n<p><b>Yamaha r15</b> được trang bị khối động cơ 155cc mạnh mẽ, nổi bật với công nghệ van biến thiên VVA độc quyền của Yamaha. Động cơ này không chỉ mang lại công suất cực đại lên đến 14.2 kW (tương đương 19.3 PS) tại 10.000 vòng/phút, mà còn kết hợp với hệ thống phun xăng điện tử SOHC và làm mát bằng dung dịch, tạo ra hiệu suất vận hành vượt trội và trải nghiệm lái đầy phấn khích.</p>\n<p>Một trong những điểm đáng chú ý của<b> xe moto r15</b> chính là khả năng tiết kiệm nhiên liệu ấn tượng. Xe chỉ tiêu thụ khoảng 2,03 lít/100km, giúp người dùng giảm thiểu chi phí vận hành một cách hiệu quả. Điều này không chỉ mang lại lợi ích kinh tế mà còn góp phần bảo vệ môi trường.</p>\n\n<p><b>Yamaha r15</b> không chỉ là một chiếc <a href=\"/xe-may?nhom=yamaha\"><b>xe máy yamaha</b></a> đơn thuần mà còn là biểu tượng của sự đam mê và phong cách sống năng động. Sự kết hợp hoàn hảo giữa sức mạnh và hiệu suất tiết kiệm khiến <b>xe r15</b> trở thành lựa chọn lý tưởng cho những ai yêu thích tốc độ và sự linh hoạt trên mọi cung đường.</p>\n<h2>3. Cập nhật giá xe R15 tại đại lý xe máy Yên Thoa</h2>\n<p><b>Yamaha r15</b>, một trong những mẫu xe moto nổi bật và được ưa chuộng nhất của Yamaha, luôn là lựa chọn hàng đầu của nhiều khách hàng nam. Tuy nhiên, không phải cửa hàng nào cũng có sẵn đầy đủ các phiên bản và màu sắc của dòng xe này.</p>\n<p>Hệ thống Siêu Thị Yên Thoa tự hào là <b>đại lý xe máy</b> chính hãng của Yamaha. Chúng tôi cam kết mang đến cho khách hàng các dòng xe Yamaha mới nhất với mức giá cực kỳ hấp dẫn.</p>\n<p>Hiện tại, <b>giá xe r15</b> tại Yên Thoa dao động từ 78 triệu đồng, cụ thể như sau:</p>\n<p><b>Giá xe r15</b> tiêu chuẩn: <strong>79.150.000đ</strong></p>\n\n<p>Đặc biệt, khi đăng ký mua xe ngay hôm nay, quý khách còn có cơ hội nhận được Combo quà tặng độc quyền trị giá 2.950.000 đồng cùng hàng ngàn chương trình khuyến mãi hấp dẫn khác. Hãy liên hệ ngay với Hệ thống Siêu Thị Yên Thoa qua hotline để tham khảo <b>giá xe r15</b> mới nhất hiện nay và sở hữu ngay chiếc <b>yamaha r15</b> yêu thích với mức giá tốt nhất!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
