INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-satria', 'Xe Satria', 'suzuki', '[\"xe-tay-con\"]', 53900000, 53900000, '/sites/yenthoa/img/2024/11/satria-150r-mau-den-trang.webp', '[\"/sites/yenthoa/img/2024/11/satria-150r-mau-den-trang.webp\"]', '[\"Đen Đỏ\",\"Đen Trắng\",\"Xanh Bạc Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/yenthoa/img/2024/11/satria-150r-mau-den-do.webp\",\"price\":53900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/satria-150r-mau-den-trang.webp\",\"price\":53900000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh Bạc Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/satria-150r-mau-xanh-bac-den.webp\",\"price\":53900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Cụm đồng hồ hiển thị\",\"value\":\"Kỹ thuật số toàn phần\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đề điện / Đạp\"},{\"label\":\"Khởi động dễ dàng\",\"value\":\"Có trang bị (1 lần ấn)\"},{\"label\":\"Loại động cơ\",\"value\":\"DOHC, 4 thì, làm mát bằng dung dịch\"},{\"label\":\"Hệ thống valve\",\"value\":\"Valves\"},{\"label\":\"Bố trí xy-lanh\",\"value\":\"Xy-lanh đơn\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"147.3 cm3\"},{\"label\":\"Công suất cực đại\",\"value\":\"13.6 kW / 10,000 vòng / phút\"},{\"label\":\"Mô-men cực đại\",\"value\":\"13.8 Nm / 8,500 vòng / phút\"},{\"label\":\"Hệ thống truyền động\",\"value\":\"Côn tay, 6 cấp số\"},{\"label\":\"Hệ thống nhiên liệu\",\"value\":\"Phun xăng điện tử\"},{\"label\":\"Loại bình điện\",\"value\":\"12V - 5Ah\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích thước bánh xe\",\"value\":\"70/90-17M/C 38P 80/90-17M/C 44P\"},{\"label\":\"Phanh trước/ sau\",\"value\":\"Đĩa / Đĩa\"},{\"label\":\"Loại khung sườn\",\"value\":\"Underbone\"},{\"label\":\"Hệ thống đèn trước\",\"value\":\"LED/Bóng đèn\"},{\"label\":\"Ổ khóa\",\"value\":\"Dạng nắp trập, 1 ấn mở\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Chiều dài x rộng x cao\",\"value\":\"1960 mm x 675 mm x 980 mm\"},{\"label\":\"Chiều cao yên\",\"value\":\"765 mm\"},{\"label\":\"Trọng lượng tổng thể\",\"value\":\"109 Kg\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"130mm\"},{\"label\":\"Chiều cao yên\",\"value\":\"770mm\"},{\"label\":\"Chiều dài cơ sở\",\"value\":\"1280 mm\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4 Lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2,56 Lít/ 100 Km\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành thông thường\",\"value\":\"3 năm hoặc 100.000km kể từ ngày giao xe mới, tùy điều kiện nào tới trước\"}]}]', '<p>Với thiết kế hiện đại cùng các phiên bản màu sắc đa dạng, xe satria f150 không chỉ đơn thuần là phương tiện di chuyển mà còn là biểu tượng thời trang và phong cách sống cho giới trẻ.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE SATRIA F150 ƯU ĐÃI MỚI NHẤT TẠI ĐẠI LÝ SUZUKI</h2>\n<p>Thu hút người yêu xe bởi thiết kế “Hyper Underbone” độc đáo, <b>Satria f150</b> còn là sự kết hợp hoàn hảo giữa phong cách thể thao và sức mạnh vượt trội. Với những tem màu sắc nổi bật lấy cảm hứng từ các mẫu xe đua MotoGP huyền thoại, <b>suzuki satria </b>thực sự là biểu tượng của sự cá tính và chất chơi. Hãy cùng Yên Thoa khám phá ngay những điểm nổi bật của dòng <b>xe máy satria</b> và <b>giá xe satria</b> mới nhất qua bài viết dưới đây.</p>\n<h2>1. Giới thiệu về thiết kế của xe Suzuki Satria&nbsp;</h2>\n<p>Mỗi chi tiết trong thiết kế của <b>satria f150</b> đều được lấy cảm hứng từ những mẫu xe đua MotoGP huyền thoại của Suzuki. Những đường nét sắc sảo, khí động học kết hợp với các tem màu nổi bật không chỉ làm tăng thêm vẻ đẹp cho chiếc xe mà còn tạo nên một phong cách riêng biệt, giúp bạn trở thành tâm điểm chú ý trên phố. Đặc biệt, sự kết hợp hoàn hảo giữa tính năng và thẩm mỹ trong thiết kế đã giúp <b>xe satria</b> trở thành một sản phẩm hoàn hảo cho những ai yêu thích tốc độ và sự khác biệt.</p>\n<p>Hiện tại, <b>suzuki satria</b> có ba phiên bản màu sắc đa dạng để bạn lựa chọn, mỗi phiên bản không chỉ thể hiện vẻ đẹp thẩm mỹ mà còn phản ánh cá tính riêng biệt của từng người sở hữu.&nbsp;</p>\n<p>Phiên bản Đen – Đỏ: Đây là sự lựa chọn hoàn hảo cho những ai yêu thích sự mạnh mẽ và cá tính. Màu đen huyền bí kết hợp với đỏ nổi bật tạo nên một tổng thể ấn tượng, thể hiện sức mạnh và sự quyết đoán.</p>\n<p>Phiên bản Đen – Trắng: Phiên bản này mang đến cảm giác sang trọng và lịch lãm. Màu trắng tinh khiết hòa quyện cùng màu đen tạo nên vẻ đẹp hoàn hảo, phản ánh gu thẩm mỹ tinh tế của chủ nhân.</p>\n<p>Phiên bản Xanh – Bạc – Đen: Đây là sự kết hợp mới lạ và độc đáo. Màu xanh biển thanh thoát cùng bạc sang trọng và đen cổ điển tạo nên tổng thể hài hòa, thể hiện phong cách cá nhân nổi bật của người sở hữu.</p>\n<p>Với thiết kế hiện đại cùng các phiên bản màu sắc đa dạng, <b>satria f150</b> không chỉ đơn thuần là phương tiện di chuyển mà còn là biểu tượng thời trang và phong cách sống cho giới trẻ yêu thích tốc độ. Hãy để<b> xe máy satria </b>trở thành người bạn đồng hành đáng tin cậy trên những chặng đường đầy thử thách của bạn!</p>\n<h2>2. Những ưu điểm nổi bật trong tính năng của xe Satria F150</h2>\n<p>Với nhiều tính năng nổi bật, <b>suzuki satria</b> hứa hẹn mang đến cho người dùng những trải nghiệm lái xe tuyệt vời. Dưới đây là những điểm nổi bật nhất của<b> satria f150</b>.</p>\n<p>Hệ thống khởi động thông minh</p>\n<p>Một trong những tính năng đáng chú ý nhất của <b>satria f150</b> chính là hệ thống khởi động thông minh. Người dùng chỉ cần nhấn và thả nút khởi động để khởi động xe, giúp tiết kiệm thời gian và công sức so với việc giữ nút lâu như trên nhiều dòng xe khác. Điều này không chỉ mang lại sự tiện lợi mà còn thể hiện sự tinh tế trong thiết kế của Suzuki.</p>\n<p>Đồng hồ hiển thị kỹ thuật số hiện đại</p>\n<p><b>Xe satria </b>được trang bị đồng hồ hiển thị kỹ thuật số sắc nét, cung cấp đầy đủ các thông số cần thiết cho người lái như tốc độ, vòng tua máy và mức nhiên liệu. Màn hình LCD rõ ràng giúp người dùng dễ dàng theo dõi tình trạng xe trong suốt quá trình vận hành, từ đó nâng cao sự an toàn khi lái xe.</p>\n<p>Hệ thống đèn LED tiết kiệm năng lượng</p>\n<p>Thiết kế đầu <b>xe satria </b>thể thao và thời trang được tô điểm bởi hệ thống đèn LED siêu sáng, không chỉ mang lại ánh sáng tốt hơn mà còn tiết kiệm điện năng hiệu quả. Đèn hậu tròn sắc nét cũng góp phần tạo nên vẻ đẹp hoàn mỹ cho tổng thể chiếc xe, đồng thời tăng cường khả năng nhận diện từ xa.</p>\n<p>Thiết kế ống xả thể thao cao cấp</p>\n<p>Ống xả của<b> satria f150 </b>được thiết kế với phong cách thể thao và cao cấp, không chỉ tạo ra âm thanh mạnh mẽ mà còn làm tăng hiệu suất vận hành của động cơ. Gác chân chính theo kiểu lò xo có khả năng gập vào trong giúp tối ưu hóa không gian và đảm bảo an toàn cho người sử dụng.</p>\n<p>Khung sườn chắc chắn với công nghệ tiên tiến</p>\n<p>Khung sườn của<b> xe máy satria</b> được sản xuất bằng công nghệ Suzuki Advanced Twin Spar, mang lại độ cứng cáp và ổn định cao khi di chuyển trên mọi địa hình. Điều này đặc biệt quan trọng khi người lái phải vào cua hoặc di chuyển trên đường thẳng với tốc độ cao, giúp tăng cường cảm giác an toàn cho người điều khiển.</p>\n<p>Động cơ mạnh mẽ và hiệu suất vượt trội</p>\n<p><b>Xe satria</b> sở hữu động cơ mạnh mẽ với dung tích 150 phân khối cùng các tính năng DOHC và bốn van xả (XUAP), sản sinh công suất lên đến 18.5 mã lực tại vòng tua máy 10.000 rpm (vòng/phút). Hệ thống làm mát bằng dung dịch kết hợp với phun xăng điện tử không chỉ giúp tiết kiệm nhiên liệu mà còn tối ưu hóa hiệu suất vận hành.</p>\n<p>Khả năng linh hoạt vượt trội trong di chuyển</p>\n<p>Với góc quay đầu lên đến 45 độ,<b> suzuki satria</b> dễ dàng vượt qua các đoạn đường cua hẹp hay quay đầu trong không gian chật chội. Tính linh hoạt này rất phù hợp cho việc di chuyển trong đô thị đông đúc hoặc trên những con đường khó khăn.</p>\n<p><b>Satria f150</b> không chỉ nổi bật với thiết kế thể thao cuốn hút mà còn được trang bị nhiều tính năng hiện đại nhằm nâng cao trải nghiệm lái xe an toàn và thoải mái cho người sử dụng. Với những ưu điểm vượt trội về công nghệ cũng như hiệu suất vận hành, <b>xe satria </b>chắc chắn sẽ là lựa chọn lý tưởng cho những ai yêu thích <a href=\"/xe-may?nhom=suzuki\"><strong>xe máy suzuki</strong></a> và phong cách trong từng chuyến đi.</p>\n<h2>3. Cập nhật giá xe Satria mới nhất chính hãng của Suzuki</h2>\n<p>Hiện tại, Hệ thống Siêu Thị Yên Thoa đang có đầy đủ các dòng xe và phiên bản mới nhất của mẫu xe côn tay <b>suzuki satria</b> với mức <b>giá xe satria</b> khởi điểm chỉ từ 54 triệu đồng. Đây là một trong những lựa chọn hấp dẫn cho những ai yêu thích sự mạnh mẽ và phong cách thể thao.</p>\n<p>Ngoài mức <b>giá xe satria</b> cạnh tranh, khi mua xe <b>satria f150 </b>tại Yên Thoa quý khách hàng còn có cơ hội nhận được nhiều phần quà tặng và ưu đãi hấp dẫn. Đặc biệt, chúng tôi còn cung cấp chương trình trả góp với lãi suất thấp và thủ tục đơn giản, giúp quý khách dễ dàng sở hữu chiếc<b> xe satria</b> mơ ước mà không gặp khó khăn về tài chính.</p>\n<p>Là <a href=\"/xe-may\"><strong>đại lý xe máy</strong></a> chuyên kinh doanh các dòng xe Suzuki, Yên Thoa cam kết mang đến cho quý khách hàng những sản phẩm chất lượng cao nhất cùng dịch vụ tận tâm. Đội ngũ nhân viên chuyên nghiệp của chúng tôi luôn sẵn sàng tư vấn và hỗ trợ quý khách trong việc lựa chọn mẫu xe <b>satria f150</b> phù hợp nhất với nhu cầu và sở thích cá nhân. Nếu bạn đang có ý định tham khảo <b>giá xe satria</b> hoặc muốn tìm hiểu thêm về các dòng sản phẩm của Suzuki, hãy liên hệ ngay với chúng tôi qua hotline hoặc gửi thông tin để được tư vấn nhanh chóng và chi tiết!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
