INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-scoopy', 'Xe Scoopy', 'xe-may-nhap-khau', '[]', 37500000, 39000000, '/sites/yenthoa/img/2024/11/scoopy-smartkey.webp', '[\"/sites/yenthoa/img/2024/11/scoopy-smartkey.webp\"]', '[]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Chìa khoá\"}],\"img\":\"/sites/yenthoa/img/2024/11/scoopy-chia-khoa.webp\",\"price\":37500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Smartkey\"}],\"img\":\"/sites/yenthoa/img/2024/11/scoopy-smartkey.webp\",\"price\":39000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại động cơ\",\"value\":\"4 - kỳ, SOHC, eSP\"},{\"label\":\"Loại làm mát\",\"value\":\"Điều hòa không khí\"},{\"label\":\"Hệ thống cung cấp nhiên liệu\",\"value\":\"PGM-FI (Phun nhiên liệu theo chương trình)\"},{\"label\":\"Bước âm lượng\",\"value\":\"109,5cc\"},{\"label\":\"Đường kính X hành trình piston\",\"value\":\"47 x 63,1mm\"},{\"label\":\"Tỷ lệ nén\",\"value\":\"10,0 : 1\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,6 kW (9,0 PS) / 7.500 vòng/phút\"},{\"label\":\"Mô-men cực đại\",\"value\":\"9,2 Nm (0,94 kgf.m) / 6.000 vòng/phút\"},{\"label\":\"Loại khởi động\",\"value\":\"Khởi động bằng điện (STD) / Điện (Chìa khóa thông minh)\"},{\"label\":\"Loại ly hợp\",\"value\":\"Tự động, ly tâm, loại khô\"},{\"label\":\"Dung tích dầu bôi trơn\",\"value\":\"0,65 Lít (Thay thế định kỳ)\"},{\"label\":\"Chất bôi trơn\",\"value\":\"Ướt\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4,2 lít\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Underbone\"},{\"label\":\"Kích thước lốp trước\",\"value\":\"100/90 – 12 59J (Không săm)\"},{\"label\":\"Kích thước lốp sau\",\"value\":\"110/90 – 12 64J (Không săm)\"},{\"label\":\"Phanh trước\",\"value\":\"Đĩa thủy lực với Piston đơn\"},{\"label\":\"Phanh sau\",\"value\":\"Tay đòn\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Phuộc ống lồng\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Phuộc nhún\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x rộng x cao\",\"value\":\"1.869 x 693 x 1.075mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"746mm\"},{\"label\":\"Chiều dài\",\"value\":\"1.251mm\"},{\"label\":\"Khoảng cách gầm\",\"value\":\"145mm\"},{\"label\":\"Trọng lượng\",\"value\":\"94 kg (phiên bản tiêu chuẩn)\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"Kiểm tra định kỳ 18 tháng\"}]}]', '<p>Với kiểu dáng tinh tế và phong cách mini độc đáo, Honda scoopy thực sự khẳng định đúng tinh thần của slogan “My First Ride, My Way is always meaningful”.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE SCOOPY 110 NHẬP KHẨU KHUYẾN MÃI GIÁ TỐT</h2>\n<p><b>Xe scoopy 110 </b>là một trong những mẫu xe tay ga nhập khẩu được nhiều người tìm kiếm nhất hiện nay. Với kiểu dáng thanh lịch, đường nét mềm mại và màu sắc đa dạng, <b>honda scoopy</b> không chỉ thu hút ánh nhìn mà còn thể hiện phong cách cá nhân của người sử dụng. Dưới đây là những điểm nổi bật của <b>xe scoopy 110</b> nhập khẩu và <b>giá xe scoopy</b> mới nhất trên thị trường.</p>\n<h2>1. Giới thiệu về thiết kế của xe Honda Scoppy chính hãng nhập khẩu</h2>\n<p><b>Honda scoopy</b> là mẫu xe tay ga mini nổi bật, mang đến sự kết hợp hoàn hảo giữa vẻ đẹp nữ tính và tính năng hiện đại. Được thiết kế lại hoàn toàn so với các thế hệ trước, Scoopy phiên bản mới không chỉ thu hút ánh nhìn mà còn thể hiện sự chuyển mình mạnh mẽ theo xu hướng công nghệ thông minh của Honda.</p>\n<p>Mẫu <b>xe scoopy</b> sở hữu đèn pha được thiết kế độc đáo như một viên bảo thạch, với các đường nét cong mềm mại và không điểm chết, tạo nên điểm nhấn ấn tượng cho phần đầu xe. Hai đèn xi-nhan được bố trí tinh tế ở hai bên, không chỉ đảm bảo dãy sáng rộng mà còn góp phần làm tăng vẻ sang trọng và bắt mắt cho chiếc xe.</p>\n<p>Với kiểu dáng tinh tế và phong cách mini độc đáo, <b>Honda scoopy</b> thực sự khẳng định đúng tinh thần của slogan “My First Ride, My Way is always meaningful”. Xe không chỉ đơn thuần là phương tiện di chuyển mà còn là biểu tượng của sự tự tin và phong cách sống năng động dành riêng cho phái nữ. Những đường nét mềm mại kết hợp cùng màu sắc tươi sáng đã tạo nên một diện mạo cuốn hút và đầy sức sống.</p>\n<p>Ngoài ra, <b>xe scoopy 110</b> còn được trang bị nhiều tính năng tiện ích hiện đại như hệ thống phanh an toàn, khoang chứa đồ rộng rãi và khả năng tiết kiệm nhiên liệu vượt trội. Tất cả những yếu tố này đều góp phần mang lại trải nghiệm lái xe thoải mái và an toàn cho người sử dụng. Với <b>scoopy</b>, mỗi chuyến đi không chỉ đơn thuần là di chuyển mà còn là hành trình khám phá phong cách sống riêng biệt của bạn.</p>\n<h2>2. Giới thiệu về động cơ và tiện ích của xe Scoopy 110&nbsp;</h2>\n<p>Động cơ mạnh mẽ và tiết kiệm</p>\n<p><b>Honda scoopy</b> được trang bị động cơ eSP 110cc, 4 thì, với hệ thống làm mát bằng không khí và công nghệ phun xăng điện tử PGM-Fi. Động cơ này không chỉ mang lại hiệu suất vận hành ổn định mà còn nổi bật với khả năng tiết kiệm nhiên liệu vượt trội. Theo thông số kỹ thuật, xe có thể đạt mức tiêu thụ nhiên liệu lên tới 62,5 km/lít, giúp người dùng tiết kiệm chi phí đáng kể trong quá trình sử dụng.</p>\n<p>Tiện ích vượt trội cho người dùng</p>\n<p>Một trong những điểm nổi bật của <b>xe scoopy 110 </b>chính là không gian cốp rộng rãi. Cốp xe có khả năng chứa vừa vặn một chiếc mũ bảo hiểm 3/4 cùng một số vật dụng nhỏ khác, mang đến sự tiện lợi tối đa cho người sử dụng. Đồng hồ hiển thị LCD kỹ thuật số được thiết kế lớn hơn, cung cấp đầy đủ thông tin về mức xăng, quãng đường đã đi, tình trạng dầu và năng lượng còn lại. Điều này không chỉ giúp người lái dễ dàng theo dõi mà còn tạo cảm giác hiện đại và sang trọng cho chiếc xe.</p>\n<p>Đặc biệt, phiên bản mới của <b>xe scoopy </b>đã được trang bị hệ thống Smartkey kết hợp với khóa Keyless. Tính năng này không chỉ nâng cao khả năng chống trộm mà còn mang lại sự tiện lợi tối đa khi khởi động và mở khóa xe.</p>\n<p>Thiết kế thông minh và tiện lợi</p>\n<p><b>Honda scoopy</b> chính hãng cũng đã cải tiến móc treo đồ với thiết kế dạng chữ O thay vì kiểu móc truyền thống. Móc này có thể gập gọn khi không sử dụng, rất thuận tiện để treo túi ni lông khi đi chợ hoặc mang theo các vật dụng cần thiết khác.</p>\n<p>Một điểm cộng lớn nữa là cổng sạc tích hợp 12V 1A ở phần đầu xe. Tính năng này cho phép người dùng dễ dàng sạc pin điện thoại hoặc các thiết bị điện tử khác ngay trên xe, đáp ứng nhu cầu kết nối trong thời đại công nghệ hiện nay.</p>\n<p>Hệ thống an toàn tiên tiến</p>\n<p>Dòng <b>xe scoopy</b> cũng chú trọng đến vấn đề an toàn với hệ thống dừng tạm thời Idling Stop. Hệ thống này tự động ngắt động cơ sau khi dừng lại quá 3 giây nhằm giảm thiểu lượng nhiên liệu tiêu thụ. Khi cần di chuyển trở lại, người lái chỉ cần nhấn ga để tiếp tục hành trình mà không mất thời gian khởi động lại máy.</p>\n<p>Hệ thống phanh đĩa thủy lực kết hợp công nghệ CBS đảm bảo an toàn tối đa khi di chuyển trên những tuyến đường khó khăn hoặc trong điều kiện giao thông đông đúc. Công nghệ này giúp phân bổ lực phanh đồng đều giữa bánh trước và bánh sau, tăng cường khả năng kiểm soát và ổn định cho chiếc xe.</p>\n<p><b>Scoopy 110 </b>không chỉ là một phương tiện di chuyển đơn thuần mà còn là một sản phẩm tích hợp nhiều tính năng hiện đại và tiện ích dành riêng cho phái đẹp. Với thiết kế tinh tế cùng những cải tiến vượt bậc về động cơ và tính năng an toàn, <b>Scoopy </b>chắc chắn sẽ là lựa chọn lý tưởng cho những ai yêu thích sự trẻ trung và phong cách sống hiện đại.</p>\n<h2>3. Giá xe Scoopy mới nhất tại Yên Thoa&nbsp;</h2>\n<p>Hiện nay, <b>giá xe scoopy </b>tại các đại lý xe máy đang dao động từ 37 triệu đồng, tùy thuộc vào từng khu vực và các chương trình khuyến mãi đi kèm. Đây là một trong những mẫu xe được ưa chuộng nhất trên thị trường nhờ thiết kế trẻ trung, năng động và tính năng vượt trội.</p>\n<p>Tại hệ thống cửa hàng xe máy Yên Thoa, chúng tôi tự hào là một trong những đại lý uy tín hàng đầu trong lĩnh vực nhập khẩu và phân phối <a href=\"/xe-may?nhom=xe-may-nhap-khau\"><strong>xe máy nhập</strong></a>. Chúng tôi cam kết mang đến cho khách hàng mức <b>giá xe scoopy</b> cạnh tranh nhất cùng với nhiều ưu đãi độc quyền hấp dẫn. Đặc biệt, với đội ngũ nhân viên chuyên nghiệp và tận tâm, chúng tôi luôn sẵn sàng hỗ trợ và tư vấn để giúp quý khách lựa chọn được mẫu xe phù hợp nhất với nhu cầu của mình.</p>\n<p>Chúng tôi hiểu rằng sự hài lòng của khách hàng là yếu tố quyết định cho sự phát triển bền vững của doanh nghiệp. Chính vì vậy, Yên Thoa không ngừng nỗ lực cải thiện dịch vụ và nâng cao trải nghiệm mua sắm cho quý khách hàng. Từ việc cung cấp thông tin chi tiết về sản phẩm đến các dịch vụ hậu mãi chu đáo, chúng tôi luôn mong muốn mang lại sự an tâm và tin tưởng tuyệt đối cho khách hàng khi lựa chọn sản phẩm của chúng tôi.</p>\n<p>Hãy đến với Yên Thoa để trải nghiệm dịch vụ mua sắm chuyên nghiệp cùng mức <a href=\"/xe-may\"><b>giá xe máy</b></a> tốt nhất cho chiếc xe <b>honda scoopy</b> mà bạn mơ ước! Chúng tôi rất hân hạnh được phục vụ bạn!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
