INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-sh-mode', 'Xe Sh Mode', 'honda', '[]', 60600000, 67100000, '/sites/yenthoa/img/2024/11/sh-mode-phien-ban-cao-cap-mau-do-den.webp', '[\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-cao-cap-mau-do-den.webp\"]', '[\"Bạc Đen\",\"Đen\",\"Đỏ\",\"Đỏ Đen\",\"Trắng\",\"Xám Đen\",\"Xanh đậm\",\"Xanh Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-tieu-chuan-mau-do.webp\",\"price\":60600000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-tieu-chuan-mau-trang.webp\",\"price\":60600000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-tieu-chuan-mau-xanh.webp\",\"price\":60600000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-cao-cap-mau-do-den.webp\",\"price\":65300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-cao-cap-mau-xanh-den.webp\",\"price\":65300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-cao-cap-mau-den.webp\",\"price\":67100000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-dac-biet-mau-bac-den.webp\",\"price\":67100000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sh-mode-phien-ban-the-thao-mau-xam-den.webp\",\"price\":67100000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"5,6 lít\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xy lanh, làm mát bằng chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"8,2kW/8500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả 0,8 L Sau khi rã máy 0,9 L\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2,12 lít/100km\"},{\"label\":\"Loại truyền động\",\"value\":\"Tự động, vô cấp\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"11,7 N.m/5000 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"124,8 cc\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"53,5 x 55,5 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,5:1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Lốp trước 80/90-16M/C 43P Lốp sau 100/90-14M/C 57P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Phuộc đơn\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"116 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1,950x669x1,100 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1,304 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"765 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"151 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Xe sh mode 125 được xem là biểu tượng của phong cách sống sang trọng. Từ động cơ mạnh mẽ đến khả năng tiết kiệm nhiên liệu tối ưu, honda sh mode 125 đáp ứng đầy đủ nhu cầu di chuyển hàng ngày.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE SH MODE 125 ƯU ĐÃI GIÁ TỐT TẠI ĐẠI LÝ HONDA&nbsp;</h2>\n<p>Với phong cách tinh tế và hiện đại, <b>xe sh mode</b> chính là sự lựa chọn lý tưởng cho những ai luôn tìm kiếm sự hoàn hảo trong từng chi tiết. Chiếc xe này không chỉ thu hút ánh nhìn bởi vẻ ngoài thanh lịch mà còn mang đến trải nghiệm lái xe tuyệt vời. Từ động cơ mạnh mẽ đến khả năng tiết kiệm nhiên liệu tối ưu, <b>honda sh mode 125</b> đáp ứng đầy đủ nhu cầu di chuyển hàng ngày của phái đẹp một cách dễ dàng và thoải mái.</p>\n\n<p>Hãy cùng Yên Thoa khám phá thêm về<b> giá xe sh mode</b> và những tính năng vượt trội của dòng <b>xe sh mode mới</b> này qua bài viết dưới đây!</p>\n<h2>1. Thiết kế nổi bật của Honda SH mode 125</h2>\n<p>Với ngoại hình sang trọng và nổi bật, <b>honda sh mode 125</b> xứng đáng là dòng xe tay cao cấp bán chạy nhất hiện nay. Dưới đây là những điểm đặc sắc trong thiết kế của dòng xe này.</p>\n\n<p><em>Các phiên bản và màu sắc nổi bật</em></p>\n<p><b>Sh mode 125</b> không chỉ đơn thuần là một phương tiện di chuyển, mà còn là biểu tượng của phong cách sống hiện đại và sự sang trọng. Dòng xe này được phân chia thành nhiều phiên bản, mỗi phiên bản đều mang đến những nét đặc trưng riêng biệt, phù hợp với sở thích và cá tính của từng người dùng.</p>\n<p>Phiên bản thể thao: Với gam màu xám xi măng trẻ trung, phiên bản này thể hiện sự năng động và hiện đại. Nó không chỉ thu hút ánh nhìn mà còn mang lại cảm giác mạnh mẽ, tương tự như các mẫu xe cao cấp khác trong dòng sản phẩm như SH350i và SH160i.</p>\n<p>Phiên bản đặc biệt: Sự kết hợp hoàn hảo giữa lớp sơn mờ trên nền đen và xám chủ đạo cùng logo<b> sh mode</b> nổi bật tạo nên một diện mạo sang trọng. Điểm nhấn với giảm xóc sau màu đỏ rực rỡ không chỉ làm tăng tính thẩm mỹ mà còn thể hiện sự cá tính mạnh mẽ cho người sở hữu.</p>\n<p>Phiên bản cao cấp: Hai tông màu Đỏ đen và Xanh đen được phối hợp tinh tế, mang đến vẻ đẹp thời thượng và cảm giác cao cấp. Những chi tiết thiết kế tỉ mỉ giúp phiên bản này nổi bật hơn bao giờ hết, phù hợp với những ai yêu thích sự khác biệt.</p>\n<p>Phiên bản tiêu chuẩn: Với ba lựa chọn màu sắc quen thuộc là Trắng, Đỏ và Xanh, phiên bản này vẫn giữ được nét thanh lịch vốn có của dòng xe SH. Sự đơn giản nhưng tinh tế trong thiết kế khiến nó trở thành lựa chọn lý tưởng cho những ai yêu thích sự nhẹ nhàng nhưng không kém phần sang trọng.</p>\n<p><em>Thiết kế phía trước tinh tế</em></p>\n<p>Phần thiết kế phía trước của <b>xe sh mode 125 </b>được lấy cảm hứng từ những chai nước hoa cao cấp, tạo nên vẻ đẹp thanh lịch đầy cuốn hút. Cụm đèn trước sử dụng công nghệ LED hiện đại, tỏa sáng lấp lánh như một dải trang sức quý giá. Việc áp dụng công nghệ xi mạ chrome ở phần kết nối giữa đèn trước và thân xe không chỉ tăng tính thẩm mỹ mà còn tạo sự liền mạch cho tổng thể thiết kế. Đèn chiếu sáng luôn hoạt động giúp nâng cao khả năng nhận diện của xe khi di chuyển trong đô thị.</p>\n\n<p><em>Kiểu dáng sang trọng</em></p>\n<p>Với thiết kế tổng thể nhỏ gọn hình chữ S đặc trưng theo phong cách Châu Âu, <b>sh mode mới</b> toát lên vẻ thanh lịch và quyến rũ. Độ cao yên được tối ưu hóa để phù hợp với nhiều đối tượng khách hàng, kể cả những người có vóc dáng nhỏ nhắn cũng có thể dễ dàng điều khiển chiếc xe này một cách tự tin.</p>\n<p><em>Logo 3D nổi bật</em></p>\n<p>Logo “Sh” 3D nổi bật trên thân <b>xe máy sh mode</b> không chỉ mang hình dáng giống như logo của dòng xe SH cao cấp mà còn thể hiện sự tinh tế qua đường nét bo tròn mềm mại. Logo “mode” tiếp nối với thiết kế tỉ mỉ càng làm tăng thêm giá trị thẩm mỹ cho chiếc xe.</p>\n\n<p><em>Khung dập thế hệ mới eSAF</em></p>\n<p>Một trong những điểm nhấn nổi bật của mẫu <b>xe sh mode</b> chính là khung dập thế hệ mới eSAF, được Honda phát triển với nhiều ưu điểm vượt trội.</p>\n<p>Khung eSAF được chế tạo từ vật liệu nhẹ nhưng vẫn đảm bảo độ bền cao, giúp giảm thiểu trọng lượng tổng thể của xe. Điều này không chỉ mang lại hiệu suất vận hành tốt hơn mà còn tạo cảm giác lái thoải mái và linh hoạt cho người sử dụng. Với thiết kế thông minh, khung eSAF giúp tăng cường khả năng ổn định khi di chuyển, đồng thời cải thiện khả năng xử lý trong các tình huống giao thông khác nhau.</p>\n<h2>2. Khám phá động cơ và tiện ích nổi bật của xe SH Mode</h2>\n<p><em>Động cơ eSP+ 4 van hiện đại</em></p>\n<p><b>Sh mode 125</b> được trang bị động cơ thế hệ mới eSP+ 4 van, mang lại khả năng vận hành mạnh mẽ và hiệu suất tối ưu. Đặc biệt, động cơ này không chỉ giúp tiết kiệm nhiên liệu mà còn góp phần bảo vệ môi trường, thể hiện cam kết của hãng đối với sự phát triển bền vững.</p>\n\n<p><em>Thiết kế mặt đồng hồ sang trọng</em></p>\n<p>Mặt đồng hồ của <b>honda sh mode 125</b> được thiết kế tinh tế, lấy cảm hứng từ những chiếc đồng hồ đeo tay cao cấp. Với kiểu dáng đơn giản nhưng sang trọng cùng viền phát sáng hình tròn, mặt đồng hồ không chỉ dễ nhìn mà còn tạo ra hiệu ứng ánh sáng ấn tượng vào ban đêm, nâng tầm trải nghiệm lái xe.</p>\n<p><em>Hệ thống chống bó cứng phanh (ABS) được trang bị trên phiên bản cao cấp đặc biệt và thể thao</em></p>\n<p>Để đảm bảo an toàn tối đa cho người sử dụng, bánh trước của<b> xe máy sh mode </b>được trang bị hệ thống chống bó cứng phanh ABS. Hệ thống này giúp duy trì sự ổn định khi phanh gấp ở tốc độ cao hoặc trên các đoạn đường trơn trượt, mang lại cảm giác an tâm tuyệt đối cho người lái.</p>\n\n<p><em>Hộc để đồ tiện lợi với cổng sạc USB</em></p>\n<p>Dòng <b>xe sh mode</b> sở hữu hộc để đồ phía trước được tích hợp cổng sạc USB đầy tiện lợi. Điều này không chỉ giúp bạn dễ dàng lưu trữ các vật dụng cá nhân mà còn đảm bảo thiết bị di động luôn được sạc đầy trong suốt hành trình.</p>\n\n<p><em>Không gian lưu trữ rộng rãi dưới yên xe</em></p>\n<p>Với dung tích lên tới 18.5 lít, hộc đựng đồ dưới yên xe của <b>sh mode mới</b> mang đến không gian lưu trữ rộng rãi và thoải mái. Bạn có thể thoải mái chứa đựng đồ dùng cá nhân hay hàng hóa khi đi mua sắm mà không lo thiếu chỗ.</p>\n\n<p><em>Hệ thống khóa thông minh Smart Key</em></p>\n<p>Xe <b>sh mode mới</b> trang bị hệ thống khóa thông minh Smart Key, cho phép người dùng khóa/mở xe từ xa một cách dễ dàng. Tính năng xác định vị trí xe và báo động cũng được tích hợp trong thiết bị điều khiển FOB chỉ với một nút bấm, gia tăng sự tiện lợi và an toàn cho người sử dụng.</p>\n\n<p>Với những tính năng nổi bật trên, <b>xe máy sh mode </b>không chỉ là một phương tiện di chuyển mà còn là biểu tượng của sự sang trọng và hiện đại trong cuộc sống hàng ngày. Hiện tại, ở Hệ thống Siêu Thị Yên Thoa đang có đầy đủ phiên bản của <b>honda sh mode 125</b> với <b>giá xe sh mode </b>vô cùng ưu đãi.</p>\n<h2>3. Địa chỉ mua xe máy SH Mode mới giá rẻ chính hãng</h2>\n<p>Với nhiều năm kinh nghiệm trong ngành xe máy, Yên Thoa tự hào là <a href=\"/xe-may\"><b>đại lý xe máy</b></a> được đông đảo khách hàng lựa chọn. Mỗi chiếc <b>xe sh mode 125</b> tại cửa hàng đều được nhập trực tiếp từ nhà sản xuất, đảm bảo đáp ứng tiêu chuẩn cao về thiết kế, công nghệ hiện đại và tính năng an toàn.</p>\n<p>Đặc biệt, khi đăng ký mua <b>sh mode 125</b> mới trong hôm nay, quý khách còn có cơ hội nhận được những ưu đãi sau:</p>\n<p>– Dịch vụ giao xe tận nơi: Chúng tôi cam kết mang đến sự tiện lợi tối đa cho quý khách với dịch vụ giao xe tận nhà của Yên Thoa</p>\n<p>– Hỗ trợ trả góp lãi suất ưu đãi chỉ từ 0%: Quý khách sẽ được hưởng mức lãi suất cực kỳ hấp dẫn khi lựa chọn hình thức trả góp.</p>\n<p>– Chỉ cần trả trước 10%: Quý khách chỉ cần thanh toán 10% giá trị xe và có thể rước ngay chiếc <b>sh mode mới </b>về nhà.</p>\n<p>– Quà tặng độc quyền trị giá 2.350.000đ: Khi mua xe, quý khách sẽ nhận ngay combo quà tặng đặc biệt cùng hàng ngàn chương trình khuyến mãi khác đang diễn ra.<br>\n</p>\n\n<p>Theo thông tin mới nhất trên thị trường, hiện nay giá <b>xe sh mode</b> tại các đại lý dao động từ 65 đến 70 triệu đồng. Tại Hệ thống Siêu Thị Yên Thoa, chúng tôi đang cung cấp mẫu xe này với mức <strong>giá xe sh mode</strong> ưu đãi chỉ 65.800.000 đồng. Nếu bạn đang có ý định sở hữu một chiếc xe máy Honda chất lượng, hãy đến ngay Yên Thoa để trải nghiệm dịch vụ tuyệt vời.</p>\n<p>Để biết thêm thông tin chi tiết về <b>honda sh mode 125</b> quý khách vui lòng liên hệ với <strong><a href=\"/xe-may?nhom=honda\">cửa hàng honda</a></strong> Yên Thoa qua hotline để được tư vấn nhanh chóng và sớm nhất.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
