INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-sirius-50cc', 'Xe Sirius 50cc', 'xe-50cc', '[\"xe-so\"]', 13900000, 15500000, '/sites/yenthoa/img/2024/11/sirius-50.webp', '[\"/sites/yenthoa/img/2024/11/sirius-50.webp\"]', '[]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Căm Việt Thái\"}],\"img\":\"/sites/yenthoa/img/2024/11/sirius-50.webp\",\"price\":13900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Mâm Victoria\"}],\"img\":\"/sites/yenthoa/img/2024/11/sirius-50.webp\",\"price\":15500000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Mâm Việt Thái\"}],\"img\":\"/sites/yenthoa/img/2024/11/sirius-50.webp\",\"price\":14700000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Mức tiêu hao nhiên liệu\",\"value\":\"1.60 lít / 100 KM\"},{\"label\":\"Động cơ\",\"value\":\"Chạy bằng xăng, 4 kỳ, làm mát bằng không khí\"},{\"label\":\"Vận tốc tối đa\",\"value\":\"50km/h\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"4 lít\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"0.7 lít\"},{\"label\":\"Dung tích xi lanh\",\"value\":\"49.5 cm3\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh đĩa trước và đĩa sau\"},{\"label\":\"Vành xe\",\"value\":\"Đúc\"},{\"label\":\"Lốp trước/sau\",\"value\":\"Lốp trước: 70/90-17 38P TUBE Lốp sau: 80/90-17 50P TUBE\"},{\"label\":\"Giảm Xóc\",\"value\":\"Giảm chấn thuỷ lực\"},{\"label\":\"Càng sau\",\"value\":\"Càng thép đúc nguyên khối\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1914x709x1081\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"740mm\"},{\"label\":\"Trọng lượng\",\"value\":\"84kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]', '<p>Sirius 50 thu hút ánh nhìn ngay từ cái nhìn đầu tiên với thiết kế nhỏ gọn nhưng không kém phần mạnh mẽ. Những đường nét thể thao và cá tính tạo nên một diện mạo cuốn hút, phù hợp với nhiều phong cách khác nhau.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>MUA XE SIRIUS 50CC KHUYẾN MÃI GIÁ TỐT</h2>\n<p>Với động cơ mẽ, khả năng vận hành êm ái và thiết kế nhỏ gọn, <b>sirius 50cc</b> không chỉ là phương tiện di chuyển mà còn là người bạn đồng hành lý tưởng cho mọi đối tượng. Bài viết này sẽ giúp bạn hiểu rõ hơn về những điểm nổi bật của dòng <b>xe sirius 50</b> và <strong>giá xe sirius 50</strong> mới nhất!</p>\n<h2>1. Những điểm nổi bật của dòng xe Sirius 50cc</h2>\n<p><i>Thiết kế độc đáo và cá tính</i></p>\n<p><b>Sirius 50 </b>thu hút ánh nhìn ngay từ cái nhìn đầu tiên với thiết kế nhỏ gọn nhưng không kém phần mạnh mẽ. Những đường nét thể thao và cá tính tạo nên một diện mạo cuốn hút, phù hợp với nhiều phong cách khác nhau. Hiện nay, dòng xe <b>sirius 50 mới</b> có sẵn nhiều màu sắc đa dạng, đáp ứng nhu cầu và sở thích của từng khách hàng.</p>\n<p><i>Hệ thống đèn chiếu sáng hiện đại</i></p>\n<p>Một trong những điểm nhấn của<b> sirius 50cc </b>chính là hệ thống đèn pha lớn sử dụng bóng đèn sợi đốt công suất 35W. Khả năng chiếu sáng vượt trội với hai chế độ chiếu gần và chiếu xa giúp người điều khiển dễ dàng điều chỉnh ánh sáng phù hợp khi di chuyển vào ban đêm. Cặp xi nhan đỏ cá tính hai bên đèn pha càng làm tăng thêm sự nổi bật cho thiết kế tổng thể <b>xe </b><b>sirius 50</b>.</p>\n<p><i>Mặt đồng hồ thông minh</i></p>\n<p>Mặt đồng hồ của <b>sirius 50</b> được thiết kế hiện đại với góc nghiêng tối ưu, giúp người lái dễ dàng quan sát các thông số ngay cả trong điều kiện ánh sáng mạnh mà không bị chói mắt. Đồng hồ hiển thị đầy đủ thông tin về vận tốc, quãng đường, lượng xăng và các tín hiệu cảnh báo khác, giúp người lái kiểm soát tình trạng xe một cách hiệu quả.</p>\n<p><i>Hệ thống phanh an toàn</i></p>\n<p>Bánh xe của <b>sirius 50 mới</b> được trang bị kiểu vành đúc năm chấu kép chắc chắn cùng bộ lốp DRC kích thước lớn với độ rãnh sâu, đảm bảo khả năng bám đường tốt hơn trên mọi địa hình. Hệ thống phanh bao gồm phanh đĩa lớn ở bánh trước và phanh cơ ở bánh sau hoạt động rất nhạy bén, đảm bảo an toàn tối đa cho người sử dụng.</p>\n<p><i>Hệ thống giảm xóc&nbsp;</i></p>\n<p>Hệ thống giảm xóc của <b>sirius 50cc</b> cũng được chú trọng phát triển với công nghệ tiên tiến nhất hiện nay. Giảm xóc trước sử dụng loại thụt dầu hiện đại mang lại cảm giác lái cực kỳ thoải mái; trong khi đó giảm xóc sau là cặp lò xo trụ cao cấp giúp giảm thiểu lực tác động từ mặt đất lên <b>xe </b><b>sirius 50</b>.</p>\n<p><i>Phần đuôi xe tích hợp hệ thống đèn hậu và xi nhan</i></p>\n<p>Phần đuôi xe <b>sirius 50 mới </b>cũng rất tinh tế khi tích hợp hệ thống đèn hậu và xi nhan sau sử dụng bóng đèn sợi đốt chất lượng cao. Đặc biệt, hệ thống này hoạt động đồng bộ với cả phanh tay và phanh chân để đảm bảo an toàn tối đa cho người tham gia giao thông phía sau.</p>\n<h2>2. Động cơ mạnh mẽ và tiết kiệm nhiên liệu của xe sirius 50 mới</h2>\n<p><b>Sirius 50cc</b> không chỉ gây ấn tượng bởi thiết kế mà còn bởi động cơ mạnh mẽ được cải tiến đáng kể. Với dung tích động cơ đạt 49.5cc cùng công nghệ SOHC làm mát bằng không khí, xe <b>sirius 50 mới</b> mang lại khả năng vận hành ổn định và hiệu quả cao.</p>\n<p>Buồng đốt của <b>xe </b><b>sirius 50</b> được thiết kế đặc biệt giúp tăng hiệu suất cháy nhiên liệu, từ đó nâng cao khả năng tăng tốc nhanh chóng mà vẫn tiết kiệm nhiên liệu tối ưu. Với tốc độ tối đa lên đến 50km/h cùng mức tiêu hao nhiên liệu chỉ khoảng 1.7 lít xăng cho mỗi 100km, <b>sirius 50cc</b> thực sự là lựa chọn hàng đầu trong phân khúc xe máy cỡ nhỏ.</p>\n<h2>3. Địa chỉ mua xe sirius 50cc uy tín&nbsp;</h2>\n<p>Hiện nay có rất nhiều cửa hàng chuyên cung cấp các dòng <a href=\"/xe-may?nhom=xe-50cc\"><b>xe 50cc</b></a>, tuy nhiên không phải nơi nào cũng được đảm bảo chất lượng sản phẩm và dịch vụ hậu mãi tốt nhất cho khách hàng.</p>\n<p>Với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh xe máy, Hệ thống Siêu Thị Yên Thoa đã trở thành một địa chỉ uy tín mà nhiều khách hàng tin tưởng lựa chọn khi muốn mua xe máy 50cc nói chung và <b>sirius 50cc</b> nói riêng.</p>\n<p>Hiện giá xe sirius 50cc tại Yên Thoa đang từ 14 triệu đồng, tuỳ vào từng phiên bản giá xe sẽ có thể thay đổi.</p>\n<p>Đặc biệt, khi mua xe <b>sirius 50 mới</b> tại Hệ thống Siêu Thị Yên Thoa, quý khách hàng còn có cơ hội nhận ngay các chương trình khuyến mãi hấp dẫn cùng nhiều ưu đãi đặc biệt.&nbsp;</p>\n<p>– Giá cả cạnh tranh nhất: Hiểu được nhu cầu và mong muốn của khách hàng, Yên Thoa cam kết cung cấp mức <b>giá xe sirius 50</b> tốt nhất trên thị trường, giúp bạn tiết kiệm chi phí mà vẫn sở hữu một chiếc xe chất lượng.</p>\n<p>– Chế độ bảo hành toàn diện: Khách hàng hoàn toàn yên tâm khi mua xe <b>sirius 50</b> tại Yên Thoa với chế độ bảo hành chu đáo, đảm bảo mọi sản phẩm đều đạt tiêu chuẩn chất lượng cao nhất.</p>\n<p>– Hỗ trợ trả góp linh hoạt: Yên Thoa cung cấp các phương thức trả góp linh hoạt với lãi suất ưu đãi chỉ từ 0%, giúp bạn dễ dàng hiện thực hóa ước mơ sở hữu xe <b>sirius 50cc</b> mới yêu thích.</p>\n<p>– Quà tặng hấp dẫn: Cơ hội nhận ngay combo quà tặng độc quyền giá trị lên đến 2.350.000đ, bao gồm 11 phần quà hấp dẫn.</p>\n<p>– Dịch vụ hậu mãi xuất sắc: Đội ngũ hỗ trợ khách hàng của Yên Thoa luôn sẵn sàng phục vụ và tư vấn tận tình sau khi bạn mua sản phẩm, đảm bảo sự hài lòng tuyệt đối cho từng khách hàng.</p>\n<p>Nếu bạn đang tìm kiếm một địa chỉ uy tín để <a href=\"/\"><b>mua xe máy</b></a> <b>sirius 50cc</b> thì còn chờ gì mà không liên hệ với Yên Thoa qua hotline để được tư vấn miễn phí!</p>\n<p>Xe <b>sirius 50 </b>không chỉ đơn thuần là phương tiện di chuyển mà còn mang đến trải nghiệm tuyệt vời cho người dùng nhờ vào thiết kế tinh tế cùng công nghệ tiên tiến vượt trội. Nếu bạn đang tìm kiếm một chiếc xe vừa tiết kiệm nhiên liệu vừa an toàn thì chắc chắn rằng <b>sirius 50cc</b> sẽ là lựa chọn hoàn hảo dành cho bạn! Mọi chi tiết xin về <strong>giá xe sirius 50</strong>, quý khách vui lòng liên hệ qua hotline để được tư vấn.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
