c\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sirius-phien-ban-phanh-co-mau-xam-den.webp\",\"price\":27800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Phanh cơ\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sirius-phien-ban-phanh-co-mau-do-den.webp\",\"price\":27800000}]' WHERE slug = 'xe-sirius' AND variants IS NULL;
