INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-super-cub-125', 'Xe Super Cub', 'honda', '[\"xe-so\"]', 92300000, 110300000, '/sites/yenthoa/img/2024/11/super-cub-phien-ban-tieu-chuan-mau-xanh-duong.webp', '[\"/sites/yenthoa/img/2024/11/super-cub-phien-ban-tieu-chuan-mau-xanh-duong.webp\"]', '[\"Đen\",\"Xanh dương\",\"Xanh nhạt Xám\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh nhạt Xám\"}],\"img\":\"/sites/yenthoa/img/2024/11/super-cub-phien-ban-tieu-chuan-mau-xanh-xam.webp\",\"price\":92300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/super-cub-phien-ban-dac-biet-mau-den.webp\",\"price\":110300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh dương\"}],\"img\":\"/sites/yenthoa/img/2024/11/super-cub-phien-ban-tieu-chuan-mau-xanh-duong.webp\",\"price\":92300000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"3,7 lít\"},{\"label\":\"Loại động cơ\",\"value\":\"4 kỳ, 1 xy-lanh, làm mát bằng không khí\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,87kW/7.500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả: 0,80 lít Sau khi xả & thay bộ lọc dầu động cơ: 0,85 lít Sau khi rã máy: 1,00 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,52l/100km\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"10,15Nm/5.000 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"123.94 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"50,000 x 63,121 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"10:01\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Trước: 70/90-17 Sau: 80/90-17\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ đôi\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"109kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.910 x 718 x 1.002 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.243mm\"},{\"label\":\"Độ cao yên\",\"value\":\"780mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"136mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Dòng xe số cao cấp của honda, xe cub 125 từ lâu đã khẳng định vị thế của mình trong lòng người tiêu dùng nhờ thiết kế ấn tượng và tính năng vượt trội.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE SUPER CUB 125 MỚI NHẤT CỦA HONDA</h2>\n<p><b>Cub 125</b> là một trong những dòng xe số cao cấp nhất của Honda, không chỉ nổi bật với thiết kế cổ điển, độc đáo và cuốn hút, <b>super cub c125</b> còn gây ấn tượng nhờ động cơ bền bỉ và khả năng tiết kiệm nhiên liệu vượt trội. <strong>Honda s</strong><strong>uper cub</strong> không chỉ đơn thuần là một phương tiện di chuyển mà còn là sự kết hợp hoàn hảo giữa phong cách và hiệu suất, đáp ứng nhu cầu của những ai yêu thích sự hoài cổ nhưng vẫn muốn tận hưởng công nghệ hiện đại.</p>\n\n<p>Quý khách hàng đang có nhu cầu mua <b>xe cub 125</b> hoặc tham khảo <b>giá xe cub 125</b> vui lòng liên hệ với Hệ thống Siêu Thị Yên Thoa qua hotline. Dưới đây là bài giới thiệu về dòng <b>xe cub 125</b> mới nhất hiện nay.</p>\n<h2>1. Thiết kế ấn tượng của dòng xe số cao cấp Honda Super Cub</h2>\n<p>Dòng xe số cao cấp <b>honda super cub</b> từ lâu đã khẳng định vị thế của mình trong lòng người tiêu dùng nhờ thiết kế ấn tượng và tính năng vượt trội. Với sự kết hợp hoàn hảo giữa nét cổ điển và hiện đại, <b>super cub</b> không chỉ là một phương tiện di chuyển mà còn là biểu tượng của phong cách sống tinh tế.</p>\n<p>Thiết kế của <b>honda super cub</b> mang đậm dấu ấn huyền thoại với hình dáng chữ S đặc trưng, gợi nhớ đến những chiếc xe <b>super cub</b> đầu tiên xuất hiện vào thập niên 50. Kiểu dáng này không chỉ tạo nên sự hài hòa và mềm mại mà còn thể hiện được vẻ đẹp vượt thời gian. Lớp sơn nhũ ánh kim kết hợp cùng các chi tiết mạ crôm tinh tế càng làm nổi bật lên sự sang trọng và đẳng cấp của dòng xe này. Đây chính là điểm nhấn giúp <b>xe cub 125</b> luôn giữ vững vị thế trong lòng những người yêu thích phong cách cổ điển.</p>\n\n<p>Không chỉ chú trọng vào thiết kế bên ngoài, thương hiệu <a href=\"/xe-may?nhom=honda\"><b>xe honda</b></a> còn đặc biệt quan tâm đến trải nghiệm lái xe của người dùng. Tay lái được thiết kế tối ưu giúp người điều khiển có tư thế ngồi thẳng lưng thoải mái, đồng thời dễ dàng kiểm soát và cân bằng xe trên mọi cung đường. Điều này không chỉ mang lại cảm giác an toàn mà còn giúp giảm thiểu mệt mỏi khi di chuyển trên quãng đường dài.</p>\n<p>Về màu sắc, phiên bản mới của <b>super cub c125</b> mang đến cho khách hàng nhiều lựa chọn hơn với ba gam màu chủ đạo: đen, xanh xám và xanh dương. Đặc biệt, màu xanh dương mới lấy cảm hứng từ chiếc <b>honda super cub</b> ra mắt lần đầu tiên vào năm 1958, không chỉ gợi nhớ về quá khứ Yên Thoa mà còn tôn lên vẻ đẹp lịch lãm và sang trọng cho chiếc xe. Sự đa dạng về màu sắc này giúp người dùng dễ dàng thể hiện cá tính riêng cũng như nâng tầm phong cách cá nhân.</p>\n<h2>2. Động cơ mạnh mẽ và tiện ích hiện đại của xe Cub 125</h2>\n<p>Động cơ bền bỉ và hiệu suất vượt trội</p>\n<p><b>Xe cub 125</b> được trang bị động cơ 125cc, SOHC với công nghệ PGM-FI, cho phép đạt công suất tối đa lên đến 6,87kW và mô men xoắn cực đại 10,15Nm. Điều này không chỉ mang lại khả năng vận hành mạnh mẽ mà còn giúp tiết kiệm nhiên liệu một cách tối ưu, đáp ứng nhu cầu di chuyển hàng ngày của người dùng.</p>\n\n<p>Hệ thống khóa thông minh tiện lợi</p>\n<p><strong>Honda super cub</strong> được trang bị chìa khóa thông minh với ba chức năng nổi bật: cảnh báo chống trộm, xác định vị trí xe và khởi động hệ thống điện. Tính năng này không chỉ nâng cao tính bảo mật mà còn mang lại sự thuận tiện cho người sử dụng trong việc quản lý phương tiện.</p>\n\n<p>Hệ thống chiếu sáng LED hiện đại</p>\n<p>Với hệ thống đèn LED tiên tiến,&nbsp; <b>super cub c125</b> cải thiện đáng kể tầm nhìn khi di chuyển vào ban đêm. Bên cạnh đó, hệ thống đèn AHO (Always Head On) luôn sáng giúp tăng khả năng nhận diện của xe trên đường, từ đó giảm thiểu nguy cơ va chạm và đảm bảo an toàn cho người lái.</p>\n\n<p>Mặt đồng hồ hiện đại và phanh đĩa thủy lực</p>\n<p>Mặt đồng hồ <strong>xe cub 125</strong> được thiết kế tinh tế với hai hình tròn đồng tâm, nổi bật giữa là vòng crôm sang trọng. Màn hình LCD hiển thị đầy đủ thông tin cần thiết như lượng xăng trong bình, quãng đường đã đi và thời gian. Hơn nữa, với phanh đĩa thủy lực phía trước cùng vành xe nhôm đúc 17 inch sử dụng lốp không săm, xe mang đến cảm giác vận hành ổn định và khả năng dừng xe hiệu quả.</p>\n\n<p>Yên xe thoải mái cho mọi hành trình</p>\n<p>Yên xe trước và sau được thiết kế với lớp đệm Urethane dày dạn cùng độ đàn hồi cao. Điều này không chỉ tạo cảm giác êm ái mà còn đảm bảo sự thoải mái tối đa cho cả người lái lẫn hành khách trong suốt những chuyến đi dài.</p>\n<p>Với những tính năng vượt trội này, <b>xe cub 125</b> không chỉ là phương tiện di chuyển mà còn là người bạn đồng hành đáng tin cậy trên mọi nẻo đường.</p>\n<h2>3. Giá xe Cub 125 mới nhất tại Hệ thống Siêu Thị Yên Thoa&nbsp;</h2>\n<p>Được xem là “biểu tượng của huyền thoại”, <b>honda super cub</b> là dòng xe số cực hiếm và có giá đắt nhất trên thị trường.</p>\n<p>Hiện tại, <b>giá xe cub 125</b> đang được bán tại Yên Thoa với mức giá cực thấp chỉ từ 92.300.000đ. Quý khách hàng đang có nhu cầu tham khảo <b>giá xe cub 125</b> vui lòng liên hệ qua hotline để được tư vấn miễn phí!</p>\n<p>Với hơn 25 năm kinh nghiệm trong ngành kinh doanh xe máy, Yên Thoa tự hào là địa chỉ tin cậy cho mọi khách hàng. Chúng tôi cam kết mang đến cho bạn trải nghiệm dịch vụ hoàn hảo từ khâu tư vấn chọn lựa <strong>xe cub 125</strong> cho đến khi hoàn tất thủ tục mua bán.</p>\n\n<p>Đặc biệt, khi mua xe tại <a href=\"/xe-may\"><b>cửa hàng xe máy</b></a> Yên Thoa trong hôm nay, quý khách sẽ nhận được những ưu đãi hấp dẫn:</p>\n<p>– Combo quà tặng độc quyền trị giá 2.350.000đ bao gồm 11 phần quà</p>\n<p>– Dịch vụ giao xe tận nhà: Chúng tôi sẽ giao xe đến tận nơi bạn mong muốn, bất cứ lúc nào.</p>\n<p>– Hỗ trợ mua xe trả góp với lãi suất cực thấp chỉ 0%</p>\n<p>– Chương trình thu mua xe cũ với giá cao, giúp bạn dễ dàng đổi sang chiếc xe mới.</p>\n<p>– Dịch vụ cứu hộ tận nơi và bảo hành chính hãng, đảm bảo sự an tâm cho bạn trong suốt quá trình sử dụng.</p>\n<p>Hãy đến với Hệ thống Siêu Thị Yên Thoa để trải nghiệm dịch vụ tốt nhất và sở hữu ngay chiếc <b>xe cub 125</b> huyền thoại!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
