INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-vario-125', 'Xe Vario 125', 'honda', '[]', 42800000, 43800000, '/sites/yenthoa/img/2024/11/vario-125-phien-ban-the-thao-mau-xanh-den.webp', '[\"/sites/yenthoa/img/2024/11/vario-125-phien-ban-the-thao-mau-xanh-den.webp\"]', '[\"Đen\",\"Đỏ Đen\",\"Xanh đậm Đen\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vario-125-phien-ban-dac-biet-mau-do-den-2.webp\",\"price\":42800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vario-125-phien-ban-dac-biet-mau-do-den.webp\",\"price\":42800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vario-125-phien-ban-the-thao-mau-xanh-den.webp\",\"price\":43800000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"5,5 lít\"},{\"label\":\"Loại động cơ\",\"value\":\"4 kỳ, 1 xi lanh, làm mát bằng chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"8,19kW/8500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Xả: 0,8 lít Tháo rã: 0,9 lít Thay lọc dầu: 0,8 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2,16l/100km\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"10,79Nm/5000 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"125\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"52,400 x 57,907 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,0 : 01\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Trước: 90/80 - 14M/C 43P Sau: 100/80 - 14M/C 48P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ đơn, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"113 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1918 mm x 679 mm x 1066 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1280 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"769 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"131 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Mẫu xe honda vario 125 không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn là biểu tượng cho phong cách sống năng động và sành điệu của giới trẻ.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE VARIO 125 CHÍNH HÃNG KHUYẾN MÃI CỦA HONDA&nbsp;</h2>\n<p>Được xây dựng hướng tới hình ảnh của một mẫu xe ga phổ thông hiện đại,<b> vario 125</b> không chỉ thu hút sự chú ý mà còn tạo nên ấn tượng mạnh mẽ nhờ vào thiết kế thể thao, trẻ trung mang đậm dấu ấn cá nhân. Mẫu xe <b>honda vario 125 </b>không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn là biểu tượng cho phong cách sống năng động và sành điệu của giới trẻ. <b>Xe vario 125</b> giúp người lái tự tin thể hiện cái tôi độc đáo và khẳng định cá tính riêng biệt, tạo nên một trải nghiệm lái xe thú vị và đầy cảm hứng.</p>\n\n<p>Hãy cùng khám phá ngay những ưu điểm nổi bật của xe <b>vario 125 chính hãng</b> và <b>giá xe vario 125</b> mới nhất qua bài viết dưới đây.</p>\n<h2>1. Thiết kế xe Honda Vario 125 sự kết hợp hoàn hảo giữa thể thao và trẻ trung</h2>\n<p>Kể từ lần đầu ra mắt tại thị trường Việt Nam, dòng xe <b>vario 125 chính hãng </b>đã nhanh chóng trở thành mẫu xe tay ga được yêu thích nhất hiện nay. Với thiết kế hiện đại, tinh tế và đầy cá tính, <b>vario 125 mới </b>không chỉ thu hút ánh nhìn mà còn mang đến trải nghiệm lái xe tuyệt vời cho người sử dụng.</p>\n\n<p>Thiết kế phía trước ấn tượng</p>\n<p><b>Vario 125</b> nổi bật với thiết kế phía trước mạnh mẽ và đầy cá tính. Những đường nét góc cạnh cùng hốc gió khí động học không chỉ tạo nên vẻ ngoài hầm hố mà còn tối ưu hóa hiệu suất vận hành. Đặc biệt, phần đầu đèn được thiết kế sắc sảo, vuốt nhọn về phía trước, kết hợp hoàn hảo với hệ thống đèn chiếu sáng hiện đại và dãy đèn LED trang trí tinh tế. Điều này không chỉ mang lại ánh sáng tốt trong mọi điều kiện mà còn tạo nên hình ảnh nổi bật, thể hiện phong cách riêng biệt của người sở hữu.</p>\n\n<p>Thiết kế đuôi xe hiện đại và cân đối</p>\n<p>Phần đuôi xe của<b> honda vario 125</b> được thiết kế cân xứng, hài hòa với tổng thể xe, góp phần nâng cao tính thẩm mỹ và sự hoàn thiện. Đèn hậu LED đồng bộ không chỉ mang lại vẻ đẹp sang trọng mà còn đảm bảo độ bền bỉ. Đặc biệt, đèn xi nhan sau được tách rời với kiểu dáng thể thao, tạo điểm nhấn cá tính nhưng vẫn giữ được sự gọn gàng, dễ dàng liên tưởng đến những mẫu xe phân khối lớn.</p>\n\n<p>Vành đúc thể thao và phanh hiệu suất cao</p>\n<p>Xe được trang bị phanh đĩa phía trước lượn sóng cùng bộ vành có thiết kế thể thao, đi kèm với lốp không săm kích thước rộng. Sự kết hợp này giúp tăng cường độ ổn định và khả năng bám đường, mang lại cảm giác lái thoải mái và linh hoạt cho người sử dụng trong các tình huống di chuyển hàng ngày.</p>\n\n<p>Sàn để chân thiết kế bằng phẳng</p>\n<p>Một điểm cộng lớn cho<b> xe vario 125</b> là sàn để chân bằng phẳng, mang lại sự thoải mái tối đa cho người lái cũng như hành khách. Thiết kế này không chỉ giúp dễ dàng di chuyển mà còn tạo cảm giác tự do hơn trong suốt hành trình.</p>\n\n<h2>2. Động cơ của Vario 125 hiệu suất vượt trội và tiết kiệm nhiên liệu hiệu quả</h2>\n<p><b>Vario 125 chính hãng</b> được trang bị động cơ 125cc mạnh mẽ, mang đến cho người lái nghiệm vận hành mượt mà và hiệu quả. Một trong những điểm nổi bật của động cơ này là hệ thống Idling stop, cho phép ngắt động cơ tạm thời khi dừng. Tính năng không chỉ giúp giảm thiểu tiếng ồn trong đô thị mà còn tối ưu hóa mức tiêu thụ nhiên liệu, góp phần tiết kiệm chi phí cho người sử dụng.</p>\n<p>Hệ thống idling stop hoạt động thông minh, tự động khởi động lại khi người lái nhấn ga, đảm bảo sự thuận tiện và an toàn trong quá trình di chuyển. Nhờ vào công nghệ tiên tiến này, <b>vario 125 mới </b>không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn thể hiện cam kết bảo vệ môi trường thông qua việc giảm lượng khí thải.</p>\n\n<p>Với thiết kế hiện đại và tính năng thân thiện với người dùng, <b>honda vario 125</b> là lựa chọn lý tưởng cho những ai tìm kiếm một phương tiện di chuyển vừa tiết kiệm nhiên liệu vừa bảo vệ môi trường. Sự kết hợp hoàn hảo giữa hiệu suất và bền vững chính là điểm nhấn tạo nên sức hút của mẫu xe này.</p>\n<h2>3. Tiện ích nổi bật của xe Vario 125 chính hãng</h2>\n<p><b>Xe vario 125 </b>đã nhanh chóng trở thành một trong những lựa chọn hàng đầu cho những ai yêu thích sự kết hợp hoàn hảo giữa thiết kế hiện đại và tính năng tiện ích. Dưới đây là những điểm nổi bật giúp chiếc xe này ghi điểm trong lòng người tiêu dùng.</p>\n<p>Hệ thống khóa thông minh Smart Key</p>\n<p><b>Vario 125 mới </b>được trang bị hệ thống khóa thông minh Smart Key, mang đến sự tiện lợi và an toàn tối đa cho người sử dụng. Hệ thống này không chỉ giúp xác định vị trí xe một cách nhanh chóng mà còn cho phép mở khóa từ xa. Đặc biệt, chức năng báo động tích hợp giúp tăng cường cảm giác an tâm cho người lái, bảo vệ xe khỏi những rủi ro không mong muốn.</p>\n\n<p>Mặt đồng hồ LCD hiện đại</p>\n<p><b>Xe vario 125</b> sở hữu cụm đồng hồ hiển thị màn hình LCD hiện đại, cung cấp đầy đủ và trực quan các thông tin cần thiết như hành trình, tốc độ, mức tiêu thụ nhiên liệu trung bình và hiện tại. Ngoài ra, đồng hồ còn hiển thị điện áp ắc quy, nhắc nhở thay nhớt máy cùng với các đèn cảnh báo quan trọng như đèn idling stop, dung dịch làm mát, báo động chống trộm và lỗi phun xăng điện tử. Tất cả những tính năng này giúp người dùng dễ dàng theo dõi tình trạng xe một cách hiệu quả.</p>\n\n<p>Cổng sạc USB tiện lợi</p>\n<p>Với sự tích hợp cổng sạc USB loại A có cường độ 2.1A ở hộc đựng đồ phía trước, <b>honda vario 125</b> mang đến sự tiện nghi tối ưu cho người dùng. Việc sạc điện thoại trong quá trình di chuyển trở nên dễ dàng hơn bao giờ hết, đáp ứng nhu cầu kết nối của người dùng hiện đại.</p>\n\n<p>Hộc đựng đồ dưới yên rộng rãi</p>\n<p>Hộc đựng đồ dưới yên của <b>vario 125</b> có dung tích lên đến 18 lít, đủ sức chứa một mũ bảo hiểm nửa đầu cùng nhiều vật dụng cá nhân khác. Thiết kế rộng rãi này không chỉ tạo sự thuận tiện trong việc di chuyển mà còn giúp người dùng dễ dàng tổ chức đồ đạc khi ra ngoài.</p>\n\n<h2>4. Địa chỉ mua xe Vario 125 mới giá rẻ</h2>\n<p>Nếu bạn đang tìm kiếm một địa chỉ uy tín để mua xe<b> vario 125 chính hãng</b>, hãy đến ngay với Hệ thống Siêu Thị Yên Thoa! Là đại lý phân phối của những thương hiệu xe máy hàng đầu hiện nay, bao gồm: Honda, Yamaha, SYM, Suzuki và xe điện Yadea, Yên Thoa cam kết mang đến cho khách hàng những sản phẩm chất lượng cao cùng<b> giá xe vario 125</b> tốt nhất trên thị trường.&nbsp;</p>\n<p><b>Giá xe vario 125</b> phiên bản đặc biệt: 42.800.000đ</p>\n<p><b>Giá xe vario 125</b> phiên bản thể thao: 43.800.000đ</p>\n\n<p>Dưới đây là những lợi ích khi mua xe <b>honda vario 125</b> mới tại Hệ thống Siêu Thị Yên Thoa</p>\n<p>– Giao xe tận nơi: Chúng tôi cung cấp dịch vụ giao xe nhanh chóng và tiện lợi, giúp bạn tiết kiệm thời gian và công sức.</p>\n<p>– Bảo hành chính hãng: Với chế độ bảo hành từ nhà sản xuất, bạn hoàn toàn yên tâm về chất lượng và độ bền của chiếc xe mình sở hữu.</p>\n<p>– Quà tặng hấp dẫn: Khi mua <a href=\"/xe-may?nhom=honda\"><b>xe máy honda</b></a> tại Yên Thoa, bạn sẽ nhận ngay combo quà tặng độc quyền trị giá lên đến 2.350.000đ cùng nhiều ưu đãi đặc biệt khác.</p>\n<p>– Hỗ trợ trả góp linh hoạt: Chúng tôi cung cấp gói trả góp với lãi suất cực thấp, chỉ từ 0%, giúp bạn dễ dàng sở hữu chiếc xe mơ ước mà không phải lo lắng về tài chính.</p>\n<p>– Chương trình thu cũ đổi mới: Với thủ tục đơn giản và nhanh chóng, bạn có thể đổi chiếc xe cũ của mình lấy một chiếc Honda tay ga hoàn toàn mới.</p>\n<p>Đừng bỏ lỡ cơ hội sở hữu chiếc<b> xe vario 125 </b>đẳng cấp! Liên hệ ngay với chúng tôi qua hotline để được tư vấn chi tiết về <a href=\"/xe-may\"><strong>giá xe máy</strong></a> và trải nghiệm dịch vụ tốt nhất từ Hệ thống Siêu Thị Yên Thoa!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
