INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-vario-160', 'Xe Vario 160', 'honda', '[]', 52200000, 56000000, '/sites/yenthoa/img/2024/11/vario-160-phien-the-thao-biet-mau-xam-den-bac.webp', '[\"/sites/yenthoa/img/2024/11/vario-160-phien-the-thao-biet-mau-xam-den-bac.webp\"]', '[\"Đen Bạc\",\"Đỏ Đen Bạc\",\"Xám Đen Bạc\",\"Xanh đậm Đen Bạc\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/vario-160-phien-ban-cao-cap-mau-xanh-den-bac.webp\",\"price\":53300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/vario-160-phien-ban-tieu-chuan-mau-den-bac.webp\",\"price\":52200000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/vario-160-phien-ban-dac-biet-mau-do-den-bac.webp\",\"price\":54700000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/vario-160-phien-the-thao-biet-mau-xam-den-bac.webp\",\"price\":56000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"5,5 L\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xy - lanh, làm mát bằng chất lỏng\"},{\"label\":\"Công suất tối đa\",\"value\":\"11,3kW/8.500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Khi thay dầu: 0.8 lít Khi tháo lọc dầu: 0.85 lít Khi tháo rã: 0.9 lít\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"2,20 lít/100km\"},{\"label\":\"Loại truyền động\",\"value\":\"Tự động, vô cấp\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"14,1 N・m/6.500 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"156,9 cm³\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"60,0 x 55,5 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"12,0 : 1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Lốp trước:100/80-14 M/C48P Lốp sau:120/70-14 M/C61P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"118 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1929 mmx695 mm x 1088 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.278 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"778 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"138 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Với thiết kế thể thao đầy ấn tượng, vario 160 đã chinh phục trái tim của nhiều khách hàng trẻ tuổi, những người luôn tìm kiếm sự mới mẻ và khác biệt trong từng chi tiết.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>CẬP NHẬT GIÁ XE VARIO 160 CHÍNH HÃNG CỦA HONDA</h2>\n<p><b>Honda vario 160 </b>nổi bật với thiết kế thể thao độc đáo, mang đậm dấu ấn cá tính riêng biệt. Được trang bị động cơ eSP+ mạnh mẽ với dung tích 160cc,<b> xe vario 160 </b>không chỉ đảm bảo hiệu suất vượt trội mà còn mang lại trải nghiệm lái đầy phấn khích. Hãy cùng Yên Thoa khám giá ngay những ưu điểm nổi bật của <b>vario 160 chính hãng</b> và <b>giá xe vario 160</b> mới nhất hiện nay.</p>\n\n<h2>1. Những ưu điểm nổi bật trong thiết kế của xe Vario 160&nbsp;</h2>\n<p>Với thiết kế thể thao đầy ấn tượng, <b>vario 160</b> đã chinh phục trái tim của nhiều khách hàng trẻ tuổi, những người luôn tìm kiếm sự mới mẻ và khác biệt trong từng chi tiết.</p>\n<p><em>Thiết kế thể thao đầy ấn tượng</em></p>\n<p><b>Xe vario 160 </b>sở hữu một diện mạo mạnh mẽ và bề thế, thể hiện rõ nét DNA thể thao trong từng đường nét. Thiết kế này không chỉ thu hút ánh nhìn mà còn mang lại cảm giác trẻ trung, năng động cho người sử dụng. Mỗi chi tiết trên xe đều được chăm chút tỉ mỉ, từ phần đầu xe đến đuôi xe, tạo nên một tổng thể hài hòa và cuốn hút.</p>\n\n<p><em>Khung dập hàn eSAF – Sự kết hợp hoàn hảo giữa thẩm mỹ và độ bền</em></p>\n<p>Một trong những điểm nhấn đáng chú ý nhất của<b> honda vario 160</b> chính là hệ thống khung dập hàn eSAF. Công nghệ này không chỉ mang lại độ bền vượt trội mà còn giúp tối ưu hóa trọng lượng xe. Nhờ đó, người lái có thể cảm nhận được sự ổn định và an toàn trong từng chuyến đi. Khung xe được thiết kế tinh tế, vừa đảm bảo tính thẩm mỹ vừa tăng cường khả năng chịu lực.</p>\n<p><em>Hệ thống đèn led hiện đại</em></p>\n<p>Một trong những điểm nhấn nổi bật của<b> vario 160 chính hãng</b> là hệ thống đèn LED tiên tiến. Công nghệ LED không chỉ giúp tiết kiệm năng lượng mà còn nâng cao khả năng nhận diện cho xe trong mọi điều kiện ánh sáng. Cụm đèn LED phía trước được thiết kế tinh xảo với các đường nét sắc sảo, kết hợp cùng đèn định vị ban ngày tách rời tạo nên vẻ đẹp hiện đại và sang trọng. Đặc biệt, đèn hậu được bố trí gọn gàng ở phía sau với hiệu ứng 3D độc đáo, mang lại sự khác biệt cho chiếc xe khi di chuyển trên đường.</p>\n\n<p><em>Sàn để chân tiện lợi và thoải mái</em></p>\n<p>Với sàn để chân phẳng rộng rãi lên tới 422mm, <b>vario 160</b> mang đến sự tiện lợi tối đa cho người lái. Thiết kế này không chỉ giúp việc di chuyển trở nên dễ dàng hơn mà còn tạo cảm giác thoải mái khi sử dụng hàng ngày. Người dùng có thể dễ dàng đặt chân lên sàn mà không gặp phải bất kỳ trở ngại nào.</p>\n\n<p><em>Bánh xe kích thước lớn tăng cường khả năng bám đường</em></p>\n<p><b>Xe vario 160 </b>được trang bị bộ lốp lớn với kích thước (100/80-14 cho bánh trước và 120/70-14 cho bánh sau), giúp tăng cường khả năng bám đường và ổn định khi vận hành. Bộ mâm hình chữ Y không chỉ góp phần tạo nên vẻ ngoài mạnh mẽ mà còn hỗ trợ tối ưu hóa hiệu suất lái xe. Sự kết hợp giữa lốp lớn và thiết kế khung chắc chắn giúp người lái tự tin hơn khi di chuyển trên nhiều loại địa hình khác nhau.</p>\n<p>Tổng thể thiết kế của <b>honda vario 160</b> không chỉ chú trọng vào tính thẩm mỹ mà còn đảm bảo tính tiện dụng và an toàn cho người sử dụng. Với những ưu điểm nổi bật như thiết kế thể thao đầy cuốn hút, hệ thống đèn LED hiện đại, sàn để chân rộng rãi cùng bánh xe kích thước lớn, <b>vario 160</b> thực sự là lựa chọn lý tưởng cho những ai yêu thích sự mới mẻ và phong cách sống năng động. </p>\n<p>Mẫu <a href=\"/xe-may?nhom=honda\"><strong>xe honda</strong></a> này hứa hẹn sẽ đồng hành cùng bạn trên mọi nẻo đường với sự tự tin và phong cách riêng biệt! Nếu bạn đang muốn tìm hiểu về <b>giá xe vario 160</b> vui lòng liên hệ với Yên Thoa qua hotline để được tư vấn nhanh chóng.</p>\n<h2>2. Những ưu điểm nổi bật về động cơ của Honda Vario 160</h2>\n<p><b>Honda vario 160</b> được trang bị động cơ eSP+ 4 van, đại diện cho thế hệ cơ tiên tiến nhất hiện nay của Honda Việt Nam. Sự cải tiến này không chỉ mang lại hiệu suất vận hành vượt trội mà còn thể hiện sự cam kết của Honda trong việc phát triển công nghệ bền vững.</p>\n\n<p>Với dung tích 160cc, động cơ của <b>vario 160 chính hãng</b> cung cấp sức mạnh mạnh mẽ, giúp người lái dễ dàng di chuyển trong các tình huống giao thông khác nhau. Đặc biệt, công nghệ eSP+ giúp tối ưu hóa quá trình đốt cháy nhiên liệu, từ đó nâng cao hiệu suất và giảm thiểu mức tiêu thụ nhiên liệu. Điều này không chỉ tiết kiệm chi phí cho người sử dụng mà còn góp phần bảo vệ môi trường.</p>\n<h2>3. Những ưu điểm nổi bật về tiện ích và an toàn của Vario 160 chính hãng</h2>\n<p><b>Vario 160 chính hãng</b> không chỉ thu hút người dùng bởi thiết kế hiện đại mà còn nổi bật với nhiều tính năng tiện ích và an toàn vượt trội. Dưới đây là những điểm đáng chú ý của mẫu xe này:</p>\n<p><em>Đèn chiếu sáng luôn bật</em></p>\n<p>Hệ thống đèn chiếu sáng phía trước luôn được duy trì ở chế độ sáng, giúp người lái có tầm nhìn tối ưu trong mọi điều kiện ánh sáng. Tính năng này không chỉ giảm thiểu nguy cơ quên bật đèn khi di chuyển mà còn nâng cao khả năng nhận diện của xe, giúp các phương tiện khác dễ dàng quan sát và tránh va chạm.</p>\n<p><em>Hệ thống khóa thông minh Smart Key</em></p>\n<p>Với thiết kế thông minh, hệ thống khóa điện Smart Key cho phép người dùng mở khóa xe, khóa cổ xe, định vị vị trí xe và kích hoạt chức năng báo động chỉ bằng một thao tác đơn giản. Điều này không chỉ mang lại sự tiện lợi mà còn tăng cường cảm giác an tâm cho người sử dụng.</p>\n\n<p><em>Hộc đựng đồ phía trước rộng rãi kèm cổng sạc USB</em></p>\n<p><b>Vario 160 </b>được trang bị hai hộc chứa đồ phía trước rộng rãi, trong đó hộc bên trái có nắp che tích hợp cổng sạc USB loại A với công suất tối đa 10,5W (5V – 2,1A). Tính năng này cho phép người dùng sạc điện thoại một cách thuận tiện ngay cả khi đang di chuyển.</p>\n\n<p><em>Hộc đựng đồ dưới yên lớn</em></p>\n<p>Hộc đựng đồ dưới yên có dung tích lên tới 17,9 lít, đủ sức chứa một mũ bảo hiểm nửa đầu cùng nhiều vật dụng cá nhân khác. Điều này mang lại sự thoải mái và tiện lợi cho người sử dụng khi cần mang theo đồ đạc.</p>\n\n<p>Hệ thống chống bó cứng phanh ABS cho bánh trước được trang bị ở phiên bản thể thao và đặc biệt</p>\n<p>Hệ thống phanh ABS giúp duy trì sự ổn định của xe trong những tình huống phanh gấp ở tốc độ cao hoặc trên đường trơn ướt. Tính năng này mang lại cảm giác an toàn hơn cho người lái trong quá trình vận hành.</p>\n<p><b>Xe vario 160</b> không chỉ là một phương tiện di chuyển mà còn là một giải pháp hoàn hảo cho những ai tìm kiếm sự tiện ích và an toàn trên từng chặng đường. Với những tính năng nổi bật như vậy, <b>vario 160 chính hãng </b>xứng đáng là lựa chọn hàng đầu cho các tín đồ yêu thích sự hiện đại và thông minh trong thiết kế xe máy.</p>\n<h2>4. Cập nhật giá xe Vario 160 chính hãng tại Xe máy Yên Thoa</h2>\n<p>Trước khi quyết định mua xe, việc lựa chọn một <a href=\"/xe-may\"><strong>cửa hàng xe máy</strong></a> uy tín và chất lượng là yếu tố quan trọng hàng đầu. Đặc biệt, nếu bạn đang tìm kiếm một chiếc <b>xe vario 160</b> chính hãng, việc tìm đến các đại lý phân phối tại Việt Nam của Honda là điều cần thiết để đảm bảo quyền lợi và chất lượng sản phẩm.</p>\n<p>Hiện nay,<b> giá xe vario 160 </b>trên thị trường rất đa dạng và có sự khác biệt giữa các cửa hàng. Điều này khiến người tiêu dùng cần phải cân nhắc lựa chọn kỹ lưỡng trước khi đưa ra quyết định.</p>\n<p><b>Giá xe vario 160</b> tại Yên Thoa đang chỉ từ 52 triệu đồng, tuỳ theo từng phiên bản và màu sắc mà giá xe sẽ có sự thay đổi.&nbsp;</p>\n\n<p>Hệ thống Siêu Thị Yên Thoa tự hào là đại lý chính hãng của Honda với nhiều năm kinh nghiệm trong lĩnh vực kinh doanh xe máy. Chúng tôi cam kết mang đến cho quý khách hàng những sản phẩm chất lượng cao cùng dịch vụ hậu mãi chuyên nghiệp nhất. Với đội ngũ nhân viên giàu kinh nghiệm và tận tâm, Yên Thoa luôn sẵn sàng hỗ trợ khách hàng trong mọi khâu từ tư vấn chọn xe đến bảo dưỡng sau bán hàng. </p>\n<p>Chúng tôi hiểu rằng mỗi khách hàng đều có những nhu cầu và mong muốn riêng biệt. Chính vì vậy, Yên Thoa không ngừng nỗ lực cải thiện dịch vụ để đáp ứng tốt nhất nhu cầu của quý khách. Mọi chi tiết về <b>honda vario 160</b> quý khách vui lòng liên hệ qua hotline để được tư vấn miễn phí.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
