INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-vepsa-50cc', 'Xe Vepsa 50cc', 'xe-50cc', '[]', 20900000, 20900000, '/sites/yenthoa/img/2024/11/vespa-50.webp', '[\"/sites/yenthoa/img/2024/11/vespa-50.webp\"]', '[]', '[]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại động cơ\",\"value\":\"Xăng 4 kỳ, 1 xi lanh, làm mát bằng không khí\"},{\"label\":\"Dung tích xy lanh\",\"value\":\"49.6 cm3\"},{\"label\":\"Chế độ truyền\",\"value\":\"Dây curoa\"},{\"label\":\"Hộp số\",\"value\":\"Vô cấp điều khiển tự động\"},{\"label\":\"Khởi động\",\"value\":\"Đề điện (Start) và cần khởi động\"},{\"label\":\"Chống trộm\",\"value\":\"Khóa cổ\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"3.7 lít\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"50km/h\"},{\"label\":\"Tiêu thụ nhiên liệu\",\"value\":\"2,2l/100km\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Chất liệu khung\",\"value\":\"Hợp kim Sắt, Sơn tĩnh điện\"},{\"label\":\"Loại phanh (trước/sau)\",\"value\":\"Phanh đĩa trước, Phanh cơ sau\"},{\"label\":\"Chế độ phanh (trước/sau)\",\"value\":\"Thủ công\"},{\"label\":\"Loại vành xe (trước/sau)\",\"value\":\"Vành đúc\"},{\"label\":\"Đường kính vành (trước/sau)\",\"value\":\"334mm\"},{\"label\":\"Thông số lốp (trước/sau)\",\"value\":\"300-10\"},{\"label\":\"Áp suất lốp (trước/sau)\",\"value\":\"250 Kpa/ 250 Kpa\"},{\"label\":\"Thương hiệu lốp\",\"value\":\"SOBEK\"},{\"label\":\"Loại đèn chiếu sáng\",\"value\":\"Đèn led\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1730 x 650 x 1130mm\"},{\"label\":\"Chiều dài\",\"value\":\"1180mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"118mm\"},{\"label\":\"Trọng lượng xe\",\"value\":\"85kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]', '<p>Không chỉ phục vụ nhu cầu di chuyển hàng ngày, vespa 50cc còn thể hiện phong cách sống thời thượng của chủ nhân nó – một lựa chọn hoàn hảo cho những ai yêu thích sự khác biệt và sang trọng trong từng chi tiết nhỏ nhất.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE VESPA 50CC KHUYẾN MÃI GIÁ RẺ</h2>\n<p>Với thiết kế sang trọng, thanh lịch cùng mức giá hợp lý, <b>vespa 50cc</b> đang trở thành lựa chọn hàng đầu hiện nay. Không chỉ là phương tiện di chuyển tiện lợi, xe 50 vespa còn thể hiện phong cách và gu thẩm mỹ của người sử dụng.</p>\n<p>Dòng <b>xe vespa 50</b> rất dễ điều khiển, phù hợp với mọi đối tượng, đặc biệt là những ai không có bằng lái. Với khả năng tiết kiệm nhiên liệu và vận hành bền bỉ, <b>vespa 50</b> là sự lựa chọn hoàn hảo cho những ai muốn sở hữu một chiếc xe xăng hiệu quả mà không tốn kém. Nếu bạn đang tìm kiếm một chiếc xe ga nhỏ gọn, tiện ích và phong cách, hãy đến Yên Thoa để khám phá ngay những ưu điểm nổi bật của <b>xe vespa 50</b>!</p>\n<h2>1. Thiết kế của xe Vespa 50</h2>\n<p>Không chỉ phục vụ nhu cầu di chuyển hàng ngày, <b>vespa 50cc</b> còn thể hiện phong cách sống thời thượng của chủ nhân nó – một lựa chọn hoàn hảo cho những ai yêu thích sự khác biệt và sang trọng trong từng chi tiết nhỏ nhất.</p>\n<p><i>Thiết kế cổ điển, sang trọng</i></p>\n<p>Dòng xe <b>vespa 50</b> không chỉ đơn thuần là một phương tiện di chuyển mà còn là biểu tượng của phong cách sống và cái đẹp. Với thiết kế độc đáo, <b>xe 50 vespa</b> đã chinh phục hàng triệu trái tim yêu thích xe cổ điển trên toàn cầu. Sự kết hợp hoàn hảo giữa nét đẹp retro và hiện đại tạo nên một sản phẩm không chỉ thu hút ánh nhìn mà còn mang lại cảm giác sang trọng cho người sử dụng.</p>\n<p><b>Vespa 50 </b>sở hữu những đường cong mềm mại, tinh tế cùng với các chi tiết được chăm chút tỉ mỉ. Màu sắc trẻ trung và đa dạng giúp chiếc xe trở nên nổi bật hơn trong mắt người đối diện, khẳng định phong cách riêng biệt của chủ sở hữu.</p>\n<p><i>Đèn pha hình lục giác độc đáo</i></p>\n<p>Một trong những điểm nhấn đáng chú ý trên <b>xe vespa 50</b> chính là thiết kế đèn pha hình lục giác. Khác với các mẫu xe truyền thống, đèn pha này không chỉ mang lại ánh sáng mạnh mẽ mà còn tạo nên sự mới mẻ và cá tính cho phần đầu xe. Việc ứng dụng công nghệ LED tiên tiến không chỉ giúp tiết kiệm nhiên liệu mà còn nâng cao hiệu suất chiếu sáng và kéo dài tuổi thọ của đèn.</p>\n<p>Ngoài ra, cặp đèn xi nhan của <b>vespa 50cc</b> cũng được thiết kế theo phong cách hiện đại với công nghệ LED, góp phần tăng cường tính thẩm mỹ và đảm bảo an toàn khi di chuyển trong điều kiện ánh sáng yếu.</p>\n<p><i>Mặt đồng hồ điện tử tiện dụng</i></p>\n<p>Mặt đồng hồ điện tử trên <b>vespa 50</b> là một trong những bộ phận quan trọng giúp người lái dễ dàng theo dõi tình trạng của xe. Không chỉ hiển thị đầy đủ các thông số như mức xăng, quãng đường đã đi hay tốc độ hiện tại, mặt đồng hồ còn giúp người lái kiểm soát tốt hơn tình hình vận hành của phương tiện.</p>\n<p>Việc nắm bắt thông tin kịp thời từ mặt đồng hồ sẽ giúp <b>xe vespa 50</b> tránh những sự cố không mong muốn như hết xăng giữa chừng hoặc quên bật xi nhan khi rẽ.</p>\n<p><i>Cụm tay lái đầy đủ chức năng</i></p>\n<p>Cụm tay lái trên <b>vespa 50cc</b> được thiết kế thông minh với đầy đủ chức năng cần thiết cho người lái. Phía bên trái là công tắc xi nhan và còi xe, giúp việc điều khiển trở nên dễ dàng hơn bao giờ hết. Trong khi đó, tay lái bên phải tích hợp nút đề máy và đèn pha một cách hợp lý mang lại sự tiện lợi tối đa cho người sử dụng.</p>\n<p><i>Sàn để chân rộng rãi và cốp xe siêu rộng</i></p>\n<p><b>Xe 50 vespa</b> không chỉ gây ấn tượng bởi vẻ ngoài xinh xắn mà còn bởi sự tiện ích vượt trội mà nó mang lại. Với kích thước lý tưởng (1914mm x 680mm x 1075mm) cùng chiều cao yên xe đạt mức 769mm, chiếc xe này vừa tôn lên vẻ đẹp sang trọng vừa đảm bảo sự thoải mái cho người lái.</p>\n<p>Sàn để chân rộng rãi cùng cốp <b>vespa 50cc</b> siêu rộng cung cấp không gian lưu trữ lý tưởng cho các phụ kiện cá nhân như túi xách hay quần áo mà không lo thiếu chỗ để cất giữ đồ dùng cần thiết.</p>\n<p><i>Yên xe cao su cao cấp</i></p>\n<p>Điểm đặc biệt tiếp theo khiến nhiều tín đồ yêu thích dòng <b>xe 50 vespa</b> chính là yên xe được làm từ cao su cao cấp. Với độ cong nhẹ nhàng cùng phần sau được nâng cao một chút, yên xe không chỉ tạo cảm giác thoải mái mà còn góp phần làm nổi bật vẻ đẹp thẩm mỹ riêng biệt của chiếc xe.</p>\n<p>Chất liệu cao su cao cấp kết hợp lớp bọc da chống hút nắng giúp yên giữ được form dáng ban đầu lâu dài và mang lại cảm giác dễ chịu cho người sử dụng <strong>xe vespa 50cc</strong> trong suốt hành trình dài.</p>\n<h2>2. Tính năng và động cơ của xe Vespa 50cc</h2>\n<p><i>Hệ thống phanh an toàn</i></p>\n<p><b>Vespa 50 </b>được trang bị hai loại phanh hiện đại: Phanh đĩa ở phía trước và phanh cơ ở phía sau. Sự kết hợp này không chỉ nâng cao tính an toàn cho người lái mà còn mang lại cảm giác yên tâm khi di chuyển. Trong trường hợp khẩn cấp, phanh đĩa giúp tăng cường ma sát giữa bánh xe và mặt đường, từ đó hỗ trợ người lái xử lý tình huống một cách dễ dàng hơn. Đồng thời, việc sử dụng hai loại phanh này cũng giúp giữ giá thành của chiếc xe <b>vespa 50c</b>c ở mức hợp lý mà vẫn đảm bảo tiêu chuẩn an toàn cao.</p>\n<p><i>Vành xe và hệ thống giảm xóc tiên tiến</i></p>\n<p>Vành <b>xe 50 vespa</b> được chế tạo từ hợp kim cao cấp, đúc nguyên khối, mang lại sự chắc chắn và bền bỉ. Thiết kế này không chỉ giúp tránh cong vênh hay móp méo mà còn tạo nên vẻ đẹp sang trọng cho sản phẩm.</p>\n<p>Hệ thống giảm xóc của <b>vespa 50cc</b> cũng rất đáng chú ý với thiết kế hiện đại. Giảm xóc trước sử dụng công nghệ ống lòng giảm chấn thủy lực, trong khi giảm xóc sau là lò xo trụ đơn với khả năng giảm chấn hiệu quả. Nhờ vậy, <b>xe vespa 50 </b>có thể vận hành mượt mà trên mọi loại địa hình, từ đường gồ ghề đến mặt đường bê tông, mang lại trải nghiệm lái êm ái và thoải mái cho người sử dụng.</p>\n<p><i>Động cơ mạnh mẽ và tiết kiệm nhiên liệu</i></p>\n<p><b>Vespa 50cc</b> được trang bị động cơ xăng 4 kỳ với một xi lanh có dung tích bình xăng gần 4 lít. Điều này không chỉ đảm bảo sức mạnh vận hành mạnh mẽ mà còn tối ưu hóa khả năng tiết kiệm nhiên liệu. Chỉ với 2.2 lít xăng, bạn có thể di chuyển quãng đường lên tới 100km, giúp tiết kiệm chi phí nhiên liệu một cách tối đa.</p>\n<p><b>Xe 50 vespa</b> là sự kết hợp hoàn hảo giữa thiết kế hiện đại và tính năng tiện ích vượt trội. Nếu bạn đang tìm kiếm một chiếc xe ga vừa sang trọng vừa hiện đại với mức giá phải chăng thì <strong>Vespa 50cc</strong> chắc chắn là lựa chọn tuyệt vời dành cho bạn!</p>\n<h2>3. Giá xe Vespa 50 mới nhất tại Hệ thống Siêu Thị Yên Thoa</h2>\n<p>Hiện nay tại Hệ thống Siêu Thị Yên Thoa, <b>giá xe vespa 50</b> đang được chào bán với mức giá hấp dẫn chỉ từ 14 triệu đồng. Với nhiều phiên bản đa dạng, khách hàng có thể dễ dàng lựa chọn cho mình một chiếc <strong>xe vespa 50cc</strong> phù hợp với phong cách và nhu cầu sử dụng.</p>\n<p>Hệ thống Siêu Thị Yên Thoa tự hào là một trong những <a href=\"/\"><b>đại lý xe máy</b></a> uy tín hàng đầu trong lĩnh vực kinh doanh và phân phối các sản phẩm, dịch vụ. Chúng tôi cung cấp một loạt các sản phẩm từ những thương hiệu nổi tiếng như: Yamaha, Honda, Sym, Yadea, Suzuki và nhiều thương hiệu khác.</p>\n<p>Với phương châm<i> “Luôn đặt sự hài lòng của khách hàng lên hàng đầu”</i>, Yên Thoa cam kết mang đến sự hài lòng tối đa cho từng khách hàng khi lựa chọn sản phẩm tại cửa hàng. Chúng tôi luôn nỗ lực để xây dựng niềm tin và sự tín nhiệm từ phía khách hàng.</p>\n<p>Khi đến với Yên Thoa ngay hôm nay, quý khách sẽ được hưởng những ưu đãi đặc biệt:</p>\n<p>– Giao xe tận nơi: Tiện lợi hơn bao giờ hết khi chúng tôi giao xe đến tận nhà bạn.</p>\n<p>– Hỗ trợ mua xe trả góp: Với lãi suất cực kỳ ưu đãi.</p>\n<p>– Trả trước chỉ từ 0đ: Bạn có thể rước ngay chiếc xe yêu thích về nhà.</p>\n<p>– Bảo hành chính hãng: Đảm bảo chất lượng và độ bền cho sản phẩm.</p>\n<p>– Chương trình thu cũ đổi mới: Giúp bạn dễ dàng nâng cấp chiếc xe của mình.</p>\n<p>– Quà tặng hấp dẫn trị giá 2.350.000đ cùng nhiều ưu đãi khác đang chờ đón bạn.</p>\n<p>Hãy đến với Hệ thống Siêu Thị Yên Thoa để trải nghiệm dịch vụ chuyên nghiệp và nhận ngay chiếc <b>vespa 50cc</b> mà bạn mong muốn! Mọi thắc mắc về dòng <b>xe 50 vespa</b> hoặc <b>giá xe 50cc</b>, quý khách có thể liên hệ tư vấn qua thông tin dưới đây.</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
