INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-vision', 'Xe Vision', 'honda', '[]', 31800000, 39800000, '/sites/yenthoa/img/2024/11/vision-phien-ban-dac-biet-mau-nau-den.webp', '[\"/sites/yenthoa/img/2024/11/vision-phien-ban-dac-biet-mau-nau-den.webp\"]', '[\"Bạc Đen\",\"Đen\",\"Đỏ Đen\",\"Đỏ Xám\",\"Nâu Đen\",\"Nâu Xám\",\"Trắng Đen\",\"Vàng Đen Bạc\",\"Xám Đen\",\"Xanh Đen\",\"Xanh Đen Bạc\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp mới\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Xám\"}],\"img\":\"/sites/yenthoa/img/2025/12/vision-phien-ban-cao-cap-mau-do-xam-2026.webp\",\"price\":36000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt mới\"},{\"name\":\"Màu sắc\",\"value\":\"Nâu Xám\"}],\"img\":\"/sites/yenthoa/img/2025/12/vision-phien-ban-dac-biet-mau-nau-xam-2026.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn mới\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/yenthoa/img/2025/12/vision-phien-ban-tieu-chuan-mau-trang-den-2026.webp\",\"price\":34100000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao mới\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Đen\"}],\"img\":\"/sites/yenthoa/img/2025/12/vision-phien-ban-the-thao-mau-bac-den-2026.webp\",\"price\":39800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao mới\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2025/12/vision-phien-ban-the-thao-mau-xam-den-2026.webp\",\"price\":39800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao mới\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2025/12/vision-phien-ban-the-thao-mau-den-2026.webp\",\"price\":39800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-tieu-chuan-mau-trang-den.webp\",\"price\":31800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-cao-cap-mau-do-den.webp\",\"price\":33300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-cao-cap-mau-xanh-den.webp\",\"price\":33300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Nâu Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-ban-dac-biet-mau-nau-den.webp\",\"price\":34800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cổ điển\"},{\"name\":\"Màu sắc\",\"value\":\"Vàng Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-ban-co-dien-mau-vang-den-bac.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cổ điển\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-ban-co-dien-mau-xanh-den-bac.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-ban-the-thao-mau-xam-den.webp\",\"price\":38000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/vision-phien-ban-the-thao-mau-den.webp\",\"price\":38000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"4,8 L\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xi lanh, làm mát bằng không khí\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,59 kw/7500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả 0,65 L Sau khi rã máy 0,8 L\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,82L/100km\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"9,29 Nm/6000 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"109,5 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"47,0 x 63,1 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"10,0 : 1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"80/90-16M/C 43P 90/90-14M/C 46P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ đơn, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"97 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.925mm x 686mm x 1.126mm\"},{\"label\":\"Độ cao yên\",\"value\":\"785 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.277 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"175 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Không chỉ thu hút bởi vẻ ngoài bắt mắt, dòng xe vision còn đa dạng về phiên bản và màu sắc, đáp ứng nhu cầu phong phú của người tiêu dùng.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE VISION MỚI NHẤT HÔM NAY CỦA HONDA&nbsp;</h2>\n<p>Với thiết kế trẻ trung, thanh lịch và kích thước nhỏ gọn, <b>vision </b>nhanh chóng trở thành lựa chọn hàng đầu của giới trẻ và là một trong những mẫu xe bán chạy nhất trên thị trường trong những năm gần đây.&nbsp;</p>\n<p>Không chỉ thu hút bởi vẻ ngoài bắt mắt, dòng<b> xe vision</b> còn đa dạng về phiên bản và màu sắc, đáp ứng nhu cầu phong phú của người tiêu dùng. Từ những gam màu tươi sáng đến những sắc thái trang nhã, mỗi phiên bản của <b>honda vision</b> đều mang đến cho người lái cảm giác cá tính và phong cách riêng biệt.</p>\n\n<p>Hãy cùng Hệ thống Siêu Thị Yên Thoa khám phá chi tiết hơn về dòng<b> xe vision mới</b> và <b>giá xe vision</b> qua bài viết dưới đây!</p>\n<h2>1. Những điểm nổi bật trong thiết kế của xe vision mới</h2>\n<p>Thiết kế phía trước hiện đại và năng động</p>\n<p>Dòng<b> xe vision</b> luôn được xem là biểu tượng của sự hiện đại và năng động. Với những cải tiến mới nhất, <b>vision </b>không chỉ giữ vững phong cách trẻ trung mà còn nâng tầm với những chi tiết tinh tế và sang trọng. Phần đầu <b>xe vision mới </b>được thiết kế với hiệu ứng ánh sáng độc đáo, tạo nên từ sự kết hợp hài hòa giữa các đường nét ba chiều và hệ thống đèn trước tiên tiến. Điều này không chỉ mang lại vẻ ngoài bắt mắt mà còn tăng cường khả năng chiếu sáng, đảm bảo an toàn cho người lái trong mọi điều kiện thời tiết.</p>\n\n<p>Sự đa dạng trong phiên bản và màu sắc của honda vision</p>\n<p><b>Vision</b> tự hào mang đến cho khách hàng một bộ sưu tập đa dạng với bốn phiên bản độc đáo, mỗi phiên bản đều được thiết kế với những màu sắc đặc trưng riêng biệt, đáp ứng nhu cầu và sở thích của từng cá nhân.</p>\n<p>Phiên bản tiêu chuẩn nổi bật với gam màu đen cổ điển, là lựa chọn lý tưởng cho những ai yêu thích sự tối giản nhưng vẫn muốn khẳng định phong cách cá nhân. Trong khi đó, phiên bản cao cấp gây ấn tượng mạnh mẽ với hai tùy chọn màu sắc: trắng đen và đỏ đen. Sự kết hợp này không chỉ tạo nên vẻ đẹp sang trọng mà còn thể hiện sự năng động và cuốn hút.</p>\n<p>Đối với những tín đồ yêu thích sự khác biệt, phiên bản đặc biệt với màu xanh đen sẽ là lựa chọn hoàn hảo, mang đến cảm giác mới mẻ và độc đáo. Cuối cùng, phiên bản thể thao dành riêng cho những người yêu thích phong cách mạnh mẽ được cung cấp với hai màu sắc ấn tượng: xám đen và đen, thể hiện sự năng động và cá tính.</p>\n\n<p>Ngoài ra, <b>xe vision </b>còn giới thiệu phiên bản cổ điển với hai tùy chọn màu sắc vàng đen bạc và xanh đen bạc. Sự kết hợp giữa nét hoài cổ và hiện đại trong thiết kế này chắc chắn sẽ chinh phục những ai yêu thích vẻ đẹp vượt thời gian.</p>\n<p>Logo 3D nổi bật</p>\n<p>Một điểm nhấn không thể bỏ qua trên<b> xe vision mới </b>chính là logo 3D được thiết kế nổi bật trên thân xe. Với các đường nét liền mạch và rõ ràng, logo này không chỉ tạo nên hình ảnh trẻ trung mà còn thể hiện sự năng động của chiếc xe.</p>\n<p>Thiết kế phía sau tinh tế</p>\n<p>Phần sau của<b> xe vision </b>cũng được chăm chút kỹ lưỡng với cụm đèn hậu và xi nhan được thiết kế tinh xảo. Các chi tiết này được bố trí liền khối một cách hài hòa, mang lại phong cách thanh lịch nhưng vẫn đảm bảo tính nhỏ gọn tiện lợi cho người sử dụng.</p>\n<p>Vành đúc mang phong cách châu âu</p>\n<p>Vành đúc của <b>vision</b> là một điểm nhấn quan trọng trong tổng thể thiết kế xe. Với phong cách đặc trưng Châu Âu cùng bề mặt có cấu trúc ba chiều độc đáo, bộ phận này không chỉ góp phần làm tăng thêm vẻ thanh lịch mà còn đảm bảo độ bền vững chắc khi vận hành.</p>\n<p><b>Xe vision</b> đã khẳng định vị thế của mình trên thị trường bằng việc kết hợp hoàn hảo giữa thiết kế hiện đại và tính năng vượt trội. Với nhiều lựa chọn về phiên bản và màu sắc cùng các chi tiết thiết kế tinh tế như logo 3D hay cụm đèn hậu liền khối, Vision chắc chắn sẽ tiếp tục chinh phục trái tim của nhiều khách hàng yêu thích sự trẻ trung và năng động trong thời gian tới.</p>\n<h2>2. Động cơ và tính năng của dòng xe Honda vision&nbsp;</h2>\n<p><b>Honda vision </b>không chỉ là một phương tiện di chuyển mà còn là một sản phẩm kết hợp hoàn hảo giữa công nghệ hiện đại và tính tiện ích dành cho người sử dụng. Dưới đây là những điểm nổi bật về động cơ và tính năng của dòng<b> xe vision</b>.</p>\n<p>Động cơ eSP thế hệ mới – Sự kết hợp hoàn hảo giữa hiệu suất và tiết kiệm nhiên liệu</p>\n<p><b>Xe vision </b>được trang bị động cơ eSP (Enhanced Smart Power) thế hệ mới, với thiết kế nhỏ gọn 110cc, 4 kỳ, xy-lanh đơn và làm mát bằng không khí. Động cơ này tích hợp nhiều công nghệ tiên tiến như hệ thống phun xăng điện tử PGM-FI, bộ đề ACG và hệ thống ngắt động cơ tạm thời (Idling Stop). Những cải tiến này không chỉ giúp giảm thiểu ma sát mà còn tối ưu hóa khả năng đốt cháy nhiên liệu, mang lại hiệu suất vận hành vượt trội và tiết kiệm nhiên liệu tối đa.</p>\n\n<p>Khung dập hàn laser eSAF – Đột phá trong thiết kế khung xe</p>\n<p>Khung xe<b> honda vision </b>sử dụng công nghệ dập hàn laser thế hệ mới eSAF, giúp giảm trọng lượng nhưng vẫn đảm bảo độ bền cao. Thiết kế này không chỉ mang lại sự chắc chắn mà còn tạo cảm giác lái thoải mái và linh hoạt cho người điều khiển.</p>\n<p>Hộc đựng đồ thông minh – Tiện lợi cho cuộc sống di chuyển</p>\n<p>Hộc đựng đồ phía trước của<b> xe vision mới </b>được thiết kế rộng rãi với nắp đậy kín đáo, có khả năng chứa nhiều vật dụng cá nhân. Việc nâng cấp từ cổng sạc ACC sang cổng sạc USB cùng vị trí thuận tiện hơn giúp người dùng dễ dàng sạc điện thoại hoặc các thiết bị di động trong quá trình di chuyển. Điều này đặc biệt phù hợp với giới trẻ năng động.</p>\n\n<p>Ngoài ra, hộc đựng đồ dưới yên cũng có dung tích lớn, góp phần nâng cao trải nghiệm sử dụng cho khách hàng.</p>\n<p>Mặt đồng hồ hiện đại – Dễ dàng quan sát thông tin</p>\n<p>Xe <b>honda vision </b>được trang bị mặt đồng hồ LCD sắc nét, cho phép người lái theo dõi tất cả các thông số quan trọng như quãng đường đã đi, mức tiêu hao nhiên liệu và tình trạng đèn xi nhan một cách dễ dàng. Điều này giúp người điều khiển luôn nắm bắt thông tin cần thiết để đảm bảo an toàn khi tham gia giao thông.</p>\n\n<p>Hệ thống khóa thông minh – An toàn và tiện ích</p>\n<p>Với hệ thống khóa thông minh Smart Key, người dùng có thể dễ dàng định vị xe trong bãi đỗ. Tính năng này không chỉ mang lại sự tiện lợi mà còn tăng cường an toàn cho phương tiện.</p>\n\n<p>Chế độ đèn chiếu sáng luôn bật – Tăng cường an toàn khi lưu thông</p>\n<p><b>Xe vision</b> được trang bị chế độ đèn chiếu sáng luôn bật, đảm bảo tầm nhìn tốt nhất cho người sử dụng trong mọi điều kiện ánh sáng. Tính năng này giúp hạn chế tình trạng quên bật đèn khi di chuyển vào ban đêm hoặc trong điều kiện ánh sáng yếu, đồng thời nâng cao khả năng hiện diện của xe trên đường phố.</p>\n<h2>3. Giá xe Vision mới nhất tại Hệ thống Siêu Thị Yên Thoa&nbsp;</h2>\n<p>Với mức <b>giá xe vision</b> chỉ ở mức tầm trung, Honda Vision hướng đến phân khúc khách hàng phổ thông, mang lại sự lựa chọn hợp lý cho nhiều người tiêu dùng.</p>\n<p>Hiện tại, <b>giá xe vision </b>đang dao động trong khoảng 36.800.000đ. Với mức giá này, Honda Vision đã nhận được sự đánh giá cao từ phía người tiêu dùng và được xem là một trong những mẫu xe tay ga đáng mua nhất hiện tại.</p>\n\n<p>Để đáp ứng nhu cầu của khách hàng, Hệ thống Siêu Thị Yên Thoa cung cấp chính sách ưu đãi hấp dẫn khi quý khách hàng quyết định mua xe Honda, đặc biệt là dòng <b>xe vision</b>. Chúng tôi luôn nỗ lực mang đến cho quý khách những trải nghiệm mua sắm hài lòng và trọn vẹn nhất.</p>\n<p>Với nhiều năm kinh nghiệm lĩnh vực kinh doanh <a href=\"/xe-may\"><strong>xe máy</strong></a>, Yên Thoa đã khẳng định được uy tín và chất lượng dịch vụ của mình. Chúng tôi cam kết mang đến sự an tâm tuyệt đối cho quý khách khi tìm kiếm địa chỉ mua xe máy chính hãng.</p>\n<p>Để biết thêm chi tiết về <b>giá xe vision</b> cũng như các chương trình ưu đãi liên quan đến <a href=\"/xe-may?nhom=honda\"><strong>xe máy honda</strong></a>, xin vui lòng liên hệ với chúng tôi qua hotline để được hỗ trợ nhanh chóng và tận tình. Cảm ơn quý khách đã tin tưởng lựa chọn Hệ thống Siêu Thị Yên Thoa!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
