INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-wave-50cc', 'Xe Wave 50cc', 'xe-50cc', '[\"xe-so\"]', 14300000, 16000000, '/sites/yenthoa/img/2024/11/wave-alpha-50cc.webp', '[\"/sites/yenthoa/img/2024/11/wave-alpha-50cc.webp\"]', '[]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Việt Thái\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-50cc.webp\",\"price\":14300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Mâm Victoria\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-50cc.webp\",\"price\":16000000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Căm Victoria\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-50cc.webp\",\"price\":15500000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích xi lanh\",\"value\":\"49,5 cm3\"},{\"label\":\"Động cơ\",\"value\":\"Xăng, 4 kỳ, xy-lanh, làm mát bằng không khí\"},{\"label\":\"Tốc độ tối đa\",\"value\":\"50 km/h\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"3.7 lít\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đề điện (Start) và cần khởi động\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh cơ/Phanh cơ\"},{\"label\":\"Lốp\",\"value\":\"Có Săm\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thuỷ lực\"},{\"label\":\"Hộp số\",\"value\":\"Cơ Khí , 4 Số Tròn\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.715 mm x 696 mm x 1.052 mm\"},{\"label\":\"Trọng lượng bản thân\",\"value\":\"70kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"18 tháng kiểm tra định kỳ\"}]}]', '<p>Với kiểu dáng hiện đại và trẻ trung, wave alpha 50 không chỉ thuận tiện trong việc di chuyển trong đô thị mà còn thể hiện phong cách sống năng động của người sử dụng.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE WAVE ALPHA 50CC MỚI NHẤT TRÊN THỊ TRƯỜNG </h2>\n<p><b>Wave 50cc</b> là một trong những dòng xe máy phổ thông được yêu thích nhất tại Việt Nam. Với mức giá hợp lý và thiết kế thân thiện, mẫu xe này đã trở thành sự lựa chọn hàng đầu cho nhiều đối tượng, đặc biệt là học sinh và sinh viên. Sự kết hợp giữa hiệu suất ổn định và tính năng tiện ích đã giúp<b> xe wave 50 phân khối</b> khẳng định vị thế của mình trên thị trường xe máy.</p>\n<h2>1. Thiết kế nổi bật của Wave 50cc</h2>\n<p>Dòng <b>xe wave 50cc</b> nổi bật với thiết kế nhỏ gọn, thanh thoát, mang lại cảm giác thoải mái và dễ chịu cho người lái. Với kiểu dáng hiện đại và trẻ trung, <b>wave alpha 50 </b>không chỉ thuận tiện trong việc di chuyển trong đô thị mà còn thể hiện phong cách sống năng động của người sử dụng.&nbsp;</p>\n<p>Một trong những điểm nổi bật của <b>xe wave alpha 50</b> chính là hệ thống đèn pha LED tiên tiến. Đèn pha LED không chỉ cung cấp khả năng chiếu sáng vượt trội khi di chuyển vào ban đêm mà còn góp phần nâng cao tính thẩm mỹ cho chiếc xe. Ánh sáng mạnh mẽ và rõ nét giúp người lái dễ dàng quan sát đường đi, từ đó đảm bảo an toàn tối đa trong mọi điều kiện ánh sáng.</p>\n<p>Bảng đồng hồ hiển thị trên <b>wave 50cc</b> được thiết kế tiện lợi, cung cấp đầy đủ thông tin cần thiết như quãng đường đã đi, tốc độ hiện tại cùng các đèn báo hiệu như nhiên liệu và xi nhan. Thiết kế này giúp người lái dễ dàng theo dõi tình trạng hoạt động của xe một cách nhanh chóng và chính xác, từ đó có những điều chỉnh kịp thời để đảm bảo chuyến đi suôn sẻ.</p>\n<p>Tay lái của xe <b>wave 50 phân khối</b> được thiết kế thông minh với hình dáng thon gọn nhưng vẫn đảm bảo khả năng kiểm soát tốt khi di chuyển. Các nút chức năng được bố trí hợp lý, giúp người dùng dễ dàng làm quen và thao tác linh hoạt trong quá trình điều khiển xe. Điều này không chỉ mang lại sự tiện lợi mà còn tạo cảm giác tự tin cho người lái.</p>\n<p>Thân x<b>e wave 50cc</b> nổi bật với những đường nét đơn giản nhưng tinh tế, tạo nên vẻ đẹp chắc chắn và cân đối từ mọi góc nhìn. Đặc biệt, thiết kế đèn hậu liền khối không chỉ mang lại sự gọn gàng mà còn thể hiện sự hiện đại cho chiếc xe. Sự kết hợp hoàn hảo giữa tính năng và thẩm mỹ đã tạo nên một sản phẩm đáng chú ý trên thị trường xe máy hiện nay.</p>\n<h2>2. Tính năng và động cơ vượt trội của xe Wave 50</h2>\n<p><i>2.1 Tính năng nổi bật</i></p>\n<p><b>Xe wave 50 phân khối </b>nổi bật với nhiều tính năng ưu việt, mang đến trải nghiệm lái an toàn và thoải mái cho người sử dụng.&nbsp;</p>\n<p>Thiết kế chắn bùn thông minh: Một trong những điểm đáng chú ý nhất của mẫu xe <b>wave 50cc</b> chính là thiết kế chắn bùn trước dài hơn so với các dòng xe khác. Điều này không chỉ giúp bảo vệ người lái khỏi bùn đất khi di chuyển trên những con đường lầy lội hay ngập nước, mà còn tạo nên vẻ ngoài thể thao và năng động cho chiếc xe.</p>\n<p>Yên xe <b>wave alpha 50</b> thiết kế thông minh: Yên<b> xe wave 50cc</b> được thiết kế nhỏ gọn nhưng vẫn đảm bảo sự thoải mái tối đa. Với lớp bọc da giả chất lượng cao, người dùng có thể dễ dàng di chuyển trong thời gian dài mà không cảm thấy mệt mỏi. Ngoài ra, cốp dưới yên rộng rãi là một điểm cộng lớn, cho phép bạn dễ dàng lưu trữ các vật dụng cá nhân như áo mưa hay ví tiền mà không lo thiếu chỗ.</p>\n<p>Hệ thống phanh đảm bảo an toàn: <b>Xe wave 50cc </b>được trang bị hệ thống phanh cơ trên cả hai bánh, giúp tăng cường độ an toàn trong mọi tình huống giao thông. Người lái có thể hoàn toàn yên tâm khi điều khiển chiếc xe này trên những con đường đông đúc hay trong điều kiện thời tiết xấu.</p>\n<p>Lốp săm dễ dàng thay thế: Với thiết kế lốp săm tiện lợi, việc thay thế lốp cũ trở nên đơn giản hơn bao giờ hết. Điều này không chỉ giúp xe <b>wave alpha 50</b> tiết kiệm thời gian mà còn giảm thiểu chi phí sửa chữa cho người dùng.</p>\n<p>Hệ thống giảm xóc hiện đại: Cuối cùng, hệ thống giảm xóc cao cấp của <b>wave 50cc </b>mang đến trải nghiệm lái mượt mà trên mọi địa hình. Từ những con phố nhộn nhịp đến các tuyến đường gồ ghề, chiếc xe luôn đảm bảo sự ổn định và thoải mái cho người điều khiển.</p>\n<p><i>2.2 Động cơ tiết kiệm nhiên liệu</i></p>\n<p><b>Xe wave 50cc</b> không chỉ là một phương tiện di chuyển đơn thuần mà còn là biểu tượng của sự tiết kiệm nhiên liệu với động cơ dung tích xy lanh 49.5cc mạnh mẽ nhưng vẫn rất nhẹ nhàng trong vận hành.</p>\n<p>– Hiệu suất vượt trội: Với trọng lượng nhẹ cùng công suất cao, <b>xe wave 50 phân khối </b>cho phép người dùng di chuyển linh hoạt mà không lo tốn kém nhiên liệu.</p>\n<p>– Cải tiến hiện đại: Nhờ vào các cải tiến công nghệ hiện đại như giảm thiểu ma sát và tối ưu hóa buồng đốt, xe <b>wave 50cc</b> hoạt động mạnh mẽ hơn đồng thời tiết kiệm nhiên liệu tối ưu.</p>\n<p>– Ắc quy khô tiện lợi: Việc sử dụng bình acquy khô thay vì bình thường giúp xe <b>wave alpha 50</b> giảm thiểu rủi ro tràn axit ra ngoài và loại bỏ nhu cầu kiểm tra hay châm nước thường xuyên.</p>\n<h2>3. Địa chỉ mua xe Wave 50cc uy tín giá rẻ</h2>\n<p>Hệ thống Siêu Thị Yên Thoa là một trong những địa chỉ uy tín hàng đầu trong lĩnh vực kinh doanh xe máy tại Việt Nam. Với nhiều năm kinh nghiệm trong lĩnh vực kinh xe máy, Yên Thoa từ hào là một trong những <a href=\"/\"><b>đại lý xe máy</b></a> uy tín tại Thành phố Hồ Chí Minh khi được khách hàng sử dụng sản phẩm, dịch vụ.</p>\n<p>– Sản phẩm chất lượng cao: Yên Thoa cam kết cung cấp sản phẩm chất lượng nhất đến tay khách hàng cùng dịch vụ hậu mãi tận tình.</p>\n<p>– Ưu đãi hấp dẫn khi mua xe: Khi mua <b>wave 50cc</b> tại Yên Thoa, quý khách sẽ nhận ngay nhiều ưu đãi hấp dẫn như bảo hành sau mua hàng cùng combo quà tặng độc quyền trị giá lên tới 2.350.000đ.</p>\n<p>–&nbsp; Hỗ trợ trả góp linh hoạt: Yên Thoa cung cấp dịch vụ hỗ trợ trả góp với lãi suất cực thấp để quý khách có thể dễ dàng sở hữu chiếc <b>xe wave 50cc</b> yêu thích của mình.</p>\n<p>– Đội ngũ nhân viên chuyên nghiệp: Đội ngũ nhân viên giàu kinh nghiệm tại Yên Thoa luôn sẵn sàng tư vấn để bạn chọn lựa sản phẩm phù hợp nhất với nhu cầu cá nhân.</p>\n<p>Hiện tại, Hệ thống Siêu Thị Yên Thoa đang có đầy đủ các phiên bản và màu sắc của <a href=\"/xe-may?nhom=xe-50cc\"><b>xe máy 50cc</b></a> với giá xe <b>wave 50cc</b> chỉ từ 14 triệu đồng. Nếu bạn đang tìm kiếm một cửa hàng xe máy chất lượng với giá xe <b>wave alpha 50</b> phải chăng thì hãy liên hệ ngay với hệ thống cửa hàng Yên Thoa để trải nghiệm dòng sản phẩm tuyệt vời này!</p>\n<p><b>Xe wave 50cc </b>không chỉ đơn thuần là một phương tiện giao thông mà còn là biểu tượng của sự tiện ích và an toàn trong cuộc sống hiện đại ngày nay. Với thiết kế tinh tế cùng động cơ mạnh mẽ nhưng tiết kiệm nhiên liệu, đây chắc chắn sẽ là lựa chọn hoàn hảo cho mọi đối tượng người dùng tại Việt Nam!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
