INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-wave-alpha', 'Xe Wave Alpha', 'honda', '[\"xe-so\"]', 18900000, 19900000, '/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-co-dien-mau-xam-trang.webp', '[\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-co-dien-mau-xam-trang.webp\"]', '[\"Đen nhám\",\"Đỏ\",\"Trắng\",\"Xám\",\"Xám Trắng\",\"Xanh\",\"Xanh dương\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-tieu-chuan-mau-trang.webp\",\"price\":18900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-tieu-chuan-mau-do.webp\",\"price\":18900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-tieu-chuan-mau-xanh.webp\",\"price\":18900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen nhám\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-dac-biet-mau-den-nham.webp\",\"price\":19300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cổ điển\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Trắng\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-co-dien-mau-xam-trang.webp\",\"price\":19900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cổ điển\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-co-dien-mau-xanh.webp\",\"price\":19900000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cổ điển\"},{\"name\":\"Màu sắc\",\"value\":\"Xám\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-alpha-phien-ban-co-dien-mau-xam.webp\",\"price\":19900000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"3,7 L\"},{\"label\":\"Loại động cơ\",\"value\":\"4 kỳ, 1 xilanh, làm mát bằng không khí\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,12 kW/7.500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"Sau khi xả 0,8 L Sau khi rã máy 1,0 L\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,72 l/100km\"},{\"label\":\"Loại truyền động\",\"value\":\"Cơ khí, 4 số tròn\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"8,44 Nm/5.500 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"109,2 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"50,0 x 55,6 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9,0 : 1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Kích cỡ lốp trước/ sau\",\"value\":\"Lốp trước 70/90-17M/C 38P Lốp sau 80/90-17M/C 50P\"},{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"96 kg\"},{\"label\":\"Dài x Rộng x Cao\",\"value\":\"1.913 x 689 x 1.076 mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1.224 mm\"},{\"label\":\"Độ cao yên\",\"value\":\"770 mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"134 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Thiết kế của dòng xe wave alpha không chỉ đa dạng về phiên bản mà còn phong phú về màu sắc, đáp ứng nhu cầu thẩm mỹ của từng khách hàng. Đây cũng chính là lý do khiến xe wave trở thành mẫu xe số quốc dân.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE WAVE ALPHA 110 CHÍNH HÃNG MỚI NHẤT TẠI ĐẠI LÝ HONDA</h2>\n<p><b>Wave alpha</b> chính là sự lựa chọn lý tưởng dành cho những ai đang tìm kiếm một chiếc xe máy bền bỉ, có hiệu suất ổn định và phong cách trẻ trung. Với mức giá hợp lý, <b>xe wave alpha </b>không chỉ là phương tiện di chuyển tiện lợi mà còn là mẫu xe số bán chạy nhất hiện nay.&nbsp;</p>\n<p>Hiện tại, <b>honda wave alpha</b> đang có sẵn đầy đủ các phiên bản và màu sắc tại Yên Thoa. Quý khách hàng có nhu cầu sở hữu các phiên bản mới nhất với <b>giá xe wave</b> hợp lý, vui lòng liên hệ ngay với chúng tôi để được tư vấn và hỗ trợ tốt nhất.</p>\n\n<h2>1. Giới thiệu về thiết kế của dòng xe số quốc dân honda wave alpha&nbsp;</h2>\n<p><b>Wave alpha 110</b>, một trong những mẫu xe số được ưa chuộng nhất tại Việt Nam, không chỉ nổi bật với hiệu suất vận hành mà còn thu hút người tiêu dùng bởi thiết kế đa dạng và phong phú. Được biết đến như một “biểu tượng” trong phân khúc xe số, <b>xe wave alpha</b> mang đến cho người dùng nhiều sự lựa chọn phù hợp với sở thích và phong cách cá nhân. Hãy cùng khám phá những điểm nổi bật trong thiết kế của <b>wave alpha 110</b> qua các phiên bản hiện tại.</p>\n\n<p><em>Đa dạng phiên bản và màu sắc</em></p>\n<p>Phiên bản tiêu chuẩn: Đây là lựa chọn phổ biến nhất với ba màu sắc cơ bản là trắng, đỏ và xanh. Những gam màu này không chỉ thể hiện sự trẻ trung, năng động mà còn dễ dàng phối hợp với nhiều phong cách thời trang khác nhau. Phiên bản tiêu chuẩn mang lại cảm giác thân thiện và gần gũi cho người sử dụng.</p>\n<p>Phiên bản đặc biệt: Với màu đen cá tính, phiên bản này hướng đến những người yêu thích sự mạnh mẽ và nổi bật. Màu đen không chỉ tạo nên vẻ ngoài sang trọng mà còn thể hiện cá tính riêng biệt của người lái. Đây là lựa chọn lý tưởng cho những ai muốn khẳng định phong cách riêng trong từng chuyến đi.</p>\n<p>Phiên bản cổ điển: Đối với những tín đồ yêu thích vẻ đẹp hoài cổ, phiên bản cổ điển với ba màu sắc xám, xanh và xám trắng sẽ là sự lựa chọn hoàn hảo. Thiết kế mang đậm dấu ấn truyền thống nhưng vẫn giữ được nét hiện đại giúp chiếc xe trở nên nổi bật giữa phố phường tấp nập.</p>\n<p><em>Tem xe thiết kế độc đáo</em></p>\n<p>Không chỉ dừng lại ở việc đa dạng hóa màu sắc, <b>Honda wave alpha</b> còn chú trọng đến từng chi tiết nhỏ như tem xe để tạo nên sự khác biệt rõ rệt giữa các phiên bản.</p>\n<p>Ở phiên bản tiêu chuẩn và đặc biệt: tem xe được thiết kế hài hòa với logo “<b>Wave alpha</b>” cách điệu. Nền họa tiết trẻ trung kết hợp cùng các gam màu khác nhau trên mỗi chiếc xe tạo nên một tổng thể năng động và mạnh mẽ. Thiết kế này không chỉ giúp chiếc xe trở nên bắt mắt hơn mà còn giúp người dùng tự tin khoe trọn cá tính của mình khi di chuyển trên đường phố.</p>\n<p>Đối với phiên bản cổ điển: tem xe mang một diện mạo hoàn toàn mới với logo “<b>Wave alpha</b>” được viết theo kiểu chữ “retro” cách điệu cùng sắc xám nhạt. Thiết kế này không chỉ tôn vinh vẻ đẹp thời trang theo khuynh hướng cổ điển mà còn mang lại cảm giác hoài niệm nhưng vẫn rất hiện đại cho người sử dụng.</p>\n<p>Thiết kế của dòng<b> xe wave alpha </b>không chỉ đa dạng về phiên bản mà còn phong phú về màu sắc, đáp ứng nhu cầu thẩm mỹ của từng khách hàng. Đây cũng chính là lý do khiến <b>xe wave</b> trở thành một trong những mẫu xe số quốc dân được yêu thích nhất tại Việt Nam. Hiện tại <b>giá xe wave alpha</b> trên thị trường cũng rất đa dạng, tuỳ thuộc vào từng <a href=\"/xe-may?nhom=honda\"><strong>cửa hàng honda</strong></a> và khu vực mà sẽ <b>giá xe wave</b> sẽ có sự thay đổi.</p>\n<h2>2.Giới thiệu về động cơ và tiện ích của wave alpha 110</h2>\n<p><b>Wave alpha 110</b> là một trong những mẫu xe máy được ưa chuộng nhất trên thị trường hiện nay, không chỉ nhờ vào thiết kế tinh tế mà còn bởi những tính năng vượt trội mà nó mang lại. Đặc biệt, động cơ 110cc của <b>xe wave </b>được đánh giá cao về độ bền bỉ và hiệu suất hoạt động.</p>\n<p>Động cơ mạnh mẽ và tiết kiệm nhiên liệu</p>\n<p><b>Honda wave alpha</b> được trang bị động cơ 110cc, cho phép xe vận hành mạnh mẽ nhưng vẫn đảm bảo khả năng tiết kiệm nhiên liệu tối ưu. Với công nghệ tiên tiến, động cơ này không chỉ mang lại trải nghiệm lái thú vị mà còn giúp người sử dụng tiết kiệm chi phí vận hành hàng tháng. Điều này khiến <b>xe wave alpha</b> trở thành lựa chọn lý tưởng cho những ai thường xuyên di chuyển trong đô thị.</p>\n\n<p>Hệ thống chiếu sáng thông minh</p>\n<p>Một trong những điểm nổi bật của <b>xe wave alpha</b> là hệ thống đèn chiếu sáng phía trước luôn bật sáng khi xe hoạt động. Chế độ đèn này không chỉ đảm bảo tầm nhìn tốt nhất cho người lái mà còn tăng cường khả năng nhận diện của xe trên đường phố, ngay cả trong điều kiện ánh sáng ban ngày. Điều này giúp người lái cảm thấy an tâm hơn khi di chuyển, đặc biệt là vào ban đêm hoặc trong điều kiện thời tiết xấu.</p>\n\n<p>Mặt đồng hồ dễ quan sát</p>\n<p><b>Honda wave alpha</b> cũng được trang bị mặt đồng hồ hiển thị thông số vận hành rõ ràng và dễ dàng quan sát. Các thông tin như tốc độ, mức nhiên liệu và các cảnh báo kỹ thuật đều được trình bày một cách trực quan, giúp người lái nắm bắt tình trạng xe một cách nhanh chóng và thuận tiện.</p>\n\n<p>Ổ khóa đa năng tiện lợi</p>\n<p>Một tính năng đáng chú ý khác của <b>wave alpha 110</b> là ổ khóa đa năng 3 trong 1, bao gồm khóa điện, khóa cổ và khóa từ. Thiết kế này không chỉ mang lại sự tiện lợi cho người sử dụng mà còn giúp chống rỉ sét hiệu quả, đảm bảo an toàn cho chiếc xe của bạn.</p>\n\n<p><b>Wave alpha 110</b> không chỉ là một phương tiện di chuyển đơn thuần mà còn là sự kết hợp hoàn hảo giữa hiệu suất mạnh mẽ và tính năng tiện ích thông minh. Đây chắc chắn sẽ là lựa chọn lý tưởng cho những ai đang tìm kiếm một chiếc xe máy đáng tin cậy và tiết kiệm.&nbsp;</p>\n<h2>3. Cập nhật giá xe Wave alpha mới nhất hiện nay</h2>\n<p>Với nhiều năm uy tín trong lĩnh vực kinh doanh xe máy, Hệ thống Siêu Thị Yên Thoa tự hào là <strong>đại lý xe máy</strong> đáng tin cậy được nhiều khách hàng lựa chọn. Chúng tôi cam kết mang đến cho khách hàng những sản phẩm chất lượng cao nhất cùng dịch vụ tận tâm và chuyên nghiệp nhất.</p>\n<p>Dưới đây là <b>giá xe wave alpha </b>mới nhất tại Yên Thoa. Lưu ý tuỳ theo từng phiên bản và thời điểm mà <b>giá xe wave</b> sẽ có sự chênh lệch.</p>\n<p><b>Giá xe wave alpha</b> phiên bản tiêu chuẩn: <b>18.900.000đ</b></p>\n<p><b>Giá xe wave alpha</b> phiên bản đặc biệt: <b>19.300.000đ</b></p>\n<p><b>Giá xe wave alpha</b> phiên bản cổ điển:&nbsp; <b>19.900.000đ</b></p>\n\n<p>Đặc biệt, khi mua xe <b>wave alpha 110</b> tại Yên Thoa trong hôm nay, quý khách còn được nhận ngay những ưu đãi hấp dẫn như:</p>\n<p>– Giao xe tận nhà theo yêu cầu</p>\n<p>– Hỗ trợ trả góp với lãi suất cực thấp 0%</p>\n<p>– Chỉ cần trả trước 0đ rước xe về ngay</p>\n<p>– Nhận ngay combo quà tặng độc quyền trị giá 2.350.000đ cùng hàng ngàn chương trình khuyến mãi khác</p>\n<p>– Dịch vụ thu xe cũ đổi xe mới nhanh chóng</p>\n<p>– Bảo hành chính hãng cho sản phẩm</p>\n<p>Nếu quý khách có nhu cầu tìm hiểu về <b>giá xe wave</b> hoặc muốn sở hữu ngay dòng xe này, vui lòng liên hệ với Yên Thoa để được nhân viên tư vấn và hỗ trợ nhanh chóng!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
