INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-wave-rsx', 'Xe Wave RSX', 'honda', '[\"xe-so\"]', 23300000, 26800000, '/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-the-thao-mau-trang-den-bac.webp', '[\"/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-the-thao-mau-trang-den-bac.webp\"]', '[\"Đen\",\"Đen Bạc\",\"Đỏ Đen\",\"Đỏ Đen Bạc\",\"Trắng Đen Bạc\",\"Xanh đậm Đen Bạc\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-tieu-chuan-mau-do-den.webp\",\"price\":23300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-tieu-chuan-mau-den.webp\",\"price\":23300000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Đặc biệt\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-dac-biet-mau-den-bac.webp\",\"price\":24800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-the-thao-mau-trang-den-bac.webp\",\"price\":26800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh đậm Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-the-thao-mau-xanh-den-bac.webp\",\"price\":26800000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Thể thao\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/wave-rsx-phien-ban-the-thao-mau-do-den-bac.webp\",\"price\":26800000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Dung tích bình xăng\",\"value\":\"0,4L\"},{\"label\":\"Loại động cơ\",\"value\":\"Xăng, 4 kỳ, 1 xilanh, làm mát bằng không khí\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,46 kW / 7.500 vòng/phút\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"0,8 lít khi thay nhớt 1,0 lít khi rã máy\"},{\"label\":\"Mức tiêu thụ nhiên liệu\",\"value\":\"1,56 L/100 km\"},{\"label\":\"Hộp số\",\"value\":\"Cơ khí, 4 số tròn\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Đạp chân/Điện\"},{\"label\":\"Moment cực đại\",\"value\":\"8,70 Nm/6.000 vòng/phút\"},{\"label\":\"Dung tích xy-lanh\",\"value\":\"109,2 cm3\"},{\"label\":\"Đường kính x Hành trình pít tông\",\"value\":\"50,00 x 55,60 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"9,3 : 1\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Phuộc trước\",\"value\":\"Ống lồng, giảm chấn thủy lực\"},{\"label\":\"Phuộc sau\",\"value\":\"Lò xo trụ, giảm chấn thủy lực\"},{\"label\":\"Kích cỡ lớp trước/sau\",\"value\":\"Lốp trước: 70/90 - 17 M/C 38P Lốp sau: 80/90 - 17 M/C 50P\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Khối lượng bản thân\",\"value\":\"98kg\"},{\"label\":\"Độ cao yên\",\"value\":\"760mm\"},{\"label\":\"Khoảng cách trục bánh xe\",\"value\":\"1227mm\"},{\"label\":\"Dài x rộng x cao\",\"value\":\"1922mm x 709mm x 1082mm\"},{\"label\":\"Khoảng sáng gầm xe\",\"value\":\"135mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tùy điều kiện nào đến trước)\"}]}]', '<p>Xe wave rsx không chỉ là một phương tiện di chuyển đơn thuần mà còn là một sản phẩm kết hợp hoàn hảo giữa công nghệ hiện đại và sự tiện lợi.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE WAVE RSX 110 CỦA HONDA MỚI NHẤT HIỆN NAY&nbsp;</h2>\n<p>Kể từ lần đầu ra mắt, dòng xe số <b>honda rsx</b> đã nhanh chóng thu hút sự chú ý của những khách hàng trẻ tuổi. Với thiết kế mạnh mẽ đầy cuốn hút, dòng<b> xe wave rsx </b>không chỉ đơn thuần là phương tiện di chuyển mà còn là biểu tượng của sự phá cách độc đáo. Hãy cùng Hệ thống Siêu Thị Yên Thoa khám phá ngay <b>giá xe wave rxs</b> và những ưu điểm của mẫu<b> xe </b><b>wave rsx 110</b> qua bài viết dưới đây.</p>\n\n<h2>1. Thiết kế trẻ trung mạnh mẽ của dòng xe wave rsx 110</h2>\n<p><b>Wave rsx 110</b> là một trong những dòng xe số bán chạy nhất hiện nay. Được thiết kế với phong cách thể thao, hiện đại và cuốn hút, Wave RSX fi mang đến hình ảnh trẻ trung và năng động cho người sử dụng.</p>\n\n<p><em>Thiết kế phía trước mạnh mẽ</em></p>\n<p>Phần đầu xe của <b>wave rsx 110</b> được thiết kế mới mẻ với mặt nạ trước mang biểu tượng chữ V sắc nét. Sự kết hợp hài hòa giữa đèn xi nhan mới và mặt nạ tạo nên một diện mạo thon gọn nhưng không kém phần mạnh mẽ và thể thao. Đây chính là điểm nhấn giúp <b>wave rsx fi</b> nổi bật trên đường phố, thu hút mọi ánh nhìn.</p>\n\n<p><em>Tem xe mới ấn tượng</em></p>\n<p>Một trong những yếu tố làm nên sự khác biệt của <b>xe wave rsx </b>chính là bộ tem xe độc đáo. Thiết kế tem xe mang phong cách đột phá với các đường nét sắc sảo chạy dọc thân xe, tạo nên vẻ ngoài thanh thoát nhưng đầy cá tính. Logo 3D “RSX” nổi bật trên nền tem càng làm tăng thêm sự cuốn hút, giúp người dùng dễ dàng thể hiện phong cách riêng biệt của mình.</p>\n<p><em>Thiết kế hai bên linh hoạt</em></p>\n<p>Yếm xe <b>honda rsx</b> được cải tiến hoàn toàn mới với độ dày dặn và chắc chắn hơn, mang lại cảm giác an toàn cho người sử dụng. Hai bên thân xe cũng được điều chỉnh để trở nên thon gọn hơn, tạo ra hình ảnh thể thao và nhanh nhẹn cho chiếc xe. Sự linh hoạt trong thiết kế này không chỉ nâng cao tính thẩm mỹ mà còn cải thiện hiệu suất khí động học khi vận hành.</p>\n<p><em>Thiết kế phía sau thể thao </em></p>\n<p>Phần đuôi xe của <b>xe máy rsx</b> tiếp tục khẳng định phong cách thể thao với cụm đèn hậu vuốt cao kiêu hãnh. Thiết kế này không chỉ tăng cường khả năng nhận diện từ xa mà còn góp phần tạo nên vẻ ngoài khỏe khoắn cho <b>honda rsx</b>. Bên cạnh đó, ốp ống xả màu đen mới được chế tác từ vật liệu nhựa cao cấp cũng đóng vai trò quan trọng trong việc gia tăng hình ảnh mạnh mẽ và hiện đại.</p>\n\n<p>Với thiết kế tinh tế cùng những cải tiến vượt trội về mặt thẩm mỹ lẫn công nghệ, dòng <b>wave rsx 110</b> chắc chắn sẽ đáp ứng mọi nhu cầu di chuyển hàng ngày cũng như khẳng định cá tính riêng biệt của người sử dụng. Hiện tại, <b>giá xe wave rxs</b> được bán tại Yên Thoa đang ở mức cực kỳ ưu đãi. Qúy khách có nhu cầu mua xe vui lòng liên hệ qua hotline để được tư vấn.</p>\n<h2>2. Động cơ được cải tiến mới của honda rsx</h2>\n<p><b>Wave rsx fi</b> vừa được nâng cấp với động cơ 110cc, trang bị công nghệ phun xăng điện tử tiên tiến. Động cơ này hoạt động theo chu trình 4 kỳ, sử dụng xi-lanh đơn, không chỉ mang lại hiệu suất vượt trội mà còn đáp ứng tiêu chuẩn khí thải Euro 3, góp phần bảo vệ môi trường.</p>\n\n<p>Với thiết kế tối ưu hóa khả năng tăng tốc, <b>wave rsx 110</b> cho phép người lái trải nghiệm cảm giác lái mượt mà và mạnh mẽ. Đặc biệt, nhờ vào hệ thống phun xăng điện tử PGM-FI, <b>xe máy rsx</b> không chỉ tiết kiệm nhiên liệu một cách hiệu quả mà còn đảm bảo sự bền bỉ trong quá trình vận hành. Điều này giúp người dùng yên tâm hơn khi di chuyển trên những chặng đường dài.</p>\n<p>Sự kết hợp hoàn hảo giữa công nghệ hiện đại và thiết kế tinh tế đã tạo nên một chiếc xe máy không chỉ đáp ứng nhu cầu di chuyển hàng ngày mà còn mang lại trải nghiệm lái xe thú vị. <b>Honda rsx</b> thực sự là lựa chọn lý tưởng cho những ai yêu thích sự tiện lợi và hiệu suất cao trong từng chuyến đi.</p>\n<h2>3. Những tiện ích được trang bị trên dòng xe wave rsx fi</h2>\n<p>Dòng xe <b>wave rsx fi</b> không chỉ nổi bật với thiết kế thể thao, mà còn được trang bị nhiều tiện ích hiện đại, mang lại trải nghiệm lái xe an toàn và thoải mái cho người sử dụng.</p>\n<p><em>Ổ khóa thông minh 4 trong 1</em></p>\n<p>Một trong những điểm nhấn đáng chú ý của <b>wave rsx 110</b> chính là hệ thống ổ khóa tích hợp 4 trong 1. Hệ thống này bao gồm khóa điện, khóa từ, khóa cổ và khóa yên, giúp người dùng dễ dàng thao tác và tăng cường độ an toàn cho xe. Với thiết kế chống rỉ sét, ổ khóa này không chỉ bền bỉ theo thời gian mà còn mang lại sự yên tâm cho người sử dụng khi để xe ở nơi công cộng.</p>\n\n<p><em>Hộc đựng đồ U-box tiện lợi</em></p>\n<p><b>Honda rsx</b> được trang bị hộc đựng đồ U-box thông minh, có khả năng chứa một chiếc mũ bảo hiểm nửa đầu cùng nhiều vật dụng cá nhân khác. Thiết kế này không chỉ giúp tối ưu hóa không gian lưu trữ mà còn tạo sự thuận tiện cho người dùng khi di chuyển hàng ngày.</p>\n\n<p><em>Đèn chiếu sáng tự động</em></p>\n<p>Một tính năng nổi bật khác là hệ thống đèn chiếu sáng phía trước luôn tự động bật sáng khi xe vận hành. Điều này đảm bảo rằng người lái luôn có tầm nhìn tốt nhất trong mọi điều kiện ánh sáng, đồng thời giảm thiểu nguy cơ quên bật đèn khi di chuyển vào ban đêm hoặc trong điều kiện thiếu sáng. Tính năng này cũng góp phần nâng cao khả năng nhận diện của xe trên đường phố, giúp tăng cường an toàn giao thông.</p>\n\n<p><em>Mặt đồng hồ hiện đại và dễ quan sát</em></p>\n<p>Mặt đồng hồ của <b>wave rsx fi</b> được thiết kế với phong cách thể thao hiện đại và bố trí khoa học. Người dùng sẽ dễ dàng theo dõi các thông số vận hành như tốc độ, mức nhiên liệu hay tình trạng hoạt động của xe chỉ bằng một cái nhìn nhanh chóng. Thiết kế tinh tế này không chỉ mang lại tính thẩm mỹ cao mà còn giúp người lái tập trung hơn vào việc điều khiển phương tiện.</p>\n<p><b>Xe wave rsx</b> không chỉ là một phương tiện di chuyển đơn thuần mà còn là một sản phẩm kết hợp hoàn hảo giữa công nghệ hiện đại và sự tiện lợi. Những tính năng vượt trội này chắc chắn sẽ làm hài lòng cả những khách hàng khó tính nhất.</p>\n<h2>4. Giá xe wave rsx mới nhất tại Hệ thống Siêu Thị Yên Thoa&nbsp;</h2>\n<p>Bạn đang tìm kiếm một địa chỉ uy tín để mua <b>xe wave rsx</b>? Hãy đến với Yên Thoa – <a href=\"/xe-may\"><strong>cửa hàng xe máy</strong></a> hàng đầu chuyên cung cấp các dòng xe chất lượng, đáng tin cậy với mức <b>giá xe wave rxs</b> hợp lý.</p>\n<p>Dưới đây là <b>giá xe wave rsx</b> tại Yên Thoa&nbsp;</p>\n<p><strong>Wave rsx 110</strong> phiên bản tiêu chuẩn: 23.300.000đ</p>\n<p><strong>Wave rsx 110</strong> phiên bản đặc biệt: 24.800.000đ</p>\n<p><strong>Wave rsx 110</strong> phiên bản thể thao: 26.800.000đ</p>\n\n<p>Với nhiều năm kinh nghiệm trong ngành kinh doanh xe máy, Yên Thoa tự hào mang đến cho khách hàng những sản phẩm chất lượng cao, được bảo hành chính hãng. Đội ngũ nhân viên của chúng tôi không chỉ nhiệt tình mà còn dày dạn kinh nghiệm, sẵn sàng tư vấn và hỗ trợ bạn trong việc lựa chọn chiếc <a href=\"/xe-may?nhom=honda\"><strong>xe honda</strong></a> phù hợp nhất với nhu cầu và sở thích của mình.</p>\n<p>Đặc biệt, Yên Thoa còn cung cấp dịch vụ hỗ trợ trả góp linh hoạt, giúp bạn dễ dàng hiện thực hóa ước mơ sở hữu chiếc <b>honda rsx</b> yêu thích mà không cần lo lắng về vấn đề tài chính.</p>\n<p>Hãy liên hệ ngay với chúng tôi để nhận được sự tư vấn tận tình và thông tin chi tiết về <b>giá xe wave rsx</b> cũng như các chương trình khuyến mãi hấp dẫn. Chúng tôi luôn sẵn sàng đồng hành cùng bạn trên mọi nẻo đường!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
