INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-wr155r', 'Xe WR155R', 'yamaha', '[\"xe-tay-con\"]', 79000000, 79000000, '/sites/yenthoa/img/2026/09/xe-wr155r-den.webp', '[\"/sites/yenthoa/img/2026/09/xe-wr155r-den.webp\"]', '[\"Đen\",\"Xanh\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2026/09/xe-wr155r-den.webp\",\"price\":79000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh\"}],\"img\":\"/sites/yenthoa/img/2026/09/xe-wr155r-xanh.webp\",\"price\":79000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"Làm mát bằng dung dịch, 4 thì, SOHC, 4 van\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy-lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"155,1 cm³\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"58,0 × 58,7 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,6:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"12,3 kW (16,7 PS) tại 10.000 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"14,3 N·m (1,5 kgf·m) tại 6.500 vòng/phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Khởi động điện\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Cácte ướt\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"1,10 L\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"8,1 L\"},{\"label\":\"Hệ thống cung cấp nhiên liệu\",\"value\":\"Phun xăng điện tử\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI (đánh lửa điều khiển bằng transistor)\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"3,042 (73/24) / 3,643 (51/14)\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Ly hợp ướt, đa đĩa\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"Tỉ số truyền 1: 2,833 (34/12) | Tỷ số truyền số 2: 1,875 (30/16) | Tỷ số truyền số 3: 1,364 (30/22) | Tỷ số truyền số 4: 1,143 (24/21) | Tỷ số truyền 5: 0,957 (22/23) | Tỷ số truyền 6: 0,840 (21/25)\"},{\"label\":\"Điện áp ắc quy\",\"value\":\"12V, 3,0Ah / 3,0Ah (10HR)\"},{\"label\":\"Hộp số\",\"value\":\"Ăn khớp thường xuyên, 6 cấp / kiểu hồi về\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Semi-double cradle\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Phuộc ống lồng\"},{\"label\":\"Độ lệch phương trục lái\",\"value\":\"27°55’ / 115 mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Gắp sau với hệ thống liên kết\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa đơn thủy lực\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh đĩa đơn thủy lực\"},{\"label\":\"Kích thước bánh trước / bánh sau\",\"value\":\"2.75-21 45P (loại có săm) / 4.10-18 59P (loại có săm)\"},{\"label\":\"Đèn trước\",\"value\":\"12V, 35/35W × 1 (đèn Halogen)\"},{\"label\":\"Đèn báo rẽ (trước/sau)\",\"value\":\"12V, 10W × 2 (trước/sau)\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"2.145 × 840 × 1.200 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"880 mm\"},{\"label\":\"Chiều dài cơ sở\",\"value\":\"1.430 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"134 kg (bao gồm đầy dầu và nhiên liệu)\"},{\"label\":\"Khoảng sáng gầm xe tối thiểu\",\"value\":\"245 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30,000km (tuỳ điều kiện nào đến trước)\"}]}]', '<p>WR155R là mẫu xe địa hình 155cc thuộc dòng WR Series, được phát triển dành cho những người trẻ mong muốn mở rộng trải nghiệm chinh phục mọi cung đường. Kế thừa tinh thần off-road đặc trưng, WR155R được tích hợp công nghệ VVA cùng những trang bị độc đáo, mang đến khả năng vận hành mạnh mẽ trên địa hình đầy thử thách cũng như sự linh hoạt trong sử dụng hằng ngày.</p>\n<p>(*) Giá xe trên chỉ là giá đề xuất chứ không phải giá chính thức, giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm. Để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline.</p>', '<h2><strong>Giá Xe Yamaha WR155R Chính Hãng Mới Nhất</strong></h2>\n<p>Bạn là một biker đam mê những cung đường phượt đầy thử thách, hay đơn giản muốn tìm kiếm một chiếc cào cào thương mại linh hoạt để vừa đi phố vừa chinh phục địa hình? Phân khúc xe đa địa hình (dual-sport) tại Việt Nam đang trở nên sôi động hơn bao giờ hết với sự góp mặt của <b>xe WR155</b> (WR155R) – mẫu xe côn tay địa hình 155cc tích hợp công nghệ VVA, hộp số 6 cấp, hệ thống treo hành trình dài và thiết kế hướng đến khả năng vận hành đa địa hình.&nbsp;</p>\n<p>Trong bài viết này, hãy cùng cập nhật chi tiết <b>giá xe Yamaha WR155 chính hãng mới nhất</b>, đánh giá thông số kỹ thuật thực tế, bảng tính chi phí lăn bánh cũng như các chương trình hỗ trợ mua <b>xe trả góp</b> siêu ưu đãi tại hệ thống Yên Thoa!</p>\n\n<h2><b>1. Đánh giá xe Yamaha WR155: Chiến binh cào cào phố đỉnh cao phân khúc 155cc</b></h2>\n<p>Không phải ngẫu nhiên mà <b>xe cào cào Yamaha</b> thế hệ mới lại tạo nên cơn sốt trong cộng đồng mê phượt và xe địa hình tại Việt Nam. <a href=\"/xe/xe-wr155r\"><b>Yamaha WR155R</b></a> sở hữu hàng loạt trang bị và thông số kỹ thuật vượt trội:</p>\n<ul>\n<li><b>Khối động cơ 155cc VVA uy lực:</b> Trái tim của chiếc xe là khối động cơ SOHC 4 thì, 4 van, làm mát bằng dung dịch, tích hợp công nghệ van biến thiên <b>VVA</b>. Xe sản sinh công suất tối đa lên tới <b>16,7 mã lực (12,3 kW) tại 10.000 vòng/phút</b> và mô-men xoắn cực đại <b>14,3 Nm tại 6.500 vòng/phút</b>. Nhờ van biến thiên VVA giúp tối ưu khả năng vận hành ở các dải vòng tua khác nhau. Đây là điểm phù hợp với người dùng muốn một chiếc xe có khả năng tăng tốc linh hoạt nhưng vẫn giữ được tính thực dụng khi sử dụng hàng ngày. .</li>\n<li><b>Hộp số 6 cấp &amp; Hệ thống phun xăng điện tử Fi:</b> Giúp tối ưu hóa mức tiêu hao nhiên liệu (chỉ khoảng 2,33L/100km) – con số cực kỳ kinh tế cho một mẫu xe hiệu năng cao.</li>\n<li><b>Kích thước chuẩn Off-road &amp; Bình xăng lớn:</b> Bánh trước kích thước 21 inch, bánh sau 18 inch kết hợp lốp gai địa hình. Khoảng sáng gầm xe đạt <b>245mm</b>, chiều cao yên <b>880mm</b> mang lại góc nhìn thoáng rộng. Đặc biệt, dung tích bình xăng khủng <b>8,1 lít</b> cho phép bạn tự tin đi phượt xuyên tỉnh từ 300 – 350 km mà không lo cạn nhiên liệu giữa chừng.</li>\n<li><b>Hệ thống giảm xóc hành trình dài chuyên dụng:</b>\n<ul>\n<li><i>Phuộc trước:</i> Ống lồng đường kính lớn <b>41mm</b>, chiều dài hành trình lên tới 899mm, trang bị bọc cao su bảo vệ ty phuộc trước bùn đất.</li>\n<li><i>Phuộc sau:</i> Monoshock liên kết Monocross kèm <b>bình dầu phụ (Piggyback)</b> có khả năng tùy chỉnh tải trước (preload), đảm bảo độ êm ái khi vượt gờ, hố đá hay bay dốc.</li>\n</ul>\n</li>\n<li><b>Khung sườn Semi-Double Cradle bền bỉ:</b> Khung ống thép đôi cải tiến giúp xe vững chãi khi chịu lực vặn xoắn cao nhưng vẫn duy trì trọng lượng ướt nhẹ chỉ <b>134 kg</b>.</li>\n</ul>\n<p>Ngoài ra, thiết kế <b>xe Yamaha WR155R</b> mang đậm phong cách adventure với yên xe thể thao, thân xe gọn và khoảng sáng gầm cao. Yamaha cũng thiết kế yên theo hướng hỗ trợ người lái thay đổi tư thế khi vận hành trên những loại địa hình khác nhau.&nbsp;</p>\n<p>Về màu sắc, <b>WR155R</b> hiện được công bố với hai lựa chọn gồm <b>Đen</b> và <b>Xanh</b>. Trong đó, màu xanh mang dấu ấn đặc trưng của Yamaha, còn màu đen tạo cảm giác mạnh mẽ và cá tính hơn.</p>\n<p>Nếu đang cân nhắc <b>mua xe WR155R</b>, bạn cũng nên xác định rõ mục đích sử dụng. Người thường xuyên đi phố có thể ưu tiên khả năng kiểm soát và tư thế lái; người đi tour hoặc khám phá địa hình sẽ quan tâm nhiều hơn đến hệ thống treo, khoảng sáng gầm, kích thước bánh xe và khả năng vận hành đường dài.</p>\n\n<h2><b>2. Bảng giá xe Yamaha WR155 chính hãng mới nhất và chi phí lăn bánh</b></h2>\n<p>Hiện nay, <b>giá xe WR155R chính hãng </b>được niêm yết với mức giá cực kỳ cạnh tranh so với các đối thủ cùng phân khúc nhập khẩu tư nhân trước đây.</p>\n<p>Dưới đây là bảng giá niêm yết và ước tính <b>giá lăn bánh WR155R</b> tham khảo:</p>\n<table>\n<tbody>\n<tr>\n<td><b>Phiên bản màu sắc</b></td>\n<td><b>Giá niêm yết (Đã gồm VAT)</b></td>\n<td><b>Giá lăn bánh tạm tính (TP.HCM / HN)</b></td>\n<td><b>Giá lăn bánh tạm tính (Tỉnh/Thị xã)</b></td>\n</tr>\n<tr>\n<td><b>Yamaha WR155R Xanh Dương (Icon Blue)</b></td>\n<td><b>79.000.000 VNĐ</b></td>\n<td>~ 86.500.000 VNĐ</td>\n<td>~ 82.500.000 VNĐ</td>\n</tr>\n<tr>\n<td><b>Yamaha WR155R Đen Nhám (Yamaha Black)</b></td>\n<td><b>79.000.000 VNĐ</b></td>\n<td>~ 86.500.000 VNĐ</td>\n<td>~ 82.500.000 VNĐ</td>\n</tr>\n</tbody>\n</table>\n<p><i>Lưu ý: Giá lăn bánh đã bao gồm lệ phí trước bạ (5% tại TP lớn, 2% tại tỉnh), phí cấp biển số và bảo hiểm TNDS bắt buộc. Mức giá thực tế tại đại lý có thể thay đổi tùy thuộc vào chương trình ưu đãi, quà tặng tiền mặt hoặc phụ kiện tại thời điểm mua hàng.</i></p>\n<p>Đặc biệt, nếu ngân sách chưa đủ để thanh toán toàn bộ một lần, khách hàng có thể cân nhắc phương án <b>xe trả góp</b>. Hình thức này giúp giảm áp lực tài chính ban đầu và chủ động hơn trong kế hoạch sở hữu xe. Tuy nhiên, khoản trả trước, thời hạn vay, lãi suất và số tiền thanh toán hàng tháng sẽ phụ thuộc vào đơn vị tài chính và hồ sơ của từng khách hàng.&nbsp;</p>\n<h2><b>3. Hướng dẫn mua xe Yamaha WR155 trả góp lãi suất thấp, duyệt hồ sơ nhanh</b></h2>\n<p>Mức giá niêm yết 79 triệu đồng là con số rất dễ tiếp cận cho một chiếc <b>xe cào cào</b> chính hãng, tuy nhiên nếu bạn muốn tối ưu dòng tiền cá nhân để sắm thêm phụ kiện đi tour hay đồ bảo hộ, phương án <b>mua xe yamaha WR155R trả góp</b> là lựa chọn vô cùng thông minh.</p>\n<p>Tại Yên Thoa, chương trình hỗ trợ mua trả góp được liên kết với nhiều ngân hàng và công ty tài chính uy tín (HD SAISON, FE Credit, MCredit, Home Credit…) với nhiều đặc quyền:</p>\n<ul>\n<li><b>Mức trả trước linh hoạt:</b> Chỉ cần trả trước từ <b>20% – 30% giá trị xe</b> (tương đương khoảng 16 – 24 triệu đồng) là có thể nhận xe ngay trong ngày.</li>\n<li><b>Thời gian vay linh hoạt:</b> Tùy chọn từ 6, 9, 12, 18 đến 24 tháng theo khả năng tài chính.</li>\n<li><b>Thủ tục đơn giản:</b> Chỉ cần <b>CCCD gắn chip</b>, không cần chứng minh thu nhập rườm rà. Duyệt hồ sơ nhanh chóng chỉ từ 15 – 30 phút.</li>\n<li><b>Ưu đãi nhận cà vẹt gốc:</b> Áp dụng cho các gói vay tiêu chuẩn có điều kiện hỗ trợ giữ bản gốc giấy đăng ký xe.</li>\n</ul>\n<h2><b>4. Mua xe Yamaha WR155 chính hãng tại Yên Thoa&nbsp;</b></h2>\n<p>Đối với khách hàng tại TP.HCM đang quan tâm <b>địa chỉ mua xe Yamaha WR155 chính hãng</b>, Yên Thoa là địa chỉ bạn có thể liên hệ để được tư vấn thông tin mua xe, giá bán thực tế và chính sách tại thời điểm mua.&nbsp;</p>\n\n<p>Yên Thoa tự hào là một trong những đối tác phân phối chính hãng xe máy Yamaha hàng đầu, mang đến cho khách hàng trải nghiệm mua sắm và dịch vụ hậu mãi chu đáo.</p>\n<p>Khi chọn mua <b>xe Yamaha WR155</b> tại Yên Thoa, quý khách hàng nhận được các quyền lợi vàng:</p>\n<ul>\n<li><b>Hỗ trợ trọn gói từ A – Z:</b> Đội ngũ chuyên viên hỗ trợ đăng ký biển số tận nơi, giao xe tận nhà theo yêu cầu và tư vấn gói độ pô, dán decal, lắp thêm phụ kiện touring/cào cào chuyên nghiệp.</li>\n<li><b>Xe chính hãng 100%:</b> Cam kết nguồn gốc xuất xứ rõ ràng, đầy đủ linh kiện, phụ tùng và quà tặng theo tiêu chuẩn Yamaha Motor Việt Nam.</li>\n<li><b>Chính sách bảo hành, bảo dưỡng dài hạn:</b> Hưởng trọn vẹn chế độ bảo hành 3 năm hoặc 30.000 km, cùng các lượt bảo dưỡng miễn phí tại trạm dịch vụ đạt chuẩn kỹ thuật cao.</li>\n<li><b>Tư vấn tận tâm 24/7:</b> Báo giá lăn bánh minh bạch, rõ ràng, không phát sinh chi phí ẩn.</li>\n</ul>\n<p>Nếu đang cân nhắc mua xe, bạn cũng nên xác định rõ mục đích sử dụng. Người thường xuyên đi phố có thể ưu tiên khả năng kiểm soát và tư thế lái; người đi tour hoặc khám phá địa hình sẽ quan tâm nhiều hơn đến hệ thống treo, khoảng sáng gầm, kích thước bánh xe và khả năng vận hành đường dài. Liên hệ ngay Yên Thoa để lái thử trải nghiệm và nhận báo giá ưu đãi độc quyền:</p>\n<ul>\n\n<li><b>Hotline tư vấn &amp; báo giá trả góp 24/7:</b> <b>0789.619.698</b></li>\n<li><i>Hỗ trợ làm hồ sơ trả góp online – Giao xe tận nhà nhanh chóng!</i></li>\n</ul>', 1);
UPDATE products SET variants = '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2026/09/xe-wr155r-den.webp\",\"price\":79000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh\"}],\"img\":\"/sites/yenthoa/img/2026/09/xe-wr155r-xanh.webp\",\"price\":79000000}]' WHERE slug = 'xe-wr155r' AND variants IS NULL;
