ánh sau\",\"value\":\"2.75-21 45P (loại có săm) / 4.10-18 59P (loại có săm)\"},{\"label\":\"Đèn trước\",\"value\":\"12V, 35/35W × 1 (đèn Halogen)\"},{\"label\":\"Đèn báo rẽ (trước/sau)\",\"value\":\"12V, 10W × 2 (trước/sau)\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"2.145 × 840 × 1.200 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"880 mm\"},{\"label\":\"Chiều dài cơ sở\",\"value\":\"1.430 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"134 kg (bao gồm đầy dầu và nhiên liệu)\"},{\"label\":\"Khoảng sáng gầm xe tối thiểu\",\"value\":\"245 mm\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30,000km (tuỳ điều kiện nào đến trước)\"}]}]' WHERE slug = 'xe-wr155r' AND specs IS NULL;
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-xmax-300', 'Xe XMAX 300', 'yamaha', '[]', 140000000, 140000000, '/sites/yenthoa/img/2025/04/xmax-300-den.webp', '[\"/sites/yenthoa/img/2025/04/xmax-300-den.webp\"]', '[\"Bạc Đen\",\"Đen\",\"Đen Xanh đậm\",\"Đỏ Đen\",\"Xám Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Bạc Đen\"}],\"img\":\"/sites/yenthoa/img/2025/04/xmax-300-bac-den.webp\",\"price\":140000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2025/04/xmax-300-den.webp\",\"price\":140000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen Xanh đậm\"}],\"img\":\"/sites/yenthoa/img/2025/04/xmax-300-xanh-den.webp\",\"price\":140000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đỏ Đen\"}],\"img\":\"/sites/yenthoa/img/2025/04/xmax-300-do-den.webp\",\"price\":140000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xám Đen\"}],\"img\":\"/sites/yenthoa/img/2025/04/xmax-300-xam-den.webp\",\"price\":140000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"4 kỳ 1 xy lanh, làm mát bằng chất lỏng\"},{\"label\":\"Dung tích\",\"value\":\"292cc\"},{\"label\":\"Đường kính x hành trình piston\",\"value\":\"70 × 75,9 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"10,9:1\"},{\"label\":\"Công suất cực đại\",\"value\":\"20,6 kW tại 7.250 vòng/phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"29 Nm tại 5.750 vòng/phút\"},{\"label\":\"Bộ ly hợp\",\"value\":\"Ly tâm, ma sát khô\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Lò xo trụ, giảm chấn thủy lực Lò xo trụ, giảm chấn thủy lực\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"110 mm\"},{\"label\":\"Hành trình phuộc trước\",\"value\":\"79 mm\"},{\"label\":\"Phanh trước\",\"value\":\"Đĩa, thủy lực, ABS\"},{\"label\":\"Lốp sau\",\"value\":\"Đĩa, thủy lực, ABS\"},{\"label\":\"Lốp trước\",\"value\":\"120/70-15M/C 56P\"},{\"label\":\"Lốp sau\",\"value\":\"140/70-14M/C 62P\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Dài x rộng x cao\",\"value\":\"2185 x 795 x 1410 mm\"},{\"label\":\"Chiều cao yên\",\"value\":\"795 mm\"},{\"label\":\"Trục cơ sở\",\"value\":\"1540 mm\"},{\"label\":\"Khoảng sáng gầm\",\"value\":\"135 mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"181 kg\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"13 L\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"30.000 km hoặc 3 năm (tuỳ theo điều kiện nào đến trước)\"}]}]', '<p>Yamaha xmax 300 đã chính thức có mặt trên thị trường Việt Nam thông qua đại lý Yên Thoa, mang đến cho người tiêu dùng hai tùy chọn màu sắc nổi bật: Đen Nhám và Xanh Đen.&nbsp;</p>\n<p><em>(*) Giá xe trên chỉ là giá đề xuất chứ không phải giá chính thức, giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm. Để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline.</em></p>', '<h2>GIÁ XE YAMAHA XMAX 300 CHÍNH HÃNG MỚI NHẤT</h2>\n<p><b>Yamaha X MAX 300</b> đã chính thức ra mắt với thiết kế hoàn toàn mới, mang đến sự năng động và hiện đại, phù hợp với nhu cầu di chuyển của những khách hàng yêu thích sự thoải mái trong những chuyến đi xa.</p>\n<p><b>X MAX 300</b> không chỉ đơn thuần là một phương tiện di chuyển, mà còn là biểu tượng của phong cách sống năng động. Với thiết kế tinh tế và các tính năng tiên tiến, mẫu xe này đã nhanh chóng trở thành một trong những lựa chọn hàng đầu tại thị trường Châu Âu.</p>\n<p>Đặc biệt, phiên bản mới này còn được bổ sung thêm nhiều màu sắc mới mẻ, tạo nên sự hấp dẫn và đa dạng cho người dùng. Những tín đồ yêu thích dòng xe này sẽ dễ dàng tìm thấy màu sắc phù hợp với cá tính của mình.</p>\n\n<h2>1. Yamaha Xmax 300 có điểm gì mới trong thiết kế?</h2>\n<p><strong>Yamaha xmax</strong><strong> 300</strong> mang đến một làn gió mới trong phân khúc xe tay ga cao cấp, lấy cảm hứng từ dòng TMAX danh tiếng. Với thiết kế tập trung vào sự thoải mái và khả năng vận hành linh hoạt trong đô thị, <b>x max 300 yamaha</b> hứa hẹn sẽ làm hài lòng những người đam mê xe.</p>\n<h3>1.1 Thiết kế tinh tế và tiện lợi</h3>\n<p>Về kích thước, dòng xe này có chiều dài, rộng và cao lần lượt là 2.180 x 795 x 1.410 mm, cùng chiều dài cơ sở đạt 1.540 mm. Với chiều cao yên ở mức 795 mm và trọng lượng chỉ 181 kg, mẫu xe này rất phù hợp với thể trạng của người Việt Nam, giúp người lái dễ dàng điều khiển và chống chân.</p>\n<p>Một điểm nhấn đáng chú ý trên <b>xe yamaha x max 300</b> là hệ thống kính chắn gió có thể điều chỉnh thông qua nút điều khiển trên cùm bên trái. Điều này cho phép người lái tùy chỉnh độ cao của kính chắn gió theo điều kiện môi trường thực tế, đảm bảo tầm nhìn tốt nhất và giảm thiểu tác động của gió.</p>\n\n<h3>1.2 Công nghệ hiện đại</h3>\n<p>Cụm đồng hồ trên xe được thiết kế hiện đại với hai màn hình riêng biệt. Màn hình LCD đơn sắc kích thước 3,2 inch hiển thị các thông tin cơ bản như tốc độ và mức nhiên liệu. Bên dưới là màn hình TFT màu kích thước 4,2 inch cung cấp nhiều tính năng giải trí và hỗ trợ vận hành khác nhau.</p>\n<p>Cụm công tắc trên <b>xe xmax 300</b> thế hệ mới được bố trí một cách khoa học để người lái dễ dàng thao tác nhanh chóng khi cần thiết. Các chức năng như điều chỉnh chiều cao kính chắn gió hay bật tắt hệ thống kiểm soát lực kéo HSTC đều có thể thực hiện dễ dàng.</p>\n<h3>1.3 Tiện ích vượt trội&nbsp;</h3>\n<p>Thiết kế yên xe dạng hai tầng không chỉ mang lại tư thế ngồi thoải mái cho cả người lái lẫn hành khách mà còn tạo sự thuận tiện trong các chuyến đi dài ngày. Đặc biệt, phần yên sau không bị bè ra hai bên giúp những người có chiều cao khiêm tốn dễ dàng chống chân hơn.</p>\n<p>Tay nắm sau được làm tách biệt hai bên và sơn bóng tạo điểm nhấn tương phản với màu sơn tổng thể của xe, tăng thêm phần sang trọng cho thiết kế tổng thể.</p>\n<p>Dung tích cốp xe lớn là một ưu điểm khác của <b>xe x max</b> phiên bản mới này. Người dùng có thể để vừa hai mũ bảo hiểm fullface cùng nhiều vật dụng nhỏ gọn khác như kính mát hay găng tay. Ngoài ra, xe còn được trang bị thêm hai hộc chứa đồ phía trước cùng cổng sạc USB-A 12V tích hợp tiện lợi.</p>\n<p>Một cải tiến đáng giá khác là nắp bình xăng được bố trí phía trước giúp việc đổ xăng trở nên thuận tiện hơn bao giờ hết mà không cần phải bước xuống xe. Bình xăng dung tích lớn lên tới 15 lít đảm bảo hành trình dài mà không lo hết nhiên liệu giữa chừng.</p>\n<p>Yamaha cũng trang bị cho <b>mẫu xe yamaha xmax 300</b> khóa thông minh SmartKey với thiết kế sang trọng tích hợp nhiều tính năng hiện đại như mở/tắt xe từ xa, định vị vị trí xe hay báo động chống trộm hiệu quả.</p>\n<p>Phần đuôi xe sử dụng công nghệ LED với tạo hình chữ X sắc nét hơn so với phiên bản trước đó, đồng bộ hoàn hảo với thiết kế phía trước tạo nên vẻ ngoài mạnh mẽ và hiện đại.</p>\n<h3>1.4 Hiệu suất vận hành an toàn</h3>\n<p>Hệ thống giảm xóc trước đã được tinh chỉnh kết hợp cùng mâm thể thao sử dụng lốp trước kích thước 120/70R15 và lốp sau kích thước 140/70R14 mang lại khả năng bám đường tốt hơn trong mọi điều kiện địa hình.</p>\n<p>Hệ thống phanh cũng được nâng cấp đáng kể với phanh đĩa kép đường kính lớn ở phía trước (267 mm) và phanh đĩa đơn ở phía sau (245 mm). Đặc biệt, hệ thống chống bó cứng phanh ABS tiêu chuẩn giúp tăng cường độ an toàn khi di chuyển trên mọi cung đường.</p>\n<h3>1.5 Động cơ xe XMAX 300</h3>\n<p><b>Xe yamaha xmax 300 phiên bản mới</b> tiếp tục khẳng định vị thế của mình trong phân khúc xe tay ga cao cấp với những cải tiến vượt bậc về hiệu suất động cơ và khả năng vận hành. Mẫu xe này vẫn được trang bị động cơ Blue Core mạnh mẽ, với cấu trúc xi lanh đơn có dung tích 292cc và hệ thống 4 van, đáp ứng đầy đủ tiêu chuẩn khí thải Euro 5 nghiêm ngặt.</p>\n\n<p>Về mặt công suất, dòng xe này mang đến sức mạnh tối ưu với công suất cực đại đạt 28 mã lực tại vòng tua máy 7.250 vòng/phút. Đồng thời, mô-men xoắn cực đại đạt tới 29Nm tại vòng tua máy 5.750 vòng/phút, giúp xe có khả năng tăng tốc nhanh chóng và linh hoạt trong mọi tình huống giao thông.</p>\n<p>Một điểm nổi bật khác của <b>yamaha xmax</b> là mức tiêu thụ nhiên liệu rất tiết kiệm, chỉ khoảng 3 lít/100 km. Điều này không chỉ giúp người lái tiết kiệm chi phí nhiên liệu mà còn góp phần bảo vệ môi trường.</p>\n<p>Với những cải tiến vượt bậc về thiết kế cũng như công nghệ, <b>xe máy yamaha xmax mới nhất</b> chắc chắn sẽ là lựa chọn lý tưởng cho những ai tìm kiếm một chiếc xe tay ga mạnh mẽ nhưng không kém phần tiện nghi và an toàn.</p>\n<h2>2. Giá xe yamaha XMAX 300 chính hãng&nbsp;</h2>\n<p><b>Yamaha x max 300</b> đã chính thức có mặt trên thị trường Việt Nam thông qua đại lý Yên Thoa, mang đến cho người tiêu dùng hai tùy chọn màu sắc nổi bật: Đen Nhám và Xanh Đen. Yên Thoa tự hào là một trong 4 đại lý duy nhất trở thành đại lý phân phối chính hãng của dòng xe này.</p>\n<p>Với mức <b>giá xe xmax 300</b> đề xuất đang là <strong>140 triệu đồng</strong>, dòng xe này không chỉ thu hút bởi thiết kế hiện đại mà còn bởi những tính năng vượt trội. Khách hàng khi mua xe sẽ được hưởng chế độ bảo hành lên đến 3 năm hoặc 30.000 km, tùy theo điều kiện nào đến trước, đảm bảo sự yên tâm trong quá trình sử dụng.</p>\n\n<p>Ngoài ra, Yên Thoa còn triển khai nhiều chương trình hậu mãi hấp dẫn dành cho khách hàng sở hữu <b>mua xe xmax 300</b>. Cụ thể, khách hàng sẽ nhận được:</p>\n<p>– Combo quà tặng độc quyền khi <a href=\"/xe-may\"><strong>mua xe máy</strong></a>.</p>\n<p>– Chính sách hỗ trợ trả góp với lãi suất ưu đãi cực thấp.</p>\n<p>– Cơ hội tham gia vào các chương trình khuyến mãi và ưu đãi hấp dẫn khác trong suốt thời gian sử dụng sản phẩm.</p>\n<p>Với những lợi ích này, <a href=\"/xe-may?nhom=yamaha\"><b>xe máy yamaha</b></a> hứa hẹn sẽ là một lựa chọn tuyệt vời cho những ai yêu thích sự tiện nghi và phong cách trong từng chuyến đi. Hãy đến ngay đại lý xe máy Yên Thoa để trải nghiệm và cập nhật <b>giá xe yamaha xmax 300</b>! Mọi chi tiết xin vui lòng liên hệ qua hotline 0789.619.698 để được tư vấn!</p>', 1);
