INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-xs155r', 'Xe XS155R', 'yamaha', '[\"xe-the-thao\"]', 78650000, 78650000, '/sites/yenthoa/img/2024/11/sx-155r-mau-bac.webp', '[\"/sites/yenthoa/img/2024/11/sx-155r-mau-bac.webp\"]', '[\"Bạc\",\"Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Bạc\"}],\"img\":\"/sites/yenthoa/img/2024/11/sx-155r-mau-bac.webp\",\"price\":78650000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2024/11/sx-155r-mau-den.webp\",\"price\":78650000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"Động cơ 4 thì, làm mát bằng dung dịch, SOHC, xy-lanh đơn 4 van\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xi lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"155.1\"},{\"label\":\"Tỷ số nén\",\"value\":\"11.6:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"14.2 kW (19.3 PS)/10,000 r/min\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"14.7 N・m (1.5 kgf・m) / 8,500 r/min\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Khởi động bằng điện\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Loại cát te ướt\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"10 L (2.6 US gal./2.2 Imp. Gal)\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"2\"},{\"label\":\"Bộ chế hòa khí\",\"value\":\"Phun xăng điện tử (FI)\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI (Hệ thống đánh lửa bán dẫn)\"},{\"label\":\"Tỷ số truyền sơ cấp và thứ cấp\",\"value\":\"3.042 (73/24) / 3.429 (48/14)\"},{\"label\":\"Đường kính xy lanh\",\"value\":\"58.0×58.7 mm\"},{\"label\":\"Tổng lượng dầu (khi tháo rã)\",\"value\":\"1.05 L (1.10 US qt./0.92 Imp. qt)\"},{\"label\":\"Điện áp ắc quy\",\"value\":\"12V,3.0Ah (10 HR)\"},{\"label\":\"Bộ ly hợp\",\"value\":\"Ướt, đa đĩa\"},{\"label\":\"Tỉ lệ chuyển động (thứ 1 – thứ 6)\",\"value\":\"1st: 2.833, 2nd: 1.875, 3rd: 1.364, 4th: 1.143, 5th: 0.957, 6th: 0.840\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Diamond\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa đơn thủy lực\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh đĩa đơn thủy lực\"},{\"label\":\"Lốp trước\",\"value\":\"110/70-17 M/C 54S không săm\"},{\"label\":\"Lốp sau\",\"value\":\"140/70-17 M/C 66S không săm\"},{\"label\":\"Góc cào (Caster)/đường mòn (Trail)\",\"value\":\"25.4°/ 89 mm\"},{\"label\":\"Hệ thống treo (trước/sau)\",\"value\":\"Phuộc ống lồng / Cánh tay đòn (hệ thống treo liên kết)\"},{\"label\":\"Đèn pha/Đèn báo rẽ (trước/sau)\",\"value\":\"LED / 12V, 10W x 2 / 12V, 10W x 2\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"2,005 mm x 805 mm x 1,080 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"810 mm\"},{\"label\":\"Chiều dài cơ sở\",\"value\":\"1,330 mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"Độ cao gầm xe\"},{\"label\":\"Trọng lượng\",\"value\":\"134 kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"30.000 km hoặc 3 năm (tuỳ theo điều kiện nào đến trước)\"}]}]', '<p>Xe xs155r là một mẫu xe nổi bật trong phân khúc Neo-Retro, mang đến sự kết hợp hoàn hảo giữa thiết kế cổ điển và công nghệ hiện đại. Dưới đây là những điểm nổi bật về thiết kế, động cơ và tính năng của mẫu xe này.</p>\n<p><em>(*) Giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline</em></p>', '<h2>GIÁ XE XS155R MỚI NHẤT CỦA YAMAHA</h2>\n<p><b>Yamaha xs155r</b> là một trong những dòng xe thể thao mới nhất vừa được ra mắt của yamaha. Với thông điệp “Feel your ride: Lái cảm xúc, Chất đam mê”, dòng xe này sở hữu khối động cơ mạnh mẽ cùng ngoại hình cổ điển đầy lịch lãm. Hãy cùng Yên Thoa khám phá ngay <b>giá xe xs155r</b> và những điểm nổi bật của <strong>xsr 155</strong>&nbsp;này qua bài viết dưới đây.</p>\n\n<h2>1. Giới thiệu về xe XS155R của Yamaha</h2>\n<p><b>Yamaha xs155r</b> không chỉ đơn thuần là một chiếc <b>xe máy</b>, mà còn là một tác phẩm nghệ thuật mang đậm phong cách Neo-Retro, thể hiện sự phóng khoáng và cá tính mạnh mẽ. Được phân phối chính hãng tại thị trường Việt Nam, XS155R hứa hẹn sẽ là lựa chọn lý tưởng cho những tín đồ yêu thích sự kết hợp giữa thiết kế cổ điển và công nghệ hiện đại.</p>\n<p>Ngoài động cơ mạnh mẽ, <b>Yamaha xs155r</b> còn được trang bị nhiều tính năng thông minh và hiện đại khác. Tất cả những yếu tố này kết hợp lại tạo nên một chiếc xe không chỉ đẹp mắt mà còn vô cùng tiện nghi và hiệu quả.</p>\n\n<p>Với <strong>xe xsr 155</strong><strong>,</strong> bạn sẽ không chỉ đơn thuần là di chuyển mà còn được trải nghiệm cảm giác tự do tuyệt vời trên từng cây số.&nbsp;</p>\n<h2>2. Những điểm nổi bật của yamaha XS155R&nbsp;</h2>\n<p><b>Xe xs155r</b> là một mẫu xe nổi bật trong phân khúc Neo-Retro, mang đến sự kết hợp hoàn hảo giữa thiết kế cổ điển và công nghệ hiện đại. Dưới đây là những điểm nổi bật về thiết kế, động cơ và tính năng của mẫu xe này.</p>\n<p><em>Thiết kế độc đáo</em></p>\n<p><b>XS155R</b> gây ấn tượng mạnh mẽ với phong cách Neo-Retro, thể hiện qua vẻ ngoài sang trọng và các chi tiết thể thao đầy cá tính. Phần đầu xe nổi bật với cụm đèn pha bo tròn cổ điển, nhưng được nâng cấp bằng màn hình LCD hiện đại, cung cấp đầy đủ thông tin như vận tốc, lượng xăng và các chỉ số kỹ thuật khác. Tay lái được thiết kế đơn giản nhưng tinh tế, tạo tư thế lái thoải mái cho người điều khiển.</p>\n\n<p>Bên hông xe là bình xăng hình giọt nước dung tích 10 lít, kết hợp với yên xe kiểu bánh mì và bộ vành hợp kim đúc nguyên khối. Lốp gai bền bỉ giúp tăng khả năng bám đường tối ưu. Phía sau xe là cụm đèn hậu LED hiện đại nhưng vẫn giữ nét cổ điển với thiết kế tròn truyền thống. Các chi tiết nhôm ở khung phụ và gầm máy không chỉ tăng thêm vẻ đẹp mà còn bảo vệ xe tốt hơn.</p>\n<p>Với ngoại hình chuẩn Neo-Retro, <b>Yamaha xs155r</b> thực sự là lựa chọn lý tưởng cho những ai yêu thích phong cách cổ điển nhưng không kém phần lịch lãm.</p>\n<p><em>Động cơ mạnh mẽ</em></p>\n<p>Được trang bị động cơ 4 thì, xy-lanh đơn 4 van dung tích 155cc cùng công nghệ van biến thiên VVA tiên tiến, Yamaha XS155R mang đến trải nghiệm lái mạnh mẽ với công suất tối đa lên tới 14.2 kW (19,3 PS) tại 10.000 vòng/phút và mô-men xoắn cực đại 14,7 N·m tại 8.500 vòng/phút.</p>\n\n<p>Khung sườn Deltabox cải tiến cùng khung nhôm thế hệ mới giúp tăng cường độ ổn định và khả năng cân bằng khi vận hành ở tốc độ cao. Bộ ly hợp A&amp;S kết hợp hộp số 6 cấp giúp giảm lực kéo của cần ly hợp và ngăn phanh quá mức, đảm bảo chuyển số nhanh chóng và mượt mà.</p>\n<p><em>Tính năng an toàn vượt trội</em></p>\n<p><b>Yamaha xsr 155</b>&nbsp;không chỉ chú trọng đến hiệu suất mà còn đảm bảo an toàn tối đa cho người lái với nhiều tính năng tiên tiến.</p>\n\n<p>Hệ thống phanh đĩa đơn: <b>Xe xs155r</b> được trang bị phanh đĩa đơn cho cả bánh trước và bánh sau, giúp tăng cường khả năng kiểm soát và giảm thiểu khoảng cách phanh trong mọi tình huống. Điều này không chỉ mang lại sự tự tin cho người lái mà còn đảm bảo an toàn tối đa khi di chuyển trên các cung đường khác nhau.</p>\n<p>Bộ mâm hợp kim 17 inch: Với kích thước 17 inch, bộ mâm hợp kim không chỉ giúp tăng cường tính thẩm mỹ mà còn hỗ trợ khả năng vận hành ổn định. Lốp đa địa hình không săm với kích thước 110/70 ở bánh trước và 140/70 ở bánh sau giúp xe dễ dàng vượt qua các loại địa hình khác nhau.</p>\n<p>Hệ thống treo hiện đại: Cụm phuộc trước Up-side-down kết hợp với phuộc sau Monoshock cải tiến mang đến độ ổn định cao, giúp người lái tự tin hơn khi di chuyển trên các cung đường gồ ghề hay khó khăn.</p>\n<p>Với những ưu điểm vượt trội về thiết kế, động cơ cũng như ưu đãi hấp dẫn, <b>giá xe xs155r</b> chắc chắn sẽ làm hài lòng những tín đồ của dòng xe thể thao mạnh mẽ.&nbsp;</p>\n<h2>3. Giá xe XS155R mới nhất tại Hệ thống Siêu Thị Yên Thoa&nbsp;</h2>\n<p><b>Yamaha xs155r</b>, một trong những mẫu xe thể thao được yêu thích nhất hiện nay, đã chính thức có mặt tại Hệ thống Siêu Thị Yên Thoa. Với thiết kế tinh tế và hiệu suất vượt trội, <b>xs155r</b> không chỉ thu hút những tín đồ đam mê tốc độ mà còn là lựa chọn lý tưởng cho những ai tìm kiếm một chiếc xe mạnh mẽ và phong cách.</p>\n<p>Hiện tại, <b>giá xe xs155r</b> tại Hệ thống Siêu Thị Yên Thoa chỉ từ 78.150.000 đồng. Đây là mức giá rất cạnh tranh so với các mẫu xe cùng phân khúc, mang lại cơ hội sở hữu một chiếc xe chất lượng cao với công nghệ tiên tiến cho đông đảo khách hàng.</p>\n\n<p>Đặc biêt, khi mua <b>xe xs155r </b>tại Yên Thoa trong hôm nay, khách hàng sẽ nhận được ngay nhiều ưu đãi hấp dẫn:</p>\n<p>– Tặng ngay Combo quà tặng độc quyền 2.950.000đ</p>\n<p>– Chương trình hỗ trợ mua xe trả góp với lãi suất cực thấp</p>\n<p>– Hỗ trợ thu xe cũ đổi xe mới&nbsp;</p>\n<p>– Giao xe tận nơi theo nhu cầu của khách hàng</p>\n<p>Không chỉ dừng lại ở đó, <a href=\"/xe-may?nhom=yamaha\"><strong>đại lý yamaha</strong></a> Yên Thoa cam kết bảo hành chính hãng cho tất cả các sản phẩm <b>xs155r</b> bán ra. Điều này giúp bạn sẽ luôn an tâm về chất lượng và hiệu suất của xe trong suốt quá trình sử dụng.Đừng bỏ lỡ cơ hội sở hữu <b>yamaha xs155r</b> ngay hôm nay! Hãy đến Xe máy Yên Thoa để trải nghiệm trực tiếp và nhận những ưu đãi hấp dẫn từ chúng tôi. Mọi chi tiết liên qua đến<b> giá </b><b>xe xs155r</b>, quý khách vui lòng liên hệ qua hotline để được tư vấn miễn phí!</p>\n<p><strong>HỆ THỐNG XE MÁY YÊN THOA&nbsp;</strong></p>', 1);
