lue\":\"LED / 12V, 10W x 2 / 12V, 10W x 2\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"2,005 mm x 805 mm x 1,080 mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"810 mm\"},{\"label\":\"Chiều dài cơ sở\",\"value\":\"1,330 mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"Độ cao gầm xe\"},{\"label\":\"Trọng lượng\",\"value\":\"134 kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"30.000 km hoặc 3 năm (tuỳ theo điều kiện nào đến trước)\"}]}]' WHERE slug = 'xe-xs155r' AND specs IS NULL;
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-yamaha-gear-125', 'Xe Yamaha Gear 125', 'yamaha', '[]', 30437000, 34364000, '/sites/yenthoa/img/2026/04/gear125.webp', '[\"/sites/yenthoa/img/2026/04/gear125.webp\",\"/sites/yenthoa/img/2026/04/gear-bac-xam-1.webp\",\"/sites/yenthoa/img/2026/04/gear-den-xam.webp\",\"/sites/yenthoa/img/2026/04/gear-trang-xam.webp\",\"/sites/yenthoa/img/2026/04/gear-den-do.webp\",\"/sites/yenthoa/img/2026/04/gear-xam-xanh.webp\",\"/sites/yenthoa/img/2026/04/gear-xanh-trang.webp\",\"/sites/yenthoa/img/2026/04/gear-do-trang.webp\"]', '[\"Bạc Xám\",\"Đen Đỏ\",\"Đen Xám\",\"Đỏ Trắng\",\"Trắng Xám\",\"Xám Xanh dương\",\"Xanh Trắng\"]', '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Xám\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-trang-xam.webp\",\"price\":34364000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-den-do.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Xanh dương\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-xam-xanh.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Trắng\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-xanh-trang.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Trắng\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-do-trang.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Xám\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-bac-xam-1.webp\",\"price\":34364000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Xám\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-den-xam.webp\",\"price\":34364000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"Xăng, 4 kỳ, 1 xi lanh, làm mát bằng không khí\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"Xy lanh đơn\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"124,9\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"52,4 × 57,9\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,0:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"6,2/ 6.500\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"10,6/ 4.500\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Hệ thống bôi trơn\",\"value\":\"Các te ướt / Dầu bôi trơn: 10W-40\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"0,8L\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"5,1L\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"1,7\"},{\"label\":\"Hệ thống cung cấp nhiên liệu\",\"value\":\"Phun xăng điện tử (FI)\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Ly hợp ma sát khô, tự động\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"2.286~0.770: Truyền động đai,7.773: Truyền động cuối\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"Hộp số vô cấp\"},{\"label\":\"Phương thức truyền động\",\"value\":\"Truyền động đai\"},{\"label\":\"Ắc quy\",\"value\":\"5Ah\"},{\"label\":\"Điện áp hệ thống\",\"value\":\"12V\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Loại khung\",\"value\":\"Backbone\"},{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Lò xo trụ/ Thủy lực\"},{\"label\":\"Độ lệch phương trục lái\",\"value\":\"27°/85mm\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Lò xo trụ/ Thủy lực\"},{\"label\":\"Phanh trước\",\"value\":\"Phanh đĩa đơn thủy lực\"},{\"label\":\"Phanh sau\",\"value\":\"Phanh tang trống dẫn động cơ khí\"},{\"label\":\"Kích thước bánh trước / bánh sau\",\"value\":\"110/70-12 47L (không săm)\"},{\"label\":\"Đèn trước/đèn sau\",\"value\":\"LED\"},{\"label\":\"Đèn sau\",\"value\":\"Halogen\"},{\"label\":\"Đèn pha/Đèn báo rẽ (trước/sau)\",\"value\":\"Halogen\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"1850 x 685 x 1075\"},{\"label\":\"Độ cao yên xe\",\"value\":\"750mm\"},{\"label\":\"Chiều dài mặt yên\",\"value\":\"790mm\"},{\"label\":\"Độ cao gầm xe\",\"value\":\"135mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1280mm\"},{\"label\":\"Trọng lượng\",\"value\":\"96kg\"},{\"label\":\"Ngăn chứa đồ\",\"value\":\"17,4L\"},{\"label\":\"Tải trọng lớn nhất (kg)\",\"value\":\"157\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Bảo hành\",\"value\":\"Bảo hành chính hãng 3 năm hoặc 30.000km\"}]}]', '<p>Được trang bị công nghệ động cơ Blue Core Hybrid cùng thiết kế hiện đại thể thao, Yamaha Gear 125 Hybrid mang đến sự tự tin tuyệt đối khi di chuyển.</p>\n<p>(*) Giá xe trên chỉ là giá đề xuất chứ không phải giá chính thức, giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm. Để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline.</p>', '<h2><b>GIÁ XE YAMAHA GEAR 125 HYBRID CHÍNH HÃNG GIÁ RẺ</b></h2>\n<p>Trong phân khúc xe ga tầm trung, <b>Yamaha Gear 125</b> nổi bật như một lựa chọn đáng cân nhắc nhờ sự kết hợp hài hòa giữa thiết kế gọn gàng, khả năng vận hành bền bỉ, tính tiện dụng cao và chi phí hợp lý.</p>\n<p>Yamaha Gear 125 Hybrid ra mắt tại thị trường Việt Nam hướng đến người dùng trẻ với nhu cầu di chuyển linh hoạt trong đô thị, đồng thời được trang bị công nghệ hybrid giúp hỗ trợ tăng tốc và tiết kiệm nhiên liệu hiệu quả.</p>\n\n<h2><b>1. Yamaha Gear 125 Hybrid – Xe tay ga đô thị dành cho giới trẻ</b></h2>\n<p><b>Yamaha Gear 125</b> là dòng xe tay ga được Yamaha phát triển nhằm phục vụ nhu cầu di chuyển linh hoạt trong môi trường đô thị đông đúc. Ngay từ cái nhìn đầu tiên, xe gây ấn tượng với thiết kế khỏe khoắn, mang hơi hướng thực dụng nhưng vẫn giữ được nét trẻ trung, cá tính.</p>\n<p>Điểm nổi bật của <b>Yamaha Gear 125 Hybrid</b> nằm ở việc trang bị động cơ Blue Core kết hợp công nghệ hybrid hiện đại. Đây là trang bị đáng giá giúp xe vận hành mượt mà hơn, tiết kiệm nhiên liệu tốt hơn so với các dòng xe tay ga truyền thống.</p>\n<p>Về tổng thể,Yamaha Gear 125 Hybrid sở hữu kiểu dáng gọn gàng, chiều cao yên phù hợp với thể trạng người Việt, dễ điều khiển trong điều kiện giao thông đông đúc. Xe cũng được thiết kế để tối ưu cho việc di chuyển hàng ngày như đi làm, đi học, đi chợ hay giao hàng.</p>\n<p>Không chỉ là một phương tiện di chuyển, <b>Gear 125</b> còn mang đến trải nghiệm tiện lợi và hiện đại, đáp ứng tốt nhu cầu của người dùng trẻ trong cuộc sống đô thị năng động.</p>\n\n<h2><b>2. Những ưu điểm nổi bật của Yamaha Gear 125 Hybrid</b></h2>\n<h3><b>2.1 Động cơ Hybrid tiết kiệm xăng vượt trội</b></h3>\n<p>Một trong những lý do khiến<em><a href=\"/xe/xe-yamaha-gear-125\"><b> xe Yamaha Gear 125</b></a></em> được quan tâm nhiều chính là khả năng tiết kiệm nhiên liệu ấn tượng. Xe sử dụng động cơ:</p>\n<ul>\n<li>Xăng 4 kỳ, 1 xi lanh</li>\n<li>Dung tích 124,9cc</li>\n<li>Làm mát bằng không khí</li>\n<li>Tích hợp công nghệ Hybrid</li>\n</ul>\n<p>Điểm nhấn được đánh giá cao trên Yamaha Gear 125 là công nghệ hybrid hỗ trợ tăng lực kéo khi tăng tốc, giúp xe vận hành êm ái hơn, đặc biệt khi di chuyển trong đô thị đông đúc. Đồng thời, hệ thống này còn giúp giảm tiêu hao nhiên liệu đáng kể, phù hợp với người dùng thường xuyên di chuyển.</p>\n<p>Điểm nổi bật của <b>Yamaha Gear</b> còn nằm ở động cơ Blue Core Hybrid 125cc – công nghệ tiên tiến giúp xe vận hành êm ái, bền bỉ và tối ưu mức tiêu hao nhiên liệu. Hệ thống trợ lực điện (Hybrid) sẽ kích hoạt trong khoảng 3 giây sau khi khởi động, tăng lực kéo, hỗ trợ tăng tốc mượt mà, đặc biệt hiệu quả khi chở nặng hoặc di chuyển trên địa hình dốc. Nhờ đó, xe không chỉ mang lại trải nghiệm lái nhẹ nhàng mà còn giúp tiết kiệm xăng đáng kể.</p>\n<p>Không chỉ vậy, hệ thống này còn góp phần giảm mức tiêu hao nhiên liệu đáng kể, giúp người dùng tiết kiệm chi phí trong quá trình sử dụng lâu dài.</p>\n<p><b>Thông số vận hành ấn tượng:</b></p>\n<ul>\n<li>Công suất: 7.0 kW tại 8000 vòng/phút</li>\n<li>Mô-men xoắn: 9.5 Nm tại 5500 vòng/phút</li>\n</ul>\n<p>Yamaha Gear 125 Hybrid không chỉ tiết kiệm xăng mà còn mang lại trải nghiệm lái êm ái, thân thiện với người dùng.</p>\n\n<h3><b>2.2 Thiết kế tiện ích đáp ứng nhu cầu</b></h3>\n<p>Dù thuộc phân khúc giá phổ thông, nhưng <b>Yamaha Gear 125</b> vẫn được trang bị nhiều tiện ích đáng giá:</p>\n<p><b>Cụm đèn LED chiếu sáng hiện đại:</b></p>\n<p>Toàn bộ cụm đèn LED chiếu sáng được trang bị công nghệ LED tiên tiến, mang đến ánh sáng mạnh mẽ và sắc nét.</p>\n<p><b>Cổng sạc thông minh:</b></p>\n<p>Cổng sạc phía trước tiện lợi, giúp bạn tự tin sạc điện thoại hoặc các thiết bị điện tử khác khi đang di chuyển</p>\n<p><b>Chỗ để chân rộng rãi:</b></p>\n<p>Sàn để chân rộng rãi, mang lại cảm giác lái xe thoải mái, đặc biệt trong hành trình dài.</p>\n<p><b>Tay dắt phía sau đa năng:</b></p>\n<p>Tay nắm phía sau được thiết kế dài và phẳng, tích hợp với móc phía dưới giúp dễ dàng chở hàng.</p>\n<p><b>Màn hình LCD đa chức năng:</b></p>\n<p>Tích hợp nhiều tính năng hiện đại: tốc độ, nhiên liệu, tiêu thụ xăng, thông báo cuộc gọi, tin nhắn. Thông tin được hiển thị trực quan, dễ đọc dưới mọi điều kiện ánh sáng, nâng cao sự an toàn và thoải mái khi di chuyển.</p>\n<p><b>Móc treo đôi phía trước tiện lợi:</b></p>\n<p>Chỗ để chân phía trước được tích hợp hai móc treo đồ chắc chắn, tiện lợi khi di chuyển.</p>\n<p>Những trang bị này giúp nâng cao trải nghiệm người dùng, mang lại sự tiện lợi tối đa trong quá trình sử dụng hàng ngày.</p>\n\n\n<h3><b>3.1 Mức giá cạnh tranh</b></h3>\n<p>Một trong những yếu tố quan trọng khiến nhiều người tìm kiếm <b>giá xe Yamaha Gear 125 Hybrid chính hãng</b> chính là mức giá cực kỳ hợp lý.</p>\n<p>So với các đối thủ trong cùng phân khúc, <b>giá xe Yamaha Gear 125</b> được đánh giá là “dễ tiếp cận”, phù hợp với nhiều đối tượng khách hàng. Hiện nay, <b>giá xe Yamaha Gear 125 Hybrid</b> trên thị trường dao động tùy theo phiên bản và khu vực. Mức giá đề xuất:</p>\n<ul>\n<li>Phiên bản tiêu chuẩn:<b>30.437.000 VNĐ</b></li>\n<li>Phiên bản cao cấp (có Smart Key): <b>34.364.000 VNĐ</b></li>\n</ul>\n<p><b>Lưu ý:</b> Giá xe có thể thay đổi tùy theo thời điểm và chương trình ưu đãi tại từng đại lý Yamaha.</p>\n<h3><b>3.2 Địa chỉ mua xe Yamaha Gear 125 chính hãng</b></h3>\n<p>Nếu bạn đang tìm <b>địa chỉ mua xe Yamaha Gear 125 chính hãng</b>, việc lựa chọn một<em><a href=\"/xe-may?nhom=yamaha\"> <b>đại lý Yamaha</b></a></em> uy tín là yếu tố cực kỳ quan trọng để đảm bảo:</p>\n<ul>\n<li>Giá tốt – minh bạch</li>\n<li>Xe chính hãng 100%</li>\n<li>Bảo hành đầy đủ</li>\n<li>Hỗ trợ trả góp nhanh chóng</li>\n</ul>\n<p>Tại TP.HCM,<b> cửa hàng bán xe Yamaha Gear 125 tại HCM</b> được nhiều khách hàng tin tưởng hiện nay chính là <b>Yên Thoa</b> – hệ thống phân phối xe Yamaha chính hãng với nhiều năm kinh nghiệm.</p>\n<p><b>Vì sao nên mua xe tại Yên Thoa?</b></p>\n<ul>\n<li>Là <b>đại lý Yamaha chính hãng</b>, cung cấp đầy đủ các dòng xe mới nhất</li>\n<li>Cập nhật giá xe Yamaha Gear 125 nhanh chóng, cạnh tranh</li>\n<li>Nhiều chương trình ưu đãi, quà tặng hấp dẫn</li>\n<li>Hỗ trợ trả góp lãi suất thấp, thủ tục đơn giản</li>\n<li>Đội ngũ tư vấn chuyên nghiệp, tận tâm</li>\n</ul>\n<p>Đặc biệt, khi mua xe tại đây, khách hàng còn được:</p>\n<ul>\n<li>Trải nghiệm xe trực tiếp</li>\n<li>Tư vấn chọn phiên bản phù hợp nhu cầu</li>\n<li>Hỗ trợ đăng ký xe nhanh gọn</li>\n</ul>\n<p>Nếu bạn đang tìm kiếm một cửa hàng xe máy uy tín để mua xe hoặc cần tư vấn chi tiết về xe, đừng ngần ngại liên hệ Yên Thoa – nơi mang đến cho bạn sự an tâm khi mua xe và trải nghiệm dịch vụ tốt nhất.</p>\n<p>Liên hệ ngay holtine <b>0789.619.698</b> để được tư vấn mua xe nhanh chóng và sớm nhất!</p>', 1);
UPDATE products SET variants = '[{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Trắng Xám\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-trang-xam.webp\",\"price\":34364000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Đỏ\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-den-do.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xám Xanh dương\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-xam-xanh.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Xanh Trắng\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-xanh-trang.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Tiêu chuẩn\"},{\"name\":\"Màu sắc\",\"value\":\"Đỏ Trắng\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-do-trang.webp\",\"price\":30437000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Bạc Xám\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-bac-xam-1.webp\",\"price\":34364000},{\"attrs\":[{\"name\":\"Phiên bản\",\"value\":\"Cao cấp\"},{\"name\":\"Màu sắc\",\"value\":\"Đen Xám\"}],\"img\":\"/sites/yenthoa/img/2026/04/gear-den-xam.webp\",\"price\":34364000}]' WHERE slug = 'xe-yamaha-gear-125' AND variants IS NULL;
