INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-yzf-r3', 'Xe YZF-R3', 'yamaha', '[\"xe-the-thao\"]', 132000000, 132000000, '/sites/yenthoa/img/2026/09/yzf-r3-xanh-den.webp', '[\"/sites/yenthoa/img/2026/09/yzf-r3-xanh-den.webp\",\"/sites/yenthoa/img/2026/09/yzf-r3-xanh-den.webp\"]', '[\"Đen\",\"Trắng Xám\",\"Xanh Đen\"]', '[{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Trắng Xám\"}],\"img\":\"/sites/yenthoa/img/2026/09/yzf-r3-trang-xam.webp\",\"price\":132000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Đen\"}],\"img\":\"/sites/yenthoa/img/2026/09/yzf-r3-den.webp\",\"price\":132000000},{\"attrs\":[{\"name\":\"Màu sắc\",\"value\":\"Xanh Đen\"}],\"img\":\"/sites/yenthoa/img/2026/09/yzf-r3-xanh-den.webp\",\"price\":132000000}]', '[{\"title\":\"Động cơ\",\"items\":[{\"label\":\"Loại\",\"value\":\"4 thì, 2 xy lanh, làm mát bằng chất lỏng\"},{\"label\":\"Bố trí xi lanh\",\"value\":\"2 xy lanh nằm ngang\"},{\"label\":\"Dung tích xy lanh (CC)\",\"value\":\"321\"},{\"label\":\"Đường kính và hành trình piston\",\"value\":\"68,0 mm x 44,1 mm\"},{\"label\":\"Tỷ số nén\",\"value\":\"11,2:1\"},{\"label\":\"Công suất tối đa\",\"value\":\"30.9 kW/ 10.750 vòng/ phút\"},{\"label\":\"Mô men xoắn cực đại\",\"value\":\"29.5 Nm/ 9.000 vòng/ phút\"},{\"label\":\"Hệ thống khởi động\",\"value\":\"Điện\"},{\"label\":\"Mức tiêu thụ nhiên liệu (l/100km)\",\"value\":\"3,65 lít/100km\"},{\"label\":\"Hệ thống cung cấp nhiên liệu\",\"value\":\"Hệ thống phun xăng điện tử\"},{\"label\":\"Hệ thống đánh lửa\",\"value\":\"TCI\"},{\"label\":\"Hệ thống ly hợp\",\"value\":\"Đa đĩa, ly tâm loại ướt\"},{\"label\":\"Tỷ số truyền động\",\"value\":\"Số 1: 35/14=2,500; Số 2: 31/17=1,824; Số 3: 31/23=1,348; Số 4: 25/23=1,087; Số 5: 23/25=0,920; Số 6: 24/30=0,800\"},{\"label\":\"Kiểu hệ thống truyền lực\",\"value\":\"Bánh răng ăn khớp, 6 số\"}]},{\"title\":\"Khung xe\",\"items\":[{\"label\":\"Hệ thống giảm xóc trước\",\"value\":\"Lò xo trụ/ thủy lực\"},{\"label\":\"Hệ thống giảm xóc sau\",\"value\":\"Lò xo trụ/ thủy lực\"},{\"label\":\"Phanh trước\",\"value\":\"Đĩa đơn thủy lực, ∅298 x 4,5 mm, ABS\"},{\"label\":\"Phanh sau\",\"value\":\"Đĩa đơn thủy lực, ∅298 x 4,5 mm, ABS\"},{\"label\":\"Lốp trước\",\"value\":\"110/70-17M/C 54H (Lốp không săm)\"},{\"label\":\"Lốp sau\",\"value\":\"140/70-17M/C 66H (Lốp không săm)\"},{\"label\":\"Đèn trước\",\"value\":\"LED\"},{\"label\":\"Đèn sau\",\"value\":\"LED\"},{\"label\":\"Đèn báo rẽ (trước/sau)\",\"value\":\"LED\"}]},{\"title\":\"Kích thước\",\"items\":[{\"label\":\"Kích thước (dài x rộng x cao)\",\"value\":\"2.090mm x 735mm x 1.140mm\"},{\"label\":\"Độ cao yên xe\",\"value\":\"780mm\"},{\"label\":\"Khoảng cách giữa 2 trục bánh xe\",\"value\":\"1.380mm\"},{\"label\":\"Trọng lượng ướt\",\"value\":\"169kg\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"14.0 lít\"},{\"label\":\"Dung tích dầu máy\",\"value\":\"2.4 lít\"},{\"label\":\"Khoảng sáng gầm xe tối thiểu\",\"value\":\"160 mm\"},{\"label\":\"Tải trọng lớn nhất (kg)\",\"value\":\"329kg\"}]},{\"title\":\"Bảo hành\",\"items\":[{\"label\":\"Thời gian bảo hành\",\"value\":\"3 năm hoặc 30.000km (tuỳ điều kiện nào đến trước)\"}]}]', '<p>Yamaha YZF R3 là mẫu xe phân khối lớn được thiết kế dựa trên cảm hứng từ huyền thoại YZR-M1 của giải đua MotoGP danh tiếng. Mẫu xe moto này được trang bị động cơ 4 thì, xi-lanh đôi, 321 phân khối, làm mát bằng dung dịch, công suất 30.9 kW tại 10.750 vòng/phút và mô-men xoắn cực đại 29,5 Nm tại 9.000 vòng/phút, tích hợp phun xăng điện tử.</p>\n<p>(*) Giá xe trên chỉ là giá đề xuất chứ không phải giá chính thức, giá xe có thể thay đổi tuỳ theo từng phiên bản và thời điểm. Để cập nhật giá xe mới nhất quý khách vui lòng liên hệ qua hotline.</p>', '<h2><b>Giá xe Yamaha YZF-R3 mới nhất</b></h2>\n<p>Khi nhắc đến phân khúc mô tô thể thao hạng trung tại thị trường Việt Nam, các biker thường dành một sự quan tâm đặc biệt cho dòng sportbike đến từ Nhật Bản. Trong đó, việc tìm hiểu mức <b>giá xe Yamaha YZF-R3 mới nhất</b> luôn là chủ đề “hot” trên các diễn đàn mê xe tốc độ. Không chỉ mang trên mình DNA thể thao thuần chất từ đường đua MotoGP, mẫu <b>xe máy Yamaha</b> này còn là bước đệm hoàn hảo cho những ai muốn chinh phục dòng xe phân khối lớn.</p>\n<p>Cùng <b>Yên Thoa</b> cập nhật ngay bảng giá chi tiết, thông số và những đánh giá thực tế về mẫu <b>YZF R3</b> đình đám này ngay dưới đây!</p>\n\n<h2><b>1. Đánh giá thiết kế và trang bị nổi bật trên Yamaha YZF-R3</b></h2>\n<p>Về thiết kế, <a href=\"/xe/xe-yzf-r3\"><b>Yamaha YZF-R3</b></a> mang đậm phong cách sportbike với phần đầu xe khí động học, thân xe ôm sát và tư thế ngồi hướng về phía trước. Ngôn ngữ thiết kế của mẫu xe được Yamaha phát triển dựa trên cảm hứng từ dòng xe đua YZR-M1, tạo cảm giác thể thao ngay từ cái nhìn đầu tiên.&nbsp;</p>\n<ul>\n<li><b>Ngoại hình khí động học:</b> Phần mặt nạ trước được bổ sung hệ thống đèn pha LED projector trung tâm sắc sảo kết hợp dải đèn định vị vuốt nhọn. Các cánh gió khí động học nhỏ gọn đặt hai bên sườn không chỉ làm tăng vẻ hầm hố, nam tính mà còn giúp xe bám đường tốt hơn khi vận hành ở tốc độ cao.</li>\n<li><b>Hệ thống treo và khung sườn:</b> Xe sử dụng bộ phuộc trước hành trình ngược (Upside-down) thương hiệu KYB màu đen tuyền cứng cáp, kết hợp giảm xóc sau dạng lò xo trụ đơn. Thiết kế này giúp triệt tiêu độ rung lắc, mang lại cảm giác lái đầm chắc, ôm cua ngọt ngào ở mọi dải tốc độ.</li>\n<li><b>Trang bị an toàn:</b> Hệ thống phanh đĩa thủy lực trước 298mm và sau 220mm tích hợp công nghệ chống bó cứng phanh (ABS) 2 kênh là điểm cộng lớn, giúp biker tự tin xử lý các tình huống khẩn cấp.</li>\n</ul>\n<p>Một điểm đáng chú ý là chiều cao yên khoảng 780 mm. So với nhiều mẫu mô tô thể thao dung tích lớn, thông số này tương đối dễ tiếp cận, giúp người mới chuyển từ xe côn tay hoặc sportbike dung tích nhỏ lên <b>YZF R3</b> bớt áp lực khi chống chân.</p>\n<p>Hệ thống chiếu sáng LED ở phía trước và phía sau kết hợp cùng bộ mâm thể thao, lốp kích thước lớn giúp tổng thể xe cân đối hơn. Đây là kiểu thiết kế phù hợp với nhóm khách hàng trẻ muốn một mẫu <b>xe Yamaha thể thao</b> có ngoại hình nổi bật nhưng không quá hầm hố.</p>\n\n<h2><b>2. Sức mạnh động cơ và khả năng vận hành thực tế của Yamaha YZF-R3&nbsp;</b></h2>\n<p>Điểm đáng giá nhất trên<b> xe Yamaha thể thao YZF-R3</b> là khối động cơ vô cùng mạnh mẽ, đủ sức làm thỏa mãn những tín đồ tốc độ khó tính nhất.</p>\n<ul>\n<li><b>Thông số vận hành:</b> <b>YZF R3</b> được trang bị cỗ máy 2 xi-lanh thẳng hàng, 4 thì, 8 van, dung tích 321cc, làm mát bằng dung dịch, phun xăng điện tử và sử dụng trục cam kép DOHC.</li>\n<li><b>Công suất:</b> Xe sản sinh công suất tối đa lên đến <b>42 mã lực tại 10.750 vòng/phút</b> và mô-men xoắn cực đại đạt <b>29.6 Nm tại 9.000 vòng/phút</b>, kết hợp hộp số 6 cấp ăn khớp mượt mà.</li>\n<li><b>Cảm giác lái:</b> Xe đáp ứng dải vòng tua lớn cực kỳ nhanh nhạy. Đặc biệt, việc bổ sung bộ ly hợp hỗ trợ và chống trượt (Assist &amp; Slipper Clutch) giúp hiện tượng khóa bánh sau khi dồn số gấp bị loại bỏ hoàn toàn, mang lại trải nghiệm cầm lái an toàn và phấn khích hơn hẳn.</li>\n</ul>\n<p><b>Xe YZF R3</b> với hộp số 6 cấp, động cơ 2 xi-lanh mang đến đặc tính vận hành phù hợp với một chiếc sportbike đường phố. Ở dải tua thấp, xe có thể vận hành tương đối nhẹ nhàng cho nhu cầu đi lại. Khi vòng tua tăng cao, sức mạnh của động cơ bắt đầu thể hiện rõ hơn, phù hợp với người thích cảm giác tăng tốc và kiểm soát chiếc xe bằng tay côn, tay ga.</p>\n<p>Đây cũng là điểm khiến <b>xe Yamaha YZF R3</b> khác biệt so với những mẫu xe dung tích nhỏ hơn. Thay vì tập trung hoàn toàn vào khả năng tiết kiệm nhiên liệu, Yamaha hướng R3 đến trải nghiệm lái thể thao nhưng vẫn đủ thân thiện để sử dụng thường xuyên.</p>\n\n<h2><b>3. Cập nhật bảng giá xe Yamaha YZF-R3 mới nhất tại đại lý</b></h2>\n<p>Theo thông tin từ Yamaha Motor Việt Nam, <b>giá Yamaha YZF-R3</b> hiện được niêm yết từ <b>132.000.000 đồng</b>, Mức giá này là giá bán lẻ đề xuất và chưa phải tổng chi phí để xe được phép lưu thông trên đường, bởi người mua còn cần tính thêm các khoản như lệ phí trước bạ, phí đăng ký biển số và bảo hiểm bắt buộc. Điểm cần lưu ý là <b>giá xe Yamaha YZF-R3 mới nhất </b>tại đại lý có thể thay đổi tùy thời điểm, chương trình ưu đãi, màu xe và chính sách bán hàng. Vì vậy, khách hàng nên liên hệ trực tiếp đại lý trước khi quyết định mua để nhận báo giá thực tế và các khoản chi phí liên quan.&nbsp;</p>\n<p>Đặc biệt, với khách hàng quan tâm đến <b>giá xe Yamaha YZF-R3</b>, mức niêm yết 132 triệu đồng giúp việc dự trù ngân sách trở nên dễ dàng hơn. Tuy nhiên, trước khi mua, người dùng nên xác định tổng chi phí lăn bánh, chi phí trang bị bảo hộ và chi phí bảo dưỡng để có kế hoạch tài chính phù hợp.&nbsp;</p>\n<h2><b>4. Mua xe Yamaha YZF-R3 chính hãng, uy tín ở đâu?</b></h2>\n<p>Việc lựa chọn một địa chỉ mua hàng uy tín, dịch vụ hậu mãi chính hãng và hỗ trợ trả góp nhanh chóng là ưu tiên hàng đầu của bất kỳ khách hàng nào khi đầu tư một chiếc mô tô tầm trung.</p>\n<p>Nếu đang tìm <b>địa chỉ mua Yamaha YZF-R3 chính hãng</b>, khách hàng có thể tham khảo hệ thống <b>Yên Thoa</b>. Đại lý cung cấp các sản phẩm Yamaha chính hãng cùng dịch vụ tư vấn, hỗ trợ thủ tục mua xe và chăm sóc sau bán hàng.&nbsp;</p>\n<p><b>Yên Thoa – Hotline: 0789.619.698</b></p>\n\n<p>Nếu bạn đang cân nhắc giữa YZF-R3 và những mẫu mô tô Yamaha khác như YZF-R15, MT-03 hay XS155R, đội ngũ tư vấn có thể hỗ trợ so sánh dựa trên ngân sách và nhu cầu sử dụng thực tế để lựa chọn mẫu xe phù hợp hơn.</p>\n<p>Hãy liên hệ với chúng tôi ngay hôm nay để không bỏ lỡ những chương trình ưu đãi độc quyền dành riêng cho dòng <b>YZF R3</b>.</p>', 1);
